# §22  ОЦЕНКА ВОЛАТИЛЬНОСТИ
# ─────────────────────────────────────────────────────────────────────────────

class VolatilityEstimation:
    """§22 — Все методы оценки волатильности."""

    # ── Historical Volatility ─────────────────────────────────────────────────
    @staticmethod
    def historical_vol(prices: np.ndarray, ticks_per_day: int = 252) -> dict:
        """
        §22: Historical vol = std(log_returns) × √(тиков в дне).
        Annualization factor уточняется из количества тиков в раунде.
        """
        log_ret = np.diff(np.log(prices + 1e-12))
        hv = np.std(log_ret, ddof=1) * np.sqrt(ticks_per_day)
        return {
            "historical_vol": hv,
            "log_returns": log_ret,
            "annualization_factor": ticks_per_day,
            "n_obs": len(log_ret),
        }

    # ── EWMA Volatility ────────────────────────────────────────────────────────
    @staticmethod
    def ewma_vol(prices: np.ndarray, lam: float = 0.94,
                 ticks_per_day: int = 252) -> dict:
        """
        §22: EWMA vol — более быстрая адаптация к recent vol.
        σ²_t = λ·σ²_{t-1} + (1-λ)·r²_{t-1}
        """
        log_ret = np.diff(np.log(prices + 1e-12))
        var = np.empty(len(log_ret))
        var[0] = log_ret[0] ** 2
        for i in range(1, len(log_ret)):
            var[i] = lam * var[i - 1] + (1 - lam) * log_ret[i - 1] ** 2
        vol_series = np.sqrt(var) * np.sqrt(ticks_per_day)
        return {
            "ewma_vol_series": vol_series,
            "ewma_vol_latest": vol_series[-1],
            "lambda": lam,
            "annualized": True,
        }

    # ── Parkinson Volatility ──────────────────────────────────────────────────
    @staticmethod
    def parkinson_vol(highs: np.ndarray, lows: np.ndarray,
                      ticks_per_day: int = 252) -> dict:
        """
        §22: Parkinson vol — (high-low) based, эффективнее HV.
        σ_park = √[ 1/(4n·ln2) · Σ(ln(H_i/L_i))² ] × √(ticks_per_day)
        """
        n = len(highs)
        log_hl = np.log((highs + 1e-12) / (lows + 1e-12))
        pv = np.sqrt(np.sum(log_hl ** 2) / (4 * n * np.log(2)))
        pv_ann = pv * np.sqrt(ticks_per_day)
        return {
            "parkinson_vol": pv_ann,
            "parkinson_vol_raw": pv,
            "efficiency_vs_hv": "more_efficient_with_fewer_obs",
            "n_obs": n,
        }

    # ── GARCH(1,1) ────────────────────────────────────────────────────────────
    @staticmethod
    def garch_11(prices: np.ndarray,
                 omega: float = 1e-6,
                 alpha: float = 0.1,
                 beta:  float = 0.85,
                 ticks_per_day: int = 252) -> dict:
        """
        §22: GARCH(1,1) — моделирование кластеризации волатильности.
        σ²_t = ω + α·r²_{t-1} + β·σ²_{t-1}
        MLE-калибровка через scipy.optimize.
        """
        log_ret = np.diff(np.log(prices + 1e-12))
        n = len(log_ret)

        def garch_variance_series(params, r):
            w, a, b = params
            var = np.empty(len(r))
            var[0] = np.var(r)
            for i in range(1, len(r)):
                var[i] = w + a * r[i - 1] ** 2 + b * var[i - 1]
            return np.clip(var, 1e-12, None)

        def neg_log_likelihood(params):
            w, a, b = params
            if w <= 0 or a < 0 or b < 0 or a + b >= 1:
                return 1e9
            var = garch_variance_series(params, log_ret)
            ll = -0.5 * np.sum(np.log(var) + log_ret ** 2 / var)
            return -ll

        # Калибровка
        res = optimize.minimize(
            neg_log_likelihood, [omega, alpha, beta],
            method="L-BFGS-B",
            bounds=[(1e-9, 0.1), (1e-9, 0.5), (1e-9, 0.9999)],
            options={"maxiter": 500},
        )
        w_opt, a_opt, b_opt = res.x
        var_series = garch_variance_series(res.x, log_ret)
        vol_series = np.sqrt(var_series) * np.sqrt(ticks_per_day)
        # Long-run vol
        long_run_var = w_opt / (1 - a_opt - b_opt + 1e-12)
        return {
            "omega": w_opt, "alpha": a_opt, "beta": b_opt,
            "vol_series": vol_series,
            "vol_latest": vol_series[-1],
            "long_run_vol": np.sqrt(long_run_var) * np.sqrt(ticks_per_day),
            "volatility_clustering": True,
            "persistence": a_opt + b_opt,
            "mle_success": res.success,
        }

    # ── Annualization factor ──────────────────────────────────────────────────
    @staticmethod
    def annualization_factor(round_ticks: int, trading_days: int = 1) -> dict:
        """
        §22: Annualization factor — уточнять из количества тиков в раунде.
        """
        ticks_per_day = round_ticks / trading_days
        return {
            "round_ticks": round_ticks,
            "trading_days": trading_days,
            "ticks_per_day": ticks_per_day,
            "annualization_factor": ticks_per_day,
            "sqrt_factor": np.sqrt(ticks_per_day),
        }

    # ── Heston Model (implied vol smile) ─────────────────────────────────────
    @staticmethod
    def heston_call_price(S: float, K: float, T: float, r: float,
                          v0: float, kappa: float, theta: float,
                          sigma: float, rho: float,
                          n_steps: int = 200) -> dict:
        """
        §22: Heston model вместо quadratic smile для опционов.
        Аналитическое решение через характеристическую функцию.
        v0: начальная vol, kappa: mean-reversion speed,
        theta: long-run variance, sigma: vol-of-vol, rho: correlation.
        """
        def integrand(phi, j):
            i  = complex(0, 1)
            x  = np.log(S)
            a  = kappa * theta
            if j == 1:
                u = 0.5; b = kappa - rho * sigma
            else:
                u = -0.5; b = kappa
            d = np.sqrt((rho * sigma * i * phi - b) ** 2
                        - sigma ** 2 * (2 * u * i * phi - phi ** 2))
            g = (b - rho * sigma * i * phi + d) / \
                (b - rho * sigma * i * phi - d + 1e-14)
            C = r * i * phi * T + (a / sigma ** 2) * (
                (b - rho * sigma * i * phi + d) * T
                - 2 * np.log((1 - g * np.exp(d * T)) / (1 - g + 1e-14))
            )
            D = ((b - rho * sigma * i * phi + d) / sigma ** 2) * \
                (1 - np.exp(d * T)) / (1 - g * np.exp(d * T) + 1e-14)
            f = np.exp(C + D * v0 + i * phi * x)
            return np.real(np.exp(-i * phi * np.log(K)) * f / (i * phi + 1e-14))

        phi_range = np.linspace(1e-5, 100, n_steps)
        dphi = phi_range[1] - phi_range[0]
        P = []
        for j in [1, 2]:
            integral = np.sum([integrand(phi, j) for phi in phi_range]) * dphi
            P.append(0.5 + integral / np.pi)

        price = S * P[0] - K * np.exp(-r * T) * P[1]
        return {
            "heston_call_price": max(price, 0),
            "P1": P[0], "P2": P[1],
            "model": "Heston",
            "params": {"v0": v0, "kappa": kappa, "theta": theta,
                       "sigma": sigma, "rho": rho},
        }

    # ── SABR Implied Vol ──────────────────────────────────────────────────────
    @staticmethod
    def sabr_implied_vol(F: float, K: float, T: float,
                         alpha: float, beta: float,
                         rho: float, nu: float) -> dict:
        """
        §22: SABR model — implied vol для smile.
        Hagan 2002 approximation.
        F: forward, K: strike, T: time to expiry.
        """
        if abs(F - K) < 1e-8:   # ATM
            term1 = alpha / (F ** (1 - beta))
            term2 = 1 + ((1 - beta) ** 2 / 24 * alpha ** 2 / F ** (2 - 2 * beta)
                         + rho * beta * nu * alpha / (4 * F ** (1 - beta))
                         + (2 - 3 * rho ** 2) / 24 * nu ** 2) * T
            sigma = term1 * term2
        else:
            FK_mid = (F * K) ** ((1 - beta) / 2)
            log_FK = np.log(F / (K + 1e-14))
            z = nu / alpha * FK_mid * log_FK
            x = np.log((np.sqrt(1 - 2 * rho * z + z ** 2) + z - rho)
                       / (1 - rho + 1e-14))
            numer = alpha
            denom = (FK_mid * (1
                     + (1 - beta) ** 2 / 24 * log_FK ** 2
                     + (1 - beta) ** 4 / 1920 * log_FK ** 4))
            factor = z / (x + 1e-14)
            corr = 1 + ((1 - beta) ** 2 / 24 * alpha ** 2 / FK_mid ** 2
                        + rho * beta * nu * alpha / (4 * FK_mid)
                        + (2 - 3 * rho ** 2) / 24 * nu ** 2) * T
            sigma = numer / denom * factor * corr
        return {
            "sabr_implied_vol": max(sigma, 0),
            "model": "SABR",
            "params": {"alpha": alpha, "beta": beta, "rho": rho, "nu": nu},
        }


