# ==============================================================================
# SECTION 1 — CONSTANTS
# ==============================================================================

# --- [5.1] Taxonomy ---
AUTOCORR_TREND_THRESHOLD   = 0.4    # [5.1] высокая autocorrelation → trend follower
FILL_RATE_INSIDER_THRESHOLD = 0.6   # [5.1] цена идёт за ними → insider
BID_ASK_MM_SYMMETRY        = 0.30   # [5.1] ~50/50 ± 30% → MM
BID_ASK_DIRECTIONAL        = 0.80   # [5.1] 80/20 → directional

# --- [5.2] Fingerprinting ---
FRONT_RUN_CONFIDENCE       = 0.80   # [5.2] уверенность > 80% → front-run
PATTERN_CHANGE_THRESHOLD   = 0.30   # [5.2] отклонение > 30% → паттерн изменился
HISTORY_DETECTION_TICKS    = 1000   # [5.2] детектировать изменения в первые 1000 тиков

# --- [5.3] Bot position limits ---
BOT_LIMIT_DETECTION_FRAC   = 0.80   # [5.3] порог детекции 80% от estimated limit

# --- [5.4] Bot timing ---
TIMING_MIN_INTERVALS       = 10     # [5.4] мин. история для надёжной детекции
TIMING_STABLE_CV           = 0.05   # [5.4] std/mean < 5% → hardcoded timing
TIMING_FRONT_RUN_TICKS     = 1      # [5.4] front-run за 1 тик до ожидаемого ордера

# --- [5.6] Volume imbalance ---
VOLUME_IMBALANCE_THRESHOLD = 9      # [5.6] threshold = 9 как baseline

# --- [5.7] Hardcoded patterns ---
PATTERN_DETECTION_WINDOW   = 200    # [5.7] искать паттерн в первые 100–200 тиков
RESIN_TRADE_RANGE          = 3      # [5.7] диапазон торговли 1–3 от константы

# --- [5.8] Crowded trade ---
EDGE_DECAY_THRESHOLD       = 0.50   # [5.8] если edge упал на 50% → перегружен

# --- [5.10] Cold start ---
COLD_START_OBSERVE         = 200    # [5.10] 0–200 тиков только наблюдение
COLD_START_CLASSIFY        = 200    # [5.10] 200+ тиков первичная классификация
COLD_START_ACTIVATE        = 1000   # [5.10] 1000+ тиков подтверждение и активация


# ==============================================================================
# SECTION 2 — ENUMS
# ==============================================================================

class BotType(Enum):
    """[5.1] Таксономия ботов."""
    MARKET_MAKER   = "market_maker"   # [5.1] обе стороны, узкий spread, пассивный
    TREND_FOLLOWER = "trend_follower" # [5.1] покупают после роста, усиливают движение
    MEAN_REVERSION = "mean_reversion" # [5.1] покупают при падении, стабилизируют
    INSIDER        = "insider"        # [5.1] знают будущую цену, всегда правы краткосрочно
    NOISE          = "noise"          # [5.1] случайные ордера без информации
    UNKNOWN        = "unknown"        # [5.1] неопознанный — не торговать против


class PatternType(Enum):
    """[5.7] Типы hardcoded паттернов."""
    SINE       = "sine"       # [5.7] синусоидальный паттерн
    LINEAR     = "linear"     # [5.7] линейный тренд
    STEP       = "step"       # [5.7] ступенчатая функция с шумом
    MEAN_REV   = "mean_rev"   # [5.7] RAINFOREST_RESIN-like — возврат к константе
    NONE       = "none"       # [5.7] нет паттерна → MM с широким спредом


class Strategy_bots(Enum):
    """Стратегия против бота."""
    COPY_IMMEDIATELY  = "copy_immediately"   # [5.1] insider
    FRONT_RUN         = "front_run"          # [5.2] hardcoded
    TRADE_AROUND      = "trade_around"       # [5.1] MM
    LEAD_TREND        = "lead_trend"         # [5.1] trend follower
    FOLLOW_REVERSION  = "follow_reversion"   # [5.1] mean reversion
    LIQUIDITY_ONLY    = "liquidity_only"     # [5.1] noise
    OBSERVE           = "observe"            # [5.10] cold start
    NO_TRADE          = "no_trade"           # [5.1] unknown


# ==============================================================================
# SECTION 3 — STATE DATA CLASSES  [5.9]
# ==============================================================================

@dataclass
class BotTrade:
    """Одна сделка бота."""
    timestamp: int
    price: float
    volume: int
    side: str   # "buy" or "sell"


@dataclass
class BotFingerprint:
    """
    Fingerprint бота.                                            [5.2]
    Характерный размер ордера.                                   [5.2]
    Паттерн ценообразования (bid-1, ask+1 и т.д.).              [5.2]
    Время появления.                                             [5.2]
    Реакция на рыночные условия (активнее при vol > X).         [5.2]
    Baseline для детекции изменений.                             [5.2]
    """
    typical_size: float = 0.0         # [5.2] характерный размер ордера
    price_offset: float = 0.0         # [5.2] паттерн ценообразования (bid-1, ask+1)
    active_period_start: int = 0      # [5.2] время появления — начало
    active_period_end: int = 999999   # [5.2] время появления — конец
    vol_activation_threshold: float = 0.0  # [5.2] активнее при vol > X
    size_std: float = 0.0             # разброс размеров
    # [28] Паттерны агрессивности: доля market orders vs limit orders
    aggression_ratio: float = 0.0      # [28] 1.0 = всегда market (агрессивный), 0 = всегда limit
    # [28] Любимые цены / уровни — конкретные price levels к которым бот возвращается
    favourite_levels: list = None      # [28] favourite price levels (filled by build_fingerprint) список часто используемых price levels
    # [28] Реакция на сделки — как бот реагирует на чужие сделки в стакане
    reaction_to_trades: str = "none"   # [28] "follow" / "fade" / "none"
    # [5.2] Baseline для детекции изменений
    baseline_bid_ask_ratio: float = 0.5
    baseline_avg_interval: float = 0.0
    baseline_tick: int = 0            # когда построен baseline


@dataclass
class BotState:
    """
    Полный state одного бота.                                    [5.9]
    bot_trades: последние N timestamps, prices, volumes, sides.  [5.9]
    Estimated net position.                                      [5.9]
    Timing интервал.                                             [5.9]
    Классификация.                                               [5.9]
    Fingerprint baseline.                                        [5.9]
    Edge метрика (crowded trade detection).                      [5.9]
    """
    bot_id: str
    # [5.9] bot_trades по каждому bot_id
    trades: List[BotTrade] = field(default_factory=list)
    # [5.9] Estimated net position
    estimated_net_position: float = 0.0
    # [5.9] Timing интервал
    timing_intervals: List[float] = field(default_factory=list)
    mean_interval: float = 0.0
    # [5.9] Классификация
    bot_type: BotType = BotType.UNKNOWN
    classification_confidence: float = 0.0
    # [5.9] Fingerprint baseline
    fingerprint: BotFingerprint = field(default_factory=BotFingerprint)
    # [5.9] Edge метрика для crowded trade detection
    edge_history: List[float] = field(default_factory=list)
    current_edge: float = 0.0
    # Вспомогательные
    last_timestamp: int = -1
    estimated_limit: float = 0.0     # [5.3]
    max_observed_position: float = 0.0


@dataclass
class HardcodedPatternState:
    """[5.7] Состояние detekции hardcoded паттернов."""
    pattern_type: PatternType = PatternType.NONE
    # Параметры sine
    sine_amplitude: float = 0.0
    sine_period: float = 0.0
    sine_phase: float = 0.0
    sine_offset: float = 0.0
    # Параметры linear
    linear_slope: float = 0.0
    linear_intercept: float = 0.0
    # Параметры step
    step_levels: List[float] = field(default_factory=list)
    step_duration: float = 0.0
    # [5.7] RAINFOREST_RESIN-like
    mean_rev_constant: float = 0.0
    mean_rev_detected: bool = False
    # Confidence
    pattern_confidence: float = 0.0
    detection_tick: int = 0


@dataclass
class BotsIntelligenceState:
    """
    Главный state — сериализуется в traderData.                  [5.9]
    """
    bots: Dict[str, BotState] = field(default_factory=dict)
    global_tick: int = 0
    # [5.7] Hardcoded pattern per product
    patterns: Dict[str, HardcodedPatternState] = field(default_factory=dict)
    # Volume imbalance calibration per product  [5.6]
    vol_imbalance_thresholds: Dict[str, float] = field(default_factory=dict)

    def get_bot(self, bot_id: str) -> BotState:
        if bot_id not in self.bots:
            self.bots[bot_id] = BotState(bot_id=bot_id)
        return self.bots[bot_id]

    def get_pattern(self, product: str) -> HardcodedPatternState:
        if product not in self.patterns:
            self.patterns[product] = HardcodedPatternState()
        return self.patterns[product]


# ==============================================================================
# SECTION 4 — BOT CLASSIFIER  [5.1]
# ==============================================================================

class BotClassifier:
    """
    Таксономия и классификация ботов.                            [5.1]
    По autocorrelation: высокая → trend follower.                [5.1]
    По fill rate: цена идёт за ними → insider.                  [5.1]
    По симметрии bid/ask: ~50/50 → MM, 80/20 → directional.    [5.1]
    Неопознанный → не торговать против.                         [5.1]
    """

    def classify(self, bot: BotState, price_history: List[float]) -> Tuple[BotType, float]:
        """
        Классифицирует бота по его торговому паттерну.
        Возвращает (BotType, confidence).
        """
        if len(bot.trades) < 5:
            return BotType.UNKNOWN, 0.0

        # [5.1] Симметрия bid/ask
        buys  = sum(1 for t in bot.trades if t.side == "buy")
        sells = sum(1 for t in bot.trades if t.side == "sell")
        total = buys + sells
        bid_ratio = buys / max(1, total)

        if abs(bid_ratio - 0.5) < BID_ASK_MM_SYMMETRY:
            return BotType.MARKET_MAKER, 0.7 + (1 - abs(bid_ratio - 0.5) * 2) * 0.3

        # [5.1] Autocorrelation → trend follower
        autocorr = self._trade_autocorrelation(bot.trades)
        if autocorr > AUTOCORR_TREND_THRESHOLD:
            return BotType.TREND_FOLLOWER, min(1.0, autocorr)
        if autocorr < -AUTOCORR_TREND_THRESHOLD:
            return BotType.MEAN_REVERSION, min(1.0, -autocorr)

        # [5.1] Fill rate: цена идёт за ними → insider
        fill_signal = self._fill_rate_signal(bot.trades, price_history)
        if fill_signal > FILL_RATE_INSIDER_THRESHOLD:
            return BotType.INSIDER, fill_signal

        # [5.1] Random noise — нет паттерна
        if abs(autocorr) < 0.1 and abs(bid_ratio - 0.5) < 0.15:
            return BotType.NOISE, 0.6

        return BotType.UNKNOWN, 0.3

    def _trade_autocorrelation(self, trades: List[BotTrade]) -> float:
        """[5.1] Autocorrelation по направлению сделок."""
        if len(trades) < 4:
            return 0.0
        dirs = [1 if t.side == "buy" else -1 for t in trades[-20:]]
        n = len(dirs)
        if n < 2:
            return 0.0
        mean = sum(dirs) / n
        num = sum((dirs[i] - mean) * (dirs[i-1] - mean) for i in range(1, n))
        den = sum((d - mean)**2 for d in dirs)
        return num / den if den > 0 else 0.0

    def _fill_rate_signal(
        self, trades: List[BotTrade], prices: List[float]
    ) -> float:
        """
        [5.1] Детекция insider: цена идёт за ними после fill.
        Проверяем: после buy → цена выросла, после sell → упала.
        """
        if len(trades) < 5 or len(prices) < 10:
            return 0.0
        correct = 0
        checked = 0
        for t in trades[-20:]:
            # Найти индекс в истории цен близкий к времени сделки
            idx = min(t.timestamp, len(prices) - 2)
            if idx < 0 or idx + 3 >= len(prices):
                continue
            future_move = prices[min(idx + 3, len(prices)-1)] - prices[idx]
            if t.side == "buy" and future_move > 0:
                correct += 1
            elif t.side == "sell" and future_move < 0:
                correct += 1
            checked += 1
        return correct / max(1, checked)

    def get_strategy(self, bot_type: BotType) -> Strategy_bots:
        """[5.1] Стратегия против каждого типа бота."""
        mapping = {
            BotType.MARKET_MAKER:   Strategy_bots.TRADE_AROUND,     # [5.1]
            BotType.TREND_FOLLOWER: Strategy_bots.LEAD_TREND,        # [5.1]
            BotType.MEAN_REVERSION: Strategy_bots.FOLLOW_REVERSION,  # [5.1]
            BotType.INSIDER:        Strategy_bots.COPY_IMMEDIATELY,  # [5.1]
            BotType.NOISE:          Strategy_bots.LIQUIDITY_ONLY,    # [5.1]
            BotType.UNKNOWN:        Strategy_bots.NO_TRADE,          # [5.1] не торговать против
        }
        return mapping[bot_type]


# ==============================================================================
# SECTION 4b — BAYESIAN BOT TRACKER  [bayesian_bot_learning.py inline]
# ==============================================================================

class BayesianBotTracker:
    """
    Minimal Bayesian tracker for a single named bot.
    Maintains a Beta posterior over the bot's trade-size threshold.
    Each observation: if trade size >= threshold guess → success, else failure.
    """

    def __init__(self, name: str = "", threshold_init: float = 10.0):
        self.name = name
        self.threshold = threshold_init
        self._alpha = 1.0   # Beta(alpha, beta) posterior
        self._beta  = 1.0
        self._obs: list = []   # recent (product, price, qty, tick)

    def observe(self, product: str, price: float, qty: int, tick: int) -> None:
        """Record one trade observation; update posterior."""
        self._obs.append((product, price, qty, tick))
        if len(self._obs) > 100:
            self._obs = self._obs[-100:]
        # Success = this qty >= current threshold estimate
        if abs(qty) >= self.threshold:
            self._alpha += 1
        else:
            self._beta += 1
        # Adaptive threshold: posterior mean of threshold
        total = self._alpha + self._beta
        self.threshold = (self.threshold * (total - 1) + abs(qty)) / total

    @property
    def posterior_mean(self) -> float:
        return self._alpha / (self._alpha + self._beta)

    @property
    def confidence(self) -> float:
        """High confidence when many observations agree."""
        n = self._alpha + self._beta - 2
        return min(n / 50.0, 1.0)

    def predict_buy(self) -> bool:
        """Returns True if bot is likely to buy based on posterior."""
        return self.posterior_mean > 0.5

    def __repr__(self) -> str:
        return (f"BayesianBotTracker({self.name!r}, "
                f"threshold={self.threshold:.1f}, "
                f"posterior={self.posterior_mean:.3f})")


# ==============================================================================
# SECTION 5 — FINGERPRINTER  [5.2]
# ==============================================================================

class BotFingerprinter:
    """
    Идентификация и fingerprinting ботов.                        [5.2]
    Характерный размер ордера.                                   [5.2]
    Паттерн ценообразования.                                     [5.2]
    Время появления.                                             [5.2]
    Реакция на vol.                                              [5.2]
    Reverse engineering по логам.                                [5.2]
    Модель следующего ордера: >80% → front-run.                  [5.2]
    Детектор изменений vs baseline.                              [5.2]
    IMC меняет параметры — сброс модели.                         [5.2]
    Детектировать изменения в первые 1000 тиков.                 [5.2]
    Не называть fingerprinting публично в Discord.               [base]
    """

    # Known bots из прошлых раундов  [5.2]
    KNOWN_BOTS = {
        "Rhianna": {                         # [5.2] направленная торговля
            "typical_size": 15,
            "price_offset": 0,
            "type": BotType.INSIDER,
            "strategy": Strategy_bots.COPY_IMMEDIATELY,  # [5.2] копировать немедленно
        },
        "Olivia": {                           # [5.2] аналогичный паттерн
            "typical_size": 10,
            "price_offset": 0,
            "type": BotType.INSIDER,
            "strategy": Strategy_bots.COPY_IMMEDIATELY,
        },
        "Charlie": {                          # [5.2] MM с известными параметрами
            "typical_size": 20,
            "price_offset": 1,               # [5.2] bid-1 / ask+1
            "type": BotType.MARKET_MAKER,
            "strategy": Strategy_bots.FRONT_RUN,  # [5.2] front-run котировки
        },
        "Vladimir": {                         # [5.2] специфичен для продуктов
            "typical_size": 5,
            "price_offset": 0,
            "type": BotType.UNKNOWN,
            "strategy": Strategy_bots.OBSERVE,
        },
        "Pablo": {                            # [5.2] характеристики из прошлых лет
            "typical_size": 8,
            "price_offset": 0,
            "type": BotType.UNKNOWN,
            "strategy": Strategy_bots.OBSERVE,
        },
    }

    def detect_dynamic_insiders(self, trade_history: list, min_trades: int = 20,
                                  directional_threshold: float = 0.75) -> dict:
        """Dynamically find bots with directional trading patterns (potential insiders).
        For each trader: track buy% and win_rate. If buy% > threshold → likely directional.
        Returns dict of {trader_id: {direction, confidence, avg_size}}"""
        trader_stats = {}
        for trade in trade_history:
            tid = trade.get("trader_id") or trade.get("buyer") or trade.get("seller", "unknown")
            side = trade.get("side", "buy")
            price = trade.get("price", 0)
            qty = trade.get("quantity", 1)
            if tid not in trader_stats:
                trader_stats[tid] = {"buys": 0, "sells": 0, "total_qty": 0, "trades": []}
            if side in ("buy", "BUY", 1):
                trader_stats[tid]["buys"] += qty
            else:
                trader_stats[tid]["sells"] += qty
            trader_stats[tid]["total_qty"] += qty
            trader_stats[tid]["trades"].append(trade)

        insiders = {}
        for tid, stats in trader_stats.items():
            total = stats["buys"] + stats["sells"]
            if total < min_trades:
                continue
            buy_ratio = stats["buys"] / total
            if buy_ratio > directional_threshold:
                insiders[tid] = {"direction": "BUY", "confidence": buy_ratio,
                                  "avg_size": stats["total_qty"] / len(stats["trades"])}
            elif buy_ratio < (1 - directional_threshold):
                insiders[tid] = {"direction": "SELL", "confidence": 1 - buy_ratio,
                                  "avg_size": stats["total_qty"] / len(stats["trades"])}
        return insiders

    def get_copy_signal(self, dynamic_insiders: dict, latest_trades: list) -> dict:
        """Copy insider direction with 1-tick delay."""
        signals = {}
        for trade in latest_trades[-5:]:  # last 5 trades
            tid = trade.get("trader_id") or trade.get("buyer") or trade.get("seller", "")
            if tid in dynamic_insiders and dynamic_insiders[tid]["confidence"] > 0.75:
                insider = dynamic_insiders[tid]
                signals[tid] = {
                    "action": insider["direction"],
                    "confidence": insider["confidence"],
                    "size": int(insider["avg_size"])
                }
        return signals

    def build_fingerprint(self, bot: BotState) -> BotFingerprint:
        """
        Строит fingerprint по торговой истории.
        """
        fp = bot.fingerprint
        if len(bot.trades) < 5:
            return fp

        sizes = [t.volume for t in bot.trades]
        # [5.2] Характерный размер ордера
        fp.typical_size = sum(sizes) / len(sizes)
        fp.size_std = _std_full(sizes)

        # [28] Паттерны агрессивности
        # (market order = агрессивный side crossing spread, simplified: volume > mean = agressive)
        mean_vol = fp.typical_size
        aggressive = sum(1 for t in bot.trades if t.volume >= mean_vol * 1.2)
        fp.aggression_ratio = aggressive / max(1, len(bot.trades))  # [28]

        # [28] Любимые цены / уровни — price levels к которым бот часто возвращается
        price_counts: dict = {}
        for t in bot.trades:
            lvl = round(t.price)
            price_counts[lvl] = price_counts.get(lvl, 0) + 1
        threshold_count = max(2, len(bot.trades) * 0.05)
        fp.favourite_levels = sorted(
            [lvl for lvl, cnt in price_counts.items() if cnt >= threshold_count]
        )  # [28]

        # [28] Реакция на сделки — follow / fade / none
        # Follow: после роста цены бот покупает; fade: после роста продаёт
        if len(bot.trades) >= 6:
            follow_count = 0
            fade_count = 0
            for i in range(1, len(bot.trades)):
                price_move = bot.trades[i].price - bot.trades[i-1].price
                if price_move > 0 and bot.trades[i].side == "buy":
                    follow_count += 1
                elif price_move > 0 and bot.trades[i].side == "sell":
                    fade_count += 1
            if follow_count > fade_count * 1.5:
                fp.reaction_to_trades = "follow"   # [28]
            elif fade_count > follow_count * 1.5:
                fp.reaction_to_trades = "fade"     # [28]
            else:
                fp.reaction_to_trades = "none"

        # [5.2] Паттерн ценообразования
        prices = [t.price for t in bot.trades]
        if len(prices) >= 2:
            diffs = [prices[i] - prices[i-1] for i in range(1, len(prices))]
            fp.price_offset = sum(diffs) / len(diffs)

        # [5.2] Время появления (active period)
        if bot.trades:
            fp.active_period_start = min(t.timestamp for t in bot.trades)
            fp.active_period_end   = max(t.timestamp for t in bot.trades)

        # [5.2] Baseline для детекции изменений
        buys  = sum(1 for t in bot.trades if t.side == "buy")
        fp.baseline_bid_ask_ratio = buys / max(1, len(bot.trades))

        if bot.timing_intervals:
            fp.baseline_avg_interval = sum(bot.timing_intervals) / len(bot.timing_intervals)

        return fp

    def identify_known_bot(self, size: int, timestamp: int) -> Optional[str]:
        """
        [5.2] Идентификация по характерному размеру + паттерну.
        [5.5] Идентификация bot_id: по характерному размеру + паттерну ценообразования.
        """
        for name, profile in self.KNOWN_BOTS.items():
            expected = profile["typical_size"]
            if abs(size - expected) <= max(2, expected * 0.15):
                return name
        return None

    def detect_pattern_change(self, bot: BotState, current_tick: int) -> bool:
        """
        [5.2] Детектор изменений: сравнивать текущий паттерн с baseline.
        [5.2] Детектировать изменения в первые 1000 тиков раунда.
        [5.2] Если паттерн изменился → сбросить модель.
        """
        fp = bot.fingerprint
        if fp.baseline_tick == 0 or len(bot.trades) < 10:
            return False

        # Сравниваем текущее с baseline
        recent = bot.trades[-20:]
        recent_sizes = [t.volume for t in recent]
        current_avg_size = sum(recent_sizes) / len(recent_sizes)

        # [5.2] Отклонение > 30% → паттерн изменился
        if fp.typical_size > 0:
            size_deviation = abs(current_avg_size - fp.typical_size) / fp.typical_size
            if size_deviation > PATTERN_CHANGE_THRESHOLD:
                return True

        # Проверяем bid/ask ratio
        recent_buys = sum(1 for t in recent if t.side == "buy")
        current_ratio = recent_buys / max(1, len(recent))
        if abs(current_ratio - fp.baseline_bid_ask_ratio) > 0.30:
            return True

        return False

    def reset_model(self, bot: BotState) -> None:
        """
        [5.2] Если паттерн бота изменился → сбросить модель, начать детекцию заново.
        [5.2] Если паттерн не совпал → не торговать до переобучения.
        """
        bot.bot_type = BotType.UNKNOWN
        bot.classification_confidence = 0.0
        bot.fingerprint = BotFingerprint()
        bot.timing_intervals = []
        bot.mean_interval = 0.0

    def predict_next_order(
        self, bot: BotState, current_tick: int
    ) -> Tuple[float, Optional[str]]:
        """
        [5.2] Модель следующего ордера бота.
        Если уверенность > 80% → front-run.
        Возвращает (confidence, predicted_side).
        """
        if len(bot.trades) < TIMING_MIN_INTERVALS:
            return 0.0, None

        # Timing prediction
        timing_conf = self._timing_confidence(bot, current_tick)

        # Direction prediction из паттерна
        if bot.bot_type == BotType.INSIDER:
            # [5.2] Rhianna: агрессивно берёт bid → вниз, ask → вверх
            recent_side = bot.trades[-1].side if bot.trades else None
            direction_conf = 0.85 if recent_side else 0.0
            confidence = min(timing_conf * 0.5 + direction_conf * 0.5, 1.0)
            return confidence, recent_side

        if bot.bot_type == BotType.TREND_FOLLOWER:
            recent_sides = [t.side for t in bot.trades[-5:]]
            dominant = max(set(recent_sides), key=recent_sides.count) if recent_sides else None
            conf = recent_sides.count(dominant) / len(recent_sides) if recent_sides else 0
            return conf * timing_conf, dominant

        return timing_conf * 0.5, None

    def _timing_confidence(self, bot: BotState, current_tick: int) -> float:
        """Confidence из timing паттерна."""
        if not bot.timing_intervals or bot.mean_interval <= 0:
            return 0.0
        std = _std_full(bot.timing_intervals)
        cv = std / bot.mean_interval  # coefficient of variation
        # [5.4] std/mean < 5% → hardcoded timing, высокая уверенность
        if cv < TIMING_STABLE_CV:
            return 0.95
        if cv < 0.2:
            return 0.7
        return 0.3

    def load_historical_patterns(self, bot_id: str, state: BotsIntelligenceState) -> None:
        """
        [5.2] Собрать логи прошлых лет из GitHub repos.
        [5.10] Сравнение с историческими паттернами с первого тика.
        Загружает известные параметры для известных ботов.
        """
        if bot_id in self.KNOWN_BOTS:
            profile = self.KNOWN_BOTS[bot_id]
            bot = state.get_bot(bot_id)
            bot.fingerprint.typical_size = profile["typical_size"]
            bot.fingerprint.price_offset  = profile["price_offset"]
            bot.bot_type = profile["type"]


# ==============================================================================
# SECTION 6 — BOT POSITION TRACKER  [5.3]
# ==============================================================================

class BotPositionTracker:
    """
    Отслеживание позиций ботов.                                  [5.3]
    Боты тоже имеют position limits.                             [5.3]
    При достижении лимита бот меняет поведение.                 [5.3]
    Estimated net position каждого бота.                         [5.3]
    Метод оценки лимита: макс. накопленный объём за прошлые.    [5.3]
    Порог детекции: 80% от estimated limit.                      [5.3]
    Позиция сбрасывается между раундами.                         [5.3]
    Вынужденный разворот → предсказуемый price impact.          [5.3]
    """

    def update_position(self, bot: BotState, trade: BotTrade) -> None:
        """Обновляет estimated net position бота."""
        delta = trade.volume if trade.side == "buy" else -trade.volume
        bot.estimated_net_position += delta

        # [5.3] Отслеживать максимальный накопленный объём
        abs_pos = abs(bot.estimated_net_position)
        if abs_pos > bot.max_observed_position:
            bot.max_observed_position = abs_pos
            # [5.3] Метод оценки лимита по историческому максимуму
            bot.estimated_limit = abs_pos * 1.2  # +20% buffer

    def is_near_limit(self, bot: BotState) -> bool:
        """
        [5.3] Порог детекции: 80% от estimated limit.
        """
        if bot.estimated_limit <= 0:
            return False
        return abs(bot.estimated_net_position) >= bot.estimated_limit * BOT_LIMIT_DETECTION_FRAC

    def predict_forced_reversal(self, bot: BotState) -> Optional[str]:
        """
        [5.3] Если бот близко к лимиту → вынужден разворачиваться.
        [5.3] Торговать в направлении вынужденного разворота.
        """
        if not self.is_near_limit(bot):
            return None
        # Если позиция длинная → бот будет продавать
        if bot.estimated_net_position > 0:
            return "sell"  # [5.3] торгуем тоже в продажу
        return "buy"

    def reset_between_rounds(self, bot: BotState) -> None:
        """
        [5.3] Позиция бота сбрасывается между раундами.
        Учитывать при инициализации.
        """
        bot.estimated_net_position = 0.0
        # Сохраняем historical max для оценки лимита


# ==============================================================================
# SECTION 7 — BOT TIMING ENGINE  [5.4]
# ==============================================================================

class BotTimingEngine:
    """
    Timing анализ ботов.                                         [5.4]
    Отслеживать timestamps ордеров.                             [5.4]
    Мин. история: 10 интервалов.                                [5.4]
    Вычислить средний интервал.                                  [5.4]
    std/mean < 5% → hardcoded timing.                           [5.4]
    Front-run за 1 тик до ожидаемого ордера.                    [5.4]
    Нестабильный → бот адаптивный, не использовать.            [5.4]
    """

    def record_timestamp(self, bot: BotState, timestamp: int) -> None:
        """Записывает временну́ю метку ордера бота."""
        if bot.last_timestamp >= 0:
            interval = timestamp - bot.last_timestamp
            if interval > 0:
                bot.timing_intervals.append(float(interval))
        bot.last_timestamp = timestamp

        # Обновляем средний интервал
        if bot.timing_intervals:
            bot.mean_interval = sum(bot.timing_intervals) / len(bot.timing_intervals)

    def is_hardcoded_timing(self, bot: BotState) -> bool:
        """
        [5.4] Если std / mean < 5% → hardcoded timing.
        Минимум 10 интервалов для надёжной детекции.            [5.4]
        """
        if len(bot.timing_intervals) < TIMING_MIN_INTERVALS:
            return False
        if bot.mean_interval <= 0:
            return False
        std = _std_full(bot.timing_intervals)
        cv = std / bot.mean_interval
        return cv < TIMING_STABLE_CV

    def is_adaptive_timing(self, bot: BotState) -> bool:
        """
        [5.4] Нестабильный интервал → бот адаптивный, не использовать timing.
        """
        if len(bot.timing_intervals) < TIMING_MIN_INTERVALS:
            return False
        if bot.mean_interval <= 0:
            return True
        std = _std_full(bot.timing_intervals)
        cv = std / bot.mean_interval
        return cv >= 0.20

    def next_expected_tick(self, bot: BotState, current_tick: int) -> Optional[int]:
        """
        [5.4] Предсказывает следующий тик бота.
        """
        if not self.is_hardcoded_timing(bot):
            return None
        if bot.last_timestamp < 0:
            return None
        return bot.last_timestamp + int(bot.mean_interval)

    def should_front_run(self, bot: BotState, current_tick: int) -> bool:
        """
        [5.4] Front-run: поставить ордер за 1 тик до следующего ожидаемого ордера.
        """
        next_tick = self.next_expected_tick(bot, current_tick)
        if next_tick is None:
            return False
        return abs(current_tick - (next_tick - TIMING_FRONT_RUN_TICKS)) <= 1


# ==============================================================================
# SECTION 8 — MULTI-BOT INTERACTION  [5.5]
# ==============================================================================

class MultiBotInteraction:
    """
    Multi-bot interaction.                                       [5.5]
    bot_A bid, bot_B ask → посередине.                          [5.5]
    Прибыль = spread между ними.                                [5.5]
    Риск: один из ботов инсайдер → потери.                      [5.5]
    Если один бот исчезает → выйти из позиции.                 [5.5]
    Идентификация bot_id по размеру + паттерну ценообразования.[5.5]
    """

    def find_sandwich_opportunity(
        self,
        book_bids: Dict[str, Tuple[float, int]],  # bot_id → (price, size)
        book_asks: Dict[str, Tuple[float, int]],
        state: BotsIntelligenceState,
    ) -> Optional[Dict]:
        """
        [5.5] Если bot_A всегда на bid, bot_B на ask → встать посередине.
        Прибыль = spread между ними per round trip.
        """
        if not book_bids or not book_asks:
            return None

        best_bid_bot = max(book_bids, key=lambda k: book_bids[k][0])
        best_ask_bot = min(book_asks, key=lambda k: book_asks[k][0])

        if best_bid_bot == best_ask_bot:
            return None

        best_bid_price = book_bids[best_bid_bot][0]
        best_ask_price = book_asks[best_ask_bot][0]
        spread = best_ask_price - best_bid_price

        if spread <= 0:
            return None

        # [5.5] Риск: если один из ботов инсайдер → потери
        bid_bot_state = state.bots.get(best_bid_bot)
        ask_bot_state = state.bots.get(best_ask_bot)
        has_insider_risk = (
            (bid_bot_state and bid_bot_state.bot_type == BotType.INSIDER) or
            (ask_bot_state and ask_bot_state.bot_type == BotType.INSIDER)
        )

        mid_price = (best_bid_price + best_ask_price) / 2.0
        return {
            "bid_bot":       best_bid_bot,
            "ask_bot":       best_ask_bot,
            "mid_price":     mid_price,
            "spread":        spread,
            "insider_risk":  has_insider_risk,  # [5.5]
            "profit_per_rt": spread,
        }

    def should_exit_position(
        self,
        active_bid_bot: str,
        active_ask_bot: str,
        current_book_bids: Dict[str, float],
        current_book_asks: Dict[str, float],
    ) -> bool:
        """
        [5.5] Если один бот исчезает из книги → выйти из позиции посередине.
        """
        bid_present = active_bid_bot in current_book_bids
        ask_present = active_ask_bot in current_book_asks
        return not bid_present or not ask_present


# ==============================================================================
# SECTION 9 — VOLUME IMBALANCE SIGNAL  [5.6]
# ==============================================================================

class VolumeImbalanceSignal:
    """
    Volume imbalance signal.                                     [5.6]
    best_bid_volume > threshold → sell.                         [5.6]
    best_ask_volume > threshold → buy.                          [5.6]
    Threshold = 9 baseline, калибровать по раунду.              [5.6]
    Не универсальный — проверять применимость к продукту.      [5.6]
    """

    def get_signal(
        self,
        best_bid_volume: int,
        best_ask_volume: int,
        product: str,
        state: BotsIntelligenceState,
    ) -> Optional[str]:
        """
        [5.6] Возвращает "buy", "sell" или None.
        """
        threshold = state.vol_imbalance_thresholds.get(product, VOLUME_IMBALANCE_THRESHOLD)

        # [5.6] best_bid_volume > threshold → sell по best_ask сейчас
        if best_bid_volume > threshold:
            return "sell"

        # [5.6] best_ask_volume > threshold → buy по best_bid сейчас
        if best_ask_volume > threshold:
            return "buy"

        return None

    def calibrate_threshold(
        self,
        product: str,
        volume_history: List[int],
        state: BotsIntelligenceState,
    ) -> float:
        """
        [5.6] Калибровать threshold по данным конкретного раунда.
        """
        if not volume_history:
            return VOLUME_IMBALANCE_THRESHOLD
        # 75-й перцентиль как порог
        sorted_vols = sorted(volume_history)
        idx = int(len(sorted_vols) * 0.75)
        threshold = sorted_vols[idx]
        # [5.6] Не универсальный сигнал
        state.vol_imbalance_thresholds[product] = threshold
        return threshold


# ==============================================================================
# SECTION 10 — HARDCODED PATTERN DETECTOR  [5.7]
# ==============================================================================

class HardcodedPatternDetector:
    """
    Детекция hardcoded паттернов.                                [5.7]
    Искать в первые 100–200 тиков.                              [5.7]
    Проверить на синусоидальный паттерн.                        [5.7]
    Проверить на линейный тренд.                                 [5.7]
    Проверить на ступенчатую функцию с шумом.                   [5.7]
    RAINFOREST_RESIN-like: возврат к константе.                  [5.7]
    Если нет паттерна → MM с широким спредом.                   [5.7]
    Поймать хотя бы один скрытый паттерн в любом раунде.       [5.7]
    Fundamental value часто задана явно в условиях.             [5.7]
    Front-run: ставить ордер на 1 тик лучше до бота.           [5.7]
    Построить histogram (price, vol, timestamp) → паттерны.    [5.2]
    """

    def detect(
        self,
        prices: List[float],
        product: str,
        state: BotsIntelligenceState,
    ) -> HardcodedPatternState:
        """
        Запускает все детекторы паттернов.
        [5.7] Если паттерн найден → использовать напрямую без ML.
        """
        ps = state.get_pattern(product)
        n = len(prices)

        # Детектировать только в первые 100–200 тиков  [5.7]
        if n < 10:
            return ps

        # [5.7] RAINFOREST_RESIN-like: возврат к константе
        mean_rev = self._detect_mean_reversion(prices)
        if mean_rev is not None:
            ps.pattern_type    = PatternType.MEAN_REV
            ps.mean_rev_constant = mean_rev
            ps.mean_rev_detected = True
            ps.pattern_confidence = 0.9
            ps.detection_tick = n
            return ps

        # [5.7] Синусоидальный паттерн
        sine_params = self._detect_sine(prices)
        if sine_params and sine_params[4] > 0.7:
            ps.pattern_type     = PatternType.SINE
            ps.sine_amplitude   = sine_params[0]
            ps.sine_period      = sine_params[1]
            ps.sine_phase       = sine_params[2]
            ps.sine_offset      = sine_params[3]
            ps.pattern_confidence = sine_params[4]
            ps.detection_tick  = n
            return ps

        # [5.7] Линейный тренд
        lin_params = self._detect_linear(prices)
        if lin_params and abs(lin_params[2]) > 0.85:
            ps.pattern_type      = PatternType.LINEAR
            ps.linear_slope      = lin_params[0]
            ps.linear_intercept  = lin_params[1]
            ps.pattern_confidence = abs(lin_params[2])
            ps.detection_tick   = n
            return ps

        # [5.7] Ступенчатая функция
        step_params = self._detect_step(prices)
        if step_params and step_params[2] > 0.7:
            ps.pattern_type      = PatternType.STEP
            ps.step_levels       = step_params[0]
            ps.step_duration     = step_params[1]
            ps.pattern_confidence = step_params[2]
            ps.detection_tick   = n
            return ps

        # [5.7] Нет паттерна → MM с широким спредом
        ps.pattern_type = PatternType.NONE
        return ps

    def _detect_mean_reversion(self, prices: List[float]) -> Optional[float]:
        """
        [5.7] RAINFOREST_RESIN-like: цена всегда возвращается к константе.
        Стратегия: покупать ниже, продавать выше.
        Диапазон: узкий (1–3 от константы).
        """
        if len(prices) < 20:
            return None
        mean = sum(prices) / len(prices)
        deviations = [abs(p - mean) for p in prices]
        avg_dev = sum(deviations) / len(deviations)
        max_dev = max(deviations)
        # Если большинство цен в диапазоне 1–3 от среднего → mean reversion
        if avg_dev < RESIN_TRADE_RANGE * 2 and max_dev < RESIN_TRADE_RANGE * 6:
            return round(mean)
        return None

    def _detect_sine(
        self, prices: List[float]
    ) -> Optional[Tuple[float, float, float, float, float]]:
        """
        [5.7] Проверить на синусоидальный паттерн.
        Возвращает (amplitude, period, phase, offset, confidence).
        """
        if len(prices) < 20:
            return None
        offset = sum(prices) / len(prices)
        centered = [p - offset for p in prices]
        amplitude = max(abs(p) for p in centered) if centered else 0

        if amplitude < 0.5:
            return None

        # Простая оценка периода через zero-crossings
        crossings = []
        for i in range(1, len(centered)):
            if centered[i-1] * centered[i] < 0:
                crossings.append(i)
        if len(crossings) < 2:
            return None
        period = 2.0 * sum(crossings[i] - crossings[i-1]
                          for i in range(1, len(crossings))) / max(1, len(crossings) - 1)
        phase = 0.0

        # Confidence: насколько хорошо sine fit
        n = len(prices)
        if period <= 0:
            return None
        predicted = [amplitude * math.sin(2 * math.pi * i / period + phase) + offset
                     for i in range(n)]
        ss_res = sum((prices[i] - predicted[i])**2 for i in range(n))
        ss_tot = sum((prices[i] - offset)**2 for i in range(n))
        r2 = 1 - ss_res / max(1e-8, ss_tot)
        return amplitude, period, phase, offset, max(0.0, r2)

    def _detect_linear(
        self, prices: List[float]
    ) -> Optional[Tuple[float, float, float]]:
        """
        [5.7] Проверить на линейный тренд.
        Возвращает (slope, intercept, r²).
        """
        n = len(prices)
        if n < 5:
            return None
        x = list(range(n))
        x_mean = (n - 1) / 2.0
        y_mean = sum(prices) / n
        num = sum((x[i] - x_mean) * (prices[i] - y_mean) for i in range(n))
        den = sum((xi - x_mean)**2 for xi in x)
        if den == 0:
            return None
        slope = num / den
        intercept = y_mean - slope * x_mean
        predicted = [slope * xi + intercept for xi in x]
        ss_res = sum((prices[i] - predicted[i])**2 for i in range(n))
        ss_tot = sum((prices[i] - y_mean)**2 for i in range(n))
        r2 = 1 - ss_res / max(1e-8, ss_tot)
        return slope, intercept, r2

    def _detect_step(
        self, prices: List[float]
    ) -> Optional[Tuple[List[float], float, float]]:
        """
        [5.7] Проверить на ступенчатую функцию с шумом.
        Возвращает (levels, avg_duration, confidence).
        """
        if len(prices) < 20:
            return None
        # Упрощённый детектор: ищем кластеры цен
        sorted_prices = sorted(set(round(p) for p in prices))
        if len(sorted_prices) < 2:
            return None

        # Ищем значимые уровни (встречаются > 5% времени)
        n = len(prices)
        levels = []
        for level in sorted_prices:
            count = sum(1 for p in prices if abs(p - level) <= 1.5)
            if count / n > 0.05:
                levels.append(float(level))

        if len(levels) < 2:
            return None

        # Средняя длительность шага
        changes = sum(1 for i in range(1, n) if abs(prices[i] - prices[i-1]) > 1.5)
        avg_duration = n / max(1, changes)
        confidence = min(1.0, len(levels) / 5.0 * 0.5 + 0.5)
        return levels, avg_duration, confidence

    def predict_price(
        self, ps: HardcodedPatternState, tick: int
    ) -> Optional[float]:
        """
        [5.7] Если паттерн найден → использовать напрямую без ML.
        """
        if ps.pattern_type == PatternType.MEAN_REV:
            return ps.mean_rev_constant  # [5.7] RESIN-like константа

        if ps.pattern_type == PatternType.SINE:
            if ps.sine_period <= 0:
                return None
            return (ps.sine_amplitude * math.sin(
                2 * math.pi * tick / ps.sine_period + ps.sine_phase
            ) + ps.sine_offset)

        if ps.pattern_type == PatternType.LINEAR:
            return ps.linear_slope * tick + ps.linear_intercept

        return None

    def get_resin_orders(
        self,
        ps: HardcodedPatternState,
        current_price: float,
        position: int,
        limit: int,
    ) -> List[Tuple[str, float, int]]:
        """
        [5.7] RAINFOREST_RESIN-like стратегия.
        Покупать ниже константы, продавать выше.
        Диапазон: узкий (1–3 от константы).
        Очень высокий Sharpe, низкий риск.
        """
        if not ps.mean_rev_detected:
            return []
        fv = ps.mean_rev_constant
        orders = []
        capacity = limit - abs(position)

        # [5.7] Покупать ниже константы
        if current_price < fv - 0.5 and position < limit:
            buy_price = current_price
            qty = min(capacity, limit // 4)
            if qty > 0:
                orders.append(("buy", buy_price, qty))

        # [5.7] Продавать выше константы
        if current_price > fv + 0.5 and position > -limit:
            sell_price = current_price
            qty = min(capacity, limit // 4)
            if qty > 0:
                orders.append(("sell", sell_price, qty))

        return orders


# ==============================================================================
# SECTION 11 — CROWDED TRADE PROTECTION  [5.8]
# ==============================================================================

class CrowdedTradeProtector:
    """
    Crowded trade protection.                                    [5.8]
    Сигнал известен всем → front-run не работает.               [5.8]
    Мониторить edge: если падает → перегружен.                  [5.8]
    Реакция: уменьшить sizing.                                   [5.8]
    Реакция: искать другой edge.                                 [5.8]
    """

    def record_edge(self, bot: BotState, edge: float) -> None:
        """[5.8] Записывает edge метрику по bot-сигналу."""
        bot.edge_history.append(edge)
        if len(bot.edge_history) > 100:
            bot.edge_history = bot.edge_history[-100:]
        bot.current_edge = edge

    def is_crowded(self, bot: BotState) -> bool:
        """
        [5.8] Если edge падает после 1–2 дней → сигнал перегружен.
        Мониторить edge по сигналу.
        """
        if len(bot.edge_history) < 20:
            return False
        recent  = sum(bot.edge_history[-10:]) / 10
        earlier = sum(bot.edge_history[-20:-10]) / 10
        if earlier <= 0:
            return False
        # [5.8] Edge упал на EDGE_DECAY_THRESHOLD
        decay = (earlier - recent) / earlier
        return decay > EDGE_DECAY_THRESHOLD

    def adjust_sizing(self, base_size: int, bot: BotState) -> int:
        """
        [5.8] Реакция: уменьшить sizing при crowded trade.
        """
        if self.is_crowded(bot):
            return max(1, base_size // 2)
        return base_size

    def needs_new_edge(self, bot: BotState) -> bool:
        """
        [5.8] Реакция: искать другой edge.
        """
        return self.is_crowded(bot)


# ==============================================================================
# SECTION 12 — COLD START CONTROLLER  [5.10]
# ==============================================================================

class ColdStartController:
    """
    Bot detection cold start.                                    [5.10]
    0–200 тиков: только наблюдение.                             [5.10]
    200+ тиков: первичная классификация.                        [5.10]
    1000+ тиков: подтверждение и активация стратегий.           [5.10]
    Сравнение с историческими паттернами с первого тика.        [5.10]
    """

    def get_phase(self, tick: int) -> str:
        """Возвращает текущую фазу cold start."""
        if tick < COLD_START_OBSERVE:
            return "observe"       # [5.10] только наблюдение
        if tick < COLD_START_ACTIVATE:
            return "classify"      # [5.10] первичная классификация
        return "active"            # [5.10] подтверждение и активация

    def can_trade_bot_signal(self, tick: int, bot: BotState) -> bool:
        """
        [5.10] Разрешает торговлю по bot-сигналам только после cold start.
        Историческое сравнение разрешено с первого тика.
        """
        phase = self.get_phase(tick)
        if phase == "observe":
            return False   # [5.10] первые 200 тиков — только наблюдение
        if phase == "classify":
            # [5.10] Можно только если бот известный из истории
            return bot.bot_type != BotType.UNKNOWN
        return True        # [5.10] после 1000 тиков — полная активация

    def should_load_historical(self, tick: int) -> bool:
        """
        [5.10] Сравнение с историческими паттернами с первого тика.
        """
        return True  # всегда с первого тика


# ==============================================================================
# SECTION 13 — INSIDER SIGNAL HANDLER  [base] / [5.1] / [5.2]
# ==============================================================================

class InsiderSignalHandler:
    """
    Обработка инсайдерских сигналов.                            [base]
    Читать описание персонажей (Olivia, Percy и др.).           [base]
    Каждый персонаж = торговый сигнал определённого типа.      [base]
    Не копировать слепо — понять логику персонажа.             [base]
    Лаг: сигнал может приходить с задержкой.                   [base]
    Rhianna детекция: bid → вниз, ask → вверх.                 [5.2]
    Копировать немедленно без подтверждения.                    [5.2]
    Olivia: аналогичный паттерн, детекция по volume и timing.  [5.2]
    """

    def __init__(self):
        self.signal_lag: Dict[str, int] = {}   # [base] лаг по персонажу

    def interpret_character_signal(
        self,
        character_name: str,
        trade: BotTrade,
        current_price: float,
    ) -> Optional[Tuple[str, float]]:
        """
        [base] Понять логику персонажа, не копировать слепо.
        Возвращает (action, confidence).
        """
        name = character_name.lower()

        # [5.2] Rhianna: агрессивно берёт bid → вниз, берёт ask → вверх
        if "rhianna" in name:
            if trade.side == "buy":
                return "buy", 0.90   # [5.2] берёт ask → цена вверх → копируем
            else:
                return "sell", 0.90  # [5.2] берёт bid → цена вниз → копируем

        # [5.2] Olivia: аналогичный паттерн, детекция по volume и timing
        if "olivia" in name:
            confidence = min(0.85, trade.volume / 20.0)
            action = "buy" if trade.side == "buy" else "sell"
            return action, confidence

        return None

    def account_for_lag(
        self,
        character_name: str,
        signal_tick: int,
        current_tick: int,
    ) -> float:
        """
        [base] Лаг: сигнал может приходить с задержкой → учитывать.
        Возвращает degraded confidence с учётом лага.
        """
        lag = current_tick - signal_tick
        known_lag = self.signal_lag.get(character_name, 0)
        actual_lag = lag - known_lag
        # Уверенность падает со временем
        return max(0.0, 1.0 - actual_lag * 0.1)

    def order_book_pre_signal(self, order_depth, bot_name: str) -> dict:
        """Predict bot action BEFORE it happens using order book signals.

        CRITICAL: market_trades from tick T are only visible at tick T+1.
        To copy a bot, we must predict at tick T what the bot will do at tick T.

        Method: if bot always buys when bid_volume > threshold → detect threshold
        in order book NOW and enter before bot does.

        Returns: {predicted_action, confidence, entry_price}
        """
        if not order_depth.buy_orders or not order_depth.sell_orders:
            return {"predicted_action": "HOLD", "confidence": 0.0}

        best_bid = max(order_depth.buy_orders.keys())
        best_ask = min(order_depth.sell_orders.keys())

        bid_vol = sum(v for v in order_depth.buy_orders.values() if v > 0)
        ask_vol = sum(abs(v) for v in order_depth.sell_orders.values())
        total_vol = bid_vol + ask_vol + 1e-8

        imbalance = (bid_vol - ask_vol) / total_vol  # -1 to +1

        # Bot-specific order book thresholds (calibrate from observations)
        thresholds = self.bot_thresholds.get(bot_name, {})
        buy_threshold = thresholds.get("imbalance_buy", 0.3)
        sell_threshold = thresholds.get("imbalance_sell", -0.3)

        if imbalance > buy_threshold:
            confidence = min(1.0, (imbalance - buy_threshold) / 0.3)
            return {
                "predicted_action": "BUY",
                "confidence": confidence,
                "entry_price": best_ask,  # Enter before bot pushes price up
                "imbalance": imbalance,
                "reasoning": f"Bid volume dominance ({imbalance:.2f} > {buy_threshold})"
            }
        elif imbalance < sell_threshold:
            confidence = min(1.0, (sell_threshold - imbalance) / 0.3)
            return {
                "predicted_action": "SELL",
                "confidence": confidence,
                "entry_price": best_bid,
                "imbalance": imbalance,
                "reasoning": f"Ask volume dominance ({imbalance:.2f} < {sell_threshold})"
            }

        return {"predicted_action": "HOLD", "confidence": 0.0, "imbalance": imbalance}

    def update_bot_threshold(self, bot_name: str, observed_imbalance: float,
                              bot_action: str):
        """Update bot's order book signal threshold from observations."""
        if not hasattr(self, 'bot_thresholds'):
            self.bot_thresholds = {}
        if bot_name not in self.bot_thresholds:
            self.bot_thresholds[bot_name] = {"imbalance_buy": 0.3, "imbalance_sell": -0.3}

        # Simple EMA update of threshold
        alpha = 0.1
        if bot_action == "BUY" and observed_imbalance > 0:
            current = self.bot_thresholds[bot_name]["imbalance_buy"]
            self.bot_thresholds[bot_name]["imbalance_buy"] = (
                alpha * observed_imbalance + (1 - alpha) * current
            )
        elif bot_action == "SELL" and observed_imbalance < 0:
            current = self.bot_thresholds[bot_name]["imbalance_sell"]
            self.bot_thresholds[bot_name]["imbalance_sell"] = (
                alpha * observed_imbalance + (1 - alpha) * current
            )

    def copy_immediately(
        self,
        trade: BotTrade,
        position: int,
        limit: int,
    ) -> List[Tuple[str, float, int]]:
        """
        [5.1] / [5.2] Стратегия против insider: копировать немедленно.
        Rhianna стратегия: копировать немедленно без подтверждения.
        """
        capacity = limit - abs(position)
        if capacity <= 0:
            return []
        qty = min(trade.volume, capacity)
        return [(trade.side, trade.price, qty)]


