# SECTION 14 — MAIN BOT INTELLIGENCE DISPATCHER
# ==============================================================================

class BotIntelligenceDispatcher:
    """
    Главный диспетчер — интегрирует все компоненты.
    Полный цикл: observe → classify → front-run / copy / sandwich.
    """

    def __init__(self):
        self.classifier       = BotClassifier()
        self.fingerprinter    = BotFingerprinter()
        self.pos_tracker      = BotPositionTracker()
        self.timing_engine    = BotTimingEngine()
        self.multi_bot        = MultiBotInteraction()
        self.vol_imbalance    = VolumeImbalanceSignal()
        self.pattern_detector = HardcodedPatternDetector()
        self.crowded_protect  = CrowdedTradeProtector()
        self.cold_start       = ColdStartController()
        self.insider_handler  = InsiderSignalHandler()

    def process_tick(
        self,
        product: str,
        price_history: List[float],
        best_bid: float,
        best_ask: float,
        best_bid_vol: int,
        best_ask_vol: int,
        new_trades: List[Dict],   # [{"bot_id", "price", "volume", "side", "timestamp"}]
        state: BotsIntelligenceState,
        position: int,
        limit: int,
    ) -> Dict:
        """
        Полный тик:
        1. Обновить историю по каждому боту
        2. Cold start контроль
        3. Pattern detection (hardcoded)
        4. Volume imbalance
        5. Per-bot: classify, timing, position, crowded trade
        6. Генерировать сигналы
        """
        state.global_tick += 1
        tick = state.global_tick
        phase = self.cold_start.get_phase(tick)
        orders: List[Tuple[str, float, int]] = []
        signals: List[Dict] = []

        # [5.10] Загрузить исторические паттерны с первого тика
        if tick == 1:
            for bot_id in ["Rhianna", "Olivia", "Charlie", "Vladimir", "Pablo"]:
                self.fingerprinter.load_historical_patterns(bot_id, state)

        # [5.7] Hardcoded pattern detection
        ps = state.get_pattern(product)
        if tick <= PATTERN_DETECTION_WINDOW or ps.pattern_type == PatternType.NONE:
            ps = self.pattern_detector.detect(price_history, product, state)

        # [5.7] RESIN-like стратегия
        if ps.mean_rev_detected and self.cold_start.can_trade_bot_signal(tick, BotState(bot_id="system")):
            mid = (best_bid + best_ask) / 2.0
            resin_orders = self.pattern_detector.get_resin_orders(ps, mid, position, limit)
            orders.extend(resin_orders)

        # [5.6] Volume imbalance signal
        vol_signal = self.vol_imbalance.get_signal(best_bid_vol, best_ask_vol, product, state)
        if vol_signal and phase == "active":
            price = best_ask if vol_signal == "buy" else best_bid
            capacity = limit - abs(position)
            if capacity > 0:
                orders.append((vol_signal, price, min(capacity, 5)))
                signals.append({"type": "volume_imbalance", "side": vol_signal})

        # Process each new trade
        for trade_dict in new_trades:
            bot_id   = trade_dict.get("bot_id", "unknown")
            trade    = BotTrade(
                timestamp=trade_dict.get("timestamp", tick),
                price=trade_dict.get("price", 0.0),
                volume=trade_dict.get("volume", 1),
                side=trade_dict.get("side", "buy"),
            )
            bot = state.get_bot(bot_id)
            bot.trades.append(trade)
            if len(bot.trades) > 500:
                bot.trades = bot.trades[-500:]

            # [5.4] Timing
            self.timing_engine.record_timestamp(bot, trade.timestamp)

            # [5.3] Position tracking
            self.pos_tracker.update_position(bot, trade)

            # [5.2] Fingerprint
            if len(bot.trades) % 10 == 0:
                self.fingerprinter.build_fingerprint(bot)

            # [5.2] Detect pattern change
            if tick <= HISTORY_DETECTION_TICKS:
                if self.fingerprinter.detect_pattern_change(bot, tick):
                    self.fingerprinter.reset_model(bot)  # [5.2] сброс модели

            # [5.1] Classify
            if len(bot.trades) >= 5 and tick >= COLD_START_CLASSIFY:
                bot_type, conf = self.classifier.classify(bot, price_history)
                bot.bot_type = bot_type
                bot.classification_confidence = conf

            # [5.8] Crowded trade
            signal_edge = self._estimate_edge(bot, price_history)
            self.crowded_protect.record_edge(bot, signal_edge)

            if not self.cold_start.can_trade_bot_signal(tick, bot):
                continue

            strategy = self.classifier.get_strategy(bot.bot_type)

            # [5.1] Insider → копировать немедленно
            if strategy == Strategy_bots.COPY_IMMEDIATELY:
                copy_orders = self.insider_handler.copy_immediately(trade, position, limit)
                # [5.8] Adjust sizing для crowded trade
                copy_orders = [
                    (s, p, self.crowded_protect.adjust_sizing(q, bot))
                    for s, p, q in copy_orders
                ]
                orders.extend(copy_orders)
                signals.append({"type": "insider_copy", "bot": bot_id, "side": trade.side})

            # [5.4] Front-run timing
            elif self.timing_engine.should_front_run(bot, tick):
                conf, predicted_side = self.fingerprinter.predict_next_order(bot, tick)
                if conf >= FRONT_RUN_CONFIDENCE and predicted_side:  # [5.2] >80% → front-run
                    capacity = limit - abs(position)
                    if capacity > 0:
                        price = best_ask if predicted_side == "buy" else best_bid
                        qty = self.crowded_protect.adjust_sizing(min(capacity, 10), bot)
                        orders.append((predicted_side, price, qty))
                        signals.append({"type": "front_run", "bot": bot_id, "conf": conf})

            # [5.3] Forced reversal
            forced_dir = self.pos_tracker.predict_forced_reversal(bot)
            if forced_dir:
                capacity = limit - abs(position)
                if capacity > 0:
                    price = best_ask if forced_dir == "buy" else best_bid
                    orders.append((forced_dir, price, min(capacity, 5)))
                    signals.append({"type": "forced_reversal", "bot": bot_id})

        return {
            "phase":   phase,
            "orders":  orders,
            "signals": signals,
            "pattern": ps.pattern_type.value,
            "pattern_conf": ps.pattern_confidence,
            "tick":    tick,
        }

    def _estimate_edge(self, bot: BotState, prices: List[float]) -> float:
        """Простая оценка edge от следования боту."""
        if len(bot.trades) < 5 or len(prices) < 5:
            return 0.0
        correct = 0
        for t in bot.trades[-10:]:
            idx = min(t.timestamp, len(prices) - 2)
            if idx < 0:
                continue
            future = prices[min(idx + 3, len(prices)-1)] - prices[idx]
            if (t.side == "buy" and future > 0) or (t.side == "sell" and future < 0):
                correct += 1
        return correct / 10.0


