def save_bots_state(state: BotsIntelligenceState) -> str:
    """
    Сериализует BotsIntelligenceState в traderData.              [5.9]
    bot_trades: timestamps, prices, volumes, sides.              [5.9]
    Estimated net position.                                      [5.9]
    Timing интервал.                                             [5.9]
    Классификация.                                               [5.9]
    Fingerprint baseline.                                        [5.9]
    Edge метрика.                                                [5.9]
    """
    def bot_to_dict(b: BotState) -> dict:
        return {
            # [5.9] bot_trades
            "trades": [
                {"ts": t.timestamp, "p": t.price, "v": t.volume, "s": t.side}
                for t in b.trades[-100:]
            ],
            # [5.9] estimated net position
            "net_pos":    b.estimated_net_position,
            "max_pos":    b.max_observed_position,
            "est_limit":  b.estimated_limit,
            # [5.9] timing интервал
            "intervals":  b.timing_intervals[-50:],
            "mean_int":   b.mean_interval,
            "last_ts":    b.last_timestamp,
            # [5.9] классификация
            "bot_type":   b.bot_type.value,
            "conf":       b.classification_confidence,
            # [5.9] fingerprint baseline
            "fp_size":    b.fingerprint.typical_size,
            "fp_offset":  b.fingerprint.price_offset,
            "fp_ratio":   b.fingerprint.baseline_bid_ask_ratio,
            "fp_tick":    b.fingerprint.baseline_tick,
            "fp_aggr":    b.fingerprint.aggression_ratio,       # [28]
            "fp_levels":  b.fingerprint.favourite_levels or [], # [28]
            "fp_react":   b.fingerprint.reaction_to_trades,     # [28]
            # [5.9] edge метрика
            "edge_hist":  b.edge_history[-20:],
            "cur_edge":   b.current_edge,
        }

    def pattern_to_dict(ps: HardcodedPatternState) -> dict:
        return {
            "type":       ps.pattern_type.value,
            "amp":        ps.sine_amplitude,
            "period":     ps.sine_period,
            "phase":      ps.sine_phase,
            "offset":     ps.sine_offset,
            "slope":      ps.linear_slope,
            "intercept":  ps.linear_intercept,
            "levels":     ps.step_levels,
            "step_dur":   ps.step_duration,
            "mean_const": ps.mean_rev_constant,
            "mean_det":   ps.mean_rev_detected,
            "conf":       ps.pattern_confidence,
            "det_tick":   ps.detection_tick,
        }

    payload = {
        "global_tick": state.global_tick,
        "bots":     {bid: bot_to_dict(b) for bid, b in state.bots.items()},
        "patterns": {p: pattern_to_dict(ps) for p, ps in state.patterns.items()},
        "vol_thresh": state.vol_imbalance_thresholds,
    }
    return json.dumps(payload)


def load_bots_state(data: str) -> BotsIntelligenceState:
    """Десериализует BotsIntelligenceState из traderData."""
    state = BotsIntelligenceState()
    if not data:
        return state
    try:
        payload = json.loads(data)
    except Exception:
        return state

    state.global_tick = payload.get("global_tick", 0)

    for bid, d in payload.get("bots", {}).items():
        b = BotState(bot_id=bid)
        b.trades = [
            BotTrade(t["ts"], t["p"], t["v"], t["s"])
            for t in d.get("trades", [])
        ]
        b.estimated_net_position = d.get("net_pos", 0.0)
        b.max_observed_position  = d.get("max_pos", 0.0)
        b.estimated_limit        = d.get("est_limit", 0.0)
        b.timing_intervals       = d.get("intervals", [])
        b.mean_interval          = d.get("mean_int", 0.0)
        b.last_timestamp         = d.get("last_ts", -1)
        try:
            b.bot_type = BotType(d.get("bot_type", "unknown"))
        except ValueError:
            b.bot_type = BotType.UNKNOWN
        b.classification_confidence  = d.get("conf", 0.0)
        b.fingerprint.typical_size   = d.get("fp_size", 0.0)
        b.fingerprint.price_offset   = d.get("fp_offset", 0.0)
        b.fingerprint.baseline_bid_ask_ratio = d.get("fp_ratio", 0.5)
        b.fingerprint.baseline_tick          = d.get("fp_tick", 0)
        b.fingerprint.aggression_ratio       = d.get("fp_aggr", 0.0)    # [28]
        b.fingerprint.favourite_levels       = d.get("fp_levels", [])   # [28]
        b.fingerprint.reaction_to_trades     = d.get("fp_react", "none") # [28]
        b.edge_history               = d.get("edge_hist", [])
        b.current_edge               = d.get("cur_edge", 0.0)
        state.bots[bid] = b

    for p, d in payload.get("patterns", {}).items():
        ps = HardcodedPatternState()
        try:
            ps.pattern_type = PatternType(d.get("type", "none"))
        except ValueError:
            ps.pattern_type = PatternType.NONE
        ps.sine_amplitude  = d.get("amp", 0.0)
        ps.sine_period     = d.get("period", 0.0)
        ps.sine_phase      = d.get("phase", 0.0)
        ps.sine_offset     = d.get("offset", 0.0)
        ps.linear_slope    = d.get("slope", 0.0)
        ps.linear_intercept= d.get("intercept", 0.0)
        ps.step_levels     = d.get("levels", [])
        ps.step_duration   = d.get("step_dur", 0.0)
        ps.mean_rev_constant = d.get("mean_const", 0.0)
        ps.mean_rev_detected = d.get("mean_det", False)
        ps.pattern_confidence = d.get("conf", 0.0)
        ps.detection_tick  = d.get("det_tick", 0)
        state.patterns[p] = ps

    state.vol_imbalance_thresholds = payload.get("vol_thresh", {})
    return state

