    # ─────────────────────────────────────────────────────────────────────
    print("\n" + "=" * 80)
    print("  ВЕРИФИКАЦИЯ — Online Learning 9.1–9.10")
    print("=" * 80)

    section_pass = {}
    for section, desc, status in results:
        symbol = "✅" if "PASS" in status else "❌"
        print(f"  {symbol} [{section}] {desc}")
        section_pass.setdefault(section, []).append("PASS" in status)

    print("\n" + "-" * 80)
    print("  ИТОГ ПО РАЗДЕЛАМ:")
    all_pass = True
    for sec in sorted(section_pass.keys()):
        passes = sum(section_pass[sec])
        total  = len(section_pass[sec])
