EMA_ALPHA_FAST           = 0.183 # Optuna: 0.183 (was 0.35)
EMA_ALPHA_SLOW           = 0.067 # Optuna: 0.067 (was 0.07)

# --- [2.2] Avellaneda-Stoikov ---
AS_GAMMA_DEFAULT         = 0.0262 # Optuna: 0.0262 (was 0.05)
AS_GAMMA_MIN             = 0.01
AS_GAMMA_MAX             = 0.10
AS_VOL_LOOKBACK          = 100   # [2.2] σ: realized volatility rolling 100 тиков

# --- [2.2] Kalman Filter ---
KALMAN_Q_DEFAULT         = 0.0729 # Optuna: 0.0729 (was 1e-4) — sync with KF_Q
KALMAN_R_DEFAULT         = 0.266  # Optuna: 0.266 (was 1e-2) — sync with KF_R

# --- [2.2] OFI ---
OFI_LOOKBACK             = 20    # [2.2] OFI lookback window для delta volumes
OFI_CAP                  = 500   # [2.2] OFI cap при аномальных объёмах
OFI_BETA_DEFAULT         = 0.024  # Optuna: 0.024 (was 0.01)

# --- [2.2] Adverse selection ---
ADV_SEL_LOOKBACK         = 100   # [2.2] % fills за последние 100 тиков
ADV_SEL_THRESHOLD        = 0.549  # Optuna: 0.549 (was 0.70)

# --- [2.3] Queue ---
QUOTE_REFRESH_TICKS      = 3     # [2.2] optimal quote refresh rate — каждые N тиков


