@dataclass
class KalmanState:
    """
    Kalman Filter state per product.                   [2.4] / [2.2]
    Хранит x_est и P_est в traderData.                [2.4]
    """
    x_est: List[float] = field(default_factory=lambda: [0.0, 0.0])  # [price, velocity]
    P_est: List[List[float]] = field(default_factory=lambda: [[1.0, 0.0], [0.0, 1.0]])
    initialized: bool = False   # [2.2] cold start флаг


@dataclass
class OFIState:
    """OFI rolling window.                             [2.4]"""
    bid_volumes: List[float] = field(default_factory=list)   # [2.4] OFI rolling window
    ask_volumes: List[float] = field(default_factory=list)
    prev_best_bid_vol: float = 0.0
    prev_best_ask_vol: float = 0.0
    ofi_history: List[float] = field(default_factory=list)   # [2.4]
    beta: float = OFI_BETA_DEFAULT                           # [2.2] калиброванный beta


@dataclass
class AdverseSelectionState:
    """
    Adverse selection счётчики.                        [2.4]
    bid_fills и ask_fills за последние 100 тиков.     [2.4]
    """
    bid_fills: List[int] = field(default_factory=list)   # [2.4]
    ask_fills: List[int] = field(default_factory=list)   # [2.4]
    spread_widen_active: bool = False
    skew_active: bool = False


@dataclass
class MMProductState:
    """
    Полный MM state per product — сериализуется в traderData. [2.4]
    """
    # [2.4] Kalman x_est и P_est
    kalman: KalmanState = field(default_factory=KalmanState)
    # [2.4] OFI rolling window
    ofi: OFIState = field(default_factory=OFIState)
    # [2.4] Adverse selection счётчики
    adv_sel: AdverseSelectionState = field(default_factory=AdverseSelectionState)
    # [2.4] Quote refresh счётчик
    quote_refresh_counter: int = 0
    # [2.4] Partial fill остатки с предыдущего тика
    partial_fill_residual: int = 0
    partial_fill_side: str = ""   # "buy" or "sell"
    # EMA values
    ema_fast: float = 0.0
    ema_slow: float = 0.0
    ema_initialized: bool = False
    # Price history for vol calc
    price_history: List[float] = field(default_factory=list)


@dataclass
class MMState:
    """Root state — все продукты."""
    products: Dict[str, MMProductState] = field(default_factory=dict)

    def get_product(self, product: str) -> MMProductState:
        if product not in self.products:
            self.products[product] = MMProductState()
        return self.products[product]


# ==============================================================================
# SECTION 3 — KALMAN FILTER  [2.2]
# ==============================================================================

class KalmanFilter_mm:
    """
    Kalman Filter для fair value оценки.               [2.2]
    State: price + velocity.                           [2.2]
    Observation: midprice.                             [2.2]
    Q (process noise) и R (observation noise).        [2.2]
    Cold start: инициализация x_est и P_est.          [2.2]
    State хранить в traderData.                       [2.2] / [2.4]
    """

    def __init__(self, q: float = KALMAN_Q_DEFAULT, r: float = KALMAN_R_DEFAULT):
        self.Q = q   # [2.2] process noise — калибровать на данных
        self.R = r   # [2.2] observation noise — калибровать на данных
        # Transition matrix F = [[1,1],[0,1]] (price += velocity)
        self.F = [[1.0, 1.0], [0.0, 1.0]]
        # Observation matrix H = [[1, 0]] (observe price only)
        self.H = [1.0, 0.0]
        # Process noise matrix
        self.Q_mat = [[q, 0.0], [0.0, q * 0.1]]

    def _mat_mul(self, A: List[List[float]], B: List[List[float]]) -> List[List[float]]:
        n = len(A)
        m = len(B[0])
        k = len(B)
        return [[sum(A[i][p] * B[p][j] for p in range(k)) for j in range(m)] for i in range(n)]

    def _mat_add(self, A: List[List[float]], B: List[List[float]]) -> List[List[float]]:
        return [[A[i][j] + B[i][j] for j in range(len(A[0]))] for i in range(len(A))]

    def _mat_transpose(self, A: List[List[float]]) -> List[List[float]]:
        return [[A[j][i] for j in range(len(A))] for i in range(len(A[0]))]

    def update(self, ks: KalmanState, observation: float) -> float:
        """
        Один шаг Kalman: predict + update.
        Возвращает оценку fair value (price component).
        Cold start: инициализация на первом тике.     [2.2]
        """
        # [2.2] Kalman cold start
        if not ks.initialized:
            ks.x_est = [observation, 0.0]
            ks.P_est = [[1.0, 0.0], [0.0, 1.0]]
            ks.initialized = True
            return observation

        x = ks.x_est
        P = ks.P_est

        # --- Predict ---
        # x_pred = F @ x
        x_pred = [
            self.F[0][0] * x[0] + self.F[0][1] * x[1],
            self.F[1][0] * x[0] + self.F[1][1] * x[1],
        ]
        # P_pred = F @ P @ F^T + Q
        FP = self._mat_mul(self.F, P)
        FT = self._mat_transpose(self.F)
        FPFt = self._mat_mul(FP, FT)
        P_pred = self._mat_add(FPFt, self.Q_mat)

        # --- Update ---
        # y = observation - H @ x_pred
        y = observation - (self.H[0] * x_pred[0] + self.H[1] * x_pred[1])
        # S = H @ P_pred @ H^T + R
        S = (self.H[0] * P_pred[0][0] * self.H[0]
             + self.H[0] * P_pred[0][1] * self.H[1]
             + self.H[1] * P_pred[1][0] * self.H[0]
             + self.H[1] * P_pred[1][1] * self.H[1]
             + self.R)
        # K = P_pred @ H^T / S
        K = [
            (P_pred[0][0] * self.H[0] + P_pred[0][1] * self.H[1]) / S,
            (P_pred[1][0] * self.H[0] + P_pred[1][1] * self.H[1]) / S,
        ]
        # x_new = x_pred + K * y
        x_new = [x_pred[0] + K[0] * y, x_pred[1] + K[1] * y]
        # P_new = (I - K @ H) @ P_pred
        KH = [[K[i] * self.H[j] for j in range(2)] for i in range(2)]
        I_KH = [[float(i == j) - KH[i][j] for j in range(2)] for i in range(2)]
        P_new = self._mat_mul(I_KH, P_pred)

        # [2.4] Сохранить x_est и P_est в state
        ks.x_est = x_new
        ks.P_est = P_new

        return x_new[0]   # price component = fair value


# ==============================================================================
# SECTION 4 — OFI CALCULATOR  [2.2]
# ==============================================================================

class OFICalculator:
    """
    Order Flow Imbalance сигнал.                       [2.2]
    OFI = delta_bid_volume - delta_ask_volume.         [2.2]
    OFI lookback window.                               [2.2]
    OFI cap при аномальных объёмах.                   [2.2]
    fair_value_adjusted = fair_value + beta × OFI.    [2.2]
    beta калибровать регрессией.                       [2.2]
    Bid-ask bounce фильтрация.                        [2.2]
    """

    def update(
        self,
        ofi_state: OFIState,
        best_bid_vol: float,
        best_ask_vol: float,
        mid_price: float,
    ) -> float:
        """Обновляет OFI и возвращает текущее значение."""
        delta_bid = best_bid_vol - ofi_state.prev_best_bid_vol
        delta_ask = best_ask_vol - ofi_state.prev_best_ask_vol

        # [2.2] OFI = delta_bid_volume - delta_ask_volume
        ofi = delta_bid - delta_ask

        # [2.2] OFI cap при аномальных объёмах — насыщение сигнала
        ofi = max(-OFI_CAP, min(OFI_CAP, ofi))

        # [2.4] OFI rolling window значений
        ofi_state.ofi_history.append(ofi)
        if len(ofi_state.ofi_history) > OFI_LOOKBACK:
            ofi_state.ofi_history = ofi_state.ofi_history[-OFI_LOOKBACK:]

        ofi_state.prev_best_bid_vol = best_bid_vol
        ofi_state.prev_best_ask_vol = best_ask_vol

        return ofi

    def adjust_fair_value(
        self, fair_value: float, ofi: float, ofi_state: OFIState
    ) -> float:
        """
        [2.2] fair_value_adjusted = fair_value + beta × OFI
        OFI > 0 → buy pressure → FV выше mid
        OFI < 0 → sell pressure → FV ниже mid
        """
        return fair_value + ofi_state.beta * ofi

    def calibrate_beta(
        self, ofi_history: List[float], mid_history: List[float]
    ) -> float:
        """
        [2.2] beta калибровать регрессией: next_mid = alpha + beta × OFI
        Простая OLS регрессия.
        """
        n = min(len(ofi_history), len(mid_history) - 1)
        if n < 10:
            return OFI_BETA_DEFAULT
        x = ofi_history[:n]
        y = [mid_history[i + 1] - mid_history[i] for i in range(n)]
        x_mean = sum(x) / n
        y_mean = sum(y) / n
        num = sum((x[i] - x_mean) * (y[i] - y_mean) for i in range(n))
        den = sum((x[i] - x_mean) ** 2 for i in range(n))
        if den == 0:
            return OFI_BETA_DEFAULT
        return num / den

    def filter_bidask_bounce(self, mid_history: List[float]) -> float:
        """
        [2.2] Bid-ask bounce фильтрация.
        midprice прыгает bid→ask→bid — это шум, не сигнал.
        Возвращает сглаженный mid через медиану последних 3 значений.
        """
        if len(mid_history) < 3:
            return mid_history[-1] if mid_history else 0.0
        last3 = sorted(mid_history[-3:])
        return last3[1]  # медиана из 3

    def weighted_ofi(self, order_depth, prev_order_depth=None,
                      levels: int = 3,
                      level_weights: list = None) -> float:
        """[Block D] Order flow imbalance using multiple order book levels.

        Standard OFI uses only level 1. This weights levels 1,2,3 with
        decreasing weights (level 1 most informative).

        Default weights: [0.5, 0.3, 0.2] for levels 1, 2, 3.
        Returns: weighted OFI in [-1, 1].
        """
        if level_weights is None:
            level_weights = [0.5, 0.3, 0.2][:levels]
        # Normalize weights
        total_w = sum(level_weights)
        level_weights = [w / total_w for w in level_weights]

        if not order_depth.buy_orders or not order_depth.sell_orders:
            return 0.0

        bids = sorted(order_depth.buy_orders.items(), reverse=True)
        asks = sorted(order_depth.sell_orders.items())

        total_bid_vol = sum(abs(v) for _, v in order_depth.buy_orders.items()) + 1e-8
        total_ask_vol = sum(abs(v) for _, v in order_depth.sell_orders.items()) + 1e-8

        weighted_imbalance = 0.0
        for lvl in range(min(levels, len(bids), len(asks))):
            bid_vol = abs(bids[lvl][1]) if lvl < len(bids) else 0
            ask_vol = abs(asks[lvl][1]) if lvl < len(asks) else 0
            level_imbalance = (bid_vol - ask_vol) / (bid_vol + ask_vol + 1e-8)
            weighted_imbalance += level_weights[lvl] * level_imbalance

        return weighted_imbalance  # -1 = pure sell pressure, +1 = pure buy pressure

    def ofi_signal(self, order_depth, levels: int = 3, threshold: float = 0.2) -> str:
        """Directional signal from weighted multi-level OFI."""
        ofi = self.weighted_ofi(order_depth, levels=levels)
        if ofi > threshold:
            return "BUY"
        elif ofi < -threshold:
            return "SELL"
        return "NEUTRAL"


# ==============================================================================
# SECTION 5 — ADVERSE SELECTION DETECTOR  [2.2]
# ==============================================================================

class AdverseSelectionDetector_mm:
    """
    Adverse selection детекция и реакция.              [2.2]
    % fills на bid > 70% за 100 тиков → цена вниз.   [2.2]
    Реакция: widen spread, skew котировки.            [2.2]
    """

    def record_fill(
        self,
        adv: AdverseSelectionState,
        side: str,   # "buy" or "sell"
        qty: int,
    ) -> None:
        """Записывает fill в скользящее окно."""
        if side == "buy":
            adv.bid_fills.append(qty)
            adv.ask_fills.append(0)
        else:
            adv.bid_fills.append(0)
            adv.ask_fills.append(qty)
        # Ограничиваем окно 100 тиками [2.4]
        if len(adv.bid_fills) > ADV_SEL_LOOKBACK:
            adv.bid_fills = adv.bid_fills[-ADV_SEL_LOOKBACK:]
            adv.ask_fills = adv.ask_fills[-ADV_SEL_LOOKBACK:]

    def detect(self, adv: AdverseSelectionState) -> Tuple[bool, str]:
        """
        [2.2] Проверяет adverse selection.
        Возвращает (detected, direction) — направление давления.
        """
        total_bid = sum(adv.bid_fills)
        total_ask = sum(adv.ask_fills)
        total = total_bid + total_ask
        if total == 0:
            adv.spread_widen_active = False
            adv.skew_active = False
            return False, "none"

        bid_ratio = total_bid / total
        ask_ratio = total_ask / total

        # [2.2] > 70% fills на bid → цена пойдёт вниз
        if bid_ratio > ADV_SEL_THRESHOLD:
            adv.spread_widen_active = True   # [2.2] widen spread
            adv.skew_active = True           # [2.2] skew котировки
            return True, "down"
        if ask_ratio > ADV_SEL_THRESHOLD:
            adv.spread_widen_active = True
            adv.skew_active = True
            return True, "up"

        adv.spread_widen_active = False
        adv.skew_active = False
        return False, "none"


# ==============================================================================
# SECTION 6 — AVELLANEDA-STOIKOV MODEL  [2.2]
# ==============================================================================

class AvellanedaStoikov:
    """
    Avellaneda-Stoikov optimal MM model.               [2.2]
    reservation_price = mid - q × γ × σ² × T         [2.2]
    optimal_spread = γ × σ² × T + (2/γ)×ln(1+γ/k)   [2.2]
    γ (risk aversion): 0.01–0.1, калибровать.         [2.2]
    k (order arrival intensity): из истории.          [2.2]
    σ: realized volatility rolling 100 тиков.         [2.2]
    T: время до конца сессии в тиках.                 [2.2]
    """

    @staticmethod
    def realized_vol(prices: List[float]) -> float:
        """[2.2] σ: realized volatility rolling 100 тиков."""
        n = len(prices)
        if n < 2:
            return 0.0
        window = prices[-AS_VOL_LOOKBACK:] if n >= AS_VOL_LOOKBACK else prices
        log_rets = []
        for i in range(1, len(window)):
            if window[i - 1] > 0:
                log_rets.append(math.log(window[i] / window[i - 1]))
        if not log_rets:
            return 0.0
        mean = sum(log_rets) / len(log_rets)
        var = sum((r - mean) ** 2 for r in log_rets) / len(log_rets)
        return math.sqrt(var)

    @staticmethod
    def reservation_price(
        mid: float,
        position: int,
        gamma: float,
        sigma: float,
        T: float,
    ) -> float:
        """
        [2.2] reservation_price = mid - q × γ × σ² × T
        q = position (inventory), γ = risk aversion.
        """
        return mid - position * gamma * (sigma ** 2) * T

    @staticmethod
    def optimal_spread(
        gamma: float,
        sigma: float,
        T: float,
        k: float,
    ) -> float:
        """
        [2.2] optimal_spread = γ × σ² × T + (2/γ) × ln(1 + γ/k)
        """
        if k <= 0 or gamma <= 0:
            return MIN_SPREAD
        term1 = gamma * (sigma ** 2) * T
        term2 = (2.0 / gamma) * math.log(1.0 + gamma / k)
        raw = term1 + term2
        return max(MIN_SPREAD, raw)

    @staticmethod
    def calibrate_gamma(price_history: List[float], position_history: List[float]) -> float:
        """
        [2.2] γ калибровать на данных раунда, диапазон 0.01–0.1.
        Эвристика: выше вола → выше γ.
        """
        if len(price_history) < 20:
            return AS_GAMMA_DEFAULT
        prices = price_history[-100:]
        if len(prices) < 2:
            return AS_GAMMA_DEFAULT
        log_rets = [math.log(prices[i] / prices[i-1]) for i in range(1, len(prices)) if prices[i-1] > 0]
        if not log_rets:
            return AS_GAMMA_DEFAULT
        vol = math.sqrt(sum(r**2 for r in log_rets) / len(log_rets))
        gamma = min(AS_GAMMA_MAX, max(AS_GAMMA_MIN, vol * 10))
        return gamma

    @staticmethod
    def estimate_k(trade_sizes: List[float]) -> float:
        """
        [2.2] k (order arrival intensity): из исторической книги ордеров.
        Приближение: средний размер трейда.
        """
        if not trade_sizes:
            return 1.0
        avg = sum(trade_sizes) / len(trade_sizes)
        return max(0.1, avg)


# ==============================================================================
# SECTION 7 — EMA CALCULATOR  [2.2]
# ==============================================================================

class EMACalculator:
    """
    EMA для fair value волатильных активов.            [2.2]
    EMA alpha быстрая: 0.3–0.4.                       [2.2]
    EMA alpha медленная для тренда: 0.05–0.1.         [2.2]
    """

    @staticmethod
    def update(prev_ema: float, price: float, alpha: float) -> float:
        return alpha * price + (1 - alpha) * prev_ema

    @staticmethod
    def initialize(price: float) -> Tuple[float, float]:
        """Инициализация быстрой и медленной EMA."""
        return price, price  # fast, slow

    @staticmethod
    def trend_signal(fast: float, slow: float) -> float:
        """Тренд = разница fast-slow EMA. > 0 = uptrend."""
        if slow == 0:
            return 0.0
        return (fast - slow) / slow


# ==============================================================================
# SECTION 8 — INVENTORY SKEW ENGINE  [11] / [2.1] / [2.2]
# ==============================================================================

class InventorySkewEngine:
    """
    Skew котировок по позиции.                        [11]
    Skew: long позиция → сдвигать quotes вниз.        [11]
    Quote asymmetry: при накопленной позиции.         [11]
    Hard stop: не ставить если позиция близко к лимиту.[11]
    Mean reversion skew через inventory model.        [11]
    inventory_skew = position / position_limit.       [2.1]
    Proactive skew начиная с ±35 из 50.              [2.1]
    Сдвиг bid вниз при длинной позиции.              [2.1]
    Сдвиг ask вниз при длинной позиции.              [2.1]
    Нулевая позиция → симметричные котировки.        [2.1]
    Ненулевая позиция → асимметричные котировки.     [2.1]
    Proactive skew (до лимита) + реактивный (после). [2.2]
    """

    def compute_skew(
        self,
        position: int,
        position_limit: int,
        fair_value: float,
        spread: float,
        skew_threshold: int,
        is_volatile: bool = False,
    ) -> Tuple[float, float, float, float]:
        """
        Возвращает (bid_price, ask_price, bid_size_mult, ask_size_mult).
        """
        # [2.1] inventory_skew = position / position_limit
        inventory_skew = position / max(1, position_limit)

        # --- Базовые котировки [11] ---
        half_spread = spread / 2.0

        # [2.1] Нулевая позиция → симметричные котировки
        if position == 0:
            bid = fair_value - half_spread
            ask = fair_value + half_spread
            return bid, ask, 1.0, 1.0  # симметричные

        # [2.1] Ненулевая позиция → асимметричные котировки
        # [2.1] Proactive skew начиная с ±35 (skew_threshold)
        abs_pos = abs(position)
        proactive = abs_pos >= skew_threshold   # [2.1]
        reactive  = abs_pos >= int(position_limit * 0.6)  # [2.2] реактивный после накопления

        if proactive or reactive:
            # [2.1] Сдвиг bid вниз при длинной позиции
            # [2.1] Сдвиг ask вниз при длинной позиции
            price_shift = inventory_skew * spread * 1.5
            fv_adjusted = fair_value - price_shift  # mean reversion [11]
        else:
            fv_adjusted = fair_value

        bid = fv_adjusted - half_spread
        ask = fv_adjusted + half_spread

        # [11] Quote asymmetry: меньше на одну сторону при накопленной позиции
        if position > 0:   # long → уменьшаем bid размер
            bid_mult = max(0.1, 1.0 - inventory_skew)
            ask_mult = 1.0
        else:               # short → уменьшаем ask размер
            bid_mult = 1.0
            ask_mult = max(0.1, 1.0 + inventory_skew)

        return bid, ask, bid_mult, ask_mult

    def hard_stop(self, position: int, position_limit: int) -> Tuple[bool, bool]:
        """
        [11] Hard stop: не ставить ордера если позиция близко к лимиту.
        Возвращает (block_bid, block_ask).
        """
        frac = abs(position) / max(1, position_limit)
        if frac >= 0.95:
            # Полный стоп
            return True, True
        if position >= position_limit * 0.90:
            return False, True   # не котировать ask (не увеличивать лонг)
        if position <= -position_limit * 0.90:
            return True, False   # не котировать bid (не увеличивать шорт)
        return False, False

    def position_limit_exploit_signal(self, position: int, position_limit: int,
                                       tick: int, price_history: list) -> dict:
        """Detect if we can exploit inventory-sensitive bots by accumulating to limit.

        Mechanic: Inventory-sensitive bots (Avellaneda-Stoikov) shift quotes when
        market appears one-sided. If we accumulate long, they lower asks → we profit.

        Returns: {should_exploit, direction, expected_pnl_per_cycle}
        """
        if len(price_history) < 20 or position_limit == 0:
            return {"should_exploit": False}

        frac = position / position_limit
        abs_frac = abs(frac)

        # Measure recent price drift relative to position
        recent_prices = price_history[-20:]
        price_drift = recent_prices[-1] - recent_prices[0]

        # If we're near limit and price is moving in our favor → bot is responding
        bot_sensitivity = abs(price_drift) / max(abs_frac, 0.1)

        # Expected PnL per cycle: position_limit * bot_sensitivity * 2
        # (buy at fv, bot shifts up, sell at fv + shift)
        expected_pnl = position_limit * min(bot_sensitivity, 2.0) * 2

        # Only exploit if bot_sensitivity is detectable and PnL > threshold
        should_exploit = (abs_frac > 0.5 and bot_sensitivity > 0.3
                          and expected_pnl > position_limit * 0.5)

        return {
            "should_exploit": should_exploit,
            "direction": "long" if frac > 0 else "short",
            "bot_sensitivity": round(bot_sensitivity, 3),
            "expected_pnl_per_cycle": round(expected_pnl, 2),
            "current_frac": round(abs_frac, 3),
            "note": "Test first: accumulate 5 units, measure price shift, extrapolate",
        }

    def soft_liquidation_adjustment(self, position: int, position_limit: int,
                                     bid_price: float, ask_price: float) -> tuple[float, float]:
        """Gradual price shift to close position when near limits.
        When position > 75% of limit → shift quotes to encourage closing."""
        frac = position / position_limit if position_limit != 0 else 0.0
        abs_frac = abs(frac)
        if abs_frac < 0.75:
            return bid_price, ask_price
        # Scale aggressiveness: 75% → shift 1, 90% → shift 3, 95%+ → shift 5
        if abs_frac >= 0.95:
            shift = 5
        elif abs_frac >= 0.90:
            shift = 3
        else:
            shift = 1
        if frac > 0:  # long position → lower ask aggressively to sell
            return bid_price - shift, ask_price - shift
        else:         # short position → raise bid aggressively to buy
            return bid_price + shift, ask_price + shift


# ==============================================================================
# SECTION 9 — SPREAD CALCULATOR  [11] / [2.1] / [2.2]
# ==============================================================================

class SpreadCalculator:
    """
    Динамический спред по волатильности.              [11]
    Минимальный spread = 2.                           [11]
    Расширяется при высокой волатильности.            [11]
    Расширяется при риске adverse selection.          [11]
    Адаптивный spread: расширять если теряешь деньги.[11]
    """

    def compute_spread(
        self,
        base_spread: float,
        sigma: float,
        adv_sel_active: bool,
        gap_risk: bool,
        pnl_negative: bool,    # [11] адаптивный spread
        regime_volatile: bool,
    ) -> float:
        """
        Рассчитывает итоговый spread.
        [11] Минимальный spread = 2.
        [11] Расширяется при волатильности, adverse selection.
        [11] Адаптивный: расширять если теряем деньги.
        """
        spread = base_spread

        # [11] Расширяется при высокой волатильности
        vol_multiplier = 1.0 + max(0.0, sigma * 100 - 1.0)
        spread *= vol_multiplier

        # [11] Расширяется при риске adverse selection
        if adv_sel_active:
            spread *= 1.5   # [2.2] adverse selection реакция: widen spread

        # [2.2] Gap risk защита: уменьшить размер при высокой волатильности
        if gap_risk:
            spread *= 1.3

        # [11] Адаптивный spread: расширять если теряешь деньги на trades
        if pnl_negative:
            spread *= 1.2

        if regime_volatile:
            spread *= 1.25

        # [11] Минимальный spread = 2 (целочисленные цены)
        return max(MIN_SPREAD, round(spread))


# ==============================================================================
# SECTION 10 — QUOTE DISTANCE ENGINE  [2.3]
# ==============================================================================

class QuoteDistanceEngine:
    """
    Queue position и дистанция котировок.             [2.3]
    Stable: котировать на best.                       [2.3]
    Volatile: котировать на best+1 или best+2.        [2.3]
    Если нет edge — не котировать вообще.             [2.3]
    Динамическая смена дистанции по режиму рынка.    [2.3]
    FIFO: при одинаковой цене — приоритет по времени.[2.3]
    Оптимум зависит от скорости изменения book.      [2.3]
    Оптимум зависит от размера trade vs ордера.      [2.3]
    Оптимум зависит от частоты informed trades.      [2.3]
    """

    def get_quote_distance(
        self,
        is_volatile: bool,
        regime_volatile: bool,
        book_speed: float,    # [2.3] скорость изменения book (0..1)
        informed_freq: float, # [2.3] частота informed trades (0..1)
        trade_size_ratio: float,  # [2.3] средний trade / свой ордер
    ) -> int:
        """
        Возвращает дистанцию от best (0 = best, 1 = best+1, 2 = best+2).
        [2.3] На стабильных: best (0).
        [2.3] На волатильных: best+1 (1) или best+2 (2).
        """
        # [2.3] Stable — котировать на best
        if not is_volatile and not regime_volatile:
            return 0

        # [2.3] Оптимум зависит от скорости изменения book
        # Быстро меняется → уходим дальше
        dist = 1  # base для volatile: best+1

        # [2.3] Скорость изменения book
        if book_speed > 0.7:
            dist = 2

        # [2.3] Частота informed trades
        if informed_freq > 0.5:
            dist = min(dist + 1, 2)

        # [2.3] Размер среднего trade vs своего ордера
        if trade_size_ratio > 2.0:
            dist = min(dist + 1, 2)

        return dist

    def has_edge(
        self,
        bid_price: float,
        ask_price: float,
        fair_value: float,
    ) -> Tuple[bool, bool]:
        """
        [2.3] Если нет edge ни на одной дистанции — не котировать.
        Edge на bid: bid < FV.
        Edge на ask: ask > FV.
        """
        edge_bid = bid_price < fair_value
        edge_ask = ask_price > fair_value
        return edge_bid, edge_ask

    def apply_distance(
        self,
        best_bid: float,
        best_ask: float,
        distance: int,
        side: str,  # "bid" or "ask"
    ) -> float:
        """
        Применяет дистанцию от best.
        [2.3] FIFO: при одинаковой цене приоритет по времени — joinим цену.
        """
        if side == "bid":
            return best_bid - distance
        else:
            return best_ask + distance


# ==============================================================================
# SECTION 11 — MARKET MAKER (STABLE)  [2.1]
# ==============================================================================

class StableMarketMaker:
    """
    MM для стабильных активов.                        [2.1]
    Position limit soft: 80% (40 из 50).             [2.1]
    Spread: 1–2 тика.                                [2.1]
    Fair value: известная константа.                 [2.1]
    Источник FV — калибровать по историческим данным.[2.1]
    Тейкерская агрессия первым приоритетом.          [2.1]
    MM котировки вторым приоритетом.                 [2.1]
    Proactive skew начиная с ±35.                    [2.1]
    Locked market (bid=ask) — не торговать.          [2.1]
    Crossed market (bid>ask) — тейкать немедленно.   [2.1]
    Flash spike — не ловить нож без FV.              [2.1]
    """

    def __init__(self, fair_value_constant: float = 10000.0):
        # [2.1] Fair value: известная константа (RESIN ≈ 10000)
        # [2.1] Источник константы — калибровать по историческим данным
        self.fair_value = fair_value_constant
        self.inventory_engine = InventorySkewEngine()
        self.spread_calc = SpreadCalculator()
        self.quote_dist_engine = QuoteDistanceEngine()

    def compute_fair_value(self, historical_mids: List[float]) -> float:
        """[2.1] Калибровать fair value по историческим данным раунда."""
        if not historical_mids:
            return self.fair_value
        return sum(historical_mids) / len(historical_mids)

    def is_locked_market(self, best_bid: float, best_ask: float) -> bool:
        """[2.1] Locked market (bid = ask) — не торговать."""
        return best_bid == best_ask

    def is_crossed_market(self, best_bid: float, best_ask: float) -> bool:
        """[2.1] Crossed market (bid > ask) — тейкать немедленно."""
        return best_bid > best_ask

    def is_flash_spike(
        self,
        current_mid: float,
        price_history: List[float],
        threshold: float = 0.05,
    ) -> bool:
        """
        [2.1] Flash spike — не ловить нож без фундаментального fair value.
        Если цена отклонилась > threshold от FV — считаем spike.
        """
        if not price_history:
            return False
        avg = sum(price_history[-20:]) / min(20, len(price_history))
        if avg == 0:
            return False
        deviation = abs(current_mid - avg) / avg
        return deviation > threshold

    def take_aggressive(
        self,
        best_bid: float,
        best_ask: float,
        position: int,
        limit: int,
    ) -> List[Tuple[str, float, int]]:
        """
        [2.1] Тейкерская агрессия первым приоритетом.
        Съедать всё хуже fair value.
        Возвращает список (side, price, qty).
        """
        orders = []
        fv = self.fair_value
        capacity = limit - abs(position)

        # Если ask ниже FV — покупаем (ask хуже FV для продавца, лучше для нас)
        if best_ask < fv and position < limit:
            qty = min(capacity, limit)
            orders.append(("buy", best_ask, qty))

        # Если bid выше FV — продаём
        if best_bid > fv and position > -limit:
            qty = min(capacity, limit)
            orders.append(("sell", best_bid, qty))

        return orders

    def quote(
        self,
        best_bid: float,
        best_ask: float,
        position: int,
        limit: int,
        sigma: float,
        adv_sel_active: bool,
        pnl_negative: bool,
        state: MMProductState,
        refresh_counter: int,
    ) -> List[Tuple[str, float, int]]:
        """
        [2.1] MM котировки вторым приоритетом.
        Полный цикл: locked/crossed check → spike check → skew → spread → size → edge check.
        [2.2] Optimal quote refresh rate — каждые N тиков, не каждый тик.
        """
        orders = []
        mid = (best_bid + best_ask) / 2

        # [2.1] Locked market — не торговать
        if self.is_locked_market(best_bid, best_ask):
            return []

        # [2.1] Flash spike — не котировать
        if self.is_flash_spike(mid, state.price_history):
            return []

        # [2.2] Optimal quote refresh rate
        if refresh_counter % QUOTE_REFRESH_TICKS != 0:
            return []

        # [11] Hard stop
        block_bid, block_ask = self.inventory_engine.hard_stop(position, limit)

        # Spread
        spread = self.spread_calc.compute_spread(
            base_spread=STABLE_SPREAD_MIN,
            sigma=sigma,
            adv_sel_active=adv_sel_active,
            gap_risk=False,
            pnl_negative=pnl_negative,
            regime_volatile=False,
        )
        spread = min(spread, STABLE_SPREAD_MAX)

        # Skew
        fv_adjusted = self.fair_value - position * 0.5
        fv = fv_adjusted
        bid_p, ask_p, bid_m, ask_m = self.inventory_engine.compute_skew(
            position=position,
            position_limit=limit,
            fair_value=fv,
            spread=spread,
            skew_threshold=STABLE_SKEW_THRESHOLD,
            is_volatile=False,
        )

        # [6] Position threshold: use wider spread when position > 15
        if abs(position) > 15:
            bid_p = fv - 2
            ask_p = fv + 2

        # [2.3] Edge check
        edge_bid, edge_ask = self.quote_dist_engine.has_edge(bid_p, ask_p, fv)

        # [2.1] Размер MM котировки — от доступной позиционной ёмкости
        available = STABLE_SOFT_LIMIT - abs(position)
        base_qty = max(1, available // 2)

        if not block_bid and edge_bid:
            bid_qty = max(1, int(base_qty * bid_m))
            orders.append(("buy", round(bid_p), bid_qty))

        if not block_ask and edge_ask:
            ask_qty = max(1, int(base_qty * ask_m))
            orders.append(("sell", round(ask_p), ask_qty))

        return orders


# ==============================================================================
# SECTION 12 — MARKET MAKER (VOLATILE)  [2.2]
# ==============================================================================

class VolatileMarketMaker:
    """
    MM для волатильных активов.                       [2.2]
    Soft limit: 60%.                                  [2.2]
    Spread: 3–4 тика.                                [2.2]
    EMA fast 0.3–0.4, slow 0.05–0.1.                [2.2]
    Avellaneda-Stoikov.                               [2.2]
    Kalman Filter.                                    [2.2]
    OFI сигнал.                                      [2.2]
    Adverse selection.                                [2.2]
    Gap risk защита.                                  [2.2]
    Inventory accumulation hard limit + trigger.     [2.2]
    Proactive + реактивный skew.                     [2.2]
    Partial fill handling.                            [2.2]
    Two-sided quote obligation.                       [2.2]
    Optimal quote refresh rate.                       [2.2]
    """

    def __init__(self, gamma: float = AS_GAMMA_DEFAULT, k: float = 1.0):
        self.gamma = gamma
        self.k = k
        self.kalman = KalmanFilter_mm()
        self.ofi_calc = OFICalculator()
        self.adv_sel_detector = AdverseSelectionDetector_mm()
        self.ema_calc = EMACalculator()
        self.as_model = AvellanedaStoikov()
        self.inventory_engine = InventorySkewEngine()
        self.spread_calc = SpreadCalculator()
        self.quote_dist_engine = QuoteDistanceEngine()

    def compute_fair_value(
        self,
        mid: float,
        state: MMProductState,
        best_bid_vol: float,
        best_ask_vol: float,
    ) -> float:
        """
        Fair value для волатильного актива:
        1. Kalman filter [2.2]
        2. OFI adjustment [2.2]
        3. Bid-ask bounce filter [2.2]
        """
        # [2.2] Bid-ask bounce фильтрация
        state.price_history.append(mid)
        filtered_mid = self.ofi_calc.filter_bidask_bounce(state.price_history)

        # [2.2] Kalman Filter для fair value
        fv_kalman = self.kalman.update(state.kalman, filtered_mid)

        # [2.2] OFI сигнал
        ofi = self.ofi_calc.update(
            state.ofi, best_bid_vol, best_ask_vol, filtered_mid
        )
        fv_adjusted = self.ofi_calc.adjust_fair_value(fv_kalman, ofi, state.ofi)

        # [2.2] EMA update
        if not state.ema_initialized:
            state.ema_fast, state.ema_slow = self.ema_calc.initialize(filtered_mid)
            state.ema_initialized = True
        else:
            state.ema_fast = self.ema_calc.update(
                state.ema_fast, filtered_mid, EMA_ALPHA_FAST
            )
            state.ema_slow = self.ema_calc.update(
                state.ema_slow, filtered_mid, EMA_ALPHA_SLOW
            )

        return fv_adjusted

    def quote(
        self,
        best_bid: float,
        best_ask: float,
        position: int,
        limit: int,
        state: MMProductState,
        ticks_remaining: float,
        book_speed: float = 0.5,
        informed_freq: float = 0.3,
        pnl_negative: bool = False,
        prev_fill_qty: int = 0,
        prev_fill_side: str = "",
    ) -> List[Tuple[str, float, int]]:
        """
        Полный цикл котировки волатильного актива.
        """
        orders = []
        mid = (best_bid + best_ask) / 2

        # [2.2] Optimal quote refresh rate — каждые N тиков
        state.quote_refresh_counter += 1
        if state.quote_refresh_counter % QUOTE_REFRESH_TICKS != 0:
            return []

        # [2.4] Partial fill handling
        if prev_fill_qty > 0:
            state.partial_fill_residual = prev_fill_qty  # [2.4]
            state.partial_fill_side = prev_fill_side

        # FV
        fv = self.compute_fair_value(
            mid=mid,
            state=state,
            best_bid_vol=sum(state.ofi.bid_volumes[-1:]) if state.ofi.bid_volumes else 0,
            best_ask_vol=sum(state.ofi.ask_volumes[-1:]) if state.ofi.ask_volumes else 0,
        )

        # [2.2] σ realized vol
        sigma = self.as_model.realized_vol(state.price_history)

        # [2.2] Avellaneda-Stoikov
        T = max(1.0, ticks_remaining)
        gamma = self.as_model.calibrate_gamma(state.price_history, [])
        k = self.k
        res_price = self.as_model.reservation_price(fv, position, gamma, sigma, T)
        as_spread = self.as_model.optimal_spread(gamma, sigma, T, k)

        # [2.2] Adverse selection детекция
        adv_detected, adv_dir = self.adv_sel_detector.detect(state.adv_sel)

        # [2.2] Gap risk: высокая вола → уменьшить размер
        gap_risk = sigma > 0.02

        # Spread
        spread = self.spread_calc.compute_spread(
            base_spread=max(as_spread, VOLATILE_SPREAD_MIN),
            sigma=sigma,
            adv_sel_active=adv_detected,
            gap_risk=gap_risk,
            pnl_negative=pnl_negative,
            regime_volatile=True,
        )
        spread = min(spread, VOLATILE_SPREAD_MAX * 2)

        # [11] / [2.2] Inventory skew (proactive + reactive)
        bid_p, ask_p, bid_m, ask_m = self.inventory_engine.compute_skew(
            position=position,
            position_limit=limit,
            fair_value=res_price,
            spread=spread,
            skew_threshold=int(limit * 0.5),
            is_volatile=True,
        )

        # [11] Hard stop (inventory accumulation hard limit) [2.2]
        block_bid, block_ask = self.inventory_engine.hard_stop(position, limit)

        # [2.3] Queue distance
        distance = self.quote_dist_engine.get_quote_distance(
            is_volatile=True,
            regime_volatile=True,
            book_speed=book_speed,
            informed_freq=informed_freq,
            trade_size_ratio=state.partial_fill_residual / max(1, limit) * 10,
        )

        bid_final = self.quote_dist_engine.apply_distance(
            best_bid, best_ask, distance, "bid"
        )
        ask_final = self.quote_dist_engine.apply_distance(
            best_bid, best_ask, distance, "ask"
        )
        # Ограничиваем skew'нутыми ценами
        bid_final = min(bid_final, bid_p)
        ask_final = max(ask_final, ask_p)

        # [2.3] Edge check — two-sided quote obligation [2.2]
        edge_bid, edge_ask = self.quote_dist_engine.has_edge(bid_final, ask_final, fv)

        # Sizing: [2.2] Gap risk защита — уменьшить размер
        available = VOLATILE_SOFT_LIMIT - abs(position)
        base_qty = max(1, available // 3)
        if gap_risk:
            base_qty = max(1, base_qty // 2)

        # [2.2] Inventory accumulation: hard limit + liquidation trigger
        if abs(position) >= limit * 0.95:
            # Liquidation trigger — выставляем только закрывающие
            if position > 0:
                orders.append(("sell", round(ask_final), abs(position) // 2))
            else:
                orders.append(("buy", round(bid_final), abs(position) // 2))
            return orders

        # [2.2] Two-sided quote obligation — не котировать сторону если нет edge
        if not block_bid and edge_bid:
            bid_qty = max(1, int(base_qty * bid_m))
            orders.append(("buy", round(bid_final), bid_qty))

        if not block_ask and edge_ask:
            ask_qty = max(1, int(base_qty * ask_m))
            orders.append(("sell", round(ask_final), ask_qty))

        return orders


# ==============================================================================
# SECTION 13 — MM STATE SERIALIZATION  [2.4]
# ==============================================================================

def save_mm_state(state: MMState) -> str:
    """
    Сериализует MMState в строку для traderData.      [2.4]
    Kalman x_est и P_est.                             [2.4]
    OFI rolling window.                               [2.4]
    Adverse selection счётчики.                       [2.4]
    Quote refresh счётчик.                            [2.4]
    Partial fill остатки.                             [2.4]
    """
    payload: dict = {"products": {}}
    for product, ps in state.products.items():
        payload["products"][product] = {
            # [2.4] Kalman x_est и P_est
            "kalman_x_est":        ps.kalman.x_est,
            "kalman_P_est":        ps.kalman.P_est,
            "kalman_initialized":  ps.kalman.initialized,
            # [2.4] OFI rolling window значений
            "ofi_history":         ps.ofi.ofi_history[-OFI_LOOKBACK:],
            "ofi_beta":            ps.ofi.beta,
            "ofi_prev_bid_vol":    ps.ofi.prev_best_bid_vol,
            "ofi_prev_ask_vol":    ps.ofi.prev_best_ask_vol,
            # [2.4] Adverse selection счётчики
            "adv_bid_fills":       ps.adv_sel.bid_fills[-ADV_SEL_LOOKBACK:],
            "adv_ask_fills":       ps.adv_sel.ask_fills[-ADV_SEL_LOOKBACK:],
            "adv_widen":           ps.adv_sel.spread_widen_active,
            "adv_skew":            ps.adv_sel.skew_active,
            # [2.4] Quote refresh счётчик
            "refresh_counter":     ps.quote_refresh_counter,
            # [2.4] Partial fill остатки с предыдущего тика
            "partial_residual":    ps.partial_fill_residual,
            "partial_side":        ps.partial_fill_side,
            # EMA
            "ema_fast":            ps.ema_fast,
            "ema_slow":            ps.ema_slow,
            "ema_initialized":     ps.ema_initialized,
            # Price history (ограничиваем)
            "price_history":       ps.price_history[-AS_VOL_LOOKBACK:],
        }
    return json.dumps(payload)


def load_mm_state(data: str) -> MMState:
    """Десериализует MMState из traderData строки.    [2.4]"""
    state = MMState()
    if not data:
        return state
    try:
        payload = json.loads(data)
    except Exception:
        return state

    for product, d in payload.get("products", {}).items():
        ps = MMProductState()
        # [2.4] Kalman x_est и P_est
        ps.kalman.x_est       = d.get("kalman_x_est", [0.0, 0.0])
        ps.kalman.P_est       = d.get("kalman_P_est", [[1.0, 0.0], [0.0, 1.0]])
        ps.kalman.initialized = d.get("kalman_initialized", False)
        # [2.4] OFI rolling window
        ps.ofi.ofi_history          = d.get("ofi_history", [])
        ps.ofi.beta                 = d.get("ofi_beta", OFI_BETA_DEFAULT)
        ps.ofi.prev_best_bid_vol    = d.get("ofi_prev_bid_vol", 0.0)
        ps.ofi.prev_best_ask_vol    = d.get("ofi_prev_ask_vol", 0.0)
        # [2.4] Adverse selection счётчики
        ps.adv_sel.bid_fills            = d.get("adv_bid_fills", [])
        ps.adv_sel.ask_fills            = d.get("adv_ask_fills", [])
        ps.adv_sel.spread_widen_active  = d.get("adv_widen", False)
        ps.adv_sel.skew_active          = d.get("adv_skew", False)
        # [2.4] Quote refresh счётчик
        ps.quote_refresh_counter = d.get("refresh_counter", 0)
        # [2.4] Partial fill остатки
        ps.partial_fill_residual = d.get("partial_residual", 0)
        ps.partial_fill_side     = d.get("partial_side", "")
        # EMA
        ps.ema_fast        = d.get("ema_fast", 0.0)
        ps.ema_slow        = d.get("ema_slow", 0.0)
        ps.ema_initialized = d.get("ema_initialized", False)
        ps.price_history   = d.get("price_history", [])
        state.products[product] = ps

    return state


# ==============================================================================
# SECTION 14 — TOP-LEVEL MM DISPATCHER
# ==============================================================================

class MarketMakerDispatcher:
    """
    Главный диспетчер — выбирает stable vs volatile MM.
    Интегрирует все компоненты.
    """

    # AMETHYSTS P1 optimal: FV=10000, bid=9998, ask=10002
    # Inventory adjustment: fv_adjusted = 10000 - position * 0.5
    # (reduces fair value when long to encourage selling, raises when short)
    STABLE_PRODUCTS:   Dict[str, float] = {"AMETHYSTS": 10000.0, "RAINFOREST_RESIN": 10000.0}
    VOLATILE_PRODUCTS: List[str]        = ["STARFRUIT", "KELP", "SQUID_INK"]

    # P1 known optimal STARFRUIT regression weights (from public writeups)
    # predicted_fv = sum(w * p for w, p in zip(STARFRUIT_WEIGHTS, last_4_midprices))
    STARFRUIT_WEIGHTS: List[float] = [0.19, 0.21, 0.26, 0.34]  # ordered oldest to newest

    def __init__(self) -> None:
        self.stable_mms:   Dict[str, StableMarketMaker]   = {}
        self.volatile_mms: Dict[str, VolatileMarketMaker] = {}

    def _get_stable_mm(self, product: str) -> StableMarketMaker:
        if product not in self.stable_mms:
            fv = self.STABLE_PRODUCTS.get(product, 10000.0)
            self.stable_mms[product] = StableMarketMaker(fv)
        return self.stable_mms[product]

    def _get_volatile_mm(self, product: str) -> VolatileMarketMaker:
        if product not in self.volatile_mms:
            self.volatile_mms[product] = VolatileMarketMaker()
        return self.volatile_mms[product]

    def run(
        self,
        product: str,
        best_bid: float,
        best_ask: float,
        position: int,
        limit: int,
        mm_state: MMState,
        ticks_remaining: float = 1000.0,
        pnl_negative: bool = False,
        prev_fill_qty: int = 0,
        prev_fill_side: str = "",
        sigma_override: Optional[float] = None,
    ) -> List[Tuple[str, float, int]]:

        ps = mm_state.get_product(product)

        if product in self.STABLE_PRODUCTS:
            mm = self._get_stable_mm(product)
            sigma = sigma_override or AvellanedaStoikov.realized_vol(
                ps.price_history
            )
            adv_detected, _ = AdverseSelectionDetector_mm().detect(ps.adv_sel)

            # [2.1] Crossed market — тейкать немедленно
            if mm.is_crossed_market(best_bid, best_ask):
                return mm.take_aggressive(best_bid, best_ask, position, limit)

            # [2.1] Locked market — не торговать
            if mm.is_locked_market(best_bid, best_ask):
                return []

            # [2.1] Тейкерская агрессия первым приоритетом
            taker = mm.take_aggressive(best_bid, best_ask, position, limit)

            # [2.1] MM котировки вторым приоритетом
            mm_orders = mm.quote(
                best_bid, best_ask, position, limit,
                sigma=sigma,
                adv_sel_active=adv_detected,
                pnl_negative=pnl_negative,
                state=ps,
                refresh_counter=ps.quote_refresh_counter,
            )
            ps.quote_refresh_counter += 1

            return taker + mm_orders

        else:
            mm = self._get_volatile_mm(product)
            return mm.quote(
                best_bid, best_ask, position, limit,
                state=ps,
                ticks_remaining=ticks_remaining,
                pnl_negative=pnl_negative,
                prev_fill_qty=prev_fill_qty,
                prev_fill_side=prev_fill_side,
            )

