# --- [4.1] Black-Scholes ---
RISK_FREE_RATE      = 0.0      # [4.1] r обычно 0 в соревновании
IV_SEARCH_LOW       = 0.001    # [4.1] IV диапазон поиска brentq
IV_SEARCH_HIGH      = 10.0     # [4.1] IV диапазон поиска brentq
# [4.1] IV > HV → опцион дорогой → продавать vol; IV < HV → опцион дешёвый → покупать vol
IV_COLD_START       = 0.2      # [4.1] cold start fallback IV

# --- [4.2] Delta hedging ---
DELTA_BAND          = 5.0      # [4.2] rebalance trigger |net delta| > ±5
DELTA_HEDGE_MIN_POS = 5        # [4.2] delta hedge обязателен при позиции > 5

# --- [4.2] Put-Call parity ---
PCP_MIN_EDGE        = 0.0      # [4.2] прибыль > 2×spread + 2×fee (динамически)

# --- [4.2] Theta decay ---
THETA_ENTRY_SPREAD  = 3.0      # [4.2] IV_implied - realized_vol_20d > 3 пункта
THETA_REALIZED_WINDOW = 20     # [4.2] realized_vol_20d окно
# [4.2] Synthetic positions: synthetic long/short через опционы если спред узкий     # [4.2] realized_vol_20d окно

# --- [4.2] Sizing ---
VEGA_LIMIT_FRAC     = 0.30     # [4.2] Vega limit < 30% капитала
DELTA_LIMIT         = 5.0      # [4.2] Delta limit |net delta| < ±5
POSITION_LIMIT_FRAC = 0.75     # [4.2] 75% от официального лимита (150 из 200)
POSITION_LIMIT_ABS  = 150      # [4.2] 150 из 200

# --- [4.4] Strike selection ---
LOG_MONEYNESS_MAX   = 0.1      # [4.4] |log-moneyness| < 0.1

# --- [4.3] Vol surface ---
REALIZED_VOL_WINDOW = 100      # rolling window realized vol


