@dataclass
class OptionGreeks:
    """Полный набор греков по позиции. [4.2]"""
    delta: float = 0.0   # [4.2] ∂V/∂S
    gamma: float = 0.0   # [4.2] ∂²V/∂S²
    vega:  float = 0.0   # [4.2] ∂V/∂σ
    theta: float = 0.0   # [4.2] ∂V/∂T (отрицательный для long)
    rho:   float = 0.0   # [4.2] ∂V/∂r (обычно игнорировать)
    vanna: float = 0.0   # [4.2] ∂²V/∂S∂σ
    volga: float = 0.0   # [4.2] ∂²V/∂σ²


@dataclass
class OptionPosition:
    """Одна опционная позиция."""
    product: str
    strike: float
    expiry_ticks: float
    option_type: str          # "call" or "put"
    size: int                 # положительный = long
    greeks: OptionGreeks = field(default_factory=OptionGreeks)
    iv: float = IV_COLD_START


@dataclass
class VolSurfaceState:
    """Vol surface coefficients. [4.5]"""
    # [4.5] coefficients quadratic fit (a, b, c)
    coeffs_by_expiry: Dict[float, Tuple[float, float, float]] = field(default_factory=dict)
    # [4.5] Heston параметры — пересчитываются редко
    heston_params: Optional[Dict[str, float]] = None
    # [4.5] SABR параметры — пересчитываются редко
    sabr_params: Optional[Dict[str, float]] = None


@dataclass
class OptionsState:
    """
    Полный options state — сериализуется в traderData. [4.5]
    """
    # [4.5] Кэш implied vol по (S, market_price, K, T)
    iv_cache: Dict[str, float] = field(default_factory=dict)
    # [4.5] Текущие Greeks по каждой позиции
    greeks_by_position: Dict[str, OptionGreeks] = field(default_factory=dict)
    # [4.5] Cumulative realized vol rolling window
    price_history: List[float] = field(default_factory=list)
    # [4.5] Vol surface coefficients
    vol_surface: VolSurfaceState = field(default_factory=VolSurfaceState)
    # [4.5] Net delta по всем опционным позициям
