# ══════════════════════════════════════════════════════════════════
# СТРУКТУРЫ ДАННЫХ
# ══════════════════════════════════════════════════════════════════

@dataclass
class L2Level:
    """
    Один уровень L2-стакана.
    Явные поля соответствуют price_1/volume_1, price_2/volume_2 ...
    в зависимости от позиции в списке.
    """
    price: float
    volume: float

    def __post_init__(self) -> None:
        if self.price <= 0:
            raise ValueError(f"Цена должна быть > 0, получено {self.price}")
        if self.volume < 0:
            raise ValueError(f"Объём не может быть отрицательным, получено {self.volume}")


@dataclass
class OrderBook:
    """
    Стакан заявок с 3 уровнями bid и ask (L2-данные).

    bids[0] — bid_price_1 / bid_volume_1  (лучший bid)
    bids[1] — bid_price_2 / bid_volume_2
    bids[2] — bid_price_3 / bid_volume_3

    asks[0] — ask_price_1 / ask_volume_1  (лучший ask)
    asks[1] — ask_price_2 / ask_volume_2
    asks[2] — ask_price_3 / ask_volume_3

    bids упорядочены по убыванию цены (лучший = самый дорогой).
    asks упорядочены по возрастанию цены (лучший = самый дешёвый).
    """
    bids: list[L2Level]
    asks: list[L2Level]

    def __post_init__(self) -> None:
        if len(self.bids) < 1 or len(self.asks) < 1:
            raise ValueError("Стакан должен содержать хотя бы 1 уровень bid и ask")
        # проверяем сортировку bids (убывание) и asks (возрастание)
        for i in range(len(self.bids) - 1):
            if self.bids[i].price <= self.bids[i + 1].price:
                raise ValueError("bids должны быть отсортированы по убыванию цены")
        for i in range(len(self.asks) - 1):
            if self.asks[i].price >= self.asks[i + 1].price:
                raise ValueError("asks должны быть отсортированы по возрастанию цены")
        if self.bids[0].price >= self.asks[0].price:
            raise ValueError(
                f"best_bid ({self.bids[0].price}) >= best_ask ({self.asks[0].price})"
            )

    # ── удобные свойства ──────────────────────────────────────

    @property
    def best_bid(self) -> L2Level:
        return self.bids[0]

    @property
    def best_ask(self) -> L2Level:
        return self.asks[0]

    # Явные именованные свойства уровней (требование 1.1)
    @property
    def bid_price_1(self) -> float: return self.bids[0].price
    @property
    def bid_volume_1(self) -> float: return self.bids[0].volume
    @property
    def bid_price_2(self) -> Optional[float]:
        return self.bids[1].price if len(self.bids) > 1 else None
    @property
    def bid_volume_2(self) -> Optional[float]:
        return self.bids[1].volume if len(self.bids) > 1 else None
    @property
    def bid_price_3(self) -> Optional[float]:
        return self.bids[2].price if len(self.bids) > 2 else None
    @property
    def bid_volume_3(self) -> Optional[float]:
        return self.bids[2].volume if len(self.bids) > 2 else None

    @property
    def ask_price_1(self) -> float: return self.asks[0].price
    @property
    def ask_volume_1(self) -> float: return self.asks[0].volume
    @property
    def ask_price_2(self) -> Optional[float]:
        return self.asks[1].price if len(self.asks) > 1 else None
    @property
    def ask_volume_2(self) -> Optional[float]:
        return self.asks[1].volume if len(self.asks) > 1 else None
    @property
    def ask_price_3(self) -> Optional[float]:
        return self.asks[2].price if len(self.asks) > 2 else None
    @property
    def ask_volume_3(self) -> Optional[float]:
        return self.asks[2].volume if len(self.asks) > 2 else None

    def total_bid_volume(self) -> float:
        return sum(lvl.volume for lvl in self.bids)

    def total_ask_volume(self) -> float:
        return sum(lvl.volume for lvl in self.asks)


class Direction(str, Enum):
    """Предсказанное направление движения цены."""
    BULLISH  = "BULLISH"   # давление покупателей
    BEARISH  = "BEARISH"   # давление продавцов
    NEUTRAL  = "NEUTRAL"   # баланс


class TradingRisk(str, Enum):
    """Оценка риска торговли по состоянию книги."""
    DANGEROUS = "DANGEROUS"   # thin book — высокий импакт
    SAFE      = "SAFE"        # thick book — низкий импакт
    MODERATE  = "MODERATE"    # промежуточное состояние
    FORBIDDEN = "FORBIDDEN"   # iceberg на лучшем уровне


# ══════════════════════════════════════════════════════════════════
# 26.1  MID PRICE
# ══════════════════════════════════════════════════════════════════

def calc_mid_price(ob: OrderBook) -> float:
    """
    Mid price = (best_bid + best_ask) / 2

    Простейшая оценка справедливой цены.
    Не учитывает дисбаланс объёмов на best-уровнях.
    """
    return (ob.best_bid.price + ob.best_ask.price) / 2.0


# ══════════════════════════════════════════════════════════════════
# 26.2  WEIGHTED MID PRICE
# ══════════════════════════════════════════════════════════════════

def calc_weighted_mid_price(ob: OrderBook) -> float:
    """
    Weighted mid price = (bid_price × ask_vol + ask_price × bid_vol)
                         / (bid_vol + ask_vol)

    Улучшенная версия mid price: смещается в сторону стороны
    с меньшим объёмом (там цена «легче» сдвигается).

    Если ask_vol >> bid_vol → WMP < mid price (продавцов много → давление вниз).
    Если bid_vol >> ask_vol → WMP > mid price (покупателей много → давление вверх).
    """
    bp  = ob.best_bid.price
    bv  = ob.best_bid.volume
    ap  = ob.best_ask.price
    av  = ob.best_ask.volume
    total = bv + av

    if total == 0.0:
        raise ValueError("bid_vol + ask_vol = 0, невозможно вычислить WMP")

    return (bp * av + ap * bv) / total


# ══════════════════════════════════════════════════════════════════
# 26.3  VWAP ЧЕРЕЗ ВСЕ УРОВНИ L2
# ══════════════════════════════════════════════════════════════════

def calc_vwap(ob: OrderBook) -> float:
    """
    VWAP (L2) = Σ(price_i × volume_i) / Σ(volume_i)
                для всех уровней bid и ask.

    Отражает средневзвешенную «цену ликвидности» стакана.
    Используется для оценки качества исполнения vs рыночная цена.
    """
    all_levels = ob.bids + ob.asks
    total_pv   = sum(lvl.price * lvl.volume for lvl in all_levels)
    total_v    = sum(lvl.volume for lvl in all_levels)

    if total_v == 0.0:
        raise ValueError("Суммарный объём по всем уровням = 0")

    return total_pv / total_v


# ══════════════════════════════════════════════════════════════════
# 26.4  BID-ASK SPREAD
# ══════════════════════════════════════════════════════════════════

def calc_bid_ask_spread(ob: OrderBook) -> dict:
    """
    Bid-ask spread — стоимость немедленного исполнения сделки.

    absolute : ask_price_1 - bid_price_1
    relative : (ask - bid) / mid_price × 100  [%]

    Широкий спред → низкая ликвидность, высокие транзакционные издержки.
    Узкий спред   → высокая ликвидность, эффективный рынок.
    """
    spread_abs = ob.ask_price_1 - ob.bid_price_1
    mid        = calc_mid_price(ob)
    spread_pct = spread_abs / mid * 100.0 if mid > 0.0 else 0.0

    return {
        "spread_abs": spread_abs,
        "spread_pct": spread_pct,
        "mid_price":  mid,
    }


# ══════════════════════════════════════════════════════════════════
# 26.5  BID-ASK IMBALANCE (best level)
# ══════════════════════════════════════════════════════════════════

def calc_bid_ask_imbalance(ob: OrderBook) -> float:
    """
    Bid-ask imbalance = (bid_vol_1 - ask_vol_1) / (bid_vol_1 + ask_vol_1)

    Формула по требованию: использует ТОЛЬКО лучший уровень (L1).
    Диапазон [-1, +1].

    +1 → весь объём на стороне bid  (сильный спрос)
    -1 → весь объём на стороне ask  (сильное предложение)
     0 → полный баланс
    """
    bv    = ob.bid_volume_1
    av    = ob.ask_volume_1
    total = bv + av
    return 0.0 if total == 0.0 else (bv - av) / total


# ══════════════════════════════════════════════════════════════════
# 26.6  ORDER BOOK IMBALANCE (все уровни)
# ══════════════════════════════════════════════════════════════════

def calc_order_book_imbalance(ob: OrderBook) -> float:
    """
    Order book imbalance = (Σbid_vol - Σask_vol) / (Σbid_vol + Σask_vol)

    Отличие от bid-ask imbalance: учитывает ВСЕ 3 уровня стакана,
    а не только лучший. Даёт более устойчивую оценку дисбаланса.

    Диапазон [-1, +1].
    > 0 → суммарный объём bid доминирует (bullish давление)
    < 0 → суммарный объём ask доминирует (bearish давление)
    """
    total_bv = ob.total_bid_volume()
    total_av = ob.total_ask_volume()
    total    = total_bv + total_av
    return 0.0 if total == 0.0 else (total_bv - total_av) / total


# ══════════════════════════════════════════════════════════════════
# 26.7  DEPTH LEVELS  (все 3 уровня: price_1/2/3, volume_1/2/3)
# ══════════════════════════════════════════════════════════════════

def calc_depth_levels(ob: OrderBook) -> dict:
    """
    L2 глубина стакана: все 3 уровня bid и ask.

    Возвращает явные поля bid_price_1..3 / bid_volume_1..3
    и ask_price_1..3 / ask_volume_1..3 (требование 1.1).
    Также суммарные объёмы и их соотношение.
    """
    result: dict = {}

    for i, lvl in enumerate(ob.bids[:3], start=1):
        result[f"bid_price_{i}"]  = lvl.price
        result[f"bid_volume_{i}"] = lvl.volume

    for i, lvl in enumerate(ob.asks[:3], start=1):
        result[f"ask_price_{i}"]  = lvl.price
        result[f"ask_volume_{i}"] = lvl.volume

    result["total_bid_depth"] = ob.total_bid_volume()
    result["total_ask_depth"] = ob.total_ask_volume()
    total_ask = result["total_ask_depth"]
    result["depth_ratio"] = (
        result["total_bid_depth"] / total_ask
        if total_ask > 0.0
        else float("inf")
    )
    return result


# ══════════════════════════════════════════════════════════════════
# 26.8  SWEEP DETECTION
# ══════════════════════════════════════════════════════════════════

def detect_sweep(
    prev_ob: OrderBook,
    curr_ob: OrderBook,
    min_levels_consumed: int = 2,
) -> dict:
    """
    Sweep — агрессивный рыночный ордер, поглощающий ≥N уровней стакана
    за один тик. Признак сильного направленного давления.

    Ask sweep (market buy):
      текущий best_ask выше, чем были N предыдущих уровней ask.

    Bid sweep (market sell):
      текущий best_bid ниже, чем были N предыдущих уровней bid.

    Возвращает:
      detected   — True/False
      direction  — "ask_sweep" (buy pressure) / "bid_sweep" (sell) / None
      levels_consumed — количество поглощённых уровней
    """
    prev_ask_prices = [lvl.price for lvl in prev_ob.asks[:3]]
    prev_bid_prices = [lvl.price for lvl in prev_ob.bids[:3]]

    # ask sweep: сколько старых ask-уровней ниже нового best_ask
    ask_consumed = sum(1 for p in prev_ask_prices if p < curr_ob.ask_price_1)
    # bid sweep: сколько старых bid-уровней выше нового best_bid
    bid_consumed = sum(1 for p in prev_bid_prices if p > curr_ob.bid_price_1)

    if ask_consumed >= min_levels_consumed:
        return {"detected": True, "direction": "ask_sweep", "levels_consumed": ask_consumed}
    if bid_consumed >= min_levels_consumed:
        return {"detected": True, "direction": "bid_sweep", "levels_consumed": bid_consumed}

    return {"detected": False, "direction": None, "levels_consumed": 0}


# ══════════════════════════════════════════════════════════════════
# 26.9  ORDER FLOW IMBALANCE — кумулятивный за N тиков
# ══════════════════════════════════════════════════════════════════

class OrderFlowImbalanceTracker:
    """
    Кумулятивный Order Flow Imbalance (OFI) за скользящее окно N тиков.

    На каждом обновлении стакана вычисляем OFI_tick:
      delta_bid = +new_bid_vol  если bid_price ↑ (новый уровень дороже)
                = -prev_bid_vol если bid_price ↓ (лучший уровень ушёл)
                = 0             если цена не изменилась

      delta_ask = +new_ask_vol  если ask_price ↓
                = -prev_ask_vol если ask_price ↑
                = 0             если цена не изменилась

      OFI_tick = delta_bid - delta_ask

    Cumulative OFI = Σ OFI_tick за последние N тиков.

    Интерпретация:
      > 0  накопленное давление покупок  → рост цены вероятен
      < 0  накопленное давление продаж   → снижение цены вероятно
      ≈ 0  рынок в балансе
    """

    def __init__(self, window: int = 20) -> None:
        if window < 1:
            raise ValueError("window должен быть >= 1")
        self.window   = window
        self._ticks: deque[float] = deque(maxlen=window)
        self._prev: Optional[OrderBook] = None

    def update(self, ob: OrderBook) -> Optional[float]:
        """
        Добавляет тик. Возвращает cumulative OFI или None на первом тике.
        """
        if self._prev is None:
            self._prev = ob
            return None

        # bid side
        if ob.bid_price_1 > self._prev.bid_price_1:
            delta_bid = ob.bid_volume_1
        elif ob.bid_price_1 < self._prev.bid_price_1:
            delta_bid = -self._prev.bid_volume_1
        else:
            delta_bid = ob.bid_volume_1 - self._prev.bid_volume_1

        # ask side
        if ob.ask_price_1 < self._prev.ask_price_1:
            delta_ask = ob.ask_volume_1
        elif ob.ask_price_1 > self._prev.ask_price_1:
            delta_ask = -self._prev.ask_volume_1
        else:
            delta_ask = ob.ask_volume_1 - self._prev.ask_volume_1

        ofi_tick = delta_bid - delta_ask
        self._ticks.append(ofi_tick)
        self._prev = ob
        return float(np.sum(self._ticks))

    @property
    def cumulative_ofi(self) -> float:
        return float(np.sum(self._ticks))

    def reset(self) -> None:
        self._ticks.clear()
        self._prev = None


# ══════════════════════════════════════════════════════════════════
# 26.10 PRICE IMPACT
# ══════════════════════════════════════════════════════════════════

def calc_price_impact(
    ob: OrderBook,
    order_size: float,
    side: str = "buy",
) -> dict:
    """
    Price impact: насколько вырастет/упадёт средняя цена исполнения
    при размещении рыночного ордера объёмом order_size.

    side='buy'  → поглощаем уровни ask снизу вверх (цена растёт)
    side='sell' → поглощаем уровни bid сверху вниз (цена падает)

    Возвращает:
      avg_fill_price   — средневзвешенная цена исполнения
      price_impact_abs — отклонение от mid price
      price_impact_pct — импакт в %
      filled           — исполненный объём
      unfilled         — неисполненный остаток (нехватка ликвидности)
      levels_consumed  — количество поглощённых уровней
      slippage         — среднее проскальзывание от best price
    """
    if order_size <= 0:
        raise ValueError("order_size должен быть > 0")
    if side not in ("buy", "sell"):
        raise ValueError("side должен быть 'buy' или 'sell'")

    mid        = calc_mid_price(ob)
    best_price = ob.ask_price_1 if side == "buy" else ob.bid_price_1
    levels     = ob.asks if side == "buy" else ob.bids

    remaining       = order_size
    total_cost      = 0.0
    levels_consumed = 0

    for lvl in levels:
        if remaining <= 0.0:
            break
        take        = min(remaining, lvl.volume)
        total_cost += take * lvl.price
        remaining  -= take
        levels_consumed += 1

    filled         = order_size - remaining
    avg_fill       = total_cost / filled if filled > 0.0 else best_price
    impact_abs     = (avg_fill - mid) if side == "buy" else (mid - avg_fill)
    impact_pct     = impact_abs / mid * 100.0 if mid > 0.0 else 0.0
    slippage       = abs(avg_fill - best_price)

    return {
        "side":             side,
        "order_size":       order_size,
        "avg_fill_price":   avg_fill,
        "price_impact_abs": impact_abs,
        "price_impact_pct": impact_pct,
        "filled":           filled,
        "unfilled":         remaining,
        "levels_consumed":  levels_consumed,
        "slippage":         slippage,
    }


# ══════════════════════════════════════════════════════════════════
# 26.11 / 26.12  THIN & THICK MARKET DETECTION + TRADING RISK
# ══════════════════════════════════════════════════════════════════

def assess_market_depth(
    ob: OrderBook,
    thin_threshold: float  = 100.0,
    thick_threshold: float = 1000.0,
) -> dict:
    """
    Оценка состояния ликвидности стакана и торгового риска.

    Thin market  (total_depth < thin_threshold):
      ► Торговать РИСКОВАННО:
        - даже малый ордер даёт большой ценовой импакт
        - высокий слиппидж
        - возможны манипуляции

    Thick market (total_depth >= thick_threshold):
      ► Торговать БЕЗОПАСНО:
        - низкий импакт, стабильное исполнение
        - большой ордер поглощается без резких скачков цены

    Moderate (thin_threshold <= total < thick_threshold):
      ► Умеренный риск.
    """
    total = ob.total_bid_volume() + ob.total_ask_volume()

    if total < thin_threshold:
        is_thin   = True
        is_thick  = False
        risk      = TradingRisk.DANGEROUS
        note      = "Thin book — торговать РИСКОВАННО: высокий импакт, слиппидж"
    elif total >= thick_threshold:
        is_thin   = False
        is_thick  = True
        risk      = TradingRisk.SAFE
        note      = "Thick book — торговать БЕЗОПАСНЕЕ: низкий импакт"
    else:
        is_thin   = False
        is_thick  = False
        risk      = TradingRisk.MODERATE
        note      = "Moderate depth — умеренный риск"

    return {
        "total_depth":      total,
        "thin_threshold":   thin_threshold,
        "thick_threshold":  thick_threshold,
        "is_thin_market":   is_thin,
        "is_thick_market":  is_thick,
        "trading_risk":     risk,
        "note":             note,
    }


# ══════════════════════════════════════════════════════════════════
# 26.13 L2 LIQUIDITY ASSESSMENT
# ══════════════════════════════════════════════════════════════════

def calc_l2_liquidity(ob: OrderBook) -> dict:
    """
    Оценка ликвидности по L2 данным стакана.

    Метрики:
      bid_side_liquidity  — суммарный объём на bid стороне
      ask_side_liquidity  — суммарный объём на ask стороне
      total_liquidity     — общая ликвидность стакана
      weighted_spread     — взвешенный спред (spread / total_depth)
      depth_profile       — как объём распределён по уровням (%)
      liquidity_score     — агрегированный [0..1]: чем выше, тем лучше

    Замечание:
      Смотреть на L2 данные для оценки liquidity критически важно:
      L1 (best bid/ask) может показывать нормальный спред,
      но за лучшим уровнем стакан может быть почти пуст (thin L2).
    """
    depth       = calc_depth_levels(ob)
    spread_info = calc_bid_ask_spread(ob)
    total_liq   = depth["total_bid_depth"] + depth["total_ask_depth"]

    # профиль глубины: доля объёма на каждом уровне
    depth_profile = {}
    for side in ("bid", "ask"):
        for i in range(1, 4):
            vol_key = f"{side}_volume_{i}"
            if vol_key in depth and total_liq > 0:
                depth_profile[vol_key + "_pct"] = depth[vol_key] / total_liq * 100.0

    # взвешенный спред: стоимость пересечения bid-ask относительно глубины
    weighted_spread = (
        spread_info["spread_abs"] / total_liq
        if total_liq > 0.0
        else float("inf")
    )

    # liquidity_score ∈ [0, 1]
    # высокий объём + узкий спред = высокий score
    # нормируем: score = total_liq / (total_liq + k * spread_abs)
    k = 1000.0
    score = total_liq / (total_liq + k * spread_info["spread_abs"])

    return {
        "bid_side_liquidity":  depth["total_bid_depth"],
        "ask_side_liquidity":  depth["total_ask_depth"],
        "total_liquidity":     total_liq,
        "spread_abs":          spread_info["spread_abs"],
        "weighted_spread":     weighted_spread,
        "depth_profile":       depth_profile,
        "liquidity_score":     round(score, 6),
    }


# ══════════════════════════════════════════════════════════════════
# 26.14 DIRECTION PREDICTOR
# ══════════════════════════════════════════════════════════════════

def predict_direction(
    ob: OrderBook,
    ofi_tracker: Optional[OrderFlowImbalanceTracker] = None,
    imbalance_threshold: float = 0.10,
    ofi_threshold:       float = 0.0,
) -> dict:
    """
    Предсказание направления движения цены на основе дисбаланса bid/ask.

    Сигналы:
      1. Bid-ask imbalance (L1): (bid_vol_1 - ask_vol_1) / (bid_vol_1 + ask_vol_1)
      2. Order book imbalance (L2): по всем уровням
      3. Cumulative OFI (если доступен): накопленный поток

    Логика голосования (consensus):
      - Каждый сигнал даёт голос BULLISH / BEARISH / NEUTRAL
      - Итоговое направление = большинство голосов
      - confidence = доля голосов за итоговое направление

    Интерпретация:
      BULLISH: bid_vol доминирует → покупатели агрессивнее → цена вероятно ↑
      BEARISH: ask_vol доминирует → продавцы агрессивнее → цена вероятно ↓
      NEUTRAL: баланс → направление неопределённо
    """
    votes: list[Direction] = []

    # Сигнал 1: bid-ask imbalance (L1)
    ba_imb = calc_bid_ask_imbalance(ob)
    if ba_imb > imbalance_threshold:
        votes.append(Direction.BULLISH)
    elif ba_imb < -imbalance_threshold:
        votes.append(Direction.BEARISH)
    else:
        votes.append(Direction.NEUTRAL)

    # Сигнал 2: order book imbalance (L2)
    ob_imb = calc_order_book_imbalance(ob)
    if ob_imb > imbalance_threshold:
        votes.append(Direction.BULLISH)
    elif ob_imb < -imbalance_threshold:
        votes.append(Direction.BEARISH)
    else:
        votes.append(Direction.NEUTRAL)

    # Сигнал 3: cumulative OFI (опционально)
    ofi_value: Optional[float] = None
    if ofi_tracker is not None:
        ofi_value = ofi_tracker.cumulative_ofi
        if ofi_value > ofi_threshold:
            votes.append(Direction.BULLISH)
        elif ofi_value < -ofi_threshold:
            votes.append(Direction.BEARISH)
        else:
            votes.append(Direction.NEUTRAL)

    # подсчёт голосов
    bullish_n = votes.count(Direction.BULLISH)
    bearish_n = votes.count(Direction.BEARISH)
    neutral_n = votes.count(Direction.NEUTRAL)
    total_v   = len(votes)

    if bullish_n > bearish_n and bullish_n > neutral_n:
        direction  = Direction.BULLISH
        confidence = bullish_n / total_v
    elif bearish_n > bullish_n and bearish_n > neutral_n:
        direction  = Direction.BEARISH
        confidence = bearish_n / total_v
    else:
        direction  = Direction.NEUTRAL
        confidence = neutral_n / total_v

    return {
        "direction":        direction,
        "confidence":       round(confidence, 4),
        "ba_imbalance":     ba_imb,
        "ob_imbalance":     ob_imb,
        "cumulative_ofi":   ofi_value,
        "votes":            {
            Direction.BULLISH: bullish_n,
            Direction.BEARISH: bearish_n,
            Direction.NEUTRAL: neutral_n,
        },
    }


# ══════════════════════════════════════════════════════════════════
# 1.1  ICEBERG DETECTION
# ══════════════════════════════════════════════════════════════════

class IcebergDetector_order:
    """
    Iceberg detection по восстановлению объёма на уровне (требование 1.1).

    Iceberg-ордер — скрытый ордер большого размера, который выставляет
    на рынок только часть («вершину айсберга»). После каждого частичного
    исполнения объём на уровне пополняется из скрытого резервуара.

    Алгоритм:
      1. Запоминаем объём на каждой ценовой отметке.
      2. Если объём на уровне СНИЗИЛСЯ (частичное исполнение) → фиксируем.
      3. Если затем объём на ТОМ ЖЕ уровне ВЫРОС (пополнение) → refill +1.
      4. При refill_count >= refill_threshold → уровень помечается как iceberg.

    ⚠  ТОРГОВЛЯ ПРОТИВ ICEBERG-УРОВНЯ ЗАПРЕЩЕНА:
       - Скрытый объём может быть на порядки больше видимого.
       - Ордер, поставленный против iceberg, будет поглощён без движения цены.
       - После исчерпания айсберга возможен резкий гэп.
    """

    def __init__(
        self,
        refill_threshold: int   = 2,
        min_drop_ratio:   float = 0.05,
    ) -> None:
        """
        refill_threshold: сколько раз объём должен восстановиться
                          для признания уровня айсбергом.
        min_drop_ratio:   минимальное относительное снижение объёма,
                          чтобы засчитать «исполнение».
        """
        self.refill_threshold = refill_threshold
        self.min_drop_ratio   = min_drop_ratio

        # price → {"last_vol": float, "refills": int, "dropped": bool}
        self._data: dict[float, dict] = {}
        self.iceberg_prices: set[float] = set()

    def update(self, ob: OrderBook) -> set[float]:
        """
        Обновляет детектор новым срезом стакана.
        Возвращает множество цен с обнаруженными айсбергами.
        """
        for lvl in ob.bids + ob.asks:
            p   = lvl.price
            vol = lvl.volume

            if p not in self._data:
                self._data[p] = {"last_vol": vol, "refills": 0, "dropped": False}
                continue

            rec      = self._data[p]
            last_vol = rec["last_vol"]

            drop = last_vol - vol   # > 0 если объём уменьшился

            if drop > 0 and last_vol > 0 and drop / last_vol >= self.min_drop_ratio:
                # объём значимо снизился → исполнение
                rec["dropped"]  = True
                rec["last_vol"] = vol

            elif vol > last_vol and rec["dropped"]:
                # объём вырос после снижения → пополнение (refill)
                rec["refills"] += 1
                rec["dropped"]  = False
                rec["last_vol"] = vol

                if rec["refills"] >= self.refill_threshold:
                    self.iceberg_prices.add(p)
            else:
                rec["last_vol"] = vol

        return self.iceberg_prices

    def is_iceberg(self, price: float) -> bool:
        """True, если на данном ценовом уровне обнаружен айсберг."""
        return price in self.iceberg_prices

    def trade_forbidden(self, ob: OrderBook) -> bool:
        """
        Торговля ЗАПРЕЩЕНА, если best_bid или best_ask является iceberg-уровнем.
        Возвращает True → активируется TradingRisk.FORBIDDEN.
        """
        return (
            self.is_iceberg(ob.bid_price_1)
            or self.is_iceberg(ob.ask_price_1)
        )

    def get_forbidden_levels(self, ob: OrderBook) -> list[float]:
        """Список запрещённых уровней в текущем стакане."""
        forbidden = []
        for lvl in ob.bids + ob.asks:
            if self.is_iceberg(lvl.price):
                forbidden.append(lvl.price)
        return forbidden

    def reset(self) -> None:
        self._data.clear()
        self.iceberg_prices.clear()


# ══════════════════════════════════════════════════════════════════
# ПОЛНЫЙ АНАЛИЗ СТАКАНА — единая точка входа
# ══════════════════════════════════════════════════════════════════

def analyze_order_book(
    ob:               OrderBook,
    prev_ob:          Optional[OrderBook]              = None,
    iceberg_detector: Optional[IcebergDetector_order]        = None,
    ofi_tracker:      Optional[OrderFlowImbalanceTracker] = None,
    order_size:       float                            = 10.0,
    thin_threshold:   float                            = 100.0,
    thick_threshold:  float                            = 1000.0,
    imbalance_threshold: float                         = 0.10,
) -> dict:
    """
    Полный анализ стакана. Вычисляет все метрики пункта 26 и 1.1.
    """
    result = {}

    # 26.1  Mid price
    result["mid_price"] = calc_mid_price(ob)

    # 26.2  Weighted mid price
    result["weighted_mid_price"] = calc_weighted_mid_price(ob)

    # 26.3  VWAP (L2)
    result["vwap"] = calc_vwap(ob)

    # 26.4  Bid-ask spread
    result["spread"] = calc_bid_ask_spread(ob)

    # 26.5  Bid-ask imbalance (best level)
    result["bid_ask_imbalance"] = calc_bid_ask_imbalance(ob)

    # 26.6  Order book imbalance (все уровни)
    result["order_book_imbalance"] = calc_order_book_imbalance(ob)

    # 26.7  Depth levels (price_1/2/3, volume_1/2/3)
    result["depth_levels"] = calc_depth_levels(ob)

    # 26.8  Sweep detection
    result["sweep"] = (
        detect_sweep(prev_ob, ob)
        if prev_ob is not None
        else {"detected": False, "direction": None, "levels_consumed": 0}
    )

    # 26.9  Order flow imbalance
    ofi_val = ofi_tracker.update(ob) if ofi_tracker is not None else None
    result["cumulative_ofi"] = ofi_val

    # 26.10 Price impact
    result["price_impact_buy"]  = calc_price_impact(ob, order_size, "buy")
    result["price_impact_sell"] = calc_price_impact(ob, order_size, "sell")

    # 26.11/12 Thin/thick market + trading risk
    result["market_depth"] = assess_market_depth(ob, thin_threshold, thick_threshold)

    # 26.13 L2 liquidity
    result["l2_liquidity"] = calc_l2_liquidity(ob)

    # 26.14 Direction predictor
    result["direction"] = predict_direction(
        ob,
        ofi_tracker=ofi_tracker,
        imbalance_threshold=imbalance_threshold,
    )

    # 1.1   Iceberg detection
    if iceberg_detector is not None:
        icebergs = iceberg_detector.update(ob)
        result["iceberg_detected"]           = len(icebergs) > 0
        result["iceberg_levels"]             = list(icebergs)
        result["trade_against_iceberg"]      = iceberg_detector.trade_forbidden(ob)
        result["iceberg_forbidden_levels"]   = iceberg_detector.get_forbidden_levels(ob)
        if result["trade_against_iceberg"]:
            result["market_depth"]["trading_risk"] = TradingRisk.FORBIDDEN
    else:
        result["iceberg_detected"]          = False
        result["iceberg_levels"]            = []
        result["trade_against_iceberg"]     = False
        result["iceberg_forbidden_levels"]  = []

    return result


# ══════════════════════════════════════════════════════════════════
# ТЕСТЫ
# ══════════════════════════════════════════════════════════════════

def _make_ob(
    bid_prices = (100.0, 99.5, 99.0),
    bid_vols   = (200.0, 150.0, 100.0),
    ask_prices = (100.5, 101.0, 101.5),
    ask_vols   = (180.0, 120.0,  90.0),
) -> OrderBook:
    bids = [L2Level(p, v) for p, v in zip(bid_prices, bid_vols)]
    asks = [L2Level(p, v) for p, v in zip(ask_prices, ask_vols)]
    return OrderBook(bids=bids, asks=asks)


def run_tests() -> None:
    print("=" * 70)
    print("  ПЕРЕПРОВЕРКА ORDER BOOK ANALYSIS — Пункт 26 + 1.1")
    print("=" * 70)

    ob = _make_ob()
    errors: list[str] = []

    # ── Тест 1: Mid price ───────────────────────────────────────────────
    try:
        mp = calc_mid_price(ob)
        expected = (100.0 + 100.5) / 2
        assert abs(mp - expected) < 1e-9, f"got {mp}, expected {expected}"
        print(f"[OK] 26.1  Mid price                 = {mp:.4f}")
    except Exception as e:
        errors.append(f"26.1 Mid price: {e}")
        print(f"[FAIL] 26.1 Mid price: {e}")

    # ── Тест 2: Weighted mid price ──────────────────────────────────────
    try:
        bp, bv = 100.0, 200.0
        ap, av = 100.5, 180.0
        exp = (bp * av + ap * bv) / (bv + av)
        wmp = calc_weighted_mid_price(ob)
        assert abs(wmp - exp) < 1e-9, f"got {wmp}, expected {exp}"
        print(f"[OK] 26.2  Weighted mid price         = {wmp:.6f}  (formula verified)")
    except Exception as e:
        errors.append(f"26.2 WMP: {e}")
        print(f"[FAIL] 26.2 WMP: {e}")

    # ── Тест 3: VWAP через все уровни ──────────────────────────────────
    try:
        all_lvls = ob.bids + ob.asks
        exp = sum(l.price * l.volume for l in all_lvls) / sum(l.volume for l in all_lvls)
        vwap = calc_vwap(ob)
        assert abs(vwap - exp) < 1e-9, f"got {vwap}, expected {exp}"
        print(f"[OK] 26.3  VWAP (L2 all levels)      = {vwap:.6f}")
    except Exception as e:
        errors.append(f"26.3 VWAP: {e}")
        print(f"[FAIL] 26.3 VWAP: {e}")

    # ── Тест 4: Bid-ask spread ──────────────────────────────────────────
    try:
        s = calc_bid_ask_spread(ob)
        assert abs(s["spread_abs"] - 0.5) < 1e-9, f"spread={s['spread_abs']}"
        exp_pct = 0.5 / 100.25 * 100
        assert abs(s["spread_pct"] - exp_pct) < 1e-9
        print(f"[OK] 26.4  Bid-ask spread             abs={s['spread_abs']:.4f}  pct={s['spread_pct']:.4f}%")
    except Exception as e:
        errors.append(f"26.4 Spread: {e}")
        print(f"[FAIL] 26.4 Spread: {e}")

    # ── Тест 5: Bid-ask imbalance (best level) ─────────────────────────
    try:
        ba = calc_bid_ask_imbalance(ob)
        exp = (200.0 - 180.0) / (200.0 + 180.0)
        assert abs(ba - exp) < 1e-9, f"got {ba}, expected {exp}"
        print(f"[OK] 26.5  Bid-ask imbalance (L1)     = {ba:.6f}  (best level only)")
    except Exception as e:
        errors.append(f"26.5 BA imbalance: {e}")
        print(f"[FAIL] 26.5 BA imbalance: {e}")

    # ── Тест 6: Order book imbalance (все уровни) ──────────────────────
    try:
        obi = calc_order_book_imbalance(ob)
        total_bv = 200 + 150 + 100   # = 450
        total_av = 180 + 120 + 90    # = 390
        exp = (total_bv - total_av) / (total_bv + total_av)  # 60/840
        assert abs(obi - exp) < 1e-9, f"got {obi}, expected {exp}"
        # Проверяем, что OB imbalance ≠ BA imbalance (разные значения)
        ba = calc_bid_ask_imbalance(ob)
        assert abs(obi - ba) > 1e-6, "OB imbalance должен отличаться от BA imbalance!"
        print(f"[OK] 26.6  Order book imbalance (L2)  = {obi:.6f}  (all levels, ≠ L1={ba:.6f})")
    except Exception as e:
        errors.append(f"26.6 OB imbalance: {e}")
        print(f"[FAIL] 26.6 OB imbalance: {e}")

    # ── Тест 7: Depth levels (price_1/2/3, volume_1/2/3) ──────────────
    try:
        d = calc_depth_levels(ob)
        # проверяем все 6 bid + 6 ask полей
        for side, prices, vols in (
            ("bid", (100.0, 99.5, 99.0), (200, 150, 100)),
            ("ask", (100.5, 101.0, 101.5), (180, 120, 90)),
        ):
            for i, (ep, ev) in enumerate(zip(prices, vols), start=1):
                pk = f"{side}_price_{i}"
                vk = f"{side}_volume_{i}"
                assert pk in d, f"Отсутствует ключ {pk}"
                assert vk in d, f"Отсутствует ключ {vk}"
                assert abs(d[pk] - ep) < 1e-9, f"{pk}: {d[pk]} ≠ {ep}"
                assert abs(d[vk] - ev) < 1e-9, f"{vk}: {d[vk]} ≠ {ev}"
        assert abs(d["total_bid_depth"] - 450.0) < 1e-9
        assert abs(d["total_ask_depth"] - 390.0) < 1e-9
        print(f"[OK] 26.7  Depth levels (price/vol 1/2/3)  bid={d['total_bid_depth']} ask={d['total_ask_depth']}")
    except Exception as e:
        errors.append(f"26.7 Depth levels: {e}")
        print(f"[FAIL] 26.7 Depth levels: {e}")

    # ── Тест 8: Sweep detection ─────────────────────────────────────────
    try:
        # ask sweep: new best_ask выше двух старых ask уровней
        swept_ob = _make_ob(ask_prices=(101.6, 102.0, 102.5))
        res = detect_sweep(ob, swept_ob, min_levels_consumed=2)
        assert res["detected"] is True,            f"sweep не обнаружен: {res}"
        assert res["direction"] == "ask_sweep",    f"неверное направление: {res}"
        assert res["levels_consumed"] >= 2,        f"levels_consumed={res['levels_consumed']}, ожидалось >= 2"

        # нет sweep — одинаковый стакан
        res_no = detect_sweep(ob, ob, min_levels_consumed=2)
        assert res_no["detected"] is False, "ложный sweep"

        # bid sweep
        bid_swept = _make_ob(bid_prices=(98.8, 98.3, 97.8))
        res_bid = detect_sweep(ob, bid_swept, min_levels_consumed=2)
        assert res_bid["detected"] is True
        assert res_bid["direction"] == "bid_sweep"

        print(f"[OK] 26.8  Sweep detection             ask_sweep={res['levels_consumed']}lvls  bid_sweep={res_bid['levels_consumed']}lvls")
    except Exception as e:
        errors.append(f"26.8 Sweep: {e}")
        print(f"[FAIL] 26.8 Sweep: {e}")

    # ── Тест 9: Order flow imbalance ────────────────────────────────────
    try:
        tracker = OrderFlowImbalanceTracker(window=5)
        r0 = tracker.update(ob)
        assert r0 is None, f"первый тик должен вернуть None, got {r0}"

        # bid price вырос → delta_bid = new bid_vol_1 = 220
        ob2 = _make_ob(bid_prices=(100.1, 99.5, 99.0), bid_vols=(220, 150, 100),
                       ask_prices=(100.6, 101.0, 101.5), ask_vols=(180, 120, 90))
        r1 = tracker.update(ob2)
        assert r1 is not None
        # ask price вырос (пробил уровень) → delta_ask = -prev_ask_vol = -180
        exp_ofi = 220 - (-180)    # 220 + 180 = 400
        assert abs(r1 - exp_ofi) < 1e-6, f"OFI={r1}, expected={exp_ofi}"

        # cumulative_ofi property
        assert abs(tracker.cumulative_ofi - r1) < 1e-6

        print(f"[OK] 26.9  Order flow imbalance (OFI) = {r1:.2f}  (window={tracker.window})")
    except Exception as e:
        errors.append(f"26.9 OFI: {e}")
        print(f"[FAIL] 26.9 OFI: {e}")

    # ── Тест 10: Price impact ───────────────────────────────────────────
    try:
        # buy: поглощаем 250 из ask (ask_vol_1=180, ask_vol_2=120 → итого 300)
        pi = calc_price_impact(ob, order_size=250.0, side="buy")
        assert abs(pi["filled"] - 250.0) < 1e-9, f"filled={pi['filled']}"
        assert abs(pi["unfilled"] - 0.0)  < 1e-9, f"unfilled={pi['unfilled']}"
        assert pi["levels_consumed"] == 2
        exp_avg = (180 * 100.5 + 70 * 101.0) / 250
        assert abs(pi["avg_fill_price"] - exp_avg) < 1e-9, f"avg={pi['avg_fill_price']}, exp={exp_avg}"
        assert pi["price_impact_abs"] >= 0

        # sell: поглощаем 150 из bid (bid_vol_1=200 → всё в первом уровне)
        ps = calc_price_impact(ob, order_size=150.0, side="sell")
        assert abs(ps["filled"] - 150.0) < 1e-9
        assert ps["levels_consumed"] == 1
        assert abs(ps["avg_fill_price"] - 100.0) < 1e-9

        # нехватка ликвидности: ордер больше всего стакана
        pi_big = calc_price_impact(ob, order_size=9999.0, side="buy")
        assert pi_big["unfilled"] > 0, "должен быть unfilled"
        assert pi_big["levels_consumed"] == len(ob.asks)

        print(f"[OK] 26.10 Price impact buy  avg={pi['avg_fill_price']:.4f} impact={pi['price_impact_pct']:.4f}%")
        print(f"[OK] 26.10 Price impact sell avg={ps['avg_fill_price']:.4f} impact={ps['price_impact_pct']:.4f}%")
    except Exception as e:
        errors.append(f"26.10 Price impact: {e}")
        print(f"[FAIL] 26.10 Price impact: {e}")

    # ── Тест 11/12: Thin & thick market ────────────────────────────────
    try:
        # total depth = 840 > 1000? нет → moderate
        md = assess_market_depth(ob, thin_threshold=100, thick_threshold=1000)
        assert md["is_thin_market"]  is False
        assert md["is_thick_market"] is False
        assert md["trading_risk"] == TradingRisk.MODERATE

        # thin: total = 19 < 100
        thin_ob = _make_ob(bid_vols=(5, 3, 2), ask_vols=(4, 3, 2))
        md_thin = assess_market_depth(thin_ob, thin_threshold=100, thick_threshold=1000)
        assert md_thin["is_thin_market"]  is True
        assert md_thin["trading_risk"]    == TradingRisk.DANGEROUS

        # thick: lower threshold → 840 >= 500
        md_thick = assess_market_depth(ob, thin_threshold=100, thick_threshold=500)
        assert md_thick["is_thick_market"] is True
        assert md_thick["trading_risk"]    == TradingRisk.SAFE

        print(f"[OK] 26.11 Thin market detection      total={md_thin['total_depth']} risk={md_thin['trading_risk']}")
        print(f"[OK] 26.12 Thick market detection     total={md_thick['total_depth']} risk={md_thick['trading_risk']}")
    except Exception as e:
        errors.append(f"26.11/12 Thin/thick: {e}")
        print(f"[FAIL] 26.11/12 Thin/thick: {e}")

    # ── Тест 13: L2 liquidity assessment ───────────────────────────────
    try:
        liq = calc_l2_liquidity(ob)
        assert abs(liq["total_liquidity"] - 840.0) < 1e-9
        assert abs(liq["bid_side_liquidity"] - 450.0) < 1e-9
        assert abs(liq["ask_side_liquidity"] - 390.0) < 1e-9
        assert 0.0 <= liq["liquidity_score"] <= 1.0
        assert liq["weighted_spread"] > 0
        # depth_profile суммируется примерно до 100%
        total_pct = sum(liq["depth_profile"].values())
        assert abs(total_pct - 100.0) < 1e-6, f"depth_profile sum={total_pct}"
        print(f"[OK] 26.13 L2 liquidity               total={liq['total_liquidity']} score={liq['liquidity_score']:.4f}")
    except Exception as e:
        errors.append(f"26.13 L2 liquidity: {e}")
        print(f"[FAIL] 26.13 L2 liquidity: {e}")

    # ── Тест 14: Direction predictor ────────────────────────────────────
    try:
        # ob: bid_vol=200, ask_vol=180 → BA imbalance > 0 → bullish
        dp = predict_direction(ob, imbalance_threshold=0.01)
        assert dp["direction"] in (Direction.BULLISH, Direction.NEUTRAL)
        assert 0.0 <= dp["confidence"] <= 1.0

        # явно bullish стакан: bid намного больше ask
        bull_ob = _make_ob(bid_vols=(500, 400, 300), ask_vols=(50, 40, 30))
        dp_bull = predict_direction(bull_ob, imbalance_threshold=0.05)
        assert dp_bull["direction"] == Direction.BULLISH, f"expected BULLISH, got {dp_bull['direction']}"

        # явно bearish стакан
        bear_ob = _make_ob(bid_vols=(50, 40, 30), ask_vols=(500, 400, 300))
        dp_bear = predict_direction(bear_ob, imbalance_threshold=0.05)
        assert dp_bear["direction"] == Direction.BEARISH, f"expected BEARISH, got {dp_bear['direction']}"

        # нейтральный стакан
        neut_ob = _make_ob(bid_vols=(200, 150, 100), ask_vols=(200, 150, 100))
        dp_neut = predict_direction(neut_ob, imbalance_threshold=0.05)
        assert dp_neut["direction"] == Direction.NEUTRAL

        print(f"[OK] 26.14 Direction predictor         BULL={dp_bull['direction']} BEAR={dp_bear['direction']} NEUT={dp_neut['direction']}")
    except Exception as e:
        errors.append(f"26.14 Direction: {e}")
        print(f"[FAIL] 26.14 Direction: {e}")

    # ── Тест 15: 1.1 Все 3 уровня bid/ask (price_1/2/3, volume_1/2/3) ─
    try:
        assert ob.bid_price_1  == 100.0
        assert ob.bid_price_2  == 99.5
        assert ob.bid_price_3  == 99.0
        assert ob.bid_volume_1 == 200.0
        assert ob.bid_volume_2 == 150.0
        assert ob.bid_volume_3 == 100.0
        assert ob.ask_price_1  == 100.5
        assert ob.ask_price_2  == 101.0
        assert ob.ask_price_3  == 101.5
        assert ob.ask_volume_1 == 180.0
        assert ob.ask_volume_2 == 120.0
        assert ob.ask_volume_3 == 90.0
        print(f"[OK] 1.1   Все 3 уровня (price/vol 1/2/3)  bid_price_1={ob.bid_price_1}..{ob.bid_price_3}  ask_price_1={ob.ask_price_1}..{ob.ask_price_3}")
    except Exception as e:
        errors.append(f"1.1 3 levels: {e}")
        print(f"[FAIL] 1.1 3 levels: {e}")

    # ── Тест 16: 1.1 Iceberg detection ─────────────────────────────────
    try:
        det = IcebergDetector_order(refill_threshold=2, min_drop_ratio=0.05)

        # шаг 1: инициализация
        det.update(_make_ob(ask_vols=(180, 120, 90)))
        # шаг 2: объём упал (исполнение)
        det.update(_make_ob(ask_vols=(100, 120, 90)))
        # шаг 3: восстановился (refill #1)
        det.update(_make_ob(ask_vols=(180, 120, 90)))
        # шаг 4: снова упал
        det.update(_make_ob(ask_vols=(70, 120, 90)))
        # шаг 5: снова восстановился (refill #2) → ICEBERG!
        ob_final = _make_ob(ask_vols=(180, 120, 90))
        icebergs = det.update(ob_final)

        assert 100.5 in icebergs, f"iceberg не обнаружен на 100.5, icebergs={icebergs}"
        assert det.is_iceberg(100.5)
        assert det.trade_forbidden(ob_final), "торговля должна быть запрещена"

        # forbidden_levels содержит 100.5
        fl = det.get_forbidden_levels(ob_final)
        assert 100.5 in fl, f"100.5 отсутствует в forbidden_levels: {fl}"

        print(f"[OK] 1.1   Iceberg detection          price=100.5  forbidden={det.trade_forbidden(ob_final)}")
    except Exception as e:
        errors.append(f"1.1 Iceberg: {e}")
        print(f"[FAIL] 1.1 Iceberg: {e}")

    # ── Тест 17: 1.1 Торговля против iceberg ЗАПРЕЩЕНА ─────────────────
    try:
        det2 = IcebergDetector_order(refill_threshold=1, min_drop_ratio=0.05)
        det2.update(_make_ob(bid_vols=(200, 150, 100)))
        det2.update(_make_ob(bid_vols=(100, 150, 100)))
        det2.update(_make_ob(bid_vols=(200, 150, 100)))

        ob_with_iceberg = _make_ob(bid_vols=(200, 150, 100))
        icebergs2 = det2.update(ob_with_iceberg)
        assert 100.0 in icebergs2, f"bid iceberg не обнаружен, icebergs={icebergs2}"

        forbidden = det2.trade_forbidden(ob_with_iceberg)
        assert forbidden is True, "торговля против bid iceberg должна быть запрещена"
        print(f"[OK] 1.1   Торговля против iceberg    ЗАПРЕЩЕНА (bid 100.0)")
    except Exception as e:
        errors.append(f"1.1 Iceberg forbidden: {e}")
        print(f"[FAIL] 1.1 Iceberg forbidden: {e}")

    # ── Тест 18: analyze_order_book — все ключи присутствуют ───────────
    try:
        ofi  = OrderFlowImbalanceTracker(window=10)
        ice  = IcebergDetector_order()
        full = analyze_order_book(ob, iceberg_detector=ice, ofi_tracker=ofi, order_size=50.0)

        required = [
            "mid_price", "weighted_mid_price", "vwap",
            "spread", "bid_ask_imbalance", "order_book_imbalance",
            "depth_levels", "sweep",
            "cumulative_ofi",
            "price_impact_buy", "price_impact_sell",
            "market_depth", "l2_liquidity", "direction",
            "iceberg_detected", "iceberg_levels",
            "trade_against_iceberg", "iceberg_forbidden_levels",
        ]
        for k in required:
            assert k in full, f"Ключ '{k}' отсутствует"

        # bid_ask_imbalance ≠ order_book_imbalance (разные значения)
        assert abs(full["bid_ask_imbalance"] - full["order_book_imbalance"]) > 1e-6

        print(f"[OK] Полный анализ                   все {len(required)} ключей  "
              f"BA_imb≠OB_imb: {full['bid_ask_imbalance']:.4f}≠{full['order_book_imbalance']:.4f}")
    except Exception as e:
        errors.append(f"Full analysis: {e}")
        print(f"[FAIL] Full analysis: {e}")

    # ── Валидация OrderBook ─────────────────────────────────────────────
    try:
        import traceback as _tb
        caught = 0
        # bids не отсортированы → ошибка
        try:
            _ = OrderBook(
                bids=[L2Level(99.0, 100), L2Level(100.0, 200)],
                asks=[L2Level(101.0, 180)],
            )
        except ValueError:
            caught += 1
        # best_bid >= best_ask → ошибка
        try:
            _ = OrderBook(
                bids=[L2Level(101.0, 100)],
                asks=[L2Level(100.5, 180)],
            )
        except ValueError:
            caught += 1
        assert caught == 2, f"Ожидалось 2 ошибки валидации, получено {caught}"
        print(f"[OK] Валидация OrderBook             {caught}/2 некорректных книг отклонены")
    except Exception as e:
        errors.append(f"Validation: {e}")
        print(f"[FAIL] Validation: {e}")

    # ── Итог ────────────────────────────────────────────────────────────
    total = 18
    passed = total - len(errors)
    print("=" * 70)
    if errors:
        print(f"ПРОЙДЕНО {passed}/{total}. ОШИБКИ ({len(errors)}):")
        for err in errors:
            print(f"  ✗ {err}")
    else:
        print(f"ВСЕ {total} ТЕСТОВ ПРОЙДЕНЫ — ОШИБОК НЕТ ✓")
    print("=" * 70)


if __name__ == "__main__":
    run_tests()

