# --- [6.1] Sunlight ---
SUNLIGHT_CALIBRATION_TICKS  = 10_000  # [6.1] калибровка порога на первых 10k тиков
SUNLIGHT_FIELD               = "sunlight"  # [6.1] state.observations — проверить поле

# --- [6.1] Dolphin ---
DOLPHIN_SIGNAL_THRESHOLD     = 5      # [6.1] ±5 и более = реальный сигнал
DOLPHIN_NOISE_THRESHOLD      = 2      # [6.1] ±2 = шум, игнорировать
DOLPHIN_DECAY_TICKS          = 500    # [6.1] сигнал действует ~500 тиков
DOLPHIN_FIELD                = "dolphin_sightings"  # [6.1] проверить точное поле

# --- [6.1] Sugar/transport ---
REGRESSION_RECALC_INTERVAL   = 500    # [6.1] пересчитывать каждые 500 тиков

# --- [6.2] Time-of-day ---
TOD_BUCKET_SIZE              = 1000   # [6.2] bucket по 1000 тиков
TOD_SIGMA_THRESHOLD          = 2.0    # [6.2] > 2σ → предсказуемый паттерн
TOD_COLD_START_TICKS         = 1000   # [6.2] cold start: первые 1000 тиков

# --- [6.2] Intra-round trend ---
TREND_OLS_TICKS              = 200_000  # [6.2] OLS на первых 200k тиков
TREND_R2_START               = 0.7      # [6.2] R² > 0.7 → торговать
TREND_R2_STOP                = 0.5      # [6.2] R² < 0.5 → остановить
TREND_SLOPE_THRESHOLD        = 1e-4     # [6.2] |slope| > threshold

# --- [6.2] Fourier ---
FFT_MIN_PERIODS              = 2       # [6.2] мин. история: не менее 2 полных периодов

# --- [6.3] Cross-year ---
CROSS_YEAR_R2_DIRECT         = 0.95   # [6.3] R² > 0.95 → прямой сигнал
CROSS_YEAR_R2_TIMING         = 0.70   # [6.3] R² > 0.7 → pattern timing
CROSS_YEAR_R2_IGNORE         = 0.30   # [6.3] R² < 0.3 → игнорировать
CROSS_YEAR_ROLLING_WINDOW    = 1000   # [6.3] rolling corr window = 1000 тиков
CROSS_YEAR_ROLLING_MIN       = 0.30   # [6.3] rolling_corr < 0.3 → отключить
CROSS_YEAR_MAE_SIGMA         = 3.0    # [6.3] MAE > 3σ → снизить вес
CROSS_YEAR_GITHUB_QUERY      = "IMC Prosperity trading sort:stars"  # [6.3]

# --- [6.4] Negative list ---
NEGATIVE_MIN_CONFIRMATIONS   = 50     # [6.4] мин. 50 независимых подтверждений
NEGATIVE_R2_MIN              = 0.30   # [6.4] R² < 0.3 → не использовать
EDGE_DECAY_DAYS              = 2      # [6.4] bot-сигнал падает после 1-2 дней


