@dataclass
class SunlightState:
    """[6.5] Sunlight index state."""
    current_value: float = 0.0          # [6.5] текущее значение
    threshold_crossed: bool = False     # [6.5] флаг пересечения порога
    calibrated_threshold: float = 0.0  # [6.1] откалиброванный порог
    calibration_values: List[float] = field(default_factory=list)
    calibration_done: bool = False
    active: bool = True                 # [6.1] если не пересекался → False


@dataclass
class DolphinState:
    """[6.5] Dolphin signal state."""
    current_strength: float = 0.0      # [6.5] текущая сила сигнала
    last_event_tick: int = -1          # [6.5] timestamp последнего события
    last_event_value: float = 0.0
    accumulated_signal: float = 0.0   # [6.1] суммированный с decay
    decay_type: str = "linear"         # [6.1] linear или exponential


@dataclass
class RegressionState:
    """[6.5] Sugar/transport regression state."""
    coef_a: float = 0.0   # [6.5] / [6.1] коэффициент a
    coef_b: float = 0.0   # [6.5] / [6.1] коэффициент b
    coef_c: float = 0.0   # [6.5] / [6.1] коэффициент c
    last_recalc_tick: int = 0
    sugar_history:     List[float] = field(default_factory=list)
    transport_history: List[float] = field(default_factory=list)
    price_history:     List[float] = field(default_factory=list)


@dataclass
class TimeOfDayState:
    """[6.5] Time-of-day avg_price buckets."""
    buckets: Dict[int, List[float]] = field(default_factory=dict)  # [6.5]
    bucket_means: Dict[int, float] = field(default_factory=dict)
    global_mean: float = 0.0
    global_std: float = 1.0
    total_observations: int = 0


@dataclass
class TrendState:
    """[6.5] Intra-round trend slope and R²."""
    slope: float = 0.0          # [6.5] текущий slope
    r2: float = 0.0             # [6.5] текущий R²
    intercept: float = 0.0
    active: bool = False        # следуем тренду или нет
    sign_changed: bool = False  # [6.2] slope сменил знак


@dataclass
class FFTState:
    """[6.5] FFT dominant_period."""
    dominant_period: float = 0.0    # [6.5] текущий
    amplitudes: List[float] = field(default_factory=list)
    periods: List[float] = field(default_factory=list)
    weights: List[float] = field(default_factory=list)  # [6.2] веса по амплитуде
    stable: bool = False            # [6.2] стабилен между годами


@dataclass
class CrossYearProductState:
    """[6.5] Cross-year state per product."""
    rolling_correlation: float = 0.0   # [6.5] rolling correlation текущий
    signal_weight: float = 1.0         # [6.5] текущий вес сигнала
    r2: float = 0.0
    lookup_table: List[float] = field(default_factory=list)  # [6.3] предвычисленный
    mae_history: List[float] = field(default_factory=list)
    recent_prices: List[float] = field(default_factory=list)
    year_prices: Dict[str, List[float]] = field(default_factory=dict)


@dataclass
class PatternState:
    """
    Главный pattern state — сериализуется в traderData.   [6.5]
    """
    sunlight: SunlightState = field(default_factory=SunlightState)
    dolphin: DolphinState = field(default_factory=DolphinState)
    regression: RegressionState = field(default_factory=RegressionState)
    tod: TimeOfDayState = field(default_factory=TimeOfDayState)
    trend: TrendState = field(default_factory=TrendState)
    fft: FFTState = field(default_factory=FFTState)
    cross_year: Dict[str, CrossYearProductState] = field(default_factory=dict)
    global_tick: int = 0

    def get_cross_year(self, product: str) -> CrossYearProductState:
        if product not in self.cross_year:
            self.cross_year[product] = CrossYearProductState()
        return self.cross_year[product]


# ==============================================================================
# SECTION 3 — SUNLIGHT SIGNAL  [6.1]
# ==============================================================================

class SunlightSignal:
    """
    Sunlight index.                                                [6.1]
    Источник: state.observations — проверить точное поле.        [6.1]
    Пересечение порога → резкий price jump.                      [6.1]
    Стратегия: ставить ордер ДО пересечения порога.              [6.1]
    Калибровка порога: первые 10k тиков раунда.                  [6.1]
    Если не пересекается весь раунд → не использовать.           [6.1]
    """

    def read_from_observations(self, observations: object) -> Optional[float]:
        """
        [6.1] Поступает через state.observations.
        Проверить точное поле в документации раунда.
        """
        if observations is None:
            return None
        # [6.1] Проверить точное поле в документации раунда
        value = getattr(observations, SUNLIGHT_FIELD, None)
        if value is None:
            # Альтернативные поля — проверять документацию
            for attr in ["sunlightIndex", "sunlight_index", "SunlightIndex"]:
                value = getattr(observations, attr, None)
                if value is not None:
                    break
        return float(value) if value is not None else None

    def calibrate(self, sl: SunlightState, value: float, tick: int) -> None:
        """
        [6.1] Калибровка порога на первых 10k тиков раунда.
        """
        if tick <= SUNLIGHT_CALIBRATION_TICKS:
            sl.calibration_values.append(value)
        elif not sl.calibration_done and sl.calibration_values:
            # Порог = 90-й перцентиль наблюдённых значений
            sorted_vals = sorted(sl.calibration_values)
            idx = int(len(sorted_vals) * 0.90)
            sl.calibrated_threshold = sorted_vals[idx]
            sl.calibration_done = True

    def update(
        self, sl: SunlightState, value: float, tick: int
    ) -> Optional[str]:
        """
        Обновляет state и возвращает сигнал ("buy_before_jump" / None).
        [6.1] Ставить ордер ДО пересечения порога.
        """
        self.calibrate(sl, value, tick)
        sl.current_value = value

        if not sl.calibration_done:
            return None

        # [6.1] Детектируем приближение к порогу — ставим ДО
        approach_zone = sl.calibrated_threshold * 0.95
        if value >= approach_zone and not sl.threshold_crossed:
            return "buy_before_jump"

        if value >= sl.calibrated_threshold:
            sl.threshold_crossed = True

        # [6.1] Если порог не пересёкся → не использовать
        if tick > SUNLIGHT_CALIBRATION_TICKS and not sl.threshold_crossed:
            sl.active = False

        return None

    def is_active(self, sl: SunlightState, tick: int) -> bool:
        """[6.1] Если не пересекался весь раунд → не использовать."""
        return sl.active

    def get_regime_strategy(self, sunlight_value: float, sl: SunlightState = None,
                             threshold: float = None) -> str:
        """Return strategy name based on sunlight threshold.
        Below threshold: mean_reversion (low sunlight = stable prices)
        Above threshold: momentum (high sunlight = trending)"""
        effective_threshold = threshold
        if effective_threshold is None and sl is not None:
            if not sl.calibration_done or sl.calibrated_threshold == 0.0:
                return "default"
            effective_threshold = sl.calibrated_threshold
        if effective_threshold is None:
            return "default"
        if sunlight_value < effective_threshold * 0.9:
            return "mean_reversion"
        elif sunlight_value > effective_threshold * 1.1:
            return "momentum"
        else:
            return "neutral"


# ==============================================================================
# SECTION 4 — DOLPHIN SIGNAL  [6.1]
# ==============================================================================

class DolphinSignal:
    """
    Dolphin sightings.                                             [6.1]
    Источник: state.observations — проверить точное поле.        [6.1]
    ±5 и более = реальный сигнал; ±2 = шум, игнорировать.       [6.1]
    +5 = buy, −5 = sell.                                          [6.1]
    Decay: ~500 тиков.                                            [6.1]
    Линейное или экспоненциальное убывание — калибровать.        [6.1]
    Несколько событий: брать последнее или суммировать.          [6.1]
    """

    def read_from_observations(self, observations: object) -> Optional[float]:
        """[6.1] Проверить точное поле в документации раунда."""
        if observations is None:
            return None
        value = getattr(observations, DOLPHIN_FIELD, None)
        if value is None:
            for attr in ["dolphinSightings", "dolphin", "DolphinSightings"]:
                value = getattr(observations, attr, None)
                if value is not None:
                    break
        return float(value) if value is not None else None

    def update(
        self, ds: DolphinState, raw_value: float, current_tick: int
    ) -> Optional[str]:
        """
        Обновляет dolphin state, возвращает "buy" / "sell" / None.
        [6.1] ±5 реальный, ±2 шум.
        [6.1] Несколько событий: суммировать с decay.
        """
        # [6.1] ±2 = шум, игнорировать
        if abs(raw_value) < DOLPHIN_SIGNAL_THRESHOLD:
            if abs(raw_value) <= DOLPHIN_NOISE_THRESHOLD:
                pass  # [6.1] игнорировать шум
            # Промежуток 2-5: тоже игнорировать

        # [6.1] ±5 реальный сигнал
        if abs(raw_value) >= DOLPHIN_SIGNAL_THRESHOLD:
            # [6.1] Несколько событий подряд — суммировать с decay
            if ds.last_event_tick >= 0:
                ticks_elapsed = current_tick - ds.last_event_tick
                decayed = self._apply_decay(ds.last_event_value, ticks_elapsed, ds.decay_type)
                ds.accumulated_signal = decayed + raw_value
            else:
                ds.accumulated_signal = raw_value
            ds.last_event_value = raw_value
            ds.last_event_tick = current_tick

        # Decay текущего накопленного сигнала
        if ds.last_event_tick >= 0:
            ticks_since = current_tick - ds.last_event_tick
            ds.current_strength = self._apply_decay(
                ds.accumulated_signal, ticks_since, ds.decay_type
            )
        else:
            ds.current_strength = 0.0

        # [6.1] +5 buy, -5 sell
        if ds.current_strength >= DOLPHIN_SIGNAL_THRESHOLD:
            return "buy"
        if ds.current_strength <= -DOLPHIN_SIGNAL_THRESHOLD:
            return "sell"
        return None

    def _apply_decay(self, signal: float, ticks: int, decay_type: str) -> float:
        """
        [6.1] Линейное или экспоненциальное убывание — калибровать.
        """
        if ticks >= DOLPHIN_DECAY_TICKS:
            return 0.0
        frac = ticks / DOLPHIN_DECAY_TICKS
        if decay_type == "linear":
            return signal * (1.0 - frac)
        else:  # exponential
            return signal * math.exp(-3.0 * frac)


# ==============================================================================
# SECTION 5 — SUGAR/TRANSPORT REGRESSION  [6.1]
# ==============================================================================

class SugarTransportRegression:
    """
    Sugar/transport cost корреляция для MACARONS-типа.             [6.1]
    price = a×sugar + b×transport + c.                             [6.1]
    Регрессия на данных раунда → fair value.                       [6.1]
    Пересчитывать каждые 500 тиков.                                [6.1]
    Коэффициенты a, b, c хранить в traderData.                    [6.1] / [6.5]
    Другие внешние индексы: проверять документацию каждого раунда.[6.1]
    """

    def update(
        self,
        rs: RegressionState,
        sugar: float,
        transport: float,
        price: float,
        tick: int,
    ) -> None:
        """Добавляет наблюдение и пересчитывает если нужно."""
        rs.sugar_history.append(sugar)
        rs.transport_history.append(transport)
        rs.price_history.append(price)
        # Ограничиваем историю
        if len(rs.price_history) > 5000:
            rs.sugar_history     = rs.sugar_history[-5000:]
            rs.transport_history = rs.transport_history[-5000:]
            rs.price_history     = rs.price_history[-5000:]

        # [6.1] Пересчитывать каждые 500 тиков
        if tick - rs.last_recalc_tick >= REGRESSION_RECALC_INTERVAL:
            self._fit(rs)
            rs.last_recalc_tick = tick

    def _fit(self, rs: RegressionState) -> None:
        """OLS для price = a×sugar + b×transport + c."""
        n = len(rs.price_history)
        if n < 10:
            return
        # Design matrix X = [[1, sugar, transport], ...], y = price
        # Solve via normal equations: (X'X)^-1 X'y
        s  = rs.sugar_history
        t  = rs.transport_history
        y  = rs.price_history
        # Sums
        n_f = float(n)
        s1  = sum(s);    s2 = sum(t);    s3 = sum(y)
        s11 = sum(si**2 for si in s)
        s22 = sum(ti**2 for ti in t)
        s12 = sum(s[i]*t[i] for i in range(n))
        s13 = sum(s[i]*y[i] for i in range(n))
        s23 = sum(t[i]*y[i] for i in range(n))
        # 3×3 system [intercept c, coef_a, coef_b]
        A = [
            [n_f, s1,  s2 ],
            [s1,  s11, s12],
            [s2,  s12, s22],
        ]
        b_vec = [s3, s13, s23]
        sol = _solve3x3(A, b_vec)
        if sol:
            rs.coef_c, rs.coef_a, rs.coef_b = sol  # [6.5] a, b, c в traderData

    def fair_value(self, rs: RegressionState, sugar: float, transport: float) -> float:
        """[6.1] price = a×sugar + b×transport + c"""
        return rs.coef_a * sugar + rs.coef_b * transport + rs.coef_c


# ==============================================================================
# SECTION 6 — TIME-OF-DAY  [6.2]
# ==============================================================================

class TimeOfDayAnalyzer:
    """
    Time-of-day паттерны.                                          [6.2]
    Средняя цена в bucket по 1000 тиков.                          [6.2]
    Обновлять онлайн инкрементально.                              [6.2]
    Хранить в traderData.                                          [6.2]
    > 2σ от общего среднего → предсказуемый паттерн.             [6.2]
    Cold start: первые 1000 тиков → кросс-годовые данные.        [6.2]
    """

    def update(self, tod: TimeOfDayState, price: float, tick: int) -> None:
        """[6.2] Онлайн инкрементальное обновление (онлайн инкрементальное обновление) buckets."""
        bucket_id = tick // TOD_BUCKET_SIZE

        if bucket_id not in tod.buckets:
            tod.buckets[bucket_id] = []
        tod.buckets[bucket_id].append(price)

        # [6.2] Обновить global mean/std инкрементально
        tod.total_observations += 1
        delta = price - tod.global_mean
        tod.global_mean += delta / tod.total_observations

        # Обновить bucket mean
        bucket = tod.buckets[bucket_id]
        tod.bucket_means[bucket_id] = sum(bucket) / len(bucket)

        # Обновить global std
        if tod.total_observations > 1:
            all_means = list(tod.bucket_means.values())
            if all_means:
                m = sum(all_means) / len(all_means)
                var = sum((x - m)**2 for x in all_means) / len(all_means)
                tod.global_std = math.sqrt(var) if var > 0 else 1.0

    def get_signal(
        self,
        tod: TimeOfDayState,
        tick: int,
        cross_year_buckets: Optional[Dict[int, float]] = None,
    ) -> Optional[float]:
        """
        [6.2] Если avg_price[t] отклоняется > 2σ → предсказуемый паттерн.
        [6.2] Cold start: первые 1000 тиков → кросс-годовые данные.
        """
        bucket_id = tick // TOD_BUCKET_SIZE

        # [6.2] Cold start
        if tick < TOD_COLD_START_TICKS:
            if cross_year_buckets and bucket_id in cross_year_buckets:
                return cross_year_buckets[bucket_id]  # [6.2] кросс-годовые
            return None

        mean = tod.bucket_means.get(bucket_id, tod.global_mean)
        if tod.global_std <= 0:
            return None

        z = (mean - tod.global_mean) / tod.global_std
        # [6.2] > 2σ → предсказуемый паттерн
        if abs(z) > TOD_SIGMA_THRESHOLD:
            return mean
        return None

    def validate_with_cross_year(
        self,
        tod: TimeOfDayState,
        cross_year_buckets: Dict[int, float],
    ) -> bool:
        """
        [6.4] Time-of-day паттерн без подтверждения из кросс-годовых → не использовать.
        """
        if not cross_year_buckets or not tod.bucket_means:
            return False
        common = set(tod.bucket_means.keys()) & set(cross_year_buckets.keys())
        if len(common) < 5:
            return False
        corr = _pearson_patterns(
            [tod.bucket_means[k] for k in common],
            [cross_year_buckets[k] for k in common],
        )
        return corr > 0.5


# ==============================================================================
# SECTION 7 — INTRA-ROUND TREND  [6.2]
# ==============================================================================

class IntraRoundTrend:
    """
    Intra-round trend.                                             [6.2]
    OLS на первых 200k тиков.                                     [6.2]
    |slope| > threshold и R² > 0.7 → торговать.                  [6.2]
    Sizing уменьшается по мере продвижения.                      [6.2]
    Slope меняет знак → остановить.                               [6.2]
    R² < 0.5 → остановить.                                        [6.2]
    """

    def update(self, ts: TrendState, prices: List[float], tick: int) -> None:
        """OLS slope и R² по истории цен."""
        n = len(prices)
        if n < 20:
            return

        window = prices[-min(n, TREND_OLS_TICKS):]
        slope, intercept, r2 = _ols(window)

        # [6.2] Slope меняет знак в середине раунда → остановить
        if ts.slope != 0 and (slope * ts.slope < 0):
            ts.sign_changed = True
            ts.active = False

        prev_slope = ts.slope
        ts.slope     = slope
        ts.intercept = intercept
        ts.r2        = r2

        # [6.2] R² < 0.5 → остановить
        if r2 < TREND_R2_STOP:
            ts.active = False
            return

        # [6.2] |slope| > threshold и R² > 0.7 → торговать
        if abs(slope) > TREND_SLOPE_THRESHOLD and r2 > TREND_R2_START:
            ts.active = True

    def get_signal(self, ts: TrendState) -> Optional[str]:
        """Возвращает "buy" / "sell" / None."""
        if not ts.active or ts.sign_changed:
            return None
        if ts.slope > TREND_SLOPE_THRESHOLD:
            return "buy"
        if ts.slope < -TREND_SLOPE_THRESHOLD:
            return "sell"
        return None

    def get_sizing_multiplier(self, ts: TrendState, tick: int) -> float:
        """
        [6.2] Sizing уменьшается по мере продвижения по тренду.
        """
        if not ts.active:
            return 0.0
        progress = min(1.0, tick / TREND_OLS_TICKS)
        return max(0.1, 1.0 - progress * 0.8)


# ==============================================================================
# SECTION 8 — FOURIER DECOMPOSITION  [6.2]
# ==============================================================================

class FourierAnalyzer:
    """
    Fourier decomposition для цикличности.                         [6.2]
    dominant_period = 1 / fft.argmax().                           [6.2]
    Мин. история: не менее 2 полных периодов.                     [6.2]
    Несколько доминирующих → использовать все с весами.           [6.2]
    Нестабильный между годами → не использовать.                 [6.2]
    Buy в low phase, sell в high phase.                           [6.2]
    """

    def compute(self, fs: FFTState, prices: List[float]) -> None:
        """
        [6.2] DFT без numpy — O(N²) для демонстрации.
        В production использовать numpy.fft.fft.
        """
        n = len(prices)
        if n < 10:
            return

        mean = sum(prices) / n
        centered = [p - mean for p in prices]

        # Compute DFT magnitudes
        magnitudes = []
        for k in range(1, n // 2):
            re = sum(centered[j] * math.cos(2*math.pi*k*j/n) for j in range(n))
            im = sum(centered[j] * math.sin(2*math.pi*k*j/n) for j in range(n))
            magnitudes.append((math.sqrt(re**2 + im**2), k))

        if not magnitudes:
            return

        # [6.2] dominant_period = 1 / fft.argmax() — самая большая амплитуда
        magnitudes.sort(reverse=True)
        top = magnitudes[:5]   # топ-5 частот

        total_amp = sum(m for m, _ in top)
        if total_amp <= 0:
            return

        # [6.2] Несколько доминирующих периодов — использовать все с весами по амплитуде
        fs.periods  = [n / k for _, k in top]
        fs.amplitudes = [m for m, _ in top]
        fs.weights  = [m / total_amp for m, _ in top]  # [6.2] веса по амплитуде
        fs.dominant_period = fs.periods[0]  # [6.5]

        # [6.2] Мин. история: 2 полных периода
        if n < FFT_MIN_PERIODS * fs.dominant_period:
            fs.dominant_period = 0.0

    def get_phase_signal(
        self, fs: FFTState, tick: int
    ) -> Optional[str]:
        """
        [6.2] Buy в low phase, sell в high phase.
        [6.4] Нестабильный период → не использовать.
        """
        if not fs.stable:
            return None  # [6.2] нестабилен между годами → не использовать
        if fs.dominant_period <= 0:
            return None

        # Взвешенная фаза по всем периодам [6.2]
        signal = 0.0
        for period, weight in zip(fs.periods, fs.weights):
            if period <= 0:
                continue
            phase = 2 * math.pi * tick / period
            signal += weight * math.sin(phase)

        # [6.2] Low phase → buy, high phase → sell
        if signal < -0.5:
            return "buy"
        if signal > 0.5:
            return "sell"
        return None

    def check_stability(
        self,
        fs: FFTState,
        historical_periods: List[float],
        tolerance: float = 0.20,
    ) -> bool:
        """
        [6.2] / [6.4] Если dominant_period нестабилен между годами → не использовать.
        """
        if not historical_periods or fs.dominant_period <= 0:
            fs.stable = False
            return False
        deviations = [
            abs(p - fs.dominant_period) / fs.dominant_period
            for p in historical_periods if p > 0
        ]
        fs.stable = all(d < tolerance for d in deviations)
        return fs.stable


# ==============================================================================
# SECTION 9 — CROSS-YEAR PATTERNS  [6.3]
# ==============================================================================

class CrossYearAnalyzer_full:
    """
    Кросс-годовые паттерны.                                        [6.3]
    Данные Prosperity 1,2,3 с GitHub до старта.                   [6.3]
    Поиск: "IMC Prosperity trading" sort:stars.                   [6.3]
    Z-score нормализация отдельно каждый продукт каждый год.     [6.3]
    Robust normalization (median/IQR) при изменённом распределении.[6.3]
    Temporal alignment: % раунда 0–100%.                          [6.3]
    Если данные неполные → только доступный период.               [6.3]
    Pearson / Spearman / Returns / Cross-corr / DTW / Cointegration.[6.3]
    R²>0.95 прямой; R²>0.7 timing; R²<0.3 игнорировать.          [6.3]
    Взвешивание: decay — новые годы весят больше.                 [6.3]
    Lookup table предвычисленный до старта.                       [6.3]
    Online correction: MAE>3σ → снизить вес.                      [6.3]
    Correlation matrix over time.                                  [6.3]
    Rolling corr window = 1000 тиков.                             [6.3]
    rolling_corr < 0.3 → отключить.                              [6.3]
    """

    def zscore_normalize(self, prices: List[float]) -> List[float]:
        """[6.3] Z-score нормализация отдельно для каждого продукта каждого года."""
        if len(prices) < 2:
            return prices
        mean = sum(prices) / len(prices)
        std = _std_val(prices)
        if std == 0:
            return [0.0] * len(prices)
        return [(p - mean) / std for p in prices]

    def robust_normalize(self, prices: List[float]) -> List[float]:
        """[6.3] Робастная нормализация (median/IQR) при изменённом распределении."""
        if len(prices) < 4:
            return prices
        sorted_p = sorted(prices)
        n = len(sorted_p)
        median = sorted_p[n // 2]
        q1 = sorted_p[n // 4]
        q3 = sorted_p[3 * n // 4]
        iqr = q3 - q1
        if iqr == 0:
            return [0.0] * n
        return [(p - median) / iqr for p in prices]

    def temporal_align(
        self, prices: List[float], target_length: int
    ) -> List[float]:
        """
        [6.3] Temporal alignment: % раунда (0–100%), не абсолютный timestamp.
        [6.3] Если данные неполные → использовать только доступный период.
        """
        if not prices:
            return []
        n = len(prices)
        if n == target_length:
            return prices
        # Линейная интерполяция до target_length
        result = []
        for i in range(target_length):
            frac = i / max(1, target_length - 1)
            idx_f = frac * (n - 1)
            idx_lo = int(idx_f)
            idx_hi = min(idx_lo + 1, n - 1)
            w = idx_f - idx_lo
            result.append(prices[idx_lo] * (1 - w) + prices[idx_hi] * w)
        return result

    def pearson_correlation(self, x: List[float], y: List[float]) -> float:
        """[6.3] Pearson: линейная корреляция уровней."""
        return _pearson_patterns(x, y)

    def spearman_correlation(self, x: List[float], y: List[float]) -> float:
        """[6.3] Spearman: ранговая, устойчивее к outliers."""
        if len(x) != len(y) or len(x) < 2:
            return 0.0
        rx = _ranks(x)
        ry = _ranks(y)
        return _pearson_patterns(rx, ry)

    def returns_correlation(self, x: List[float], y: List[float]) -> float:
        """[6.3] Returns correlation: лучше для торговли."""
        if len(x) < 2 or len(y) < 2:
            return 0.0
        rx = [x[i] - x[i-1] for i in range(1, len(x))]
        ry = [y[i] - y[i-1] for i in range(1, len(y))]
        min_len = min(len(rx), len(ry))
        return _pearson_patterns(rx[:min_len], ry[:min_len])

    def cross_correlation(
        self, x: List[float], y: List[float], max_lag: int = 20
    ) -> Tuple[float, int]:
        """[6.3] Cross-correlation: временной лаг между годами."""
        best_corr, best_lag = 0.0, 0
        for lag in range(-max_lag, max_lag + 1):
            if lag >= 0:
                xs, ys = x[:len(x)-lag] if lag > 0 else x, y[lag:] if lag > 0 else y
            else:
                xs, ys = x[-lag:], y[:len(y)+lag]
            min_len = min(len(xs), len(ys))
            if min_len < 5:
                continue
            c = _pearson_patterns(xs[:min_len], ys[:min_len])
            if abs(c) > abs(best_corr):
                best_corr, best_lag = c, lag
        return best_corr, best_lag

    def dtw_distance(self, x: List[float], y: List[float]) -> float:
        """[6.3] DTW (dynamic time warping): нелинейное выравнивание."""
        n, m = len(x), len(y)
        if n == 0 or m == 0:
            return float("inf")
        # DP matrix
        dp = [[float("inf")] * (m + 1) for _ in range(n + 1)]
        dp[0][0] = 0.0
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                cost = abs(x[i-1] - y[j-1])
                dp[i][j] = cost + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
        return dp[n][m]

    def cointegration_test(
        self, x: List[float], y: List[float]
    ) -> Tuple[bool, float]:
        """
        [6.3] Cointegration (Engle-Granger): долгосрочная связь.
        Упрощённый тест: регрессия x на y, ADF на residuals.
        Возвращает (cointegrated, t_stat).
        """
        if len(x) < 20 or len(y) < 20:
            return False, 0.0
        n = min(len(x), len(y))
        xs, ys = x[:n], y[:n]
        # OLS: x = alpha + beta*y
        slope, intercept, _ = _ols_xy_full(ys, xs)
        residuals = [xs[i] - (slope * ys[i] + intercept) for i in range(n)]
        # ADF statistic: корреляция остатка с его лагом
        t_stat = _pearson_patterns(residuals[1:], residuals[:-1])
        cointegrated = t_stat < -0.5  # упрощённый критерий
        return cointegrated, t_stat

    def compute_r2(self, x_norm: List[float], y_norm: List[float]) -> float:
        """R² между нормализованными рядами."""
        return _pearson_patterns(x_norm, y_norm) ** 2

    def year_weight(self, year_index: int, total_years: int) -> float:
        """
        [6.3] Взвешивание: decay — более новые годы весят больше.
        year_index=0 = самый старый.
        """
        decay = 0.5
        return decay ** (total_years - 1 - year_index)

    def build_lookup_table(
        self,
        historical_prices_list: List[List[float]],
        target_length: int,
        cy: CrossYearProductState,
    ) -> None:
        """
        [6.3] Предвычислить кросс-годовой сигнал до старта.
        Хранить как lookup table.
        """
        total = len(historical_prices_list)
        if total == 0:
            return
        aligned = [
            self.temporal_align(self.zscore_normalize(p), target_length)
            for p in historical_prices_list
        ]
        weights = [self.year_weight(i, total) for i in range(total)]
        w_sum = sum(weights)
        lookup = []
        for t in range(target_length):
            val = sum(
                weights[i] * aligned[i][t]
                for i in range(total)
                if t < len(aligned[i])
            ) / max(1e-8, w_sum)
            lookup.append(val)
        cy.lookup_table = lookup  # [6.3]

    def get_signal(
        self,
        cy: CrossYearProductState,
        tick: int,
        round_length: int,
        current_price: float,
    ) -> Optional[float]:
        """
        [6.3] Возвращает кросс-годовой сигнал из lookup table.
        """
        if not cy.lookup_table:
            return None
        pct = tick / max(1, round_length)
        idx = int(pct * (len(cy.lookup_table) - 1))
        idx = max(0, min(idx, len(cy.lookup_table) - 1))
        return cy.lookup_table[idx]

    def update_rolling_correlation(
        self,
        cy: CrossYearProductState,
        current_prices: List[float],
        historical_prices: List[float],
    ) -> float:
        """
        [6.3] Rolling corr window = 1000 тиков.
        [6.3] rolling_corr < 0.3 → отключить.
        """
        w = CROSS_YEAR_ROLLING_WINDOW
        if len(current_prices) < w or len(historical_prices) < w:
            return cy.rolling_correlation
        corr = self.returns_correlation(
            current_prices[-w:], historical_prices[-w:]
        )
        cy.rolling_correlation = corr
        return corr

    def online_correction(
        self,
        cy: CrossYearProductState,
        predicted: float,
        actual: float,
    ) -> None:
        """
        [6.3] Online correction: если MAE > 3σ текущей цены → снизить вес.
        """
        error = abs(predicted - actual)
        cy.mae_history.append(error)
        if len(cy.mae_history) > 200:
            cy.mae_history = cy.mae_history[-200:]
        if len(cy.mae_history) < 10:
            return
        mae_mean = sum(cy.mae_history) / len(cy.mae_history)
        mae_std  = _std_val(cy.mae_history)
        # [6.3] MAE > 3σ → снизить вес
        if mae_std > 0 and error > mae_mean + CROSS_YEAR_MAE_SIGMA * mae_std:
            cy.signal_weight *= 0.8

    def should_use_signal(self, cy: CrossYearProductState, r2: float) -> str:
        """
        [6.3] Пороги: R²>0.95 прямой; R²>0.7 timing; R²<0.3 игнорировать.
        [6.3] rolling_corr < 0.3 → отключить.
        """
        # [6.3] rolling_corr < 0.3 → отключить
        if cy.rolling_correlation < CROSS_YEAR_ROLLING_MIN:
            return "off"
        # [6.4] R² < 0.3 → игнорировать
        if r2 < NEGATIVE_R2_MIN:
            return "off"
        if r2 >= CROSS_YEAR_R2_DIRECT:
            return "direct"      # [6.3]
        if r2 >= CROSS_YEAR_R2_TIMING:
            return "timing"      # [6.3]
        return "off"

    def build_correlation_matrix(
        self,
        prices_by_year: Dict[str, List[float]],
        window: int = 500,
    ) -> Dict[Tuple[str, str], float]:
        """[6.3] Correlation matrix over time: как корреляция меняется внутри раунда."""
        years = list(prices_by_year.keys())
        matrix = {}
        for i, y1 in enumerate(years):
            for y2 in years[i+1:]:
                p1 = prices_by_year[y1][-window:]
                p2 = prices_by_year[y2][-window:]
                min_len = min(len(p1), len(p2))
                if min_len < 10:
                    continue
                corr = self.returns_correlation(p1[:min_len], p2[:min_len])
                matrix[(y1, y2)] = corr
        return matrix


# ==============================================================================
# SECTION 10 — NEGATIVE LIST VALIDATOR  [6.4]
# ==============================================================================

class NegativeListValidator:
    """
    Негативный список паттернов.                                   [6.4]
    R² < 0.3 между годами — не использовать.                     [6.4]
    Half-life > длины раунда — не использовать.                  [6.4]
    Transaction cost > edge — не использовать.                   [6.4]
    Fourier нестабильный период — не использовать.               [6.4]
    Bot-сигнал с падающим edge после 1-2 дней — не использовать. [6.4]
    Time-of-day без подтверждения кросс-год — не использовать.  [6.4]
    Менее 50 независимых подтверждений — не использовать.        [6.4]
    """

    def check_r2(self, r2: float) -> bool:
        """[6.4] R² < 0.3 → не использовать."""
        return r2 >= NEGATIVE_R2_MIN

    def check_half_life(self, half_life: float, round_length: float) -> bool:
        """[6.4] Half-life > длины раунда → не использовать."""
        return half_life <= round_length

    def check_transaction_cost(self, edge: float, transaction_cost: float) -> bool:
        """[6.4] Transaction cost threshold выше реального edge → не использовать."""
        return edge > transaction_cost

    def check_fourier_stability(self, fs: FFTState) -> bool:
        """[6.4] Fourier нестабильный период между годами → не использовать."""
        return fs.stable

    def check_bot_edge_decay(self, edge_history: List[float]) -> bool:
        """
        [6.4] Bot-сигнал с падающим edge после 1-2 дней → не использовать.
        """
        if len(edge_history) < 20:
            return True
        recent  = sum(edge_history[-10:]) / 10
        earlier = sum(edge_history[-20:-10]) / 10
        if earlier <= 0:
            return True
        decay = (earlier - recent) / earlier
        return decay < 0.50

    def check_tod_cross_year(self, tod_validated: bool) -> bool:
        """[6.4] Time-of-day без подтверждения кросс-год → не использовать."""
        return tod_validated

    def check_min_confirmations(self, confirmations: int) -> bool:
        """[6.4] Менее 50 независимых подтверждений → не использовать."""
        return confirmations >= NEGATIVE_MIN_CONFIRMATIONS

    def validate_all(
        self,
        r2: float = 1.0,
        half_life: float = 0.0,
        round_length: float = 1e9,
        edge: float = 1.0,
        transaction_cost: float = 0.0,
        fft_state: Optional[FFTState] = None,
        bot_edge_history: Optional[List[float]] = None,
        tod_validated: bool = True,
        confirmations: int = 100,
    ) -> Tuple[bool, List[str]]:
        """Проверяет все пункты негативного списка. Возвращает (ok, reasons)."""
        failures = []
        if not self.check_r2(r2):
            failures.append(f"R²={r2:.2f} < 0.3")
        if not self.check_half_life(half_life, round_length):
            failures.append(f"half_life={half_life} > round_length={round_length}")
        if not self.check_transaction_cost(edge, transaction_cost):
            failures.append(f"edge={edge} < txcost={transaction_cost}")
        if fft_state and not self.check_fourier_stability(fft_state):
            failures.append("Fourier period unstable")
        if bot_edge_history and not self.check_bot_edge_decay(bot_edge_history):
            failures.append("bot edge decaying after 1-2 days")
        if not self.check_tod_cross_year(tod_validated):
            failures.append("tod no cross-year confirmation")
        if not self.check_min_confirmations(confirmations):
            failures.append(f"confirmations={confirmations} < 50")
        return len(failures) == 0, failures


# ==============================================================================
# SECTION 11 — MAIN PATTERN DISPATCHER
# ==============================================================================

class PatternDispatcher:
    """Главный диспетчер паттернов. Интегрирует все компоненты."""

    def __init__(self):
        self.sunlight   = SunlightSignal()
        self.dolphin    = DolphinSignal()
        self.regression = SugarTransportRegression()
        self.tod        = TimeOfDayAnalyzer()
        self.trend      = IntraRoundTrend()
        self.fourier    = FourierAnalyzer()
        self.cross_year = CrossYearAnalyzer_full()
        self.validator  = NegativeListValidator()

    def tick(
        self,
        state: PatternState,
        product: str,
        price: float,
        tick: int,
        observations: object = None,
        sugar: float = 0.0,
        transport: float = 0.0,
        price_history: Optional[List[float]] = None,
        round_length: int = 1_000_000,
        historical_prices: Optional[List[float]] = None,
        cross_year_buckets: Optional[Dict[int, float]] = None,
    ) -> Dict:
        state.global_tick = tick
        signals: Dict[str, object] = {}

        # [6.1] Sunlight
        sl_val = self.sunlight.read_from_observations(observations)
        if sl_val is not None:
            sl_sig = self.sunlight.update(state.sunlight, sl_val, tick)
            if sl_sig:
                signals["sunlight"] = sl_sig

        # [6.1] Dolphin
        dolph_val = self.dolphin.read_from_observations(observations)
        if dolph_val is not None:
            dolph_sig = self.dolphin.update(state.dolphin, dolph_val, tick)
            if dolph_sig:
                signals["dolphin"] = dolph_sig

        # [6.1] Sugar/transport regression
        if sugar != 0.0 or transport != 0.0:
            self.regression.update(state.regression, sugar, transport, price, tick)
            fv = self.regression.fair_value(state.regression, sugar, transport)
            signals["regression_fv"] = fv

        # [6.2] Time-of-day
        self.tod.update(state.tod, price, tick)
        tod_sig = self.tod.get_signal(state.tod, tick, cross_year_buckets)
        if tod_sig:
            signals["tod"] = tod_sig

        # [6.2] Intra-round trend
        if price_history and len(price_history) >= 20:
            self.trend.update(state.trend, price_history, tick)
            trend_sig = self.trend.get_signal(state.trend)
            if trend_sig:
                sz = self.trend.get_sizing_multiplier(state.trend, tick)
                signals["trend"] = {"side": trend_sig, "sizing": sz}

        # [6.2] Fourier
        if price_history and len(price_history) >= 20:
            self.fourier.compute(state.fft, price_history[-1000:])
            fft_sig = self.fourier.get_phase_signal(state.fft, tick)
            if fft_sig:
                signals["fourier"] = fft_sig

        # [6.3] Cross-year
        cy = state.get_cross_year(product)
        cy_val = self.cross_year.get_signal(cy, tick, round_length, price)
        if cy_val is not None and historical_prices:
            ph = price_history or []
            self.cross_year.update_rolling_correlation(cy, ph, historical_prices)
            r2 = self.cross_year.compute_r2(
                self.cross_year.zscore_normalize(ph[-100:]) if len(ph) >= 100 else [],
                self.cross_year.zscore_normalize(historical_prices[-100:]) if len(historical_prices) >= 100 else [],
            )
            mode = self.cross_year.should_use_signal(cy, r2)
            if mode != "off":
                self.cross_year.online_correction(cy, cy_val, price)
                signals["cross_year"] = {"value": cy_val, "mode": mode, "weight": cy.signal_weight}

        return signals


# ==============================================================================
# SECTION 12 — UTILITIES
# ==============================================================================

def _std_val(values: List[float]) -> float:
    if len(values) < 2:
        return 0.0
    mean = sum(values) / len(values)
    return math.sqrt(sum((v - mean)**2 for v in values) / len(values))

def _pearson_patterns(x: List[float], y: List[float]) -> float:
    n = min(len(x), len(y))
    if n < 2:
        return 0.0
    mx = sum(x[:n]) / n
    my = sum(y[:n]) / n
    num = sum((x[i] - mx) * (y[i] - my) for i in range(n))
    dx  = math.sqrt(sum((x[i] - mx)**2 for i in range(n)))
    dy  = math.sqrt(sum((y[i] - my)**2 for i in range(n)))
    if dx * dy == 0:
        return 0.0
    return num / (dx * dy)

def _ranks(values: List[float]) -> List[float]:
    n = len(values)
    indexed = sorted(enumerate(values), key=lambda x: x[1])
    ranks = [0.0] * n
    for rank, (i, _) in enumerate(indexed):
        ranks[i] = float(rank + 1)
    return ranks

def _ols(prices: List[float]) -> Tuple[float, float, float]:
    """OLS regression of prices on time. Returns (slope, intercept, r2)."""
    n = len(prices)
    if n < 2:
        return 0.0, prices[0] if prices else 0.0, 0.0
    x = list(range(n))
    return _ols_xy_full(x, prices)

def _ols_xy_full(x: List[float], y: List[float]) -> Tuple[float, float, float]:
    n = min(len(x), len(y))
    if n < 2:
        return 0.0, y[0] if y else 0.0, 0.0
    mx = sum(x[:n]) / n
    my = sum(y[:n]) / n
    num = sum((x[i] - mx) * (y[i] - my) for i in range(n))
    den = sum((x[i] - mx)**2 for i in range(n))
    if den == 0:
        return 0.0, my, 0.0
    slope = num / den
    intercept = my - slope * mx
    predicted = [slope * x[i] + intercept for i in range(n)]
    ss_res = sum((y[i] - predicted[i])**2 for i in range(n))
    ss_tot = sum((y[i] - my)**2 for i in range(n))
    r2 = 1.0 - ss_res / max(1e-10, ss_tot)
    return slope, intercept, max(0.0, r2)

def _solve3x3(A: List[List[float]], b: List[float]) -> Optional[Tuple[float, float, float]]:
    """Gaussian elimination for 3×3 system."""
    import copy
    M = [A[i][:] + [b[i]] for i in range(3)]
    for col in range(3):
        pivot = M[col][col]
        if abs(pivot) < 1e-12:
            return None
        for row in range(col+1, 3):
            f = M[row][col] / pivot
            for k in range(col, 4):
                M[row][k] -= f * M[col][k]
    x2 = M[2][3] / M[2][2] if abs(M[2][2]) > 1e-12 else 0.0
    x1 = (M[1][3] - M[1][2]*x2) / M[1][1] if abs(M[1][1]) > 1e-12 else 0.0
    x0 = (M[0][3] - M[0][1]*x1 - M[0][2]*x2) / M[0][0] if abs(M[0][0]) > 1e-12 else 0.0
    return x0, x1, x2


# ==============================================================================
# SECTION 13 — STATE SERIALIZATION  [6.5]
# ==============================================================================

def save_pattern_state(state: PatternState) -> str:
    """
    Сериализует PatternState в traderData.                        [6.5]
    Sunlight: значение + флаг.                                    [6.5]
    Dolphin: сила + timestamp.                                    [6.5]
    Sugar/transport a, b, c.                                      [6.5]
    Time-of-day buckets.                                          [6.5]
    Trend slope и R².                                             [6.5]
    FFT dominant_period.                                          [6.5]
    Cross-year rolling corr.                                      [6.5]
    Cross-year signal weight.                                     [6.5]
    """
    payload = {
        "tick": state.global_tick,
        # [6.5] Sunlight
        "sl_val":      state.sunlight.current_value,
        "sl_crossed":  state.sunlight.threshold_crossed,
        "sl_thresh":   state.sunlight.calibrated_threshold,
        "sl_active":   state.sunlight.active,
        "sl_cal_done": state.sunlight.calibration_done,
        # [6.5] Dolphin
        "dolph_str":   state.dolphin.current_strength,
        "dolph_ts":    state.dolphin.last_event_tick,
        "dolph_accum": state.dolphin.accumulated_signal,
        "dolph_decay": state.dolphin.decay_type,
        # [6.5] Sugar/transport a, b, c
        "reg_a": state.regression.coef_a,
        "reg_b": state.regression.coef_b,
        "reg_c": state.regression.coef_c,
        "reg_tick": state.regression.last_recalc_tick,
        "reg_sugar":     state.regression.sugar_history[-200:],
        "reg_transport": state.regression.transport_history[-200:],
        "reg_prices":    state.regression.price_history[-200:],
        # [6.5] Time-of-day avg_price buckets
        "tod_means":  state.tod.bucket_means,
        "tod_gmean":  state.tod.global_mean,
        "tod_gstd":   state.tod.global_std,
        "tod_nobs":   state.tod.total_observations,
        # [6.5] Trend slope и R²
        "trend_slope":   state.trend.slope,
        "trend_r2":      state.trend.r2,
        "trend_active":  state.trend.active,
        "trend_sign_ch": state.trend.sign_changed,
        # [6.5] FFT dominant_period
        "fft_period":  state.fft.dominant_period,
        "fft_periods": state.fft.periods,
        "fft_weights": state.fft.weights,
        "fft_stable":  state.fft.stable,
        # [6.5] Cross-year per product
        "cross_year": {
            product: {
                "rolling_corr": cy.rolling_correlation,
                "weight":       cy.signal_weight,
                "r2":           cy.r2,
                "lookup":       cy.lookup_table[:500],
            }
            for product, cy in state.cross_year.items()
        },
    }
    return json.dumps(payload)


def load_pattern_state(data: str) -> PatternState:
    """Десериализует PatternState из traderData."""
    state = PatternState()
    if not data:
        return state
    try:
        p = json.loads(data)
    except Exception:
        return state

    state.global_tick = p.get("tick", 0)
    # Sunlight
    state.sunlight.current_value         = p.get("sl_val", 0.0)
    state.sunlight.threshold_crossed     = p.get("sl_crossed", False)
    state.sunlight.calibrated_threshold  = p.get("sl_thresh", 0.0)
    state.sunlight.active                = p.get("sl_active", True)
    state.sunlight.calibration_done      = p.get("sl_cal_done", False)
    # Dolphin
    state.dolphin.current_strength    = p.get("dolph_str", 0.0)
    state.dolphin.last_event_tick     = p.get("dolph_ts", -1)
    state.dolphin.accumulated_signal  = p.get("dolph_accum", 0.0)
    state.dolphin.decay_type          = p.get("dolph_decay", "linear")
    # Regression
    state.regression.coef_a           = p.get("reg_a", 0.0)
    state.regression.coef_b           = p.get("reg_b", 0.0)
    state.regression.coef_c           = p.get("reg_c", 0.0)
    state.regression.last_recalc_tick = p.get("reg_tick", 0)
    state.regression.sugar_history     = p.get("reg_sugar", [])
    state.regression.transport_history = p.get("reg_transport", [])
    state.regression.price_history     = p.get("reg_prices", [])
    # ToD
    state.tod.bucket_means        = {int(k): v for k, v in p.get("tod_means", {}).items()}
    state.tod.global_mean         = p.get("tod_gmean", 0.0)
    state.tod.global_std          = p.get("tod_gstd", 1.0)
    state.tod.total_observations  = p.get("tod_nobs", 0)
    # Trend
    state.trend.slope       = p.get("trend_slope", 0.0)
    state.trend.r2          = p.get("trend_r2", 0.0)
    state.trend.active      = p.get("trend_active", False)
    state.trend.sign_changed = p.get("trend_sign_ch", False)
    # FFT
    state.fft.dominant_period = p.get("fft_period", 0.0)
    state.fft.periods         = p.get("fft_periods", [])
    state.fft.weights         = p.get("fft_weights", [])
    state.fft.stable          = p.get("fft_stable", False)
    # Cross-year
    for product, d in p.get("cross_year", {}).items():
        cy = CrossYearProductState()
        cy.rolling_correlation = d.get("rolling_corr", 0.0)
        cy.signal_weight       = d.get("weight", 1.0)
        cy.r2                  = d.get("r2", 0.0)
        cy.lookup_table        = d.get("lookup", [])
        state.cross_year[product] = cy

    return state

