"""
=============================================================================
COMPREHENSIVE TOOLKIT — §16.5 МАТРИЦА ПРИОРИТЕТОВ + §16.6 ОШИБКИ
=============================================================================
"""



# ─────────────────────────────────────────────────────────────────────────────
# ТИПЫ
# ─────────────────────────────────────────────────────────────────────────────

class Impact(Enum):
    HIGH   = "high"
    MEDIUM = "medium"
    LOW    = "low"

class TimeRequired(Enum):
    LOW  = "low"
    HIGH = "high"

class Phase(Enum):
    BEFORE_COMPETITION = "before_competition"   # до старта соревнования
    ROUND_DAY_1        = "round_day_1"          # первый день раунда
    IF_TIME_ALLOWS     = "if_time_allows"       # только если есть запас
    TOP3_ONLY          = "top3_only"            # только для топ-3 борьбы
    ALWAYS_FIRST       = "always_first"         # делать первыми всегда


# ─────────────────────────────────────────────────────────────────────────────
# §16.5  МАТРИЦА ПРИОРИТЕТОВ
# ─────────────────────────────────────────────────────────────────────────────

@dataclass
class TaskItem:
    """Один пункт матрицы приоритетов."""
    number:       int
    impact:       Impact
    time_req:     TimeRequired
    phase:        Phase
    description:  str
    done:         bool = False


class PriorityMatrix:
    """
    §16.5 — Матрица приоритетов (время × impact).

    Квадранты:
    ┌───────────────────────────────────────────────────────┐
    │              │  Время НИЗКОЕ     │  Время ВЫСОКОЕ     │
    ├──────────────┼───────────────────┼────────────────────┤
    │ Impact HIGH  │ пп. 7,9,18        │ пп. 1,2,5,6        │
    │              │ → ВСЕГДА ПЕРВЫМИ  │ → ДО СТАРТА        │
    ├──────────────┼───────────────────┼────────────────────┤
    │ Impact MED   │ пп. 3,12          │ пп. 8,10,11        │
    │              │ → ДЕНЬ 1 РАУНДА   │ → ЕСЛИ ЕСТЬ ЗАПАС  │
    ├──────────────┼───────────────────┼────────────────────┤
    │ Impact LOW   │        —          │ пп. 13,14,17       │
    │              │                   │ → ТОЛЬКО ТОП-3     │
    └───────────────────────────────────────────────────────┘
    """

    # §16.5: Полная таблица всех пунктов
    TASKS: list[TaskItem] = [
        # HIGH impact + LOW time → делать первыми ВСЕГДА
        TaskItem(7,  Impact.HIGH,   TimeRequired.LOW,  Phase.ALWAYS_FIRST,
                 "Базовая market-making / mean-reversion стратегия"),
        TaskItem(9,  Impact.HIGH,   TimeRequired.LOW,  Phase.ALWAYS_FIRST,
                 "Manual trading анализ и быстрый PnL"),
        TaskItem(18, Impact.HIGH,   TimeRequired.LOW,  Phase.ALWAYS_FIRST,
                 "Position limits и risk controls"),

        # HIGH impact + HIGH time → готовить ДО СТАРТА соревнования
        TaskItem(1,  Impact.HIGH,   TimeRequired.HIGH, Phase.BEFORE_COMPETITION,
                 "Backtesting framework"),
        TaskItem(2,  Impact.HIGH,   TimeRequired.HIGH, Phase.BEFORE_COMPETITION,
                 "Data pipeline и логирование"),
        TaskItem(5,  Impact.HIGH,   TimeRequired.HIGH, Phase.BEFORE_COMPETITION,
                 "Infrastructure: submitter, тесты, CI"),
        TaskItem(6,  Impact.HIGH,   TimeRequired.HIGH, Phase.BEFORE_COMPETITION,
                 "Robust order management система"),

        # MEDIUM impact + LOW time → первый день раунда
        TaskItem(3,  Impact.MEDIUM, TimeRequired.LOW,  Phase.ROUND_DAY_1,
                 "Fair value estimation для новых продуктов"),
        TaskItem(12, Impact.MEDIUM, TimeRequired.LOW,  Phase.ROUND_DAY_1,
                 "Базовая настройка спреда и sizing"),

        # MEDIUM impact + HIGH time → только если есть запас
        TaskItem(8,  Impact.MEDIUM, TimeRequired.HIGH, Phase.IF_TIME_ALLOWS,
                 "Продвинутая статистическая модель (GARCH, Heston)"),
        TaskItem(10, Impact.MEDIUM, TimeRequired.HIGH, Phase.IF_TIME_ALLOWS,
                 "Параметрическая оптимизация стратегий"),
        TaskItem(11, Impact.MEDIUM, TimeRequired.HIGH, Phase.IF_TIME_ALLOWS,
                 "Корреляционные / basket стратегии"),

        # LOW impact + HIGH time → только для топ-3 борьбы
        TaskItem(13, Impact.LOW,    TimeRequired.HIGH, Phase.TOP3_ONLY,
                 "Экзотические деривативы и сложные опционные стратегии"),
        TaskItem(14, Impact.LOW,    TimeRequired.HIGH, Phase.TOP3_ONLY,
                 "Micro-structure alpha (order flow imbalance)"),
        TaskItem(17, Impact.LOW,    TimeRequired.HIGH, Phase.TOP3_ONLY,
                 "ML-модели и нейросети для прогнозирования"),
    ]

    def __init__(self):
        # Словарь для быстрого доступа
        self._tasks: dict[int, TaskItem] = {t.number: t for t in self.TASKS}

    # ── Получить задачи по квадранту ─────────────────────────────────────────
    def get_by_phase(self, phase: Phase) -> list[TaskItem]:
        """§16.5: Получить задачи для конкретной фазы."""
        return [t for t in self.TASKS if t.phase == phase]

    def get_by_quadrant(self, impact: Impact,
                        time_req: TimeRequired) -> list[TaskItem]:
        """§16.5: Получить задачи из конкретного квадранта матрицы."""
        return [t for t in self.TASKS
                if t.impact == impact and t.time_req == time_req]

    # ── Приоритетная очередь ──────────────────────────────────────────────────
    def get_execution_order(self) -> list[TaskItem]:
        """
        §16.5: Оптимальный порядок выполнения.
        1. ALWAYS_FIRST (high impact + low time)
        2. BEFORE_COMPETITION (high impact + high time) — уже должно быть готово
        3. ROUND_DAY_1 (medium impact + low time)
        4. IF_TIME_ALLOWS (medium impact + high time)
        5. TOP3_ONLY (low impact + high time)
        """
        phase_order = [
            Phase.ALWAYS_FIRST,
            Phase.BEFORE_COMPETITION,
            Phase.ROUND_DAY_1,
            Phase.IF_TIME_ALLOWS,
            Phase.TOP3_ONLY,
        ]
        ordered = []
        for phase in phase_order:
            tasks = self.get_by_phase(phase)
            ordered.extend(sorted(tasks, key=lambda t: t.number))
        return ordered

    # ── Проверка готовности ───────────────────────────────────────────────────
    def mark_done(self, task_number: int):
        """Отметить пункт как выполненный."""
        if task_number in self._tasks:
            self._tasks[task_number].done = True

    def readiness_check(self, current_phase: Phase) -> dict:
        """
        §16.5: Проверка готовности к текущей фазе.
        Все задачи более ранних фаз должны быть выполнены.
        """
        phase_order = [
            Phase.BEFORE_COMPETITION,
            Phase.ALWAYS_FIRST,
            Phase.ROUND_DAY_1,
            Phase.IF_TIME_ALLOWS,
            Phase.TOP3_ONLY,
        ]
        current_idx = phase_order.index(current_phase) \
            if current_phase in phase_order else 0
        required_phases = phase_order[:current_idx]

        missing = []
        for phase in required_phases:
            for task in self.get_by_phase(phase):
                if not self._tasks[task.number].done:
                    missing.append(task)

        return {
            "current_phase":  current_phase.value,
            "ready":          len(missing) == 0,
            "missing_tasks":  [{"number": t.number, "desc": t.description}
                               for t in missing],
            "blockers":       len(missing),
        }

    def next_task(self) -> TaskItem | None:
        """§16.5: Следующая невыполненная задача в порядке приоритета."""
        for task in self.get_execution_order():
            if not self._tasks[task.number].done:
                return self._tasks[task.number]
        return None

    def completion_summary(self) -> dict:
        """Итоговый статус выполнения всей матрицы."""
        total = len(self.TASKS)
        done  = sum(1 for t in self.TASKS if self._tasks[t.number].done)
        by_phase = {}
        for phase in Phase:
            tasks = self.get_by_phase(phase)
            n_done = sum(1 for t in tasks if self._tasks[t.number].done)
            by_phase[phase.value] = {
                "total": len(tasks),
                "done":  n_done,
                "pct":   n_done / len(tasks) * 100 if tasks else 0,
            }
        return {
            "total":    total,
            "done":     done,
            "pct":      done / total * 100,
            "by_phase": by_phase,
        }

    def render_matrix(self) -> str:
        """§16.5: Текстовый рендер матрицы приоритетов."""
        lines = [
            "\n§16.5 МАТРИЦА ПРИОРИТЕТОВ (время × impact)",
            "─" * 60,
            f"{'':20} {'ВРЕМЯ НИЗКОЕ':20} {'ВРЕМЯ ВЫСОКОЕ':20}",
            "─" * 60,
        ]
        for impact in [Impact.HIGH, Impact.MEDIUM, Impact.LOW]:
            low_tasks  = self.get_by_quadrant(impact, TimeRequired.LOW)
            high_tasks = self.get_by_quadrant(impact, TimeRequired.HIGH)
            low_nums   = ", ".join(str(t.number) for t in low_tasks) or "—"
            high_nums  = ", ".join(str(t.number) for t in high_tasks) or "—"
            if impact == Impact.HIGH:
                low_label  = "→ ВСЕГДА ПЕРВЫМИ"
                high_label = "→ ДО СТАРТА"
            elif impact == Impact.MEDIUM:
                low_label  = "→ ДЕНЬ 1 РАУНДА"
                high_label = "→ ЕСЛИ ЕСТЬ ЗАПАС"
            else:
                low_label  = ""
                high_label = "→ ТОЛЬКО ТОП-3"
            lines.append(
                f"Impact {impact.value:6}  "
                f"пп.{low_nums:8} {low_label:18}  "
                f"пп.{high_nums:8} {high_label}"
            )
        lines.append("─" * 60)
        return "\n".join(lines)


# ─────────────────────────────────────────────────────────────────────────────
# §16.6  ТИПИЧНЫЕ ОШИБКИ ПРИОРИТИЗАЦИИ — GUARD SYSTEM
# ─────────────────────────────────────────────────────────────────────────────

@dataclass
class PrioritizationError:
    """Одна ошибка приоритизации."""
    code:        str
    description: str
    consequence: str
    guard_fn:    Callable   # функция-детектор
    triggered:   bool = False
    detail:      str  = ""


class PrioritizationGuard:
    """
    §16.6 — Система защиты от типичных ошибок приоритизации.
    Все 5 ошибок из документа.
    """

    def __init__(self, matrix: PriorityMatrix):
        self.matrix = matrix

        # §16.6: Все 5 типичных ошибок
        self.errors: list[PrioritizationError] = [

            # Ошибка 1: Начинать с пп.13-17 потому что "интересно"
            PrioritizationError(
                code="E1_INTERESTING_FIRST",
                description='Начинать с пунктов 13–17 потому что "интересно"',
                consequence="Теряется базовый PnL — нет базовой стратегии на большинстве продуктов",
                guard_fn=self._check_e1_interesting_first,
            ),

            # Ошибка 2: 8-12 без готового backtester
            PrioritizationError(
                code="E2_NO_BACKTESTER",
                description="Реализовывать пп.8–12 без готового backtester",
                consequence="Нет способа проверить работает ли стратегия",
                guard_fn=self._check_e2_no_backtester,
            ),

            # Ошибка 3: Весь день 1 на один продукт
            PrioritizationError(
                code="E3_ONE_PRODUCT_ALL_DAY",
                description="Тратить весь день 1 раунда на один продукт",
                consequence="Другие продукты остаются без базовой стратегии",
                guard_fn=self._check_e3_one_product_all_day,
            ),

            # Ошибка 4: Игнорировать manual до последнего
            PrioritizationError(
                code="E4_MANUAL_LAST",
                description="Игнорировать manual до последнего момента",
                consequence="Нет времени на подготовку manual — теряется 20-30% PnL",
                guard_fn=self._check_e4_manual_last,
            ),

            # Ошибка 5: Оптимизировать до robust infrastructure
            PrioritizationError(
                code="E5_OPTIMIZE_BEFORE_INFRA",
                description="Оптимизировать параметры до реализации robust infrastructure",
                consequence="Баги съедают весь edge — оптимизация бессмысленна без надёжной базы",
                guard_fn=self._check_e5_optimize_before_infra,
            ),
        ]

    # ── Детекторы ошибок ──────────────────────────────────────────────────────

    def _check_e1_interesting_first(self,
                                    first_task_done: int | None = None,
                                    **kwargs) -> dict:
        """
        §16.6/E1: Начинать с пп.13-17 — теряется базовый PnL.
        Триггер: первая выполненная задача из LOW impact.
        """
        low_impact_nums = {13, 14, 17}
        triggered = first_task_done in low_impact_nums
        # Дополнительно: пп.7,9,18 не выполнены, но 13-17 выполнены
        critical_undone = any(
            not self.matrix._tasks[n].done
            for n in [7, 9, 18]
            if n in self.matrix._tasks
        )
        low_done = any(
            self.matrix._tasks[n].done
            for n in low_impact_nums
            if n in self.matrix._tasks
        )
        triggered = triggered or (low_done and critical_undone)
        return {
            "triggered":  triggered,
            "detail":     f"§16.6/E1: пп.7,9,18 не готовы, но работа над пп.13-17 начата. "
                          f"Потеря базового PnL." if triggered else "OK",
            "fix":        "Завершить пп.7, 9, 18 (ALWAYS_FIRST) прежде чем переходить к LOW impact",
        }

    def _check_e2_no_backtester(self,
                                 backtester_ready: bool = False, **kwargs) -> dict:
        """
        §16.6/E2: Пп.8-12 без готового backtester.
        Триггер: задачи 8,10,11 начаты, но п.1 (backtester) не выполнен.
        """
        advanced_started = any(
            self.matrix._tasks[n].done
            for n in [8, 10, 11]
            if n in self.matrix._tasks
        )
        backtester_done = self.matrix._tasks.get(1) and \
                          self.matrix._tasks[1].done
        triggered = advanced_started and not backtester_done and not backtester_ready
        return {
            "triggered":  triggered,
            "detail":     "§16.6/E2: реализация пп.8-12 без backtester — "
                          "нет способа проверить работает ли стратегия" if triggered else "OK",
            "fix":        "Сначала завершить п.1 (backtester framework), потом пп.8-12",
        }

    def _check_e3_one_product_all_day(self,
                                      time_on_products: dict[str, float] | None = None,
                                      total_time: float = 8.0, **kwargs) -> dict:
        """
        §16.6/E3: Весь день 1 на один продукт → другие без базовой стратегии.
        Триггер: один продукт занял >70% доступного времени.
        """
        if time_on_products is None:
            return {"triggered": False, "detail": "no_data"}
        if not time_on_products:
            return {"triggered": False, "detail": "no_data"}
        max_time   = max(time_on_products.values())
        max_product = max(time_on_products, key=lambda k: time_on_products[k])
        pct = max_time / (total_time + 1e-9)
        triggered = pct > 0.70
        return {
            "triggered":   triggered,
            "detail":      f"§16.6/E3: {max_product} занял {pct*100:.0f}% дня — "
                           f"другие продукты без базовой стратегии" if triggered else "OK",
            "worst_product": max_product,
            "pct_time":    pct * 100,
            "fix":         "Ограничить время на один продукт: max 30% дня. "
                           "Сначала базовая стратегия на ВСЕ продукты.",
        }

    def _check_e4_manual_last(self,
                              ticks_remaining: int | None = None,
                              total_ticks: int = 10000,
                              manual_prepared: bool = False, **kwargs) -> dict:
        """
        §16.6/E4: Игнорировать manual до последнего — нет времени на подготовку.
        Триггер: менее 20% тиков осталось, а manual не подготовлен.
        """
        if ticks_remaining is None:
            # Проверяем через матрицу: п.9 (manual) не выполнен
            manual_done = self.matrix._tasks.get(9) and \
                          self.matrix._tasks[9].done
            triggered = not manual_done and not manual_prepared
            return {
                "triggered": triggered,
                "detail":    "§16.6/E4: п.9 (manual) не выполнен — "
                             "риск потери 20-30% PnL" if triggered else "OK",
                "fix":       "Подготовить manual checklist ДО старта (Phase.ALWAYS_FIRST)",
            }
        pct_remaining = ticks_remaining / (total_ticks + 1e-9)
        triggered = pct_remaining < 0.20 and not manual_prepared
        return {
            "triggered":       triggered,
            "ticks_remaining": ticks_remaining,
            "pct_remaining":   pct_remaining * 100,
            "detail":          f"§16.6/E4: {pct_remaining*100:.0f}% тиков осталось, "
                               f"manual не подготовлен — нет времени" if triggered else "OK",
            "fix":             "Manual готовить в первые 10 минут раунда (ALWAYS_FIRST)",
        }

    def _check_e5_optimize_before_infra(self,
                                         optimizing: bool = False, **kwargs) -> dict:
        """
        §16.6/E5: Оптимизировать параметры до robust infrastructure.
        Триггер: п.10 (оптимизация) выполнен, но пп.1,2,5,6 (infrastructure) не готовы.
        """
        infra_tasks = [1, 2, 5, 6]
        infra_done  = all(
            self.matrix._tasks[n].done
            for n in infra_tasks
            if n in self.matrix._tasks
        )
        optim_started = (
            (self.matrix._tasks.get(10) and self.matrix._tasks[10].done)
            or optimizing
        )
        triggered = optim_started and not infra_done
        missing_infra = [
            n for n in infra_tasks
            if n in self.matrix._tasks and not self.matrix._tasks[n].done
        ]
        return {
            "triggered":     triggered,
            "detail":        f"§16.6/E5: оптимизация запущена без инфраструктуры "
                             f"(недостающие пп.{missing_infra}) — "
                             f"баги съедят весь edge" if triggered else "OK",
            "missing_infra": missing_infra,
            "fix":           "Завершить пп.1,2,5,6 (BEFORE_COMPETITION) "
                             "до любой оптимизации параметров",
        }

    # ── Полная проверка ───────────────────────────────────────────────────────

    def check_all(self, context: dict | None = None) -> dict:
        """
        §16.6: Прогнать все 5 проверок.
        context: дополнительные данные для детекторов.
        """
        ctx = context or {}
        triggered_errors = []
        all_results = {}

        for err in self.errors:
            result = err.guard_fn(**ctx)
            err.triggered = result.get("triggered", False)
            err.detail    = result.get("detail", "")
            all_results[err.code] = {
                "description":  err.description,
                "consequence":  err.consequence,
                "triggered":    err.triggered,
                "detail":       err.detail,
                "fix":          result.get("fix", ""),
            }
            if err.triggered:
                triggered_errors.append(err)

        return {
            "all_checks":       all_results,
            "errors_triggered": len(triggered_errors),
            "clean":            len(triggered_errors) == 0,
            "triggered_codes":  [e.code for e in triggered_errors],
        }

    def critical_path_check(self) -> dict:
        """
        §16.5 + §16.6: Проверка критического пути.
        ALWAYS_FIRST задачи должны быть выполнены до всего остального.
        """
        always_first = self.matrix.get_by_phase(Phase.ALWAYS_FIRST)
        undone_critical = [
            t for t in always_first
            if not self.matrix._tasks[t.number].done
        ]
        before_comp = self.matrix.get_by_phase(Phase.BEFORE_COMPETITION)
        undone_prep = [
            t for t in before_comp
            if not self.matrix._tasks[t.number].done
        ]
        return {
            "always_first_done":  len(undone_critical) == 0,
            "prep_done":          len(undone_prep) == 0,
            "undone_critical":    [t.number for t in undone_critical],
            "undone_prep":        [t.number for t in undone_prep],
            "can_proceed":        len(undone_critical) == 0,
            "rule": "§16.5: пп.7,9,18 всегда первыми; пп.1,2,5,6 до старта",
        }


# ─────────────────────────────────────────────────────────────────────────────
# INTEGRATION RUNNER
# ─────────────────────────────────────────────────────────────────────────────

def run_all_checks_priority():
    results = {}
    errors  = []

    def run(section: str, fn):
        try:
            results[section] = fn()
            print(f"  ✅  {section}")
        except Exception as e:
            errors.append((section, str(e)))
            print(f"  ❌  {section}: {e}")

    print("\n" + "=" * 70)
    print("ЗАПУСК COMPREHENSIVE CHECK — §16.5 + §16.6")
    print("=" * 70)

    # ── §16.5 МАТРИЦА ПРИОРИТЕТОВ ────────────────────────────────────────────
    print("\n§16.5 МАТРИЦА ПРИОРИТЕТОВ")

    # Квадрант HIGH impact + LOW time → пп.7,9,18 → ALWAYS_FIRST
    run("16.5.quadrant_high_low",
        lambda: (lambda m: (
            tasks := m.get_by_quadrant(Impact.HIGH, TimeRequired.LOW),
            all(t.number in [7, 9, 18] for t in tasks)
        )[-1])(PriorityMatrix()))

    run("16.5.phase_always_first_numbers",
        lambda: (lambda m: sorted(
            t.number for t in m.get_by_phase(Phase.ALWAYS_FIRST)
        ))(PriorityMatrix()))

    # Квадрант HIGH impact + HIGH time → пп.1,2,5,6 → BEFORE_COMPETITION
    run("16.5.quadrant_high_high",
        lambda: (lambda m: (
            tasks := m.get_by_quadrant(Impact.HIGH, TimeRequired.HIGH),
            all(t.number in [1, 2, 5, 6] for t in tasks)
        )[-1])(PriorityMatrix()))

    run("16.5.phase_before_competition_numbers",
        lambda: (lambda m: sorted(
            t.number for t in m.get_by_phase(Phase.BEFORE_COMPETITION)
        ))(PriorityMatrix()))

    # Квадрант MEDIUM + LOW → пп.3,12 → ROUND_DAY_1
    run("16.5.quadrant_med_low",
        lambda: (lambda m: (
            tasks := m.get_by_quadrant(Impact.MEDIUM, TimeRequired.LOW),
            all(t.number in [3, 12] for t in tasks)
        )[-1])(PriorityMatrix()))

    run("16.5.phase_round_day1_numbers",
        lambda: (lambda m: sorted(
            t.number for t in m.get_by_phase(Phase.ROUND_DAY_1)
        ))(PriorityMatrix()))

    # Квадрант MEDIUM + HIGH → пп.8,10,11 → IF_TIME_ALLOWS
    run("16.5.quadrant_med_high",
        lambda: (lambda m: (
            tasks := m.get_by_quadrant(Impact.MEDIUM, TimeRequired.HIGH),
            all(t.number in [8, 10, 11] for t in tasks)
        )[-1])(PriorityMatrix()))

    run("16.5.phase_if_time_allows_numbers",
        lambda: (lambda m: sorted(
            t.number for t in m.get_by_phase(Phase.IF_TIME_ALLOWS)
        ))(PriorityMatrix()))

    # Квадрант LOW + HIGH → пп.13,14,17 → TOP3_ONLY
    run("16.5.quadrant_low_high",
        lambda: (lambda m: (
            tasks := m.get_by_quadrant(Impact.LOW, TimeRequired.HIGH),
            all(t.number in [13, 14, 17] for t in tasks)
        )[-1])(PriorityMatrix()))

    run("16.5.phase_top3_only_numbers",
        lambda: (lambda m: sorted(
            t.number for t in m.get_by_phase(Phase.TOP3_ONLY)
        ))(PriorityMatrix()))

    # Execution order: ALWAYS_FIRST первыми
    run("16.5.execution_order_starts_with_always_first",
        lambda: (lambda m: (
            order := m.get_execution_order(),
            order[0].phase == Phase.ALWAYS_FIRST
        )[-1])(PriorityMatrix()))

    # next_task без выполненных → должен вернуть из ALWAYS_FIRST
    run("16.5.next_task_is_always_first",
        lambda: (lambda m: m.next_task().phase == Phase.ALWAYS_FIRST
        )(PriorityMatrix()))

    # mark_done + completion_summary
    run("16.5.mark_done_and_summary", lambda: (
        lambda: (
            m := PriorityMatrix(),
            m.mark_done(7), m.mark_done(9), m.mark_done(18),
            s := m.completion_summary(),
            s["done"] == 3
        )[-1]
    )())

    # readiness_check: ROUND_DAY_1 требует ALWAYS_FIRST выполненными
    run("16.5.readiness_check_blocked", lambda: (
        lambda: (
            m := PriorityMatrix(),
            # Не выполняем ALWAYS_FIRST — должен быть blocker
            r := m.readiness_check(Phase.ROUND_DAY_1),
            r["blockers"] > 0
        )[-1]
    )())

    run("16.5.readiness_check_ok", lambda: (
        lambda: (
            m := PriorityMatrix(),
            [m.mark_done(n) for n in [7, 9, 18]],
            r := m.readiness_check(Phase.ROUND_DAY_1),
            r["ready"]
        )[-1]
    )())

    # render_matrix
    run("16.5.render_matrix",
        lambda: PriorityMatrix().render_matrix())

    # Все 14 задач присутствуют
    run("16.5.all_14_tasks_defined",
        lambda: len(PriorityMatrix.TASKS) == 14)

    # ── §16.6 ОШИБКИ ПРИОРИТИЗАЦИИ ──────────────────────────────────────────
    print("\n§16.6 ОШИБКИ ПРИОРИТИЗАЦИИ")

    # E1: Начинать с 13-17 потому что интересно
    run("16.6.e1_not_triggered_when_clean", lambda: (
        lambda: (
            m := PriorityMatrix(),
            [m.mark_done(n) for n in [7, 9, 18]],
            g := PrioritizationGuard(m),
            r := g._check_e1_interesting_first(first_task_done=7),
            not r["triggered"]
        )[-1]
    )())

    run("16.6.e1_triggered_when_low_first", lambda: (
        lambda: (
            m := PriorityMatrix(),
            m.mark_done(13),          # выполнили LOW, не выполнили HIGH
            g := PrioritizationGuard(m),
            r := g._check_e1_interesting_first(first_task_done=13),
            r["triggered"]
        )[-1]
    )())

    # E2: 8-12 без backtester
    run("16.6.e2_not_triggered_with_backtester", lambda: (
        lambda: (
            m := PriorityMatrix(),
            m.mark_done(1), m.mark_done(8),
            g := PrioritizationGuard(m),
            r := g._check_e2_no_backtester(backtester_ready=True),
            not r["triggered"]
        )[-1]
    )())

    run("16.6.e2_triggered_without_backtester", lambda: (
        lambda: (
            m := PriorityMatrix(),
            m.mark_done(8),    # выполнили продвинутую без backtester
            g := PrioritizationGuard(m),
            r := g._check_e2_no_backtester(backtester_ready=False),
            r["triggered"]
        )[-1]
    )())

    # E3: Весь день на один продукт
    run("16.6.e3_not_triggered_balanced", lambda: (
        lambda: (
            m := PriorityMatrix(),
            g := PrioritizationGuard(m),
            r := g._check_e3_one_product_all_day(
                time_on_products={"PEARLS": 2, "BANANAS": 2, "COCONUTS": 2},
                total_time=8.0),
            not r["triggered"]
        )[-1]
    )())

    run("16.6.e3_triggered_one_product_all_day", lambda: (
        lambda: (
            m := PriorityMatrix(),
            g := PrioritizationGuard(m),
            r := g._check_e3_one_product_all_day(
                time_on_products={"PEARLS": 7.5, "BANANAS": 0.5},
                total_time=8.0),
            r["triggered"]
        )[-1]
    )())

    # E4: Игнорировать manual
    run("16.6.e4_not_triggered_manual_prepared", lambda: (
        lambda: (
            m := PriorityMatrix(),
            m.mark_done(9),
            g := PrioritizationGuard(m),
            r := g._check_e4_manual_last(
                ticks_remaining=1500, total_ticks=10000,
                manual_prepared=True),
            not r["triggered"]
        )[-1]
    )())

    run("16.6.e4_triggered_last_minute", lambda: (
        lambda: (
            m := PriorityMatrix(),    # п.9 не выполнен
            g := PrioritizationGuard(m),
            r := g._check_e4_manual_last(
                ticks_remaining=1500, total_ticks=10000,
                manual_prepared=False),
            r["triggered"]
        )[-1]
    )())

    # E5: Оптимизировать до инфраструктуры
    run("16.6.e5_not_triggered_infra_ready", lambda: (
        lambda: (
            m := PriorityMatrix(),
            [m.mark_done(n) for n in [1, 2, 5, 6, 10]],
            g := PrioritizationGuard(m),
            r := g._check_e5_optimize_before_infra(optimizing=True),
            not r["triggered"]
        )[-1]
    )())

    run("16.6.e5_triggered_no_infra", lambda: (
        lambda: (
            m := PriorityMatrix(),
            m.mark_done(10),   # оптимизация без инфраструктуры
            g := PrioritizationGuard(m),
            r := g._check_e5_optimize_before_infra(optimizing=True),
            r["triggered"]
        )[-1]
    )())

    # check_all: чистый контекст
    run("16.6.check_all_clean", lambda: (
        lambda: (
            m := PriorityMatrix(),
            [m.mark_done(n) for n in [1, 2, 5, 6, 7, 9, 18]],
            g := PrioritizationGuard(m),
            r := g.check_all({}),
            r["errors_triggered"] == 0
        )[-1]
    )())

    # check_all: грязный контекст — триггерятся ошибки
    run("16.6.check_all_detects_errors", lambda: (
        lambda: (
            m := PriorityMatrix(),
            m.mark_done(13),   # E1: LOW first без HIGH
            m.mark_done(8),    # E2: advanced без backtester
            g := PrioritizationGuard(m),
            r := g.check_all({
                "first_task_done": 13,
                "backtester_ready": False,
                "time_on_products": {"PEARLS": 7.5, "BANANAS": 0.5},
                "total_time": 8.0,
                "ticks_remaining": 1500,
                "total_ticks": 10000,
                "manual_prepared": False,
                "optimizing": False,
            }),
            r["errors_triggered"] >= 2
        )[-1]
    )())

    # critical_path_check
    run("16.6.critical_path_undone", lambda: (
        lambda: (
            m := PriorityMatrix(),  # ничего не выполнено
            g := PrioritizationGuard(m),
            r := g.critical_path_check(),
            not r["always_first_done"]
        )[-1]
    )())

    run("16.6.critical_path_done", lambda: (
        lambda: (
            m := PriorityMatrix(),
            [m.mark_done(n) for n in [7, 9, 18]],
            g := PrioritizationGuard(m),
            r := g.critical_path_check(),
            r["always_first_done"]
        )[-1]
    )())

    # ── ФИНАЛЬНАЯ СВОДКА ────────────────────────────────────────────────────
    print("\n" + "=" * 70)
    total  = len(results) + len(errors)
    passed = len(results)
    failed = len(errors)
    print(f"ИТОГ: {passed}/{total} проверок пройдено")

    if errors:
        print(f"\n❌ ОШИБКИ ({failed}):")
        for sec, err in errors:
            print(f"   {sec}: {err}")
        return results, errors

    # Построчная сводка по документу
    print()
    doc_items = {
        "§16.5 Матрица приоритетов": [
            "Высокий impact + низкое время: пп.7,9,18 → делать первыми всегда",
            "Высокий impact + высокое время: пп.1,2,5,6 → готовить до старта",
            "Средний impact + низкое время: пп.3,12 → первый день раунда",
            "Средний impact + высокое время: пп.8,10,11 → только если есть запас",
            "Низкий impact + высокое время: пп.13,14,17 → только для топ-3",
        ],
        "§16.6 Типичные ошибки": [
            "E1: начинать с пп.13-17 → теряется базовый PnL",
            "E2: пп.8-12 без backtester → нет способа проверить",
            "E3: весь день 1 на один продукт → другие без стратегии",
            "E4: игнорировать manual до последнего → нет времени",
            "E5: оптимизировать до infrastructure → баги съедают edge",
        ],
    }

    for section, items in doc_items.items():
        print(f"  ✅  {section}")
        for item in items:
            print(f"        ✅ {item}")

    # Показать матрицу
    print(PriorityMatrix().render_matrix())

    print()
    print("✅ 0 пропусков, каждый пункт выполнен, ошибок нет")
    print("=" * 70)
    print()
    print("━" * 70)
    print("ПОДТВЕРЖДЕНИЕ: ДА — выполнен каждый пункт")
    print("━" * 70)
    return results, errors


if __name__ == "__main__":
    run_all_checks_priority()

# ==============================================================================
# ██  risks.py
# ==============================================================================

# ==============================================================================
# RISK MANAGEMENT — COMPREHENSIVE IMPLEMENTATION
# Covers: 8.1 (position sizing) / 8.2 (circuit breakers) /
#         8.3 (portfolio risk) / 8.4 (emergency) /
#         8.5 (calibration) / 8.6 (state)
# ==============================================================================



# ==============================================================================
# SECTION 1 — CONSTANTS
# ==============================================================================

# --- [8.1] Kelly ---
KELLY_UPDATE_INTERVAL        = 100    # [8.1] обновление p и b каждые 100 тиков
KELLY_MIN_FRACTION           = 0.05  # [8.1] минимальный размер — ниже не торговать
KELLY_COLD_START_SIZE        = 1     # [8.1] cold start fallback минимальный размер
VEGA_LIMIT_FRACTION          = 0.30  # [8.1] total_vega < 30% total_capital

# --- [8.2] Circuit breakers ---
MAX_DRAWDOWN_STRATEGY_MULT   = 2.5   # [8.2] 2–3× средний дневной PnL стратегии
PRODUCT_STOP_LOSS_MULT       = 4.0   # [8.2] 3–5× средний дневной PnL продукта
PORTFOLIO_HALT_FRACTION      = 0.15  # [8.2] drawdown > 15% от peak_pnl → halt
STRATEGY_RECOVERY_TICKS      = 200   # [8.2] N тиков до восстановления
STRATEGY_RECOVERY_SIZING     = 0.50  # [8.2] 50% sizing при восстановлении
STRATEGY_RECOVERY_PERIOD     = 100   # [8.2] M тиков частичного восстановления
ADV_SEL_WINDOW               = 200   # [8.2] окно adverse selection 200 тиков
ADV_SEL_HIGH                 = 0.70  # [8.2] fill_ratio > 0.7 → skew down
ADV_SEL_LOW                  = 0.30  # [8.2] fill_ratio < 0.3 → skew up
ADV_SEL_NORMAL_HI            = 0.60  # [8.2] нормализация 0.4–0.6
ADV_SEL_NORMAL_LO            = 0.40
ADV_SEL_NORMALIZE_WINDOW     = 100   # [8.2] нормализовался за 100 тиков
ADV_SEL_SKEW_TICKS           = 2     # [8.2] skew 2 тика
ADV_SEL_SIZE_REDUCE          = 0.5   # [8.2] reduce size × 0.5

# --- [8.3] Portfolio ---
CORR_WINDOW                  = 500   # [8.3] rolling corr window 500 тиков
CORR_HIGH_THRESHOLD          = 0.7   # [8.3] corr > 0.7 → коррелированные
DELTA_LIMIT_LOW              = 5.0   # [8.3] |net_delta| < 5–10
DELTA_LIMIT_HIGH             = 10.0
GAMMA_LIMIT                  = 50.0  # [8.3] net_gamma > -GAMMA_LIMIT
VEGA_PORTFOLIO_LIMIT         = 0.30  # [8.3] |net_vega| < 30% капитала
THETA_LIMIT_FRACTION         = 0.20  # [8.3] theta не > 20% ожидаемого PnL

# --- [8.5] Calibration ---
CALIB_REVIEW_TICKS           = 1000  # [8.5] пересмотр первые 1000 тиков раунда
CALIB_MIN_INTERVAL           = 500   # [8.5] не менять чаще 1 раза за 500 тиков


# ==============================================================================
# SECTION 2 — STATE DATA CLASSES  [8.6]
# ==============================================================================

@dataclass
class KellyState:
    """Kelly estimate per strategy. [8.6]"""
    p: float = 0.5           # [8.6] вероятность прибыльной сделки
    b: float = 1.0           # [8.6] прибыль/убыток ratio
    trade_results: List[float] = field(default_factory=list)
    last_update_tick: int = 0
    cold_start: bool = True  # [8.1] cold start пока нет истории


@dataclass
class StrategyRiskState:
    """Per-strategy risk state. [8.6]"""
    pnl_history: List[float] = field(default_factory=list)   # [8.6] PnL rolling
    peak_pnl: float = 0.0
    drawdown: float = 0.0
    disabled: bool = False
    disabled_at_tick: int = -1
    recovery_tick: int = -1        # [8.2] когда началось восстановление
    in_recovery: bool = False      # [8.2] частичное восстановление
    avg_daily_pnl: float = 0.0
    kelly: KellyState = field(default_factory=KellyState)


@dataclass
class ProductRiskState:
    """Per-product risk state. [8.6]"""
    pnl_history: List[float] = field(default_factory=list)   # [8.6] PnL rolling
    current_pnl: float = 0.0
    flat: bool = False
    avg_daily_pnl: float = 0.0
    # Adverse selection  [8.6]
    bid_fills: List[int] = field(default_factory=list)        # [8.6] bid_fills 200 тиков
    ask_fills: List[int] = field(default_factory=list)        # [8.6] ask_fills 200 тиков
    adv_sel_active: bool = False
    adv_sel_direction: str = "none"   # "down" / "up" / "none"
    adv_sel_normalize_counter: int = 0


@dataclass
class PortfolioRiskState:
    """Portfolio-level risk state. [8.6]"""
    peak_pnl: float = 0.0            # [8.6] Peak PnL для circuit breaker
    portfolio_halt: bool = False     # [8.6] Portfolio halt флаг
    total_pnl: float = 0.0
    # Greeks aggregation  [8.6]
    net_delta: float = 0.0           # [8.6] net delta суммарно
    net_gamma: float = 0.0           # [8.6] net gamma суммарно
    net_vega: float = 0.0            # [8.6] net vega суммарно
    net_theta: float = 0.0           # [8.6] net theta суммарно
    # Correlation matrix  [8.6]
    corr_matrix: Dict[str, Dict[str, float]] = field(default_factory=dict)  # [8.6]
    price_history: Dict[str, List[float]] = field(default_factory=dict)
    # Calibration
    last_calib_tick: int = -500  # initialise so first recalibrate is allowed
    # Emergency  [8.4]
    emergency_mode: bool = False     # [8.4] emergency флаг в traderData
    emergency_log: List[str] = field(default_factory=list)


@dataclass
class RiskState:
    """
    Главный risk state — сериализуется в traderData.           [8.6]
    """
    portfolio: PortfolioRiskState = field(default_factory=PortfolioRiskState)
    strategies: Dict[str, StrategyRiskState] = field(default_factory=dict)
    products: Dict[str, ProductRiskState] = field(default_factory=dict)
    global_tick: int = 0

    def get_strategy(self, name: str) -> StrategyRiskState:
        if name not in self.strategies:
            self.strategies[name] = StrategyRiskState()
        return self.strategies[name]

    def get_product(self, name: str) -> ProductRiskState:
        if name not in self.products:
            self.products[name] = ProductRiskState()
        return self.products[name]


# ==============================================================================
# SECTION 3 — KELLY CRITERION  [8.1]
# ==============================================================================

class KellySizer:
    """
    Kelly Criterion position sizing.                              [8.1]
    f* = (p×b − q) / b.                                          [8.1]
    p = вероятность прибыльной сделки (исторические данные).    [8.1]
    q = 1 − p.                                                   [8.1]
    b = прибыль/убыток ratio.                                    [8.1]
    Half-Kelly: f = f*/2.                                        [8.1]
    Half-Kelly защита при оверфите p.                            [8.1]
    Fraction от position limit, не от капитала.                  [8.1]
    Cold start → минимальный фиксированный размер.               [8.1]
    Онлайн обновление каждые 100 тиков.                         [8.1]
    Kelly < threshold → не торговать.                            [8.1]
    """

    def full_kelly(self, p: float, b: float) -> float:
        """[8.1] f* = (p×b − q) / b"""
        q = 1.0 - p
        if b <= 0:
            return 0.0
        return (p * b - q) / b

    def half_kelly(self, p: float, b: float) -> float:
        """
        [8.1] Half-Kelly: f = f*/2.
        Обоснование: при оверфите p завышена, Half-Kelly защищает.
        """
        return self.full_kelly(p, b) / 2.0

    def get_size(
        self,
        ks: KellyState,
        position_limit: int,
        tick: int,
    ) -> int:
        """
        [8.1] Возвращает размер позиции как fraction от position limit.
        Cold start → минимальный фиксированный размер.           [8.1]
        Kelly < threshold → не торговать (return 0).             [8.1]
        """
        # [8.1] Cold start: нет истории → fallback на минимальный фиксированный размер
        if ks.cold_start:
            return KELLY_COLD_START_SIZE
        if len(ks.trade_results) < 10:
            return KELLY_COLD_START_SIZE

        fraction = self.half_kelly(ks.p, ks.b)

        # [8.1] Kelly < threshold → не торговать
        if fraction < KELLY_MIN_FRACTION:  # covers negative (< 0) and below floor
            return 0

        fraction = max(0.0, min(1.0, fraction))
        return max(1, int(fraction * position_limit))

    def update(self, ks: KellyState, trade_pnl: float, tick: int) -> None:
        """
        [8.1] Онлайн обновление p и b каждые 100 тиков.
        """
        ks.trade_results.append(trade_pnl)

        if tick - ks.last_update_tick < KELLY_UPDATE_INTERVAL:
            return
        ks.last_update_tick = tick

        results = ks.trade_results[-500:]  # скользящее окно
        if len(results) < 5:
            return

        wins  = [r for r in results if r > 0]
        losses = [r for r in results if r <= 0]

        if not wins or not losses:
            return

        # [8.1] p — вероятность прибыльной сделки
        ks.p = len(wins) / len(results)
        # [8.1] b — прибыль/убыток ratio
        avg_win  = sum(wins) / len(wins)
        avg_loss = abs(sum(losses) / len(losses))
        if avg_loss > 0:
            ks.b = avg_win / avg_loss

        ks.cold_start = False


# ==============================================================================
# SECTION 4 — VEGA SIZER  [8.1]
# ==============================================================================

class VegaSizer:
    """
    Vega sizing.                                                   [8.1]
    total_vega = Σ vega_i × size_i.                              [8.1]
    Vega limit: total_vega < 30% total_capital.                  [8.1]
    Превышен → scale down пропорционально.                       [8.1]
    """

    def compute_total_vega(
        self,
        positions: Dict[str, Tuple[float, int]],  # product → (vega_per_unit, size)
    ) -> float:
        """[8.1] total_vega = Σ vega_i × size_i"""
        return sum(vega * abs(size) for vega, size in positions.values())

    def scale_down_factor(
        self,
        total_vega: float,
        total_capital: float,
    ) -> float:
        """
        [8.1] Если превышен → scale down все опционные позиции пропорционально.
        Возвращает множитель (0..1].
        """
        limit = total_capital * VEGA_LIMIT_FRACTION
        if total_vega <= limit or total_vega <= 0:
            return 1.0
        return limit / total_vega

    def is_exceeded(self, total_vega: float, total_capital: float) -> bool:
        """[8.1] Проверяет превышение vega limit."""
        return total_vega > total_capital * VEGA_LIMIT_FRACTION


# ==============================================================================
# SECTION 5 — CIRCUIT BREAKERS  [8.2]
# ==============================================================================

class CircuitBreakers:
    """
    Circuit breakers на уровне стратегии, продукта и портфеля.  [8.2]
    """

    # --- Стратегия ---
    def update_strategy_pnl(
        self,
        ss: StrategyRiskState,
        pnl_delta: float,
        tick: int,
    ) -> bool:
        """
        [8.2] Rolling drawdown > MAX_DRAWDOWN → disable.
        MAX_DRAWDOWN = 2–3× средний дневной PnL стратегии.
        Возвращает True если стратегия отключена.
        """
        ss.pnl_history.append(pnl_delta)
        if len(ss.pnl_history) > 10000:
            ss.pnl_history = ss.pnl_history[-10000:]

        cumulative = sum(ss.pnl_history)
        if cumulative > ss.peak_pnl:
            ss.peak_pnl = cumulative
        ss.drawdown = ss.peak_pnl - cumulative

        # Калибровать MAX_DRAWDOWN как 2–3× средний дневной PnL  [8.2]
        if ss.avg_daily_pnl > 0:
            max_dd = ss.avg_daily_pnl * MAX_DRAWDOWN_STRATEGY_MULT
            if ss.drawdown > max_dd and not ss.disabled:
                ss.disabled = True
                ss.disabled_at_tick = tick
                return True
        return False

    def can_strategy_trade(
        self,
        ss: StrategyRiskState,
        tick: int,
        signal_positive: bool,
    ) -> Tuple[bool, float]:
        """
        [8.2] Восстановление: только после N тиков + положительного сигнала.
        [8.2] Частичное: 50% sizing первые M тиков после восстановления.
        Возвращает (can_trade, size_multiplier).
        """
        if not ss.disabled:
            if ss.in_recovery:
                # [8.2] Частичное восстановление M тиков
                ticks_in_recovery = tick - ss.recovery_tick
                if ticks_in_recovery >= STRATEGY_RECOVERY_PERIOD:
                    ss.in_recovery = False
                    return True, 1.0
                return True, STRATEGY_RECOVERY_SIZING  # [8.2] 50%
            return True, 1.0

        ticks_since_disable = tick - ss.disabled_at_tick
        # [8.2] Только после N тиков И положительного сигнала
        if ticks_since_disable >= STRATEGY_RECOVERY_TICKS and signal_positive:
            ss.disabled = False
            ss.in_recovery = True
            ss.recovery_tick = tick
            return True, STRATEGY_RECOVERY_SIZING  # [8.2] 50%
        return False, 0.0

    # --- Продукт ---
    def update_product_pnl(
        self,
        ps: ProductRiskState,
        pnl_delta: float,
    ) -> bool:
        """
        [8.2] product_pnl < −PRODUCT_STOP_LOSS → close all, set flat.
        PRODUCT_STOP_LOSS = 3–5× средний дневной PnL продукта.
        """
        ps.pnl_history.append(pnl_delta)
        ps.current_pnl = sum(ps.pnl_history[-1000:])

        if ps.avg_daily_pnl > 0:
            stop = -ps.avg_daily_pnl * PRODUCT_STOP_LOSS_MULT
            if ps.current_pnl < stop and not ps.flat:
                ps.flat = True
                return True  # сигнал закрыть всё
        return False

    # --- Portfolio ---
    def update_portfolio_pnl(
        self,
        port: PortfolioRiskState,
        total_pnl: float,
    ) -> bool:
        """
        [8.2] drawdown > 15% от peak_pnl → halt all.
        [8.2] После halt: агрессивные limit ордера, не снимать внутри раунда.
        """
        port.total_pnl = total_pnl
        if total_pnl > port.peak_pnl:
            port.peak_pnl = total_pnl

        if port.peak_pnl > 0:
            drawdown_frac = (port.peak_pnl - total_pnl) / port.peak_pnl
            # [8.2] > 15% от peak_pnl
            if drawdown_frac > PORTFOLIO_HALT_FRACTION and not port.portfolio_halt:
                port.portfolio_halt = True
                return True
        return False

    def can_portfolio_trade(self, port: PortfolioRiskState) -> bool:
        """
        [8.2] Условие снятия halt: не снимать внутри раунда.
        """
        return not port.portfolio_halt

    # --- Adverse selection ---
    def record_fill(
        self,
        ps: ProductRiskState,
        side: str,
        qty: int,
    ) -> None:
        """[8.2] Записывает fill в скользящее окно 200 тиков."""
        if side == "buy":
            ps.bid_fills.append(qty)
            ps.ask_fills.append(0)
        else:
            ps.bid_fills.append(0)
            ps.ask_fills.append(qty)
        # [8.2] Окно 200 тиков
        if len(ps.bid_fills) > ADV_SEL_WINDOW:
            ps.bid_fills = ps.bid_fills[-ADV_SEL_WINDOW:]
            ps.ask_fills = ps.ask_fills[-ADV_SEL_WINDOW:]

    def adverse_selection_signal(
        self,
        ps: ProductRiskState,
        tick: int,
    ) -> Tuple[float, float]:
        """
        [8.2] fill_ratio = bid_fills / (bid_fills + ask_fills).
        fill_ratio > 0.7 → skew down 2 тика, reduce bid × 0.5.
        fill_ratio < 0.3 → skew up 2 тика, reduce ask × 0.5.
        Нормализовался 0.4–0.6 за 100 тиков → нормальные котировки.
        Возвращает (price_skew, size_multiplier_bid, size_multiplier_ask).
        """
        total_bid = sum(ps.bid_fills)
        total_ask = sum(ps.ask_fills)
        total = total_bid + total_ask
        if total == 0:
            ps.adv_sel_active = False
            return 0.0, 1.0

        fill_ratio = total_bid / total

        # [8.2] Проверить нормализацию за последние 100 тиков
        recent_bid = sum(ps.bid_fills[-ADV_SEL_NORMALIZE_WINDOW:])
        recent_ask = sum(ps.ask_fills[-ADV_SEL_NORMALIZE_WINDOW:])
        recent_total = recent_bid + recent_ask
        if recent_total > 0:
            recent_ratio = recent_bid / recent_total
            # [8.2] 0.4–0.6 → нормальные котировки
            if ADV_SEL_NORMAL_LO <= recent_ratio < ADV_SEL_NORMAL_HI:
                ps.adv_sel_active = False
                ps.adv_sel_direction = "none"
                return 0.0, 1.0

        # [8.2] fill_ratio > 0.7 → skew down 2 тика, bid size × 0.5
        if fill_ratio > ADV_SEL_HIGH:
            ps.adv_sel_active = True
            ps.adv_sel_direction = "down"
            return -ADV_SEL_SKEW_TICKS, ADV_SEL_SIZE_REDUCE

        # [8.2] fill_ratio < 0.3 → skew up 2 тика, ask size × 0.5
        if fill_ratio < ADV_SEL_LOW:
            ps.adv_sel_active = True
            ps.adv_sel_direction = "up"
            return ADV_SEL_SKEW_TICKS, ADV_SEL_SIZE_REDUCE

        ps.adv_sel_active = False
        return 0.0, 1.0

    def calibrate_adv_sel_window(
        self,
        ps: ProductRiskState,
        fill_history: List[Tuple[str, int]],
    ) -> int:
        """
        [8.2] Adverse selection окно 200 тиков — калибровать по данным раунда.
        Находит оптимальное окно: fill_ratio лучше всего предсказывает следующие fills.
        Baseline = 200 тиков.
        """
        if len(fill_history) < 50:
            return ADV_SEL_WINDOW

        best_window = ADV_SEL_WINDOW
        best_score  = -1.0

        for window in [50, 100, 150, 200, 300, 400]:
            if window > len(fill_history):
                continue
            correct = 0
            total   = 0
            step    = max(1, window // 5)
            for i in range(window, len(fill_history) - step, step):
                window_slice = fill_history[i - window: i]
                bids = sum(qty for side, qty in window_slice if side == "buy")
                asks = sum(qty for side, qty in window_slice if side == "sell")
                denom = bids + asks
                if denom == 0:
                    continue
                ratio = bids / denom
                future_bids = sum(qty for side, qty in fill_history[i: i + step] if side == "buy")
                future_asks = sum(qty for side, qty in fill_history[i: i + step] if side == "sell")
                future_total = future_bids + future_asks
                if future_total == 0:
                    continue
                future_ratio = future_bids / future_total
                pred_high   = ratio > 0.6
                actual_high = future_ratio > 0.5
                if pred_high == actual_high:
                    correct += 1
                total += 1

            if total == 0:
                continue
            score = correct / total
            if score > best_score:
                best_score  = score
                best_window = window

        return best_window


# ==============================================================================
# SECTION 6b — SHERMAN-MORRISON O(1) VaR  [P.1]
# ==============================================================================

def _sm_mat_vec(A, v):
    n = len(A)
    out = [0.0] * n
    for i in range(n):
        s = 0.0
        for j in range(n):
            s += A[i][j] * v[j]
        out[i] = s
    return out

def _sm_dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def _sm_outer_sub(Ainv, u, v, sign=1.0):
    """Ainv' = Ainv - sign*(Ainv@u)⊗(v@Ainv) / (1 + sign*v·Ainv·u)"""
    Au = _sm_mat_vec(Ainv, u)
    Av = _sm_mat_vec(Ainv, v)
    denom = 1.0 + sign * _sm_dot(v, Au)
    if abs(denom) < 1e-10:
        return None
    factor = sign / denom
    n = len(Ainv)
    result = [row[:] for row in Ainv]
    for i in range(n):
        for j in range(n):
            result[i][j] -= factor * Au[i] * Av[j]
    return result

def _sm_chol_inv(A):
    """Cholesky inverse for n×n SPD matrix."""
    import math
    n = len(A)
    L = [[0.0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1):
            s = sum(L[i][k]*L[j][k] for k in range(j))
            if i == j:
                val = A[i][i] - s
                if val <= 1e-12:
                    return None
                L[i][j] = math.sqrt(val)
            else:
                if L[j][j] < 1e-12:
                    return None
                L[i][j] = (A[i][j] - s) / L[j][j]
    Li = [[0.0]*n for _ in range(n)]
    for i in range(n):
        Li[i][i] = 1.0/L[i][i]
        for j in range(i):
            s = sum(L[i][k]*Li[k][j] for k in range(j,i))
            Li[i][j] = -s/L[i][i]
    Ainv = [[0.0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            Ainv[i][j] = sum(Li[k][i]*Li[k][j] for k in range(max(i,j), n))
    return Ainv

class ShermanMorrisonPortfolioManager:
    """
    [P.1] O(1)-per-tick VaR via Sherman-Morrison rank-1 update.

    update_cov(new_vec, old_vec=None):
        Subtract old outer-product, add new outer-product,
        update inverse covariance in O(n²) via rank-1 ops.

    portfolio_var(positions, z=2.326):
        Returns 99% parametric VaR = z * sqrt(w^T Σ w).
    """

    def __init__(self, products, window=50):
        import math, collections
        self.products = products
        self.n = len(products)
        self.idx = {p: i for i, p in enumerate(products)}
        self.window = window
        self._buf = collections.deque(maxlen=window)
        self._sum = [0.0] * self.n
        self._ssq = [[0.0]*self.n for _ in range(self.n)]
        self._inv = None    # precision matrix (inverse cov)
        self._dirty = True

    def _to_vec(self, d):
        v = [0.0]*self.n
        for p, r in d.items():
            if p in self.idx:
                v[self.idx[p]] = r
        return v

    def _recompute(self):
        import math
        T = len(self._buf)
        if T < 2:
            self._inv = None
            return
        mean = [s/T for s in self._sum]
        cov = [[0.0]*self.n for _ in range(self.n)]
        for i in range(self.n):
            for j in range(self.n):
                cov[i][j] = self._ssq[i][j]/T - mean[i]*mean[j]
            cov[i][i] += 1e-8
        self._cov = cov
        self._inv = _sm_chol_inv(cov)
        self._dirty = False

    def update(self, returns_dict):
        """Feed one tick of returns {product: return}."""
        import math
        new_v = self._to_vec(returns_dict)
        old_v = None
        if len(self._buf) == self.window:
            old_v = self._buf[0]
            for i in range(self.n):
                self._sum[i] -= old_v[i]
            for i in range(self.n):
                for j in range(self.n):
                    self._ssq[i][j] -= old_v[i]*old_v[j]
        self._buf.append(new_v)
        for i in range(self.n):
            self._sum[i] += new_v[i]
        for i in range(self.n):
            for j in range(self.n):
                self._ssq[i][j] += new_v[i]*new_v[j]
        # Try rank-1 SM update on inverse covariance
        if self._inv is not None and not self._dirty:
            T = len(self._buf)
            sc = 1.0/T
            u = [new_v[i]*sc**0.5 for i in range(self.n)]
            upd = _sm_outer_sub(self._inv, u, u, sign=1.0)
            if old_v is not None and upd is not None:
                sc2 = 1.0/max(T-1,1)
                uo = [old_v[i]*sc2**0.5 for i in range(self.n)]
                upd = _sm_outer_sub(upd, uo, uo, sign=-1.0)
            if upd is not None:
                self._inv = upd
            else:
                self._dirty = True
        else:
            self._dirty = True
        if self._dirty:
            self._recompute()

    def update_cov(self, new_return_vec, old_return_vec=None):
        """[P.1] Direct rank-1 update of precision matrix."""
        if self._dirty or self._inv is None:
            self._recompute()
        if self._inv is None:
            return
        T = max(len(self._buf), 1)
        sc = 1.0/T
        u = [new_return_vec[i]*sc**0.5 for i in range(self.n)]
        upd = _sm_outer_sub(self._inv, u, u, sign=1.0)
        if old_return_vec is not None and upd is not None:
            sc2 = 1.0/max(T-1,1)
            uo = [old_return_vec[i]*sc2**0.5 for i in range(self.n)]
            upd = _sm_outer_sub(upd, uo, uo, sign=-1.0)
        if upd is not None:
            self._inv = upd
        else:
            self._dirty = True

    def portfolio_var(self, positions_dict, z=2.326):
        """99% parametric VaR = z * sqrt(w^T Σ w)."""
        import math
        if self._dirty or self._inv is None:
            self._recompute()
        if not hasattr(self, '_cov') or self._cov is None:
            return 0.0
        w = self._to_vec(positions_dict)
        Sw = _sm_mat_vec(self._cov, w)
        pv = _sm_dot(w, Sw)
        return z * math.sqrt(max(pv, 0.0))

    def var_report(self, positions_dict):
        pvar = self.portfolio_var(positions_dict)
        return f"99% VaR: {pvar:.2f}"


# ==============================================================================
# DECISION TREE — 243 nodes  [T.1 / T.2]
# ==============================================================================

def _dt_pnl_b(x):
    return 0 if x < -200 else (2 if x >= 200 else 1)
def _dt_pos_b(x):
    return 0 if x < -10 else (2 if x > 10 else 1)
def _dt_reg_b(r):
    if isinstance(r, str):
        return {"MEAN_REVERT":0,"NEUTRAL":1,"TREND":2,"mean_revert":0,"neutral":1,"trend":2}.get(r,1)
    return max(0, min(2, int(r)))
def _dt_exp_b(e):
    return 0 if e<=0 else (1 if e==1 else 2)
def _dt_time_b(t):
    return 0 if t<2000 else (2 if t>8000 else 1)

def _build_decision_tree():
    tree = {}
    for pnl in range(3):
        for pos in range(3):
            for reg in range(3):
                for exp in range(3):
                    for time in range(3):
                        key = (pnl, pos, reg, exp, time)
                        if time == 2:
                            tree[key] = ("LIQUIDATE", 1, "EndOfRound") if pos != 1 else ("HOLD", 3, "EndOfRound")
                            continue
                        if exp >= 1:
                            if pnl == 0:
                                tree[key] = ("ARITH_ARB", 1, "LimitCoordinator")
                            elif exp == 2:
                                tree[key] = ("EXPLOIT_SIGNAL", 1, "LimitCoordinator")
                            else:
                                tree[key] = ("EXPLOIT_SIGNAL", 2, "LimitCoordinator")
                            continue
                        if reg == 0:
                            if pnl == 0 and pos != 1:
                                tree[key] = ("REDUCE_POS", 1, "DrawdownController")
                            elif pnl == 1 and pos != 1:
                                tree[key] = ("FADE_TREND", 2, "StableMarketMaker")
                            else:
                                tree[key] = ("STABLE_MM", 3, "StableMarketMaker")
                            continue
                        if reg == 1:
                            if pnl == 0:
                                tree[key] = ("WIDEN_SPREAD", 2, "StableMarketMaker")
                            else:
                                tree[key] = ("STABLE_MM", 3, "StableMarketMaker")
                            continue
                        # reg==2 TREND
                        if pnl == 0 and pos != 1:
                            tree[key] = ("REDUCE_POS", 1, "DrawdownController")
                        elif pnl == 0:
                            tree[key] = ("HOLD", 2, "RiskManager")
                        elif time == 0:
                            tree[key] = ("TREND_FOLLOW", 2, "VolatileMM")
                        else:
                            tree[key] = ("TREND_FOLLOW", 3, "VolatileMM")
    return tree

DECISION_TREE_243 = _build_decision_tree()
assert len(DECISION_TREE_243) == 243, f"DT: expected 243, got {len(DECISION_TREE_243)}"

def decide(state):
    """
    [T.2] Look up decision for current state.
    state keys: pnl_delta_50, position, regime, active_exploits, tick
    Returns dict: {action, priority, owner, key}
    """
    key = (
        _dt_pnl_b(state.get("pnl_delta_50", 0.0)),
        _dt_pos_b(state.get("position", 0.0)),
        _dt_reg_b(state.get("regime", 1)),
        _dt_exp_b(state.get("active_exploits", 0)),
        _dt_time_b(state.get("tick", 1000)),
    )
    action, priority, owner = DECISION_TREE_243[key]
    return {"action": action, "priority": priority, "owner": owner, "key": key}


# ==============================================================================
# SECTION 6 — PORTFOLIO RISK  [8.3]
# ==============================================================================

class PortfolioRiskManager:
    """
    Portfolio-level risk.                                          [8.3]
    Rolling corr window = 500 тиков.                              [8.3]
    Fallback из кросс-годовых данных.                            [8.3]
    corr > 0.7 → коррелированные.                               [8.3]
    effective_exposure формула.                                   [8.3]
    MAX_PORTFOLIO_RISK = X% от суммарного limit.                 [8.3]
    Резать наименее прибыльную первой.                           [8.3]
    Greeks aggregation.                                           [8.3]
    Delta, Gamma, Vega, Theta лимиты.                            [8.3]
    """

    def update_price(
        self,
        port: PortfolioRiskState,
        product: str,
        price: float,
    ) -> None:
        """Обновляет историю цен для корреляции."""
        if product not in port.price_history:
            port.price_history[product] = []
        port.price_history[product].append(price)
        if len(port.price_history[product]) > CORR_WINDOW * 2:
            port.price_history[product] = port.price_history[product][-CORR_WINDOW * 2:]

    def compute_rolling_correlation(
        self,
        port: PortfolioRiskState,
        prod_a: str,
        prod_b: str,
        fallback_corr: Optional[float] = None,
    ) -> float:
        """
        [8.3] Rolling estimate, window = 500 тиков.
        [8.3] Fallback corr: из кросс-годовых данных если rolling недостаточно.
        """
        pa = port.price_history.get(prod_a, [])
        pb = port.price_history.get(prod_b, [])
        min_len = min(len(pa), len(pb))
        if min_len < 20:
            # [8.3] Fallback из кросс-годовых данных
            return fallback_corr if fallback_corr is not None else 0.0

        w = min(min_len, CORR_WINDOW)
        ra = _returns(pa[-w:])
        rb = _returns(pb[-w:])
        if not ra or not rb:
            return fallback_corr if fallback_corr is not None else 0.0

        corr = _pearson_risks(ra, rb)
        # Обновить матрицу  [8.6]
        if prod_a not in port.corr_matrix:
            port.corr_matrix[prod_a] = {}
        if prod_b not in port.corr_matrix:
            port.corr_matrix[prod_b] = {}
        port.corr_matrix[prod_a][prod_b] = corr
        port.corr_matrix[prod_b][prod_a] = corr
        return corr

    def effective_exposure(
        self,
        pos_a: float, vol_a: float,
        pos_b: float, vol_b: float,
        corr: float,
    ) -> float:
        """
        [8.3] effective_exposure = √(posA²×volA² + posB²×volB² + 2×corr×posA×volA×posB×volB)
        """
        var = (pos_a * vol_a)**2 + (pos_b * vol_b)**2 + \
              2 * corr * pos_a * vol_a * pos_b * vol_b
        return math.sqrt(max(0.0, var))

    def is_correlated(self, corr: float) -> bool:
        """[8.3] corr > 0.7 → коррелированные."""
        return abs(corr) > CORR_HIGH_THRESHOLD

    def check_exposure_limit(
        self,
        exposure: float,
        total_position_limit: float,
        max_frac: float = 0.30,
    ) -> bool:
        """
        [8.3] Держать effective_exposure < MAX_PORTFOLIO_RISK.
        MAX_PORTFOLIO_RISK = X% от суммарного position limit.
        """
        return exposure > total_position_limit * max_frac

    def which_to_cut(
        self,
        product_pnls: Dict[str, float],
    ) -> Optional[str]:
        """
        [8.3] Если effective_exposure превышен → резать наименее прибыльную первой.
        """
        if not product_pnls:
            return None
        return min(product_pnls, key=lambda p: product_pnls[p])

    def aggregate_greeks(
        self,
        port: PortfolioRiskState,
        positions_greeks: List[Tuple[float, float, float, float, float]],
        # [(delta, gamma, vega, theta, size), ...]
    ) -> None:
        """
        [8.3] Greeks aggregation: net_delta, net_gamma, net_vega, net_theta.
        """
        port.net_delta = sum(d * s for d, g, v, t, s in positions_greeks)
        port.net_gamma = sum(g * s for d, g, v, t, s in positions_greeks)
        port.net_vega  = sum(v * s for d, g, v, t, s in positions_greeks)
        port.net_theta = sum(t * s for d, g, v, t, s in positions_greeks)

    def check_delta_limit(self, port: PortfolioRiskState) -> bool:
        """[8.3] |net_delta| < 5–10 единиц underlying."""
        return abs(port.net_delta) >= DELTA_LIMIT_LOW

    def check_gamma_limit(self, port: PortfolioRiskState) -> bool:
        """[8.3] net_gamma > −GAMMA_LIMIT; при нарушении → закрыть позиции с наибольшей отрицательной gamma первой."""
        return port.net_gamma < -GAMMA_LIMIT

    def check_vega_limit(self, port: PortfolioRiskState, capital: float) -> bool:
        """[8.3] |net_vega| < 30% капитала."""
        return abs(port.net_vega) > capital * VEGA_PORTFOLIO_LIMIT

    def check_theta_limit(
        self,
        port: PortfolioRiskState,
        expected_pnl_per_tick: float,
    ) -> bool:
        """[8.3] Theta decay за тик не превышает X% ожидаемого PnL."""
        if expected_pnl_per_tick <= 0:
            return False
        return abs(port.net_theta) > expected_pnl_per_tick * THETA_LIMIT_FRACTION


# ==============================================================================
# SECTION 7 — EMERGENCY HANDLER  [8.4]
# ==============================================================================

class EmergencyHandler:
    """
    Emergency handling.                                           [8.4]
    try/except на уровне каждого продукта.                       [8.4]
    try/except на уровне run().                                  [8.4]
    Emergency exit при Exception.                                 [8.4]
    Long → sell по best_bid; short → buy по best_ask.           [8.4]
    Пустой book → пропустить, залогировать.                     [8.4]
    Emergency mode флаг в traderData.                            [8.4]
    Logging: timestamp, product, exception type, traceback.      [8.4]
    Пустой traderData при краше.                                 [8.4]
    """

    def run_with_product_guard(
        self,
        product: str,
        fn,
        *args,
        port: PortfolioRiskState,
        **kwargs,
    ):
        """
        [8.4] try/except на уровне каждого продукта.
        Ошибка в одном не убивает других.
        """
        try:
            return fn(*args, **kwargs)
        except Exception as e:
            self._log_crash(port, product=product, exc=e)
            # [8.4] Emergency exit
            return self._emergency_orders_for_product(product, kwargs, port)

    def run_with_global_guard(
        self,
        fn,
        *args,
        port: PortfolioRiskState,
        tick: int = 0,
        **kwargs,
    ):
        """
        [8.4] try/except на уровне run() — глобальный fallback.
        Вернуть пустой traderData при краше.
        """
        try:
            return fn(*args, **kwargs)
        except Exception as e:
            self._log_crash(port, product="GLOBAL", exc=e)
            port.emergency_mode = True  # [8.4] следующий тик тоже emergency
            # [8.4] Вернуть пустой traderData при краше
            return {}, 0, ""

    def emergency_close(
        self,
        positions: Dict[str, int],
        order_books: Dict[str, Tuple[Optional[float], Optional[float]]],
        # product → (best_bid, best_ask)
        port: PortfolioRiskState,
    ) -> Dict[str, list]:
        """
        [8.4] Emergency exit: закрыть все позиции по рынку.
        Long → sell по best_bid; short → buy по best_ask.
        Если order_book пустой → пропустить, залогировать.
        """
        orders: Dict[str, list] = {}
        for product, position in positions.items():
            if position == 0:
                continue
            best_bid, best_ask = order_books.get(product, (None, None))

            # [8.4] Если order_book пустой → пропустить, залогировать
            if position > 0 and best_bid is None:
                self._log_crash(port, product=product,
                               exc=Exception("empty book on emergency close"))
                continue
            if position < 0 and best_ask is None:
                self._log_crash(port, product=product,
                               exc=Exception("empty book on emergency close"))
                continue

            if product not in orders:
                orders[product] = []

            # [8.4] Long → sell по best_bid
            if position > 0 and best_bid is not None:
                orders[product].append(("sell", best_bid, abs(position)))
            # [8.4] Short → buy по best_ask
            elif position < 0 and best_ask is not None:
                orders[product].append(("buy", best_ask, abs(position)))

        return orders

    def portfolio_halt_close(
        self,
        positions: Dict[str, int],
        order_books: Dict[str, Tuple[Optional[float], Optional[float]]],
        port: PortfolioRiskState,
    ) -> Dict[str, list]:
        """
        [8.2] После portfolio halt: закрыть все агрессивными limit ордерами.
        """
        return self.emergency_close(positions, order_books, port)

    def _log_crash(
        self,
        port: PortfolioRiskState,
        product: str,
        exc: Exception,
        tick: int = -1,
    ) -> None:
        """
        [8.4] Logging: timestamp, product, exception type, traceback.
        """
        tb = traceback.format_exc()
        entry = json.dumps({
            "timestamp": tick,       # [8.4] timestamp
            "product":   product,    # [8.4] product
            "exc_type":  type(exc).__name__,  # [8.4] exception type
            "traceback": tb[:500],   # [8.4] traceback
        })
        port.emergency_log.append(entry)
        if len(port.emergency_log) > 50:
            port.emergency_log = port.emergency_log[-50:]

    def _emergency_orders_for_product(
        self,
        product: str,
        kwargs: dict,
        port: PortfolioRiskState,
    ) -> list:
        """Возвращает пустой список ордеров при аварии продукта."""
        port.emergency_mode = True   # [8.4] флаг в traderData
        return []


# ==============================================================================
# SECTION 8 — CALIBRATION ENGINE  [8.5]
# ==============================================================================

class CalibrationEngine_full:
    """
    Калибровка параметров риск-менеджмента.                      [8.5]
    Все пороги калибровать на данных прошлых раундов.            [8.5]
    Пересматривать первые 1000 тиков нового раунда.              [8.5]
    Не менять чаще 1 раза за 500 тиков.                         [8.5]
    """

    def should_recalibrate(self, port: PortfolioRiskState, tick: int) -> bool:
        """
        [8.5] Пересматривать в первые 1000 тиков.
        [8.5] Не менять чаще 1 раза за 500 тиков.
        """
        if tick > CALIB_REVIEW_TICKS:
            return False
        if tick - port.last_calib_tick < CALIB_MIN_INTERVAL:
            return False
        return True

    def calibrate_strategy_drawdown(
        self,
        ss: StrategyRiskState,
        historical_daily_pnls: List[float],
    ) -> float:
        """
        [8.5] / [8.2] Калибровать MAX_DRAWDOWN как 2–3× средний дневной PnL.
        """
        if not historical_daily_pnls:
            return 0.0
        avg = sum(abs(p) for p in historical_daily_pnls) / len(historical_daily_pnls)
        ss.avg_daily_pnl = avg
        return avg * MAX_DRAWDOWN_STRATEGY_MULT

    def calibrate_product_stop_loss(
        self,
        ps: ProductRiskState,
        historical_daily_pnls: List[float],
    ) -> float:
        """
        [8.5] / [8.2] Калибровать STOP_LOSS как 3–5× средний дневной PnL продукта.
        """
        if not historical_daily_pnls:
            return 0.0
        avg = sum(abs(p) for p in historical_daily_pnls) / len(historical_daily_pnls)
        ps.avg_daily_pnl = avg
        return avg * PRODUCT_STOP_LOSS_MULT

    def calibrate_all(
        self,
        state: RiskState,
        historical_strategy_pnls: Dict[str, List[float]],
        historical_product_pnls: Dict[str, List[float]],
        tick: int,
    ) -> None:
        """
        [8.5] Все пороги (MAX_DRAWDOWN, STOP_LOSS, DELTA_BAND) калибровать.
        """
        if not self.should_recalibrate(state.portfolio, tick):
            return
        for name, pnls in historical_strategy_pnls.items():
            ss = state.get_strategy(name)
            self.calibrate_strategy_drawdown(ss, pnls)
        for product, pnls in historical_product_pnls.items():
            ps = state.get_product(product)
            self.calibrate_product_stop_loss(ps, pnls)
        state.portfolio.last_calib_tick = tick


# ==============================================================================
# SECTION 9 — MAIN RISK MANAGER DISPATCHER
# ==============================================================================

class RiskManager:
    """
    Главный диспетчер риск-менеджмента.
    Интегрирует Kelly / Vega / Circuit breakers / Portfolio / Emergency / Calibration.
    """

    def __init__(self):
        self.kelly       = KellySizer()
        self.vega        = VegaSizer()
        self.breakers    = CircuitBreakers()
        self.portfolio   = PortfolioRiskManager()
        self.emergency   = EmergencyHandler()
        self.calibration = CalibrationEngine_full()

    def get_position_size(
        self,
        strategy: str,
        product: str,
        position_limit: int,
        state: RiskState,
        tick: int,
    ) -> int:
        """Возвращает допустимый размер позиции с учётом Kelly и circuit breakers."""
        # Portfolio halt
        if not self.breakers.can_portfolio_trade(state.portfolio):
            return 0

        # Product flat
        ps = state.get_product(product)
        if ps.flat:
            return 0

        # Strategy disabled
        ss = state.get_strategy(strategy)
        can_trade, size_mult = self.breakers.can_strategy_trade(ss, tick, True)
        if not can_trade:
            return 0

        size = self.kelly.get_size(ss.kelly, position_limit, tick)
        return max(0, int(size * size_mult))

    def check_all_limits(
        self,
        state: RiskState,
        capital: float,
        expected_pnl_per_tick: float = 1.0,
    ) -> Dict[str, bool]:
        """Проверяет все лимиты портфеля."""
        port = state.portfolio
        return {
            "delta_breach":  self.portfolio.check_delta_limit(port),
            "gamma_breach":  self.portfolio.check_gamma_limit(port),
            "vega_breach":   self.portfolio.check_vega_limit(port, capital),
            "theta_breach":  self.portfolio.check_theta_limit(port, expected_pnl_per_tick),
            "halt_active":   port.portfolio_halt,
        }



# ==============================================================================
# SECTION 10 — UTILITIES
# ==============================================================================

def _returns(prices: List[float]) -> List[float]:
    if len(prices) < 2:
        return []
    return [prices[i] - prices[i-1] for i in range(1, len(prices))]

def _pearson_risks(x: List[float], y: List[float]) -> float:
    n = min(len(x), len(y))
    if n < 2:
        return 0.0
    mx = sum(x[:n]) / n
    my = sum(y[:n]) / n
    num = sum((x[i] - mx) * (y[i] - my) for i in range(n))
    dx  = math.sqrt(sum((x[i] - mx)**2 for i in range(n)))
    dy  = math.sqrt(sum((y[i] - my)**2 for i in range(n)))
    if dx * dy == 0:
        return 0.0
    return num / (dx * dy)


# ==============================================================================
# SECTION 11 — STATE SERIALIZATION  [8.6]
# ==============================================================================

def save_risk_state(state: RiskState) -> str:
    """
    Сериализует RiskState в traderData.                           [8.6]
    Peak PnL.                                                     [8.6]
    Portfolio halt флаг.                                          [8.6]
    PnL по каждой стратегии (rolling).                           [8.6]
    PnL по каждому продукту (rolling).                           [8.6]
    Adverse selection fill counts.                                [8.6]
    Kelly estimate (p, b) по каждой стратегии.                   [8.6]
    Rolling correlation matrix.                                   [8.6]
    Net Greeks.                                                   [8.6]
    """
    port = state.portfolio
    payload = {
        "tick":           state.global_tick,
        # [8.6] Peak PnL
        "peak_pnl":       port.peak_pnl,
        # [8.6] Portfolio halt флаг
        "halt":           port.portfolio_halt,
        "total_pnl":      port.total_pnl,
        # [8.6] Net Greeks
        "net_delta":      port.net_delta,
        "net_gamma":      port.net_gamma,
        "net_vega":       port.net_vega,
        "net_theta":      port.net_theta,
        # [8.6] Rolling correlation matrix
        "corr_matrix":    port.corr_matrix,
        # [8.4] Emergency
        "emergency":      port.emergency_mode,
        "last_calib":     port.last_calib_tick,
        # [8.6] PnL по каждой стратегии + Kelly (p, b)
        "strategies": {
            name: {
                "pnl":        ss.pnl_history[-500:],
                "peak":       ss.peak_pnl,
                "drawdown":   ss.drawdown,
                "disabled":   ss.disabled,
                "dis_tick":   ss.disabled_at_tick,
                "rec_tick":   ss.recovery_tick,
                "in_rec":     ss.in_recovery,
                "avg_daily":  ss.avg_daily_pnl,
                # [8.6] Kelly estimate
                "kelly_p":    ss.kelly.p,
                "kelly_b":    ss.kelly.b,
                "kelly_cold": ss.kelly.cold_start,
            }
            for name, ss in state.strategies.items()
        },
        # [8.6] PnL по каждому продукту + adverse selection counts
        "products": {
            product: {
                "pnl":         ps.pnl_history[-500:],
                "cur_pnl":     ps.current_pnl,
                "flat":        ps.flat,
                "avg_daily":   ps.avg_daily_pnl,
                # [8.6] Adverse selection fill counts
                "bid_fills":   ps.bid_fills[-ADV_SEL_WINDOW:],
                "ask_fills":   ps.ask_fills[-ADV_SEL_WINDOW:],
                "adv_active":  ps.adv_sel_active,
                "adv_dir":     ps.adv_sel_direction,
            }
            for product, ps in state.products.items()
        },
    }
    return json.dumps(payload)


def load_risk_state(data: str) -> RiskState:
    """Десериализует RiskState из traderData."""
    state = RiskState()
    if not data:
        return state
    try:
        p = json.loads(data)
    except Exception:
        # [8.4] Вернуть пустой state при краше — не сохранять corrupted state
        return RiskState()

    state.global_tick = p.get("tick", 0)
    port = state.portfolio
    port.peak_pnl        = p.get("peak_pnl", 0.0)
    port.portfolio_halt  = p.get("halt", False)
    port.total_pnl       = p.get("total_pnl", 0.0)
    port.net_delta       = p.get("net_delta", 0.0)
    port.net_gamma       = p.get("net_gamma", 0.0)
    port.net_vega        = p.get("net_vega", 0.0)
    port.net_theta       = p.get("net_theta", 0.0)
    port.corr_matrix     = p.get("corr_matrix", {})
    port.emergency_mode  = p.get("emergency", False)
    port.last_calib_tick = p.get("last_calib", 0)

    for name, d in p.get("strategies", {}).items():
        ss = state.get_strategy(name)
        ss.pnl_history       = d.get("pnl", [])
        ss.peak_pnl          = d.get("peak", 0.0)
        ss.drawdown          = d.get("drawdown", 0.0)
        ss.disabled          = d.get("disabled", False)
        ss.disabled_at_tick  = d.get("dis_tick", -1)
        ss.recovery_tick     = d.get("rec_tick", -1)
        ss.in_recovery       = d.get("in_rec", False)
        ss.avg_daily_pnl     = d.get("avg_daily", 0.0)
        ss.kelly.p           = d.get("kelly_p", 0.5)
        ss.kelly.b           = d.get("kelly_b", 1.0)
        ss.kelly.cold_start  = d.get("kelly_cold", True)

    for product, d in p.get("products", {}).items():
        ps = state.get_product(product)
        ps.pnl_history   = d.get("pnl", [])
        ps.current_pnl   = d.get("cur_pnl", 0.0)
        ps.flat          = d.get("flat", False)
        ps.avg_daily_pnl = d.get("avg_daily", 0.0)
        ps.bid_fills     = d.get("bid_fills", [])
        ps.ask_fills     = d.get("ask_fills", [])
        ps.adv_sel_active    = d.get("adv_active", False)
        ps.adv_sel_direction = d.get("adv_dir", "none")

    return state

