@dataclass
class StrategyDecision:
    """Результат роутинга для одного продукта на одном тике."""
    product: str
    strategy: Strategy_router
    sizing_multiplier: float = 1.0   # 0..1 скейлинг размера
    aggression: float = 1.0          # 0..1 агрессивность (цена/спред)
    spread_multiplier: float = 1.0   # расширение спреда
    closing_only: bool = False        # [1.2] только закрывающие ордера
    notes: List[str] = field(default_factory=list)


@dataclass
class RegimeRecord:
    """Запись об одной смене режима. [1.6]"""
    from_regime: MarketRegime
    to_regime: MarketRegime
    tick: int


@dataclass
class ProductRegimeState:
    """Per-product состояние режима. [1.1] / [1.6]"""
    current_regime: MarketRegime = MarketRegime.STABLE
    candidate_regime: Optional[MarketRegime] = None
    candidate_ticks: int = 0                    # [1.1] счётчик гистерезиса
    ticks_in_regime: int = 0                    # [1.6]
    regime_history: List[RegimeRecord] = field(default_factory=list)


@dataclass
class StrategyWeights:
    """Веса стратегий для signal aggregation. [1.4]"""
    weights: Dict[str, float] = field(default_factory=dict)
    tick_since_update: int = 0
    total_ticks: int = 0                        # [1.4] cold start counter
    strategy_returns: Dict[str, List[float]] = field(default_factory=dict)


@dataclass
class RouterState:
    """Полный state роутера — сериализуется в traderData. [1.6]"""
    product_regimes: Dict[str, ProductRegimeState] = field(default_factory=dict)
    strategy_weights: Dict[str, StrategyWeights] = field(default_factory=dict)
    tick_prices: Dict[str, List[float]] = field(default_factory=dict)  # история mid
    global_tick: int = 0


# ==============================================================================
# SECTION 4 — REGIME DETECTOR  [1.1]
# ==============================================================================

class RegimeDetector_router:
    """
    Детектирует режим рынка по трём методам:
      1. Realized vol за последние 100 тиков vs базовая       [1.1]
      2. Direction ratio: up ticks / total ticks за 200 тиков  [1.1]
      3. Z-score mid от 500-тиковой EMA                        [1.1]
    Применяет гистерезис — N тиков подтверждения.             [1.1]
    Per-product режим отдельно от глобального.                 [1.1]
    История смен хранится в traderData.                        [1.1] / [1.6]
    """

    # --- [1.1] Детекция: realized vol ---
    @staticmethod
    def _realized_vol(prices: List[float]) -> float:
        if len(prices) < 2:
            return 0.0
        rets = [math.log(prices[i] / prices[i - 1])
                for i in range(1, len(prices)) if prices[i - 1] > 0]
        if not rets:
            return 0.0
        mean = sum(rets) / len(rets)
        return math.sqrt(sum((r - mean) ** 2 for r in rets) / len(rets))

    # --- [1.1] Детекция: direction ratio ---
    @staticmethod
    def _direction_ratio(prices: List[float]) -> float:
        if len(prices) < 2:
            return 0.5
        ups = sum(1 for i in range(1, len(prices)) if prices[i] > prices[i - 1])
        return ups / (len(prices) - 1)

    # --- [1.1] Детекция: Z-score от EMA ---
    @staticmethod
    def _ema(prices: List[float], period: int) -> float:
        if not prices:
            return 0.0
        k = 2.0 / (period + 1)
        e = prices[0]
        for p in prices[1:]:
            e = p * k + e * (1 - k)
        return e

    @staticmethod
    def _zscore(prices: List[float], ema_val: float) -> float:
        if len(prices) < 2:
            return 0.0
        std = RegimeDetector_router._realized_vol(prices) * ema_val  # приближение std цены
        if std == 0:
            return 0.0
        return (prices[-1] - ema_val) / std

    # --- Основной метод ---
    def detect_raw_regime(self, prices: List[float]) -> MarketRegime:
        """Определяет режим без гистерезиса по трём метрикам."""
        n = len(prices)
        if n < 5:
            return MarketRegime.STABLE

        # 1. Realized vol [1.1]
        vol_window   = prices[-VOL_LOOKBACK:] if n >= VOL_LOOKBACK else prices
        base_window  = prices[:-VOL_LOOKBACK] if n > VOL_LOOKBACK else prices
        rv_current   = self._realized_vol(vol_window)
        rv_base      = self._realized_vol(base_window) if len(base_window) > 1 else rv_current
        vol_elevated = rv_base > 0 and (rv_current / rv_base) > 1.5

        # 2. Direction ratio [1.1]
        dir_window   = prices[-DIRECTION_LOOKBACK:] if n >= DIRECTION_LOOKBACK else prices
        dr           = self._direction_ratio(dir_window)
        is_trending  = dr > DIRECTION_TREND_THRESH or dr < (1 - DIRECTION_TREND_THRESH)

        # 3. Z-score от EMA [1.1]
        ema_window   = prices[-EMA_LOOKBACK:] if n >= EMA_LOOKBACK else prices
        ema_val      = self._ema(ema_window, len(ema_window))
        z            = abs(self._zscore(ema_window, ema_val))
        z_extreme    = z > ZSCORE_THRESH

        # Логика классификации
        if vol_elevated and not is_trending:
            return MarketRegime.VOLATILE
        if is_trending or z_extreme:
            return MarketRegime.TRENDING
        if vol_elevated and is_trending:
            return MarketRegime.VOLATILE  # тренд + высокая вола → volatile
        return MarketRegime.STABLE

    def update_regime(
        self,
        state: ProductRegimeState,
        prices: List[float],
        current_tick: int,
    ) -> bool:
        """
        Применяет гистерезис [1.1] — переключает режим только после N тиков подтверждения.
        Per-product hysteresis thresholds [20.3].
        Сохраняет историю смен режима [1.6].
        Возвращает True если режим сменился.
        """
        raw = self.detect_raw_regime(prices)
        changed = False

        if raw == state.current_regime:
            # Сброс кандидата при возврате к текущему режиму
            state.candidate_regime = None
            state.candidate_ticks  = 0
            state.ticks_in_regime += 1
            return False

        if state.candidate_regime != raw:
            # Новый кандидат
            state.candidate_regime = raw
            state.candidate_ticks  = 1
        else:
            state.candidate_ticks += 1

        # [1.1] / [20.3] Hysteresis threshold per transition
        threshold = TRANSITION_HYSTERESIS.get(
            (state.current_regime, raw), HYSTERESIS_TICKS
        )

        if state.candidate_ticks >= threshold:
            # Переключаем режим
            record = RegimeRecord(
                from_regime=state.current_regime,
                to_regime=raw,
                tick=current_tick,
            )
            state.regime_history.append(record)
            # Ограничиваем историю [1.6]
            if len(state.regime_history) > REGIME_HISTORY_SIZE:
                state.regime_history = state.regime_history[-REGIME_HISTORY_SIZE:]

            state.current_regime   = raw
            state.candidate_regime = None
            state.candidate_ticks  = 0
            state.ticks_in_regime  = 0
            changed = True

        return changed


# ==============================================================================
# SECTION 5 — SIGNAL AGGREGATOR  [1.4]
# ==============================================================================

class SignalAggregator:
    """
    Multiplicative weights online learning.                     [1.4]
    Обновление каждые N тиков.                                  [1.4]
    weight × exp(learning_rate × return_of_strategy_i)         [1.4]
    Нормализация весов после обновления.                        [1.4]
    Финальный сигнал — взвешенная сумма сигналов стратегий.    [1.4]
    Инициализация равными весами при отсутствии prior.          [1.4]
    Инициализация из кросс-год данных если R² > 0.95.          [1.4]
    Cold start — первые N тиков fallback на равные веса.        [1.4]
    Weight decay / forgetting factor.                           [1.4]
    Min weight floor.                                           [1.4]
    Max weight cap.                                             [1.4]
    Метод расчёта return — по lookback window.                  [1.4]
    Lookback window для расчёта return.                         [1.4]
    """

    def _equal_weights(self, strategies: List[str]) -> Dict[str, float]:
        """Равные веса [1.4] — cold start и fallback."""
        if not strategies:
            return {}
        w = 1.0 / len(strategies)
        return {s: w for s in strategies}

    def init_weights(
        self,
        sw: StrategyWeights,
        strategies: List[str],
        cross_year_data: Optional[Dict[str, float]] = None,
        cross_year_r2: float = 0.0,
    ) -> None:
        """
        Инициализация весов:
          - Из кросс-год данных если R² > 0.95  [1.4]
          - Иначе равные веса                    [1.4]
        """
        if cross_year_data and cross_year_r2 >= CROSS_YEAR_R2_THRESH:
            # Инициализация из кросс-год данных [1.4]
            total = sum(cross_year_data.get(s, 1.0) for s in strategies)
            sw.weights = {
                s: cross_year_data.get(s, 1.0) / total for s in strategies
            }
        else:
            sw.weights = self._equal_weights(strategies)

        for s in strategies:
            if s not in sw.strategy_returns:
                sw.strategy_returns[s] = []

    def _compute_return(self, returns_history: List[float]) -> float:
        """
        Метод расчёта return стратегии — среднее за lookback window. [1.4]
        Lookback window = RETURN_LOOKBACK тиков.                     [1.4]
        """
        window = returns_history[-RETURN_LOOKBACK:]
        if not window:
            return 0.0
        return sum(window) / len(window)

    def record_strategy_return(
        self,
        sw: StrategyWeights,
        strategy_id: str,
        ret: float,
    ) -> None:
        """Добавляет return в историю стратегии."""
        if strategy_id not in sw.strategy_returns:
            sw.strategy_returns[strategy_id] = []
        sw.strategy_returns[strategy_id].append(ret)

    def update_weights(self, sw: StrategyWeights) -> None:
        """
        Обновление весов каждые N тиков.                        [1.4]
        Multiplicative: weight × exp(lr × return).              [1.4]
        Weight decay / forgetting factor.                        [1.4]
        Нормализация.                                            [1.4]
        Min weight floor.                                        [1.4]
        Max weight cap.                                          [1.4]
        Cold start — первые COLD_START_TICKS тиков: равные.     [1.4]
        """
        sw.total_ticks += 1
        sw.tick_since_update += 1

        # Cold start [1.4]
        if sw.total_ticks <= COLD_START_TICKS:
            strategies = list(sw.weights.keys())
            sw.weights = self._equal_weights(strategies)
            return

        if sw.tick_since_update < WEIGHT_UPDATE_INTERVAL:
            return
        sw.tick_since_update = 0

        strategies = list(sw.weights.keys())
        if not strategies:
            return

        new_weights: Dict[str, float] = {}
        for s in strategies:
            ret = self._compute_return(sw.strategy_returns.get(s, []))
            # Multiplicative update [1.4]
            w = sw.weights.get(s, 1.0 / len(strategies))
            w *= FORGETTING_FACTOR                         # weight decay [1.4]
            w *= math.exp(LEARNING_RATE * ret)             # multiplicative [1.4]
            new_weights[s] = w

        # Нормализация [1.4]
        total = sum(new_weights.values())
        if total > 0:
            new_weights = {s: w / total for s, w in new_weights.items()}

        # Min floor [1.4]
        for s in new_weights:
            new_weights[s] = max(new_weights[s], MIN_WEIGHT)

        # Re-normalize after floor
        total = sum(new_weights.values())
        if total > 0:
            new_weights = {s: w / total for s, w in new_weights.items()}

        # Max cap [1.4]
        capped = False
        for s in new_weights:
            if new_weights[s] > MAX_WEIGHT:
                new_weights[s] = MAX_WEIGHT
                capped = True
        if capped:
            total = sum(new_weights.values())
            if total > 0:
                new_weights = {s: w / total for s, w in new_weights.items()}

        sw.weights = new_weights

    def aggregate_signal(
        self,
        sw: StrategyWeights,
        signals: Dict[str, float],
    ) -> float:
        """Взвешенная сумма сигналов стратегий. [1.4]"""
        if sw.total_ticks <= COLD_START_TICKS:
            # Cold start: равные веса [1.4]
            if not signals:
                return 0.0
            return sum(signals.values()) / len(signals)

        total = 0.0
        for s, sig in signals.items():
            total += sw.weights.get(s, 0.0) * sig
        return total


# ==============================================================================
# SECTION 6 — CAPACITY ALLOCATOR  [1.5]
# ==============================================================================

class CapacityAllocator_full:
    """
    Позиционный лимит общий на продукт.                            [1.5]
    При конфликте стратегий — распределение по приоритету.         [1.5]
    Арб занимает ёмкость первым.                                   [1.5]
    Conversion arb занимает ёмкость отдельно.                      [1.5]
    MM получает остаток.                                           [1.5]
    Basket и компоненты — общая ёмкость по умолчанию.              [1.5]
    Минимальная аллокация на стратегию — не давать 0.              [1.5]
    """

    MIN_ALLOC_FRAC = 0.05  # минимум 5% от доступного [1.5]

    # Basket ёмкость: True = общая с компонентами, False = раздельная [1.5]
    BASKET_SHARED_CAPACITY: bool = True

    @staticmethod
    def get_position_state(position: int, limit: int) -> PositionState:
        """[20.1] Классифицирует состояние позиции."""
        if limit == 0:
            return PositionState.FLAT
        frac = position / limit
        if frac > LARGE_POS_FRAC:
            return PositionState.LARGE_LONG
        if frac > SMALL_POS_FRAC:
            return PositionState.SMALL_LONG
        if frac < -LARGE_POS_FRAC:
            return PositionState.LARGE_SHORT
        if frac < -SMALL_POS_FRAC:
            return PositionState.SMALL_SHORT
        return PositionState.FLAT

    def allocate(
        self,
        strategy: Strategy_router,
        position: int,
        limit: int,
        has_arb: bool = False,
        arb_reserved: int = 0,
        conversion_reserved: int = 0,
    ) -> Tuple[int, bool]:
        """
        Возвращает (available_capacity, closing_only).
        Приоритет: арб → conversion arb → MM.                     [1.5]
        closing_only = True если позиция на лимите.                [1.2]
        """
        abs_pos = abs(position)

        # Позиция на лимите → только закрывающие ордера [1.2] / [1.5]
        if abs_pos >= limit:
            return 0, True

        total_available = limit - abs_pos

        # Арб занимает первым [1.5]
        if has_arb:
            remaining = max(0, total_available - arb_reserved)
        else:
            remaining = total_available

        # Conversion arb отдельно [1.5]
        if strategy == Strategy_router.CONVERSION_ARB:
            available = remaining
        else:
            remaining -= conversion_reserved
            available = max(0, remaining)

        # Минимальная аллокация [1.5]
        min_alloc = max(1, int(total_available * self.MIN_ALLOC_FRAC))
        if available < min_alloc and available > 0:
            available = min_alloc

        return available, False


# ==============================================================================
# SECTION 7 — FULL MATRIX ROUTER  [20.1 – 20.4]
# ==============================================================================

@dataclass
class RouterContext:
    """Полный контекст из 10 измерений для полной матрицы. [20.1]"""
    product_type:    ProductType
    market_regime:   MarketRegime
    position_state:  PositionState
    signal_strength: SignalStrength
    insider_state:   InsiderState
    liquidity:       Liquidity
    round_time:      RoundTime
    cross_year:      CrossYearSignal
    spread_state:    SpreadState
    volatility:      VolatilityLevel


class FullMatrixRouter:
    """
    Полная матрица 10 измерений.                                   [20.1]
    97 200 теоретических комбинаций.                               [20.2]
    3 000–7 000 реально торгуемых.                                 [20.2]
    >50% комбинаций = FLAT.                                        [20.2]
    Для каждой комбинации: стратегия + sizing + aggression + spread.[20.3]
    Иерархия приоритетов: инсайдер > режим > сигнал > кросс-год.  [20.4]
    Null states: когда не торговать.                               [20.3]
    Переходы с гистерезисом.                                       [20.3]
    Hysteresis thresholds для каждого перехода.                    [20.3]
    """

    def route(self, ctx: RouterContext) -> StrategyDecision:
        """
        Главный метод полного матричного роутинга.
        Иерархия приоритетов при конфликте: insider > regime > signal > cross-year [20.4]
        Реализует null states [20.3].
        """
        notes: List[str] = []

        # -----------------------------------------------------------------
        # [20.4] Шаг 1: Risk override — REGIME_CHANGE сбрасывает всё
        # -----------------------------------------------------------------
        if ctx.market_regime == MarketRegime.REGIME_CHANGE:
            base = STRATEGY_MATRIX[(ctx.product_type, MarketRegime.REGIME_CHANGE)]
            return StrategyDecision(
                product="",
                strategy=base,
                sizing_multiplier=0.0,
                aggression=0.0,
                spread_multiplier=3.0,
                closing_only=True,
                notes=["regime_change: flush + closing only"],
            )

        # -----------------------------------------------------------------
        # [20.4] Шаг 2: Conflicting signal → flat
        # -----------------------------------------------------------------
        if ctx.signal_strength == SignalStrength.CONFLICTING:
            return StrategyDecision(
                product="", strategy=Strategy_router.FLAT,
                notes=["conflicting signal: flat"],
            )

        # -----------------------------------------------------------------
        # [20.4] Шаг 3: Инсайдер приоритетнее режима
        # insider > mode, уменьшить размер вдвое
        # -----------------------------------------------------------------
        insider_override = False
        insider_size_mult = 1.0
        if ctx.insider_state == InsiderState.STRONG_SIGNAL:
            insider_override = True
            insider_size_mult = 0.5   # [20.4] уменьшить вдвое при конфликте
            notes.append("insider_strong: size × 0.5")

        # -----------------------------------------------------------------
        # [20.4] Шаг 4: Кросс-год vs текущий
        # cross-year приоритет убирается после 200 тиков — обрабатывается
        # вызывающим кодом, здесь просто снижаем доверие low_corr/no_data
        # -----------------------------------------------------------------
        cross_year_discount = 1.0
        if ctx.cross_year == CrossYearSignal.LOW_CORR:
            cross_year_discount = 0.8
        elif ctx.cross_year == CrossYearSignal.NO_DATA:
            cross_year_discount = 0.6

        # -----------------------------------------------------------------
        # Шаг 5: Базовая стратегия из матрицы 1.3  [1.3]
        # -----------------------------------------------------------------
        base_strategy = STRATEGY_MATRIX.get(
            (ctx.product_type, ctx.market_regime), Strategy_router.FLAT  # fallback [1.2]
        )

        # -----------------------------------------------------------------
        # Шаг 6: Sizing
        # -----------------------------------------------------------------
        sizing = self._compute_sizing(ctx, insider_size_mult, cross_year_discount, notes)

        # -----------------------------------------------------------------
        # Шаг 7: Aggression  — сильный сигнал + illiquid → снижать aggression [20.4]
        # -----------------------------------------------------------------
        aggression = self._compute_aggression(ctx, notes)

        # -----------------------------------------------------------------
        # Шаг 8: Spread
        # -----------------------------------------------------------------
        spread = self._compute_spread(ctx)

        # -----------------------------------------------------------------
        # Шаг 9: Null states [20.3]  — >50% комбинаций = FLAT
        # -----------------------------------------------------------------
        if self._is_null_state(ctx):
            return StrategyDecision(
                product="", strategy=Strategy_router.FLAT,
                notes=notes + ["null_state"],
            )

        return StrategyDecision(
            product="",
            strategy=base_strategy,
            sizing_multiplier=sizing,
            aggression=aggression,
            spread_multiplier=spread,
            notes=notes,
        )

    def _compute_sizing(
        self,
        ctx: RouterContext,
        insider_mult: float,
        cross_mult: float,
        notes: List[str],
    ) -> float:
        """Sizing по позиции, сигналу и сигналу инсайдера."""
        s = 1.0

        # Позиция уже большая → снижаем размер
        if ctx.position_state == PositionState.LARGE_LONG:
            s *= 0.3
            notes.append("large_long: size × 0.3")
        elif ctx.position_state == PositionState.LARGE_SHORT:
            s *= 0.3
            notes.append("large_short: size × 0.3")
        elif ctx.position_state in (PositionState.SMALL_LONG, PositionState.SMALL_SHORT):
            s *= 0.7

        # Сила сигнала
        if ctx.signal_strength == SignalStrength.STRONG:
            s *= 1.0
        elif ctx.signal_strength == SignalStrength.MODERATE:
            s *= 0.7
        elif ctx.signal_strength == SignalStrength.WEAK:
            s *= 0.3

        # Volatile режим или high vol → half-size
        if ctx.market_regime == MarketRegime.VOLATILE:
            s *= 0.5
        if ctx.volatility == VolatilityLevel.HIGH:
            s *= 0.7

        # Позднее время раунда → снижаем
        if ctx.round_time == RoundTime.LATE:
            s *= 0.5
            notes.append("late: size × 0.5")

        s *= insider_mult
        s *= cross_mult

        return max(0.0, min(1.0, s))

    def _compute_aggression(self, ctx: RouterContext, notes: List[str]) -> float:
        """
        [20.4] Сильный сигнал + illiquid → снижать aggression, не размер.
        """
        if ctx.liquidity == Liquidity.ILLIQUID:
            notes.append("illiquid: aggression reduced")
            return 0.2
        if ctx.liquidity == Liquidity.THIN:
            return 0.6
        if ctx.signal_strength == SignalStrength.STRONG:
            return 1.0
        if ctx.signal_strength == SignalStrength.MODERATE:
            return 0.7
        return 0.5

    def _compute_spread(self, ctx: RouterContext) -> float:
        """Расширение спреда в зависимости от режима и волатильности."""
        mult = 1.0
        if ctx.market_regime == MarketRegime.VOLATILE:
            mult *= 2.0
        if ctx.volatility == VolatilityLevel.HIGH:
            mult *= 1.5
        if ctx.spread_state == SpreadState.WIDE:
            mult *= 1.3
        if ctx.liquidity == Liquidity.ILLIQUID:
            mult *= 2.0
        if ctx.round_time == RoundTime.LATE:
            mult *= 1.2
        return mult

    def _is_null_state(self, ctx: RouterContext) -> bool:
        """
        [20.3] Null states — когда вообще не торговать.
        >50% комбинаций = flat [20.2].
        """
        # Illiquid + слабый сигнал + поздно — не торговать
        if (ctx.liquidity == Liquidity.ILLIQUID
                and ctx.signal_strength == SignalStrength.WEAK
                and ctx.round_time == RoundTime.LATE):
            return True
        # Flat позиция + слабый сигнал + нет кросс-год данных
        if (ctx.position_state == PositionState.FLAT
                and ctx.signal_strength == SignalStrength.WEAK
                and ctx.cross_year == CrossYearSignal.NO_DATA):
            return True
        # Volatile + illiquid + нет инсайдера
        if (ctx.market_regime == MarketRegime.VOLATILE
                and ctx.liquidity == Liquidity.ILLIQUID
                and ctx.insider_state == InsiderState.NO_SIGNAL):
            return True
        # Thin + high vol + conflicting → уже обработан выше как FLAT
        return False


# ==============================================================================
# SECTION 8 — PRODUCT ROUTER  [1.2]
# ==============================================================================

class ProductRouter:
    """
    Роутер по продукту — полная логика 1.2.
    Определяет тип продукта.                                       [1.2]
    Проверяет внешние сигналы (инсайдер, sunlight и др.).         [1.2]
    Определяет режим рынка для продукта.                           [1.2]
    Выбирает стратегию по матрице.                                 [1.2] / [1.3]
    Проверяет позиционную ёмкость.                                 [1.2] / [1.5]
    Приоритеты: арб > MM, инсайдер > сигнал.                      [1.2]
    Risk limit override всего.                                     [1.2]
    Позиция на лимите → только закрывающие ордера.                 [1.2]
    Обработка partial fills с предыдущего тика.                    [1.2]
    Cross-product зависимость basket ↔ компоненты.                 [1.2]
    Fallback стратегия если матрица не сработала.                  [1.2]
    """

    def __init__(self) -> None:
        self.regime_detector   = RegimeDetector_router()
        self.signal_aggregator = SignalAggregator()
        self.capacity_allocator = CapacityAllocator_full()
        self.full_matrix_router = FullMatrixRouter()

    # -------------------------------------------------------------------------
    # Основная точка входа
    # -------------------------------------------------------------------------
    def route_product(
        self,
        product: str,
        router_state: RouterState,
        position: int,
        limit: int,
        mid_price: float,
        # Внешние сигналы [1.2]
        insider_signal: float = 0.0,         # >0 buy, <0 sell, 0 = нет
        sunlight_index: Optional[float] = None,
        other_signals: Optional[Dict[str, float]] = None,
        # Арб
        has_arb: bool = False,
        arb_reserved: int = 0,
        conversion_reserved: int = 0,
        # Partial fills [1.2]
        prev_order_filled: int = 0,
        prev_order_size: int = 0,
        # Cross-product [1.2]
        basket_products: Optional[List[str]] = None,
        component_of: Optional[str] = None,
        # Cross-year
        cross_year_data: Optional[Dict[str, float]] = None,
        cross_year_r2: float = 0.0,
        cross_year_ticks: int = 0,          # [20.4] сколько тиков используем
        # Round info
        round_tick: int = 0,
        total_ticks: int = 1000,
    ) -> StrategyDecision:

        router_state.global_tick += 1
        tick = router_state.global_tick

        # -----------------------------------------------------------------
        # Шаг 1: Обновить историю цен [1.1]
        # -----------------------------------------------------------------
        if product not in router_state.tick_prices:
            router_state.tick_prices[product] = []
        router_state.tick_prices[product].append(mid_price)

        # -----------------------------------------------------------------
        # Шаг 2: Risk limit — override всего [1.2]
        # -----------------------------------------------------------------
        capacity, closing_only = self.capacity_allocator.allocate(
            STRATEGY_MATRIX.get(
                (self._get_product_type(product), MarketRegime.STABLE),
                Strategy_router.FLAT,
            ),
            position, limit, has_arb, arb_reserved, conversion_reserved,
        )
        if closing_only:
            return StrategyDecision(
                product=product,
                strategy=Strategy_router.FLAT,
                closing_only=True,
                notes=["risk_limit: position at max, closing only"],
            )

        # -----------------------------------------------------------------
        # Шаг 3: Определить тип продукта [1.2]
        # -----------------------------------------------------------------
        product_type = self._get_product_type(product)

        # -----------------------------------------------------------------
        # Шаг 4: Проверить внешние сигналы (инсайдер, sunlight и др.) [1.2]
        # -----------------------------------------------------------------
        insider_state = self._classify_insider(insider_signal)

        # -----------------------------------------------------------------
        # Шаг 5: Определить режим рынка per-product [1.1] / [1.2]
        # -----------------------------------------------------------------
        if product not in router_state.product_regimes:
            router_state.product_regimes[product] = ProductRegimeState()
        regime_state = router_state.product_regimes[product]

        prices = router_state.tick_prices[product]
        self.regime_detector.update_regime(regime_state, prices, tick)
        regime = regime_state.current_regime

        # -----------------------------------------------------------------
        # Шаг 6: Обработка partial fills [1.2]
        # -----------------------------------------------------------------
        partial_fill_notes: List[str] = []
        if prev_order_size > 0:
            fill_ratio = prev_order_filled / prev_order_size
            if fill_ratio < 0.3:
                partial_fill_notes.append(
                    f"partial_fill: {fill_ratio:.0%} — reduce size"
                )

        # -----------------------------------------------------------------
        # Шаг 7: Cross-product зависимость basket ↔ компоненты [1.2]
        # -----------------------------------------------------------------
        cross_product_mult = 1.0
        if basket_products and product_type != ProductType.BASKET:
            # Компонент баскета — проверяем ёмкость баскета
            if CapacityAllocator_full.BASKET_SHARED_CAPACITY:
                cross_product_mult = 0.8  # снижаем чтобы не превысить общий лимит
        if component_of:
            cross_product_mult = min(cross_product_mult, 0.9)

        # -----------------------------------------------------------------
        # Шаг 8: Кросс-годовой сигнал [20.4]
        # Текущий приоритетнее после 200 тиков
        # -----------------------------------------------------------------
        cross_year = CrossYearSignal.NO_DATA
        if cross_year_data:
            if cross_year_ticks >= 200:     # [20.4] после 200 тиков игнорируем
                cross_year = CrossYearSignal.LOW_CORR
            elif cross_year_r2 >= CROSS_YEAR_R2_THRESH:
                cross_year = CrossYearSignal.HIGH_CORR
            else:
                cross_year = CrossYearSignal.LOW_CORR

        # -----------------------------------------------------------------
        # Шаг 9: Инициализация весов [1.4]
        # -----------------------------------------------------------------
        strategies_list = [s.value for s in Strategy_router if s != Strategy_router.FLAT]
        if product not in router_state.strategy_weights:
            sw = StrategyWeights()
            self.signal_aggregator.init_weights(
                sw, strategies_list, cross_year_data, cross_year_r2
            )
            router_state.strategy_weights[product] = sw
        sw = router_state.strategy_weights[product]

        # -----------------------------------------------------------------
        # Шаг 10: Обновить веса [1.4]
        # -----------------------------------------------------------------
        self.signal_aggregator.update_weights(sw)

        # -----------------------------------------------------------------
        # Шаг 11: Классифицировать вспомогательные измерения [20.1]
        # -----------------------------------------------------------------
        pos_state   = CapacityAllocator_full.get_position_state(position, limit)
        liquidity   = self._classify_liquidity(prices)
        round_time  = self._classify_round_time(round_tick, total_ticks)
        spread_st   = self._classify_spread(prices)
        vol_level   = self._classify_vol_level(prices)
        sig_strength = self._classify_signal_strength(
            insider_signal, sunlight_index, other_signals
        )

        # -----------------------------------------------------------------
        # Шаг 12: Инсайдер приоритетнее (сигнал > собственный) [1.2] / [20.4]
        # -----------------------------------------------------------------
        if insider_state == InsiderState.STRONG_SIGNAL:
            # insider signal override собственного сигнала [1.2]
            pass  # full_matrix_router обработает через ctx

        # -----------------------------------------------------------------
        # Шаг 13: Проверить арб opportunity — приоритет над MM [1.2]
        # -----------------------------------------------------------------
        if has_arb and product_type not in (ProductType.BASKET, ProductType.LOCATION):
            return StrategyDecision(
                product=product,
                strategy=Strategy_router.BASKET_ARB,
                sizing_multiplier=min(1.0, capacity / max(1, limit)),
                aggression=1.0,
                notes=["arb_priority: arb over mm"],
            )

        # -----------------------------------------------------------------
        # Шаг 14: Выбрать стратегию из матрицы (тип × режим) [1.3]
        # -----------------------------------------------------------------
        ctx = RouterContext(
            product_type=product_type,
            market_regime=regime,
            position_state=pos_state,
            signal_strength=sig_strength,
            insider_state=insider_state,
            liquidity=liquidity,
            round_time=round_time,
            cross_year=cross_year,
            spread_state=spread_st,
            volatility=vol_level,
        )
        decision = self.full_matrix_router.route(ctx)
        decision.product = product

        # -----------------------------------------------------------------
        # Шаг 15: Fallback если матрица не вернула конкретную стратегию [1.2]
        # -----------------------------------------------------------------
        if decision.strategy == Strategy_router.FLAT and not decision.notes:
            decision.notes.append("fallback: no matrix branch matched")

        # -----------------------------------------------------------------
        # Шаг 16: Применить partial fill и cross-product корректировки [1.2]
        # -----------------------------------------------------------------
        decision.sizing_multiplier *= cross_product_mult
        if partial_fill_notes:
            decision.sizing_multiplier *= 0.7
            decision.notes.extend(partial_fill_notes)

        # Применить доступную ёмкость [1.5]
        max_size_frac = capacity / max(1, limit)
        decision.sizing_multiplier = min(decision.sizing_multiplier, max_size_frac)

        return decision

    # -------------------------------------------------------------------------
    # Вспомогательные классификаторы
    # -------------------------------------------------------------------------

    @staticmethod
    def _get_product_type(product: str) -> ProductType:
        """Тип продукта из реестра или эвристически."""
        if product in PRODUCT_TYPE_MAP:
            return PRODUCT_TYPE_MAP[product]
        p = product.upper()
        if any(x in p for x in ("BASKET", "ETF", "INDEX")):
            return ProductType.BASKET
        if any(x in p for x in ("OPT", "CALL", "PUT", "VOUCHER")):
            return ProductType.OPTION
        if any(x in p for x in ("CONV", "SOUTH", "NORTH", "EAST", "WEST")):
            return ProductType.LOCATION
        if any(x in p for x in ("KELP", "SQUID", "FISH")):
            return ProductType.VOLATILE
        return ProductType.STABLE

    @staticmethod
    def _classify_insider(signal: float) -> InsiderState:
        if abs(signal) >= 0.7:
            return InsiderState.STRONG_SIGNAL
        if abs(signal) >= 0.2:
            return InsiderState.WEAK_SIGNAL
        return InsiderState.NO_SIGNAL

    @staticmethod
    def _classify_liquidity(prices: List[float]) -> Liquidity:
        # Эвристика: спред/вола → ликвидность
        if len(prices) < 10:
            return Liquidity.LIQUID
        vol = RegimeDetector_router._realized_vol(prices[-20:]) if len(prices) >= 20 else 0
        if vol > 0.02:
            return Liquidity.ILLIQUID
        if vol > 0.008:
            return Liquidity.THIN
        return Liquidity.LIQUID

    @staticmethod
    def _classify_round_time(round_tick: int, total: int) -> RoundTime:
        frac = round_tick / max(1, total)
        if frac < 0.10:  return RoundTime.EARLY
        if frac < 0.30:  return RoundTime.MID_EARLY
        if frac < 0.70:  return RoundTime.MID
        if frac < 0.90:  return RoundTime.MID_LATE
        return RoundTime.LATE

    @staticmethod
    def _classify_spread(prices: List[float]) -> SpreadState:
        if len(prices) < 5:
            return SpreadState.NORMAL
        recent_vol = RegimeDetector_router._realized_vol(prices[-10:]) if len(prices) >= 10 else 0
        base_vol   = RegimeDetector_router._realized_vol(prices) if len(prices) >= 2 else 0
        if base_vol == 0:
            return SpreadState.NORMAL
        ratio = recent_vol / base_vol
        if ratio > 1.5:  return SpreadState.WIDE
        if ratio < 0.7:  return SpreadState.TIGHT
        return SpreadState.NORMAL

    @staticmethod
    def _classify_vol_level(prices: List[float]) -> VolatilityLevel:
        if len(prices) < 20:
            return VolatilityLevel.NORMAL
        rv = RegimeDetector_router._realized_vol(prices[-20:])
        if rv > 0.015:  return VolatilityLevel.HIGH
        if rv > 0.005:  return VolatilityLevel.NORMAL
        return VolatilityLevel.LOW

    @staticmethod
    def _classify_signal_strength(
        insider: float,
        sunlight: Optional[float],
        others: Optional[Dict[str, float]],
    ) -> SignalStrength:
        signals: List[float] = [insider]
        if sunlight is not None:
            signals.append(sunlight)
        if others:
            signals.extend(others.values())

        directions = [1 if s > 0.1 else (-1 if s < -0.1 else 0) for s in signals]
        nonzero = [d for d in directions if d != 0]
        if not nonzero:
            return SignalStrength.WEAK

        # Conflicting — разные направления [20.4]
        if len(set(nonzero)) > 1:
            return SignalStrength.CONFLICTING

        avg = sum(abs(s) for s in signals) / len(signals)
        if avg >= 0.7:  return SignalStrength.STRONG
        if avg >= 0.3:  return SignalStrength.MODERATE
        return SignalStrength.WEAK


# ==============================================================================
# SECTION 9 — TRADERDATA SERIALIZATION  [1.6]
# ==============================================================================

def save_router_state(state: RouterState) -> str:
    """Сериализует RouterState в строку для traderData. [1.6]"""
    def _regime_state(rs: ProductRegimeState) -> dict:
        return {
            "regime":         rs.current_regime.value,
            "ticks":          rs.ticks_in_regime,
            "candidate":      rs.candidate_regime.value if rs.candidate_regime else None,
            "candidate_ticks": rs.candidate_ticks,
            "history": [
                {
                    "from": r.from_regime.value,
                    "to":   r.to_regime.value,
                    "tick": r.tick,
                }
                for r in rs.regime_history
            ],
        }

    def _weights_state(sw: StrategyWeights) -> dict:
        return {
            "weights":      sw.weights,
            "total_ticks":  sw.total_ticks,
            "tick_since_update": sw.tick_since_update,
        }

    payload = {
        "global_tick":       state.global_tick,
        "product_regimes":   {p: _regime_state(rs) for p, rs in state.product_regimes.items()},
        "strategy_weights":  {p: _weights_state(sw) for p, sw in state.strategy_weights.items()},
        "tick_prices":       {
            p: prices[-max(EMA_LOOKBACK, DIRECTION_LOOKBACK):]
            for p, prices in state.tick_prices.items()
        },
    }
    return json.dumps(payload)


def load_router_state(data: str) -> RouterState:
    """Десериализует RouterState из traderData строки. [1.6]"""
    if not data:
        return RouterState()
    try:
        payload = json.loads(data)
    except Exception:
        return RouterState()

    state = RouterState()
    state.global_tick = payload.get("global_tick", 0)

    for p, rs_dict in payload.get("product_regimes", {}).items():
        rs = ProductRegimeState()
        rs.current_regime  = MarketRegime(rs_dict["regime"])
        rs.ticks_in_regime = rs_dict["ticks"]
        rs.candidate_ticks = rs_dict.get("candidate_ticks", 0)
        cand = rs_dict.get("candidate")
        rs.candidate_regime = MarketRegime(cand) if cand else None
        rs.regime_history = [
            RegimeRecord(
                from_regime=MarketRegime(r["from"]),
                to_regime=MarketRegime(r["to"]),
                tick=r["tick"],
            )
            for r in rs_dict.get("history", [])
        ]
        state.product_regimes[p] = rs

    for p, sw_dict in payload.get("strategy_weights", {}).items():
        sw = StrategyWeights()
        sw.weights            = sw_dict.get("weights", {})
        sw.total_ticks        = sw_dict.get("total_ticks", 0)
        sw.tick_since_update  = sw_dict.get("tick_since_update", 0)
        state.strategy_weights[p] = sw

    for p, prices in payload.get("tick_prices", {}).items():
        state.tick_prices[p] = prices

    return state


# ==============================================================================
# SECTION 10 — TRADER ENTRY POINT
# ==============================================================================

class Trader_router:
    """
    Главный класс трейдера. Пример интеграции роутера.
    Полный цикл: load state → route → save state.
    """

    def __init__(self) -> None:
        self.product_router = ProductRouter()

    def run(self, state: Any, trader_data: str) -> Tuple[Dict, int, str]:
        """
        state       — объект состояния от движка (TradingState)
        trader_data — строка из предыдущего тика [1.6]
        Возвращает (orders, conversions, new_trader_data).
        """
        router_state = load_router_state(trader_data)   # [1.6]
        orders: Dict[str, list] = {}

        for product in getattr(state, "order_depths", {}).keys():
            depth     = state.order_depths[product]
            position  = getattr(state, "position", {}).get(product, 0)
            limit     = 50  # default, в реальности из конфига
            timestamp = getattr(state, "timestamp", 0)

            # Mid price
            best_bid = max(depth.buy_orders.keys()) if depth.buy_orders else 0
            best_ask = min(depth.sell_orders.keys()) if depth.sell_orders else 0
            mid = (best_bid + best_ask) / 2 if best_bid and best_ask else (best_bid or best_ask)
            if mid == 0:
                continue

            # Внешние сигналы
            obs = getattr(state, "observations", None)
            sunlight = None
            if obs and hasattr(obs, "conversionObservations"):
                conv = obs.conversionObservations.get(product)
                if conv:
                    sunlight = getattr(conv, "sunlight",
                               getattr(conv, "sunlightIndex", None))

            decision = self.product_router.route_product(
                product=product,
                router_state=router_state,
                position=position,
                limit=limit,
                mid_price=mid,
                sunlight_index=sunlight,
                round_tick=timestamp,
                total_ticks=1_000_000,
            )

            # Ордера на основе decision (заглушка — реализуется в стратегиях)
            if decision.strategy != Strategy_router.FLAT and not decision.closing_only:
                orders[product] = []   # стратегии наполняют список

        new_data = save_router_state(router_state)   # [1.6]
        return orders, 0, new_data

