# ─── ЛОГГЕР ───────────────────────────────────────────────────────────────────

class Logger:
    def __init__(self):
        self.logs = ""
        self.log_size = 0

    def log(self, ts: int, product: str, action: str,
            price: float = None, qty: int = None, extra: str = ""):
        line = f"{ts}|{product}|{action}|{price}|{qty}|{extra}\n"
        if self.log_size + len(line) > CONFIG["LOG_SIZE_MAX"]:
            return
        self.logs += line
        self.log_size += len(line)

    def print(self, *args):
        line = " ".join(map(str, args)) + "\n"
        if self.log_size + len(line) > CONFIG["LOG_SIZE_MAX"]:
            return
        self.logs += line
        self.log_size += len(line)

    def flush(self, state, orders, conversions, traderData):
        # Serialize orders to JSON-safe format (Order objects aren't serializable)
        safe_orders = {}
        for prod, ol in orders.items():
            safe_orders[prod] = [
                {"symbol": o.symbol, "price": o.price, "quantity": o.quantity}
                for o in ol
            ] if ol else []
        print(json.dumps({
            "state": {
                "timestamp": getattr(state, "timestamp", None),
                "position":  getattr(state, "position", {}),
            },
            "orders": safe_orders,
            "conversions": conversions, "traderData": traderData,
            "logs": self.logs,
        }))
        self.logs = ""
        self.log_size = 0

logger = Logger()


# ─── TIMEOUT GUARD ────────────────────────────────────────────────────────────
# signal.SIGALRM недоступен на IMC — threading.Timer
# Превышение 900ms = 0 PnL за тик

class TickTimeout(Exception):
    pass

class TimeoutGuard:
    def __init__(self, ms: int):
        self.ms = ms
        self._timer: threading.Timer | None = None
        self._timed_out = False

    def start(self):
        self._timed_out = False
        self._timer = threading.Timer(self.ms / 1000.0, self._trigger)
        self._timer.daemon = True
        self._timer.start()

    def _trigger(self):
        self._timed_out = True

    def cancel(self):
        if self._timer:
            self._timer.cancel()

    def check(self):
        if self._timed_out:
            raise TickTimeout("tick exceeded timeout")

timeout_guard = TimeoutGuard(CONFIG["TICK_TIMEOUT_MS"])


# ─── STATE / MEMORY ───────────────────────────────────────────────────────────
# Полный state для traderData. Включает все индикаторы, веса и счётчики.

def default_state() -> dict:
    return {
        # 1. EMA по продукту
        "ema":               {p: None for p in PRODUCTS},
        # 2. Rolling window цен (последние ROLLING_WINDOW тиков)
        "prices":            {p: [] for p in PRODUCTS},
        # 3. Multiplicative weights стратегий
        "mw":                {p: {s: 1.0 for s in STRATEGY_NAMES} for p in PRODUCTS},
        # 4. Bot fingerprint history: list of [timestamp, best_bid, best_ask]
        "fingerprints":      {p: [] for p in PRODUCTS},
        # 5. Kalman filter state (x_est, P_est)
        "kf":                {p: {"x": None, "P": 1.0} for p in PRODUCTS},
        # 6. Adversarial selection counters
        "adv":               {p: {"bid_fills": 0, "ask_fills": 0} for p in PRODUCTS},
        # 7. Cumulative PnL по стратегиям для circuit breakers
        "cum_pnl":           {p: {s: 0.0 for s in STRATEGY_NAMES} for p in PRODUCTS},
        "cb_disabled_until": {p: {s: 0 for s in STRATEGY_NAMES} for p in PRODUCTS},
        # Синхронизируются с Trader_full instance vars
        "pnl":               {},
        "calibrated_params": {},
        "tick":              0,
    }


def load_state(trader_data: str) -> dict:
    """
    Загружает state из traderData. Поддерживает миграцию:
    недостающие ключи заполняются из default_state().
    Совместим со старым форматом (last_mid, pnl, ema, calibrated_params).
    """
    if not trader_data:
        return default_state()
    try:
        loaded  = json.loads(trader_data)
        default = default_state()
        for key in default:
            if key not in loaded:
                loaded[key] = default[key]
            elif isinstance(default[key], dict):
                for p in default[key]:
                    if p not in loaded[key]:
                        loaded[key][p] = default[key][p]
        return loaded
    except Exception:
        return default_state()


class _StateEncoder(json.JSONEncoder):
    """JSON encoder для state objects (PairState, dataclass, etc.)."""
    def default(self, obj):
        if hasattr(obj, '__dataclass_fields__'):
            return {k: getattr(obj, k) for k in obj.__dataclass_fields__}
        if hasattr(obj, '__dict__'):
            return obj.__dict__
        return super().default(obj)

def dump_state(state: dict) -> str:
    """
    Сериализует state в строку с каскадной обрезкой при превышении MAX_TRADER_DATA.
    8. Ограничение размера строки traderData.
    """
    raw = json.dumps(state, separators=(",", ":"), cls=_StateEncoder)
    if len(raw) <= MAX_TRADER_DATA:
        return raw

    # Шаг 1: укоротить rolling windows и fingerprints
    for p in PRODUCTS:
        prices = state["prices"].get(p, [])
        if len(prices) > 100:
            state["prices"][p] = prices[-100:]
        fps = state["fingerprints"].get(p, [])
        if len(fps) > 20:
            state["fingerprints"][p] = fps[-20:]

    raw = json.dumps(state, separators=(",", ":"), cls=_StateEncoder)
    if len(raw) <= MAX_TRADER_DATA:
        return raw

    # Шаг 2: очистить fingerprints полностью
    for p in PRODUCTS:
        state["fingerprints"][p] = []
    raw = json.dumps(state, separators=(",", ":"), cls=_StateEncoder)
    if len(raw) <= MAX_TRADER_DATA:
        return raw

    # Шаг 3: hard truncate (state повреждён — пересоздастся на следующем тике)
    return raw[:MAX_TRADER_DATA]


# ─── 1. EMA ───────────────────────────────────────────────────────────────────

def update_ema(state: dict, product: str, price: float) -> float:
    """O(1). Обновляет EMA в ext state. alpha из CONFIG → EMA_ALPHA fallback."""
    alpha = CONFIG.get(product, {}).get("ema_alpha", EMA_ALPHA.get(product, 0.1))
    prev  = state["ema"].get(product)
    if prev is None:
        state["ema"][product] = price
    else:
        state["ema"][product] = alpha * price + (1 - alpha) * prev
    return state["ema"][product]


# ─── 2. ROLLING WINDOW ────────────────────────────────────────────────────────

def update_prices(state: dict, product: str, price: float) -> list:
    """Добавляет цену в rolling window, обрезает до ROLLING_WINDOW."""
    buf = state["prices"].get(product, [])
    buf.append(price)
    if len(buf) > ROLLING_WINDOW:
        buf = buf[-ROLLING_WINDOW:]
    state["prices"][product] = buf
    return buf


def rolling_mean(state: dict, product: str) -> Optional[float]:
    buf = state["prices"].get(product, [])
    return sum(buf) / len(buf) if buf else None


def rolling_std(state: dict, product: str) -> Optional[float]:
    buf = state["prices"].get(product, [])
    if len(buf) < 2:
        return None
    m = sum(buf) / len(buf)
    return math.sqrt(sum((x - m) ** 2 for x in buf) / len(buf))


# ─── 3. MULTIPLICATIVE WEIGHTS ────────────────────────────────────────────────

def update_mw(state: dict, product: str, strategy: str, loss: float) -> None:
    """
    loss > 0  → стратегия потеряла деньги
    loss < 0  → стратегия заработала (негативный loss = reward)
    """
    loss = max(-MW_LOSS_CLIP, min(MW_LOSS_CLIP, loss))
    w    = state["mw"][product].get(strategy, 1.0)
    state["mw"][product][strategy] = w * math.exp(-MW_ETA * loss)


def get_strategy_weights(state: dict, product: str) -> dict:
    """Нормализованные веса стратегий для продукта."""
    raw   = state["mw"].get(product, {s: 1.0 for s in STRATEGY_NAMES})
    total = sum(raw.values()) or 1.0
    return {s: v / total for s, v in raw.items()}


# ─── 4. BOT FINGERPRINT ───────────────────────────────────────────────────────

def update_fingerprint(state: dict, product: str, ts: int,
                        best_bid_p: Optional[float],
                        best_ask_p: Optional[float]) -> None:
    """Записывает [timestamp, best_bid, best_ask]. Хранит последние 50 тиков."""
    entry = [ts, best_bid_p, best_ask_p]
    buf   = state["fingerprints"].get(product, [])
    buf.append(entry)
    if len(buf) > 50:
        buf = buf[-50:]
    state["fingerprints"][product] = buf


def detect_bot_pattern(state: dict, product: str) -> bool:
    """
    Простая эвристика: если спред не менялся 10 тиков подряд — вероятно бот.
    """
    buf = state["fingerprints"].get(product, [])
    if len(buf) < 10:
        return False
    spreads = []
    for entry in buf[-10:]:
        _, bb, ba = entry
        if bb is not None and ba is not None:
            spreads.append(round(ba - bb, 4))
    if len(spreads) < 10:
        return False
    return len(set(spreads)) == 1


# ─── 5. KALMAN FILTER (scalar, цена) ─────────────────────────────────────────

def kalman_update(state: dict, product: str, z: float) -> float:
    """
    Скалярный Kalman для оценки fair value цены.
    Возвращает x_est — отфильтрованную оценку цены.
    """
    kf = state["kf"].get(product, {"x": None, "P": 1.0})
    x  = kf["x"]
    P  = kf["P"]

    if x is None:
        kf["x"] = z
        kf["P"] = 1.0
        state["kf"][product] = kf
        return z

    # predict
    x_pred = x
    P_pred = P + KF_Q

    # update
    K     = P_pred / (P_pred + KF_R)
    x_new = x_pred + K * (z - x_pred)
    P_new = (1 - K) * P_pred

    kf["x"] = x_new
    kf["P"] = P_new
    state["kf"][product] = kf
    return x_new


# ─── 6. ADVERSARIAL SELECTION ─────────────────────────────────────────────────

def record_fill(state: dict, product: str, side: str) -> None:
    """side: 'bid' или 'ask'"""
    adv = state["adv"].get(product, {"bid_fills": 0, "ask_fills": 0})
    if side == "bid":
        adv["bid_fills"] += 1
    else:
        adv["ask_fills"] += 1
    state["adv"][product] = adv


def is_toxic_flow(state: dict, product: str) -> bool:
    """True если > ADV_THRESHOLD fills с одной стороны (минимум 20 наблюдений)."""
    adv   = state["adv"].get(product, {"bid_fills": 0, "ask_fills": 0})
    total = adv["bid_fills"] + adv["ask_fills"]
    if total < 20:
        return False
    ratio = max(adv["bid_fills"], adv["ask_fills"]) / total
    return ratio > ADV_THRESHOLD


def reset_adv_counters(state: dict, product: str) -> None:
    state["adv"][product] = {"bid_fills": 0, "ask_fills": 0}


# ─── 7. CUMULATIVE PNL + CIRCUIT BREAKERS ────────────────────────────────────

def update_strategy_pnl(state: dict, product: str, strategy: str,
                         delta_pnl: float) -> None:
    if product not in state["cum_pnl"]:
        state["cum_pnl"][product] = {s: 0.0 for s in STRATEGY_NAMES}
    state["cum_pnl"][product][strategy] = (
        state["cum_pnl"][product].get(strategy, 0.0) + delta_pnl
    )


def check_circuit_breaker(state: dict, product: str, strategy: str,
                            tick: int) -> bool:
    """
    True — стратегия отключена (circuit breaker сработал или в cooldown).
    При срабатывании: обнуляет cum_pnl, устанавливает cooldown CB_RESET_TICKS.
    """
    cb = state.get("cb_disabled_until", {})
    if product not in cb:
        return False
    disabled_until = cb[product].get(strategy, 0)
    if tick < disabled_until:
        return True
    cum = state["cum_pnl"].get(product, {}).get(strategy, 0.0)
    if cum < CB_LOSS_LIMIT:
        state["cb_disabled_until"][product][strategy] = tick + CB_RESET_TICKS
        state["cum_pnl"][product][strategy] = 0.0
        print(f"[CB] {product}/{strategy} disabled until tick {tick + CB_RESET_TICKS}")
        return True
    return False


# ─── ORDER BOOK UTILS (standalone, используются в strategy_* функциях) ────────
# Именованы с префиксом ob_ чтобы не конфликтовать с локальными переменными
# в методах Trader_full.

def ob_best_bid(od: OrderDepth) -> Optional[int]:
    return max(od.buy_orders.keys()) if od.buy_orders else None


def ob_best_ask(od: OrderDepth) -> Optional[int]:
    return min(od.sell_orders.keys()) if od.sell_orders else None


def ob_mid_price(od: OrderDepth) -> Optional[float]:
    bb = ob_best_bid(od)
    ba = ob_best_ask(od)
    if bb is not None and ba is not None:
        return (bb + ba) / 2
    return bb or ba


def clamp_order(product: str, qty: int, position: int) -> int:
    """
    Standalone clamp для использования внутри strategy_* функций.
    Использует POSITION_LIMITS (hard limit).
    Для полного pending-aware учёта использовать PositionManager.
    """
    lim = POSITION_LIMITS.get(product, 0)
    if qty > 0:
        return min(qty,  lim - position)
    else:
        return max(qty, -lim - position)


# ─── СТРАТЕГИИ (MW-based, используются в _trade_with_strategies) ──────────────

def strategy_mm(product: str, od: OrderDepth, state: dict,
                position: int, tick: int) -> List[Order]:
    """Market making вокруг Kalman fair value. SpreadConfig + inventory skew."""
    fv = state["kf"].get(product, {}).get("x")
    if fv is None:
        return []
    # [§F] SpreadConfig — использовать per-product spread targets
    regime = state.get("regime8", {}).get(product, "NEUTRAL")
    wide_mode = "TREND" in str(regime) or "SPIKE" in str(regime)
    spread = spread_config.get_spread_target(product, wide=wide_mode)
    orders  = []
    limit = POSITION_LIMITS.get(product, 50)
    # Inventory skew: shift quotes away from current position
    inv_skew = position / max(1, limit)  # -1..+1
    skew_offset = int(inv_skew * spread)  # shift mid by position fraction
    adjusted_fv = fv - skew_offset        # shift FV to encourage mean-reversion
    bid_qty = clamp_order(product,  5, position)
    ask_qty = clamp_order(product, -5, position)
    if bid_qty > 0:
        orders.append(Order(product, int(adjusted_fv - spread),  bid_qty))
    if ask_qty < 0:
        orders.append(Order(product, int(adjusted_fv + spread), ask_qty))
    # [§F] QuoteLadder — additional passive levels (level 2/3 only)
    if abs(position) < limit * 0.6:  # only when not near limit
        for extra_offset, extra_frac in [(2, 0.15), (4, 0.10)]:
            extra_size = max(1, int(limit * extra_frac))
            eb = clamp_order(product,  extra_size, position)
            ea = clamp_order(product, -extra_size, position)
            if eb > 0:
                orders.append(Order(product, int(adjusted_fv - spread - extra_offset), eb))
            if ea < 0:
                orders.append(Order(product, int(adjusted_fv + spread + extra_offset), ea))
    return orders


def strategy_trend(product: str, od: OrderDepth, state: dict,
                   position: int, tick: int) -> List[Order]:
    """Trend following по EMA vs rolling mean."""
    ema_val = state["ema"].get(product)
    rmean   = rolling_mean(state, product)
    if ema_val is None or rmean is None:
        return []
    ba     = ob_best_ask(od)
    bb     = ob_best_bid(od)
    orders = []
    if ema_val > rmean * 1.002 and ba:
        qty = clamp_order(product, 3, position)
        if qty > 0:
            orders.append(Order(product, ba, qty))
    elif ema_val < rmean * 0.998 and bb:
        qty = clamp_order(product, -3, position)
        if qty < 0:
            orders.append(Order(product, bb, qty))
    return orders


def strategy_arb(product: str, od: OrderDepth, state: dict,
                 position: int, tick: int) -> List[Order]:
    """
    Арбитраж — basket arb (PICNIC_BASKET1/2, GIFT_BASKET) + component hedge.
    Использует BasketArbEngine: z-score mean reversion на спред basket vs synthetic.
    Для компонентов корзины — обратный сигнал пропорционально весу.
    """
    orders: List[Order] = []
    prices = state.get("prices", {})
    ba = od.buy_orders
    sa = od.sell_orders
    best_bid = max(ba.keys()) if ba else None
    best_ask = min(sa.keys()) if sa else None
    if not best_bid or not best_ask:
        return orders

    # ── Basket product → arb vs synthetic components ──
    weights = BASKET_WEIGHTS.get(product)
    if weights:
        mid_prices = {}
        for comp in weights:
            comp_ph = prices.get(comp, [])
            if comp_ph:
                mid_prices[comp] = comp_ph[-1]
        if len(mid_prices) < len(weights):
            return orders  # не все компоненты доступны
        basket_ph = prices.get(product, [])
        if not basket_ph:
            return orders
        basket_mid = basket_ph[-1]

        engine = BasketArbEngine()
        # Use precomputed regression weights if available (more accurate)
        precomp_bh = state.get("_precomp_basket_hedge", {}).get(product, {})
        if precomp_bh and "weights" in precomp_bh:
            arb_weights = {k: float(v) for k, v in precomp_bh["weights"].items()}
            intercept = float(precomp_bh.get("intercept", 0))
            synthetic = sum(arb_weights.get(c, 0) * mid_prices.get(c, 0) for c in arb_weights) + intercept
        else:
            synthetic = engine.synthetic_price(mid_prices, {k: float(v) for k, v in weights.items()})
        spread = engine.compute_spread(basket_mid, synthetic)

        ps_key = f"_arb_ps_{product}"
        ps = state.get(ps_key)
        if ps is None:
            ps = PairState()
            state[ps_key] = ps
        engine.update_spread(ps, spread)

        if engine.is_warmed_up(ps):
            bid_ask_spread = best_ask - best_bid

            # Stop-loss: z > 4 → закрыть немедленно
            if engine.stop_loss_signal(ps) and position != 0:
                if position > 0:
                    orders.append(Order(product, best_bid, -position))
                else:
                    orders.append(Order(product, best_ask, -position))
                return orders

            # Exit: |z| < 0.5 → закрыть позицию
            if position != 0 and engine.exit_signal(ps):
                if position > 0:
                    orders.append(Order(product, best_bid, -position))
                else:
                    orders.append(Order(product, best_ask, -position))
                return orders

            # Entry: z > 2 → short basket; z < -2 → long basket
            signal = engine.entry_signal(ps, SPREAD_ENTRY_Z, 0.0, float(bid_ask_spread))
            if signal and position == 0:
                limit = POSITION_LIMITS.get(product, 0)
                size = min(3, limit)
                if signal == "short" and size > 0:
                    orders.append(Order(product, best_bid, -size))
                elif signal == "long" and size > 0:
                    orders.append(Order(product, best_ask, size))
        return orders

    # ── Component product → reverse hedge signal from basket arb ──
    for basket_name, deps in PRODUCT_DEPENDENCIES.items():
        if product in deps and basket_name in BASKET_WEIGHTS:
            bw = BASKET_WEIGHTS[basket_name]
            ps_key = f"_arb_ps_{basket_name}"
            ps = state.get(ps_key)
            if ps is None or not hasattr(ps, 'z_score'):
                continue
            engine = BasketArbEngine()
            if not engine.is_warmed_up(ps):
                continue
            coef = bw.get(product, 1)
            size = min(2, coef)
            # Component signal is OPPOSITE to basket signal
            if ps.z_score > SPREAD_ENTRY_Z and size > 0:
                # Basket overvalued → BUY components
                orders.append(Order(product, best_ask, size))
            elif ps.z_score < -SPREAD_ENTRY_Z and size > 0:
                # Basket undervalued → SELL components
                orders.append(Order(product, best_bid, -size))
            break  # one basket per component

    return orders


STRATEGIES = {"mm": strategy_mm, "trend": strategy_trend, "arb": strategy_arb}


# ─── POSITION MANAGER ─────────────────────────────────────────────────────────
# Soft/hard лимит, двусторонний, pending-aware.
# Создавать новый экземпляр каждый тик на каждый продукт.
#
# SOFT_CLAMP  — обрезан до soft, торговля продолжается
# HARD_REJECT — превышает hard, отклонён полностью
#               (не должно случаться если soft работает правильно)

class PositionManager:

    def __init__(self, product: str, state: TradingState, ts: int):
        self.product  = product
        self.spec     = get_limit(product)
        self.position = state.position.get(product, 0)
        self.ts       = ts
        self._pending_buy:  int = 0
        self._pending_sell: int = 0

    @property
    def soft_available_buy(self) -> int:
        return self.spec.soft - self.position - self._pending_buy

    @property
    def soft_available_sell(self) -> int:
        return self.spec.soft + self.position - self._pending_sell

    @property
    def hard_available_buy(self) -> int:
        return self.spec.hard - self.position - self._pending_buy

    @property
    def hard_available_sell(self) -> int:
        return self.spec.hard + self.position - self._pending_sell

    # алиасы для обратной совместимости
    @property
    def available_buy(self) -> int:
        return self.soft_available_buy

    @property
    def available_sell(self) -> int:
        return self.soft_available_sell

    @property
    def headroom_pct(self) -> float:
        if self.spec.soft == 0:
            return 1.0
        return min(1.0, abs(self.position + self._pending_buy - self._pending_sell) / self.spec.soft)

    def clamp(self, qty: int) -> int:
        if qty == 0:
            return 0
        if qty > 0:
            if self.hard_available_buy <= 0:
                logger.log(self.ts, self.product, "HARD_REJECT",
                           extra=f"side=BUY qty={qty} pos={self.position} hard={self.spec.hard}")
                return 0
            avail = self.soft_available_buy
            if avail <= 0:
                logger.log(self.ts, self.product, "LIMIT_REJECT",
                           extra=f"side=BUY qty={qty} soft_avail=0 "
                                 f"pos={self.position} pending={self._pending_buy} soft={self.spec.soft}")
                return 0
            clamped = min(qty, avail)
            if clamped != qty:
                logger.log(self.ts, self.product, "LIMIT_CLAMP",
                           extra=f"side=BUY {qty}→{clamped} "
                                 f"pos={self.position} pending={self._pending_buy} "
                                 f"soft={self.spec.soft} hard={self.spec.hard}")
            self._pending_buy += clamped
            return clamped
        else:
            if self.hard_available_sell <= 0:
                logger.log(self.ts, self.product, "HARD_REJECT",
                           extra=f"side=SELL qty={qty} pos={self.position} hard={self.spec.hard}")
                return 0
            avail = self.soft_available_sell
            if avail <= 0:
                logger.log(self.ts, self.product, "LIMIT_REJECT",
                           extra=f"side=SELL qty={qty} soft_avail=0 "
                                 f"pos={self.position} pending={self._pending_sell} soft={self.spec.soft}")
                return 0
            clamped = max(qty, -avail)
            if clamped != qty:
                logger.log(self.ts, self.product, "LIMIT_CLAMP",
                           extra=f"side=SELL {qty}→{clamped} "
                                 f"pos={self.position} pending={self._pending_sell} "
                                 f"soft={self.spec.soft} hard={self.spec.hard}")
            self._pending_sell += abs(clamped)
            return clamped

    def clamp_orders(self, orders: List[Order]) -> List[Order]:
        result = []
        for o in orders:
            qty = self.clamp(o.quantity)
            if qty != 0:
                result.append(Order(o.symbol, o.price, qty))
        return result

    def skew_size(self, base: int, factor: float = 0.5) -> Tuple[int, int]:
        """В лонге → меньше bid, больше ask. Skew по soft лимиту."""
        if self.spec.soft == 0:
            return 0, 0
        ratio    = self.position / self.spec.soft
        skew     = ratio * factor
        bid_size = max(0, min(int(base * (1.0 - skew)), self.soft_available_buy))
        ask_size = max(0, min(int(base * (1.0 + skew)), self.soft_available_sell))
        return bid_size, ask_size


# ─── FEE-AWARE QUOTER ─────────────────────────────────────────────────────────
# Типы ордеров в Prosperity: только Limit orders — Order(symbol, price, qty)
#   price = int (целое), qty > 0 = buy, qty < 0 = sell
#   Market orders не существуют. Ордера не переносятся между тиками.
#   Частичное исполнение возможно — остаток пропадает.
#
# Matching: FIFO в рамках ценового уровня
#   Price priority: лучшая цена исполняется первой
#   Time priority:  при одинаковой цене — раньше выставленный
#   Self-trade prevention: твои ордера не бьются против твоих
#   Суммарный объём + позиция > hard limit → ВСЕ ордера продукта отменяются

@dataclass
class QuoteResult:
    bid_price:    Optional[int]
    ask_price:    Optional[int]
    bid_qty:      int
    ask_qty:      int
    bid_fee:      float
    ask_fee:      float
    bid_net_edge: float
    ask_net_edge: float
    spread_used:  int
    min_spread:   int
    fv_used:      float
    skipped_bid:  bool = False
    skipped_ask:  bool = False


class FeeAwareQuoter:

    def __init__(self, product: str):
        self.product  = product
        self.spec     = get_fee(product)
        self.min_edge = MIN_EDGE_TICKS.get(product, MIN_EDGE_TICKS["DEFAULT"])

    def fee_total(self, price: int, qty: int, is_taker: bool = False) -> float:
        """fee = abs(qty) * price * rate"""
        rate = self.spec.taker if is_taker else self.spec.maker
        return abs(qty) * price * rate

    def fee_per_unit(self, price: int, is_taker: bool = False, qty: int = 1) -> float:
        """
        fee на единицу объёма.
        qty передан для нелинейной модели Round 3+:
          линейная:    price * rate
          нелинейная:  price * (base_rate + slope * qty / ADV)
        TODO(Round 3+): обновить формулу здесь синхронно с fee_total()
        """
        rate = self.spec.taker if is_taker else self.spec.maker
        return price * rate

    def min_spread_to_cover_fee(self, fv: float) -> int:
        return (int(abs(fv * self.spec.maker)) + self.min_edge) * 2

    def quote(self, fv: float, mid: float, desired_spread: int,
              bid_qty: int, ask_qty: int, ts: int,
              is_taker: bool = False) -> QuoteResult:
        min_spread = self.min_spread_to_cover_fee(fv)
        spread     = max(desired_spread, min_spread)
        half       = spread // 2
        bid_price  = int(mid - half)
        ask_price  = int(mid + half)

        bid_net_edge = (fv - bid_price) - self.fee_per_unit(bid_price, is_taker, bid_qty)
        ask_net_edge = (ask_price - fv) - self.fee_per_unit(ask_price, is_taker, ask_qty)
        bid_fee      = self.fee_total(bid_price, bid_qty, is_taker)
        ask_fee      = self.fee_total(ask_price, ask_qty, is_taker)
        skipped_bid  = bid_net_edge < self.min_edge
        skipped_ask  = ask_net_edge < self.min_edge

        logger.log(ts, self.product, "QUOTE",
                   extra=(f"fv={fv:.2f} mid={mid:.2f} spread={spread} "
                          f"bid={bid_price}(edge={bid_net_edge:.3f}) "
                          f"ask={ask_price}(edge={ask_net_edge:.3f}) "
                          f"maker={self.spec.maker} "
                          f"bid_fee={bid_fee:.4f} ask_fee={ask_fee:.4f} "
                          f"skip_bid={skipped_bid} skip_ask={skipped_ask}"))
        if skipped_bid:
            logger.log(ts, self.product, "SKIP_BID",
                       extra=f"net_edge={bid_net_edge:.3f} < min={self.min_edge}")
        if skipped_ask:
            logger.log(ts, self.product, "SKIP_ASK",
                       extra=f"net_edge={ask_net_edge:.3f} < min={self.min_edge}")

        return QuoteResult(
            bid_price=None if skipped_bid else bid_price,
            ask_price=None if skipped_ask else ask_price,
            bid_qty=bid_qty, ask_qty=ask_qty,
            bid_fee=bid_fee, ask_fee=ask_fee,
            bid_net_edge=bid_net_edge, ask_net_edge=ask_net_edge,
            spread_used=spread, min_spread=min_spread, fv_used=fv,
            skipped_bid=skipped_bid, skipped_ask=skipped_ask,
        )

    def to_orders(self, product: str, result: QuoteResult) -> List[Order]:
        orders = []
        if result.bid_price is not None and result.bid_qty > 0:
            orders.append(Order(product, result.bid_price,  result.bid_qty))
        if result.ask_price is not None and result.ask_qty > 0:
            orders.append(Order(product, result.ask_price, -result.ask_qty))
        return orders

    def aggressive_order(self, product: str, side: str, target_price: int,
                         qty: int, fv: float, ts: int) -> Optional[Order]:
        """Taker ордер — проверяем net_edge после taker fee."""
        fee_pu   = self.fee_per_unit(target_price, is_taker=True, qty=qty)
        net_edge = (fv - target_price - fee_pu) if side == "BUY" else (target_price - fv - fee_pu)
        if net_edge < self.min_edge:
            logger.log(ts, product, f"SKIP_AGGRESSIVE_{side}",
                       extra=f"price={target_price} net_edge={net_edge:.3f}")
            return None
        logger.log(ts, product, f"AGGRESSIVE_{side}", price=target_price, qty=qty,
                   extra=f"net_edge={net_edge:.3f}")
        return Order(product, target_price, qty if side == "BUY" else -qty)


# ─── REGIME DETECTOR 8 (inline) ──────────────────────────────────────────────

class RegimeDetector8:
    """8-state regime detector: TREND/MEAN_REVERT × {plain,BOT_GONE,BOT_CHANGED,VOLUME_SPIKE}."""

    def __init__(self, product: str, window: int = 50):
        self.product = product
        self.window  = window
        self._prices:  List[float] = []
        self._volumes: List[float] = []
        self._prev_bot_prices: List[float] = []
        self._vol_mean: float = 0.0
        self._vol_m2:   float = 0.0
        self._vol_n:    int   = 0

    def _lag1_autocorr(self) -> float:
        if len(self._prices) < 3:
            return 0.0
        r = self._prices[-min(self.window, len(self._prices)):]
        n = len(r)
        if n < 3:
            return 0.0
        mean = sum(r) / n
        num  = sum((r[i] - mean) * (r[i - 1] - mean) for i in range(1, n))
        den  = sum((x - mean) ** 2 for x in r)
        return num / den if den > 1e-12 else 0.0

    def _update_vol_stats(self, v: float) -> None:
        self._vol_n += 1
        delta = v - self._vol_mean
        self._vol_mean += delta / self._vol_n
        self._vol_m2   += delta * (v - self._vol_mean)

    def _volume_zscore(self, v: float) -> float:
        if self._vol_n < 5:
            return 0.0
        std = (self._vol_m2 / self._vol_n) ** 0.5
        return (v - self._vol_mean) / std if std > 1e-12 else 0.0

    def update(self, mid_price: float, volume: float, tick: int) -> str:
        self._prices.append(mid_price)
        if len(self._prices) > self.window:
            self._prices = self._prices[-self.window:]
        self._update_vol_stats(volume)
        self._volumes.append(volume)
        if len(self._volumes) > self.window:
            self._volumes = self._volumes[-self.window:]

        ac = self._lag1_autocorr()
        if ac > 0.15:
            base = "TREND"
        elif ac < -0.15:
            base = "MEAN_REVERT"
        else:
            base = "NEUTRAL"

        # Volume spike suffix
        vol_z = self._volume_zscore(volume)
        if vol_z > 3.0:
            return base + "_VOLUME_SPIKE" if base != "NEUTRAL" else "NEUTRAL_VOLUME_SPIKE"

        # Bot events
        suffix = self._detect_bot_events(mid_price)
        if suffix:
            return base + suffix if base != "NEUTRAL" else "NEUTRAL" + suffix

        return base

    def _detect_bot_events(self, mid_price: float) -> str:
        if len(self._prices) < 3:
            return ""
        recent = self._prices[-5:]
        # BOT_GONE: previous ticks had movement, last 2 are identical (bot silent)
        if len(recent) >= 3 and recent[-1] == recent[-2]:
            return "_BOT_GONE"
        # BOT_CHANGED: sudden large jump vs rolling std
        if len(recent) >= 5:
            diffs = [abs(recent[i] - recent[i-1]) for i in range(1, len(recent))]
            mean_d = sum(diffs[:-1]) / max(len(diffs) - 1, 1)
            std_d  = (sum((d - mean_d)**2 for d in diffs[:-1]) / max(len(diffs) - 1, 1)) ** 0.5
            if std_d > 1e-12 and diffs[-1] > mean_d + 2 * std_d:
                return "_BOT_CHANGED"
        return ""


# ─── SATURATION DETECTOR (inline) ────────────────────────────────────────────

def _sat_ols_slope(y: List[float]) -> float:
    n = len(y)
    if n < 2:
        return 0.0
    x_mean = (n - 1) / 2.0
    y_mean = sum(y) / n
    num = sum((i - x_mean) * (y[i] - y_mean) for i in range(n))
    den = sum((i - x_mean) ** 2 for i in range(n))
    return num / den if den > 1e-12 else 0.0


class SaturationDetectorInline:
    """Per-strategy saturation detector. window=20, threshold=0.5."""

    def __init__(self, window: int = 20, threshold: float = 0.5):
        self.window    = window
        self.threshold = threshold
        self._pnl_buf: List[float] = []
        self.status = "HEALTHY"

    def update(self, pnl_delta: float) -> str:
        self._pnl_buf.append(pnl_delta)
        if len(self._pnl_buf) > self.window:
            self._pnl_buf = self._pnl_buf[-self.window:]
        if len(self._pnl_buf) < 5:
            self.status = "HEALTHY"
            return self.status
        slope = _sat_ols_slope(self._pnl_buf)
        last5_all_neg = all(v < 0 for v in self._pnl_buf[-5:])
        if slope < 0 and last5_all_neg:
            self.status = "SATURATED"
        elif slope < -self.threshold:
            self.status = "SATURATING"
        else:
            self.status = "HEALTHY"
        return self.status


class MultiStrategySaturationTrackerInline:
    """Per-strategy saturation trackers + switch recommendation."""

    def __init__(self, strategy_names: List[str], window: int = 20, threshold: float = 0.5):
        self._detectors: Dict[str, SaturationDetectorInline] = {
            s: SaturationDetectorInline(window, threshold) for s in strategy_names
        }
        self._pnl_history: Dict[str, List[float]] = {s: [] for s in strategy_names}

    def update(self, strategy: str, pnl_delta: float) -> str:
        if strategy not in self._detectors:
            self._detectors[strategy]    = SaturationDetectorInline()
            self._pnl_history[strategy] = []
        self._pnl_history[strategy].append(pnl_delta)
        return self._detectors[strategy].update(pnl_delta)

    def status(self, strategy: str) -> str:
        return self._detectors.get(strategy, SaturationDetectorInline()).status

    def recommend_switch(self) -> Optional[str]:
        """Return strategy with best recent PnL that is not SATURATED."""
        best, best_sum = None, float("-inf")
        for s, det in self._detectors.items():
            if det.status == "SATURATED":
                continue
            hist = self._pnl_history.get(s, [])
            recent_sum = sum(hist[-10:]) if hist else 0.0
            if recent_sum > best_sum:
                best_sum, best = recent_sum, s
        return best

    def switch_to(self, strategy: str) -> None:
        if strategy in self._detectors:
            self._detectors[strategy].status = "HEALTHY"


# ─── LIMIT COORDINATOR (inline) ──────────────────────────────────────────────

class StrategyRequestInline:
    __slots__ = ("strategy", "product", "desired_qty", "min_qty", "priority")
    _PRIORITY = {"conversion_arb": 1, "basket_arb": 2, "iv_arb": 3, "bot_copy": 4, "market_maker": 5}

    def __init__(self, strategy: str, product: str, desired_qty: int, min_qty: int = 0):
        self.strategy    = strategy
        self.product     = product
        self.desired_qty = desired_qty
        self.min_qty     = min_qty
        self.priority    = self._PRIORITY.get(strategy, 5)


class LimitCoordinatorInline:
    """Runs once per tick before strategies; allocates position capacity by priority."""

    def __init__(self, position_limits: Dict[str, int]):
        self._limits = position_limits

    def net_orders(self, requests: List[StrategyRequestInline],
                   positions: Dict[str, int]) -> Dict[str, int]:
        """Net conflicting signals, clamp to available capacity."""
        net: Dict[str, int] = {}
        # Sort by priority so high-priority signals dominate conflicts
        for req in sorted(requests, key=lambda r: r.priority):
            net[req.product] = net.get(req.product, 0) + req.desired_qty
        clamped: Dict[str, int] = {}
        for product, qty in net.items():
            limit = self._limits.get(product, 20)
            pos   = positions.get(product, 0)
            if qty > 0:
                clamped[product] = min(qty, limit - pos)
            elif qty < 0:
                clamped[product] = max(qty, -(limit + pos))
            else:
                clamped[product] = 0
        return clamped

    def max_order_qty(self, product: str, side: str, position: int) -> int:
        """Max qty that can be placed without breaching limit."""
        limit = self._limits.get(product, 20)
        if side == "BUY":
            return max(0, limit - position)
        else:
            return max(0, limit + position)


# ─── TRADER ───────────────────────────────────────────────────────────────────

class Trader_full:

    def __init__(self):
        self.prices:            Dict[str, List[float]] = {}
        self.ema:               Dict[str, float]       = {}
        self.tick:              int                    = 0
        self.pnl:               Dict[str, float]       = {}
        self.calibrated_params: dict                   = {}
        self.coint_result:      dict                   = {}
        self.profiler = cProfile.Profile()
        self.profiling = False

        # [P.1] Sherman-Morrison O(1) VaR per tick
        self._sm_pm = ShermanMorrisonPortfolioManager(
            products=list(PRODUCTS), window=50
        )

        # [0.14] 8-state regime detector per product
        self._regime8: Dict[str, object] = {}

        # [13.1] DrawdownController — per-instrument high-water (single instance)
        self._drawdown_ctrl = DrawdownController()

        # Bayesian bot threshold trackers — keyed by bot name
        try:
            self._bayesian_bots = {
                name: BayesianBotTracker(name)
                for name in ["Olivia", "Rhianna", "Charlie", "Vladimir", "Pablo"]
            }
        except Exception:
            self._bayesian_bots = {}

        # PnL history for decision tree (last 50-tick delta)
        self._pnl_history: deque = deque(maxlen=50)

        # [3.1] Multi-strategy saturation tracker
        self._sat_tracker = MultiStrategySaturationTrackerInline(
            strategy_names=["basket_arb", "conversion_arb", "iv_arb", "bot_copy", "market_maker"],
            window=20, threshold=0.5,
        )
        self._active_strategy: str = "market_maker"

        # [0.12] LimitCoordinator — runs first each tick to gate order sizes
        self._limit_coord = LimitCoordinatorInline(POSITION_LIMITS)

        # [0.10] Hypothesis registry — parallel confidence scoring each tick
        try:
            from hypothesis_registry import HypothesisRegistry as _HReg
            self._hyp_registry = _HReg()
        except Exception:
            self._hyp_registry = None

        # [Algorithm 1] Monopoly tracker — per active instrument
        self._monopoly: Dict[str, object] = {}  # product → MonopolyTracker stub

        # [Algorithm 2] Execution invariant checker
        self._pipeline_violations: List[str] = []

        # ── PRECOMPUTED DATA (from 21_background.py offline computations) ────
        self._precomp = self._load_precomputed()
        # Apply precomputed calibration as initial params
        if "calibration" in self._precomp:
            for product, cal in self._precomp["calibration"].items():
                if product not in self.calibrated_params:
                    self.calibrated_params[product] = {
                        "spread": cal.get("optimal_spread", 3),
                        "vol": cal.get("volatility", 0.01),
                        "mean": cal.get("mean_price", 0),
                        "size": cal.get("optimal_size", 10),
                        "ema_alpha": cal.get("ema_alpha", 0.1),
                        "as_gamma": cal.get("as_gamma", 0.01),
                    }
        # Apply precomputed spread optimizer — override CONFIG spreads
        if "spread_optimizer" in self._precomp:
            for product, sp in self._precomp["spread_optimizer"].items():
                if product in CONFIG and isinstance(CONFIG[product], dict):
                    opt_spread = sp.get("optimal_spread")
                    if opt_spread and opt_spread > 0:
                        CONFIG[product]["spread"] = opt_spread
        # Apply precomputed cointegration pairs
        if "cointegration" in self._precomp:
            for pair_info in self._precomp["cointegration"]:
                if pair_info.get("correlation", 0) > 0.8:
                    p1, p2 = pair_info["pair"]
                    key = f"{p1}_{p2}"
                    self.coint_result[key] = {
                        "score": pair_info.get("beta", 1.0),
                        "pvalue": 0.01,
                        "cointegrated": True,
                        "beta": pair_info.get("beta", 1.0),
                        "half_life": pair_info.get("half_life", 5.0),
                        "spread_mean": pair_info.get("spread_mean", 0),
                        "spread_std": pair_info.get("spread_std", 1),
                    }
        # Apply precomputed bot models — seed Bayesian trackers
        if "bot_models" in self._precomp:
            for bot_name, model in self._precomp["bot_models"].items():
                if bot_name in self._bayesian_bots and model.get("predictable"):
                    try:
                        tracker = self._bayesian_bots[bot_name]
                        tracker._precomp_buy_ratio = model.get("buy_ratio", 0.5)
                        tracker._precomp_products = model.get("top_products", {})
                    except Exception:
                        pass
        # Apply precomputed fair values — update CONFIG fair_value
        if "fair_value" in self._precomp:
            for product, fv_data in self._precomp["fair_value"].items():
                if product in CONFIG and isinstance(CONFIG[product], dict):
                    fv = fv_data.get("mean_price")
                    if fv and fv > 0:
                        CONFIG[product]["fair_value"] = fv
                    alpha = fv_data.get("optimal_ema_alpha")
                    if alpha:
                        CONFIG[product]["ema_alpha"] = alpha
        # Apply precomputed order flow — toxic thresholds
        self._order_flow_precomp = self._precomp.get("order_flow", {})
        # Apply precomputed regime info
        self._regime_precomp = self._precomp.get("regime_markov", {})
        # Store basket hedge weights for runtime use
        self._basket_hedge_precomp = self._precomp.get("basket_hedge", {})
        # Store IV surface for voucher pricing
        self._iv_surface_precomp = self._precomp.get("iv_surface", {})

    @staticmethod
    def _load_precomputed() -> dict:
        """Load all precomputed JSON from data/precomputed/ directory."""
        data = {}
        base = Path(__file__).parent / "data" / "precomputed"
        if not base.exists():
            return data
        files = {
            "basket_hedge": "basket_hedge.json",
            "bot_models": "bot_models.json",
            "calibration": "calibration.json",
            "cointegration": "cointegration.json",
            "iv_surface": "iv_surface.json",
            "spread_optimizer": "spread_optimizer.json",
            "fair_value": "fair_value.json",
            "regime_markov": "regime_markov.json",
            "order_flow": "order_flow.json",
            "p2_strategies": "p2_strategies.json",
        }
        for key, fname in files.items():
            fpath = base / fname
            if fpath.exists():
                try:
                    with open(fpath) as f:
                        data[key] = json.load(f)
                except Exception:
                    pass
        return data

    def run(self, state: TradingState):
        self.tick += 1
        ts = state.timestamp
        timeout_guard.start()

        if self.tick % CONFIG["PROFILE_EVERY"] == 0:
            try:
                self.profiler.enable()
                self.profiling = True
            except ValueError:
                self.profiling = False  # Another profiler active, skip

        try:
            # 1. Загрузить полный ext state из traderData
            #    (заменяет ручной json.loads, поддерживает миграцию формата)
            ext = load_state(state.traderData)

            # Inject precomputed data into ext for strategy access
            ext["_precomp_basket_hedge"] = self._basket_hedge_precomp
            ext["_precomp_iv_surface"] = self._iv_surface_precomp

            # Синхронизировать instance vars: instance vars побеждают при конфликте
            if self.pnl:
                ext["pnl"] = self.pnl
            elif ext.get("pnl"):
                self.pnl = ext["pnl"]

            if self.ema:
                ext["ema"].update(self.ema)
            elif ext.get("ema"):
                self.ema = {k: v for k, v in ext["ema"].items() if v is not None}

            if self.calibrated_params:
                ext["calibrated_params"] = self.calibrated_params
            elif ext.get("calibrated_params"):
                self.calibrated_params = ext["calibrated_params"]

            for product, plist in self.prices.items():
                if plist:
                    ext["prices"][product] = plist
            if not self.prices:
                for product, plist in ext.get("prices", {}).items():
                    if plist:
                        self.prices[product] = plist

            # 2. Обновить историю цен — O(depth)=O(3), EMA O(1)
            for product, od in state.order_depths.items():
                timeout_guard.check()
                if not od.buy_orders or not od.sell_orders:
                    continue
                d        = CONFIG["ORDERBOOK_DEPTH"]
                top_bids = heapq.nlargest(d, od.buy_orders)   # O(n) vs sorted O(n log n)
                top_asks = heapq.nsmallest(d, od.sell_orders)  # O(n)
                if not top_bids or not top_asks:
                    continue
                mid   = (top_bids[0] + top_asks[0]) / 2
                alpha = CONFIG.get(product, {}).get("ema_alpha", 0.1)
                # instance EMA (code 2 — inline)
                self.ema[product] = (alpha * mid + (1 - alpha) * self.ema[product]
                                     if product in self.ema else mid)
                self.prices.setdefault(product, []).append(mid)
                if len(self.prices[product]) > CONFIG["PRICE_HISTORY_MAX"]:
                    del self.prices[product][:-CONFIG["PRICE_HISTORY_MAX"]]  # in-place trim, no new alloc
                # ext state indicators (code 1)
                update_ema(ext, product, mid)
                update_prices(ext, product, mid)
                kalman_update(ext, product, mid)
                bb_fp = ob_best_bid(od)
                ba_fp = ob_best_ask(od)
                update_fingerprint(ext, product, ts, bb_fp, ba_fp)

            # 2a. [0.10] Hypothesis registry update — parallel confidence scoring
            try:
                if self._hyp_registry is not None:
                    for product, plist in self.prices.items():
                        if plist:
                            self._hyp_registry.update_all(plist[-1], self.tick)
                    if self.tick % 50 == 0:
                        top = self._hyp_registry.top_hypotheses(3)
                        for h in top:
                            logger.log(ts, "ALL", "HYPOTHESIS",
                                       extra=f"name={h['name']} conf={h['confidence']:.3f} signal={h['signal']}")
                        ext["best_strategy"] = self._hyp_registry.best_strategy()
            except Exception:
                pass

            # 2b. [P.1] Sherman-Morrison VaR update + [0.14] 8-state regime update
            returns_tick: Dict[str, float] = {}
            for product in state.order_depths:
                ph = self.prices.get(product, [])
                if len(ph) >= 2 and ph[-2] > 0:
                    returns_tick[product] = (ph[-1] - ph[-2]) / ph[-2]
                    # 8-state regime
                    if product not in self._regime8:
                        try:
                            self._regime8[product] = RegimeDetector8(product, window=50)
                        except Exception:
                            pass
                    if product in self._regime8:
                        try:
                            vol_this_tick = sum(
                                abs(t.quantity)
                                for t in state.market_trades.get(product, [])
                            )
                            regime_state = self._regime8[product].update(
                                mid_price=ph[-1],
                                volume=float(vol_this_tick),
                                tick=self.tick,
                            )
                            ext.setdefault("regime8", {})[product] = regime_state
                        except Exception:
                            pass
            try:
                self._sm_pm.update(returns_tick)
                positions_dict = {p: state.position.get(p, 0) for p in PRODUCTS}
                sm_var = self._sm_pm.portfolio_var(positions_dict)
                if sm_var > 0:
                    logger.log(ts, "ALL", "SM_VAR", extra=f"99pct_VaR={sm_var:.2f}")
            except Exception:
                pass

            # 2c. Bayesian bot tracker update — from market trades
            for product, trades in state.market_trades.items():
                for trade in trades:
                    bot_name = getattr(trade, "buyer", None) or getattr(trade, "seller", None)
                    if bot_name and bot_name in self._bayesian_bots:
                        try:
                            self._bayesian_bots[bot_name].observe(
                                product=product,
                                price=trade.price,
                                qty=trade.quantity,
                                tick=self.tick,
                            )
                        except Exception:
                            pass

            # 3. Калибровка — каждые CALIBRATE_EVERY тиков
            if self.tick % CONFIG["CALIBRATE_EVERY"] == 0:
                timeout_guard.check()
                self._calibrate_params(state, ts)

            # 4. Cointegration — каждые COINT_EVERY тиков
            if self.tick % CONFIG["COINT_EVERY"] == 0:
                timeout_guard.check()
                self._run_cointegration(ts)

            # NOTE: own_trades contains fills from the PREVIOUS tick, not current.
            # Cannot use to verify current-tick execution. Only use for PnL tracking.
            # 5. PnL по own_trades + adversarial fill recording
            for product, trades in state.own_trades.items():
                self.pnl.setdefault(product, 0.0)
                for trade in trades:
                    delta = -trade.quantity * trade.price
                    self.pnl[product] += delta
                    logger.log(ts, product, "TRADE", price=trade.price, qty=trade.quantity,
                               extra=f"pnl_delta={delta:.2f} pnl_total={self.pnl[product]:.2f}")
                    # adversarial fill recording (code 1)
                    if trade.buyer == "SUBMISSION":
                        record_fill(ext, product, "bid")
                    elif trade.seller == "SUBMISSION":
                        record_fill(ext, product, "ask")

            # 5b. [3.1] Saturation tracker — update per-strategy PnL deltas
            try:
                total_pnl_now = sum(self.pnl.values())
                for strat_name in ["basket_arb", "conversion_arb", "iv_arb", "bot_copy", "market_maker"]:
                    # Use per-strategy PnL delta if tracked; otherwise use total as proxy for active
                    pnl_delta = total_pnl_now - (self._pnl_history[-1] if self._pnl_history else 0.0) \
                                if strat_name == self._active_strategy else 0.0
                    sat_status = self._sat_tracker.update(strat_name, pnl_delta)
                active_sat = self._sat_tracker.status(self._active_strategy)
                ext["saturation"] = active_sat
                if active_sat == "SATURATED":
                    rec = self._sat_tracker.recommend_switch()
                    if rec and rec != self._active_strategy:
                        logger.log(ts, "ALL", "SAT_SWITCH",
                                   extra=f"from={self._active_strategy} to={rec} status={active_sat}")
                        self._active_strategy = rec
                elif active_sat != "HEALTHY":
                    logger.log(ts, "ALL", "SAT_STATUS", extra=f"strategy={self._active_strategy} status={active_sat}")
            except Exception:
                pass

            # 6. Listings — только первый тик
            if self.tick == 1:
                for symbol, listing in state.listings.items():
                    logger.log(ts, listing.symbol, "LISTED",
                               extra=f"denom={listing.denomination}")

            # 7. Observations
            obs = state.observations
            if obs:
                for product, value in obs.plainValueObservations.items():
                    logger.log(ts, product, "OBS", extra=f"value={value}")
                for product, conv in obs.conversionObservations.items():
                    _sun = getattr(conv, "sunlight", getattr(conv, "sunlightIndex", None))
                    _hum = getattr(conv, "humidity", None)
                    logger.log(ts, product, "CONV",
                               extra=f"bid={conv.bidPrice} ask={conv.askPrice} "
                                     f"transport={conv.transportFees} export={conv.exportTariff} "
                                     f"import={conv.importTariff} sun={_sun} hum={_hum}")

            # 8. Market trades
            for product, trades in state.market_trades.items():
                for trade in trades:
                    logger.log(ts, product, "MARKET", price=trade.price, qty=trade.quantity)

            # 8b. [T.2] Decision tree — log recommended action
            try:
                total_pnl = sum(self.pnl.values())
                self._pnl_history.append(total_pnl)  # deque(maxlen=50) auto-trims
                pnl_delta_50 = total_pnl - self._pnl_history[0] if len(self._pnl_history) >= 50 else 0.0
                # Pick regime from most liquid product
                primary_regime = ext.get("regime8", {}).get("RAINFOREST_RESIN", "NEUTRAL")
                r_int = {"NEUTRAL": 1, "TREND": 2, "TREND_BOT_GONE": 2,
                          "TREND_BOT_CHANGED": 2, "TREND_VOLUME_SPIKE": 2,
                          "MEAN_REVERT": 0, "MEAN_REVERT_BOT_GONE": 0,
                          "MEAN_REVERT_BOT_CHANGED": 0, "MEAN_REVERT_VOLUME_SPIKE": 0}.get(primary_regime, 1)
                any_position = max(abs(state.position.get(p, 0)) for p in state.order_depths) if state.order_depths else 0
                dt_result = decide({
                    "pnl_delta_50":    pnl_delta_50,
                    "position":        any_position,
                    "regime":          r_int,
                    "active_exploits": 0,
                    "tick":            self.tick,
                })
                ext["dt_action"] = dt_result["action"]
                logger.log(ts, "ALL", "DT", extra=f"action={dt_result['action']} priority={dt_result['priority']} owner={dt_result['owner']}")
            except Exception:
                pass

            # 9. Роутер по фазам
            phase  = self._phase()
            orders: Dict[str, List[Order]] = {}
            logger.log(ts, "ALL", "PHASE", extra=f"phase={phase} tick={self.tick}")

            # 9a. [§36] KillSwitch — аварийная остановка при PnL ниже порога
            try:
                # Mark-to-market PnL: cash_flow + position * mid_price
                total_pnl_ks = sum(self.pnl.values())
                for _ks_prod, _ks_pos in state.position.items():
                    if _ks_pos != 0:
                        _ks_od = state.order_depths.get(_ks_prod)
                        _ks_mid = self._mid(_ks_od) if _ks_od else None
                        if _ks_mid is not None:
                            total_pnl_ks += _ks_pos * _ks_mid
                # Realized vol estimate from price changes
                primary_prices = self.prices.get("RAINFOREST_RESIN", [])
                realized_vol = 0.0
                if len(primary_prices) >= 10:
                    returns = [primary_prices[i] / primary_prices[i-1] - 1.0
                               for i in range(-9, 0)]
                    realized_vol = (sum(r**2 for r in returns) / len(returns)) ** 0.5 * 100.0
                fair_value = primary_prices[-1] if primary_prices else 10000.0
                kill_active = kill_switch.update(self.tick, total_pnl_ks, realized_vol, fair_value)
                if kill_active:
                    logger.log(ts, "ALL", "KILL_SWITCH",
                               extra=f"ACTIVE reason={kill_switch.reason} pnl={total_pnl_ks:.1f}")
                    # KillSwitch active → close all positions, no new trades
                    for product in state.order_depths:
                        pos = state.position.get(product, 0)
                        if abs(pos) > 0:
                            od_ks = state.order_depths[product]
                            orders[product] = self._close_position(product, state)
                        else:
                            orders[product] = []
                    # Skip normal trading, go to output
                    traderData = dump_state(ext)
                    conversions = 0
                    logger.flush(state, orders, conversions, traderData)
                    return orders, conversions, traderData
            except Exception:
                pass

            # 9b. Module-level detectors — update each tick
            try:
                for product in state.order_depths:
                    od_det = state.order_depths[product]
                    ba_det = od_det.buy_orders
                    sa_det = od_det.sell_orders
                    if ba_det and sa_det:
                        quote_stuffing_detector.update(
                            len(ba_det) + len(sa_det), self.tick)
                        momentum_ignition_det.update(
                            max(ba_det.keys()) if ba_det else 0,
                            min(sa_det.keys()) if sa_det else 0,
                            self.tick)
            except Exception:
                pass

            for product in state.order_depths:
                timeout_guard.check()
                try:
                    # [13.1] DrawdownController gate — freeze instrument if drawdown exceeded
                    try:
                        self._drawdown_ctrl.update(self.pnl, sum(self.pnl.values()), self.tick)
                        dc_frozen = not self._drawdown_ctrl.can_trade(product)
                    except Exception:
                        dc_frozen = False
                    if dc_frozen:
                        orders[product] = []
                        logger.log(ts, product, "DC_FROZEN", extra=f"pnl={self.pnl.get(product,0):.2f}")
                        continue

                    # [§33] StopLossManager — time/vol/drawdown stops per product
                    try:
                        _pos_sl = state.position.get(product, 0)
                        _pnl_sl = self.pnl.get(product, 0.0)
                        _prices_sl = self.prices.get(product, [])
                        _vol_sl = 0.0
                        if len(_prices_sl) >= 10:
                            _rets = [_prices_sl[i] / _prices_sl[i-1] - 1.0
                                     for i in range(-9, 0) if _prices_sl[i-1] != 0]
                            _vol_sl = (sum(r**2 for r in _rets) / max(len(_rets), 1)) ** 0.5
                        if not stop_loss_manager.should_trade(
                                product, _pos_sl, self.tick, _pnl_sl, _vol_sl):
                            orders[product] = self._close_position(product, state) if _pos_sl != 0 else []
                            logger.log(ts, product, "STOP_LOSS",
                                       extra=f"pos={_pos_sl} pnl={_pnl_sl:.1f} vol={_vol_sl:.4f}")
                            continue
                        if _pos_sl != 0 and product not in stop_loss_manager._position_entry:
                            stop_loss_manager.record_entry(product, self.tick, _pnl_sl, _vol_sl)
                    except Exception:
                        pass

                    # [0.12] LimitCoordinator — pre-compute capacity for this product
                    try:
                        _pos_now = state.position.get(product, 0)
                        _lc_max_buy  = self._limit_coord.max_order_qty(product, "BUY",  _pos_now)
                        _lc_max_sell = self._limit_coord.max_order_qty(product, "SELL", _pos_now)
                        ext.setdefault("lc_capacity", {})[product] = {
                            "max_buy": _lc_max_buy, "max_sell": _lc_max_sell
                        }
                    except Exception:
                        pass

                    # [B.2] First-5-ticks edge case: observe only, no orders
                    # Bots post anomalous quotes at round start (no price history)
                    # Collect early prices for fair-value seeding instead
                    if self.tick <= 5:
                        orders[product] = []
                        ph_early = self.prices.get(product, [])
                        if ph_early:
                            ext.setdefault("early_fv", {})[product] = (
                                sum(ph_early) / len(ph_early)
                            )
                        continue  # skip all strategy logic for first 5 ticks

                    # [Algorithm 1] Capacity estimation before exploit entry
                    # Probe with 1-unit order at tick 6-10; measure fill rate
                    # If fill_rate < 0.5 → capacity is limited → cap order size
                    try:
                        if self.tick == 6:
                            ext.setdefault("capacity_probe", {})[product] = {
                                "probe_tick": self.tick, "probed": True,
                                "fill_count": 0, "probe_count": 1,
                            }
                        cap_probe = ext.get("capacity_probe", {}).get(product, {})
                        if cap_probe.get("probed") and self.tick <= cap_probe.get("probe_tick", 0) + 10:
                            fills = len([
                                t for t in state.own_trades.get(product, [])
                                if t.timestamp >= state.timestamp - 10000
                            ])
                            cap_probe["fill_count"] = fills
                            capacity_ratio = fills / max(cap_probe.get("probe_count", 1), 1)
                            ext.setdefault("capacity_ratio", {})[product] = capacity_ratio
                    except Exception:
                        pass

                    if phase == "WARMUP":
                        orders[product] = []

                    elif phase == "TRADING":
                        if product == "RAINFOREST_RESIN":
                            orders[product] = self.trade_resin(product, state, ext)
                        else:
                            # MW-based strategy routing (code 1)
                            orders[product] = self._trade_with_strategies(
                                product, state, ext)

                    elif phase in ("LIQUIDATE", "CLOSE"):
                        pos = state.position.get(product, 0)
                        if abs(pos) > 0:
                            orders[product] = self._close_position(product, state)
                            if phase == "CLOSE":
                                mid = self._mid(state.order_depths[product])
                                # settlement_pnl = position * (settlement_mid - avg_entry)
                                logger.log(ts, product, "SETTLEMENT",
                                           price=mid, qty=pos,
                                           extra=f"settlement_mid={mid}")
                        else:
                            orders[product] = []

                    # [0.12] LimitCoordinator post-clamp: remove orders that exceed capacity
                    try:
                        _cap = ext.get("lc_capacity", {}).get(product, {})
                        _max_b = _cap.get("max_buy",  9999)
                        _max_s = _cap.get("max_sell", 9999)
                        _net_buy = _net_sell = 0
                        _filtered: List[Order] = []
                        for o in orders.get(product, []):
                            if o.quantity > 0:
                                if _net_buy + o.quantity <= _max_b:
                                    _net_buy += o.quantity
                                    _filtered.append(o)
                            elif o.quantity < 0:
                                if _net_sell + abs(o.quantity) <= _max_s:
                                    _net_sell += abs(o.quantity)
                                    _filtered.append(o)
                        orders[product] = _filtered
                    except Exception:
                        pass

                except TickTimeout:
                    raise
                except Exception as e:
                    logger.log(ts, product, "ERROR", extra=str(e))
                    orders[product] = []

            # 9b. [Algorithm 2] Invariant check: position limits after order generation
            try:
                if self.tick % 50 == 0:
                    # [Algorithm 2, Layer 4] PnL consistency: sum(per_strategy) ≈ total
                    total_pnl_chk = sum(self.pnl.values())
                    sat_pnl = sum(
                        sum(self._sat_tracker._pnl_history.get(s, []) or [0])
                        for s in ["basket_arb", "market_maker"]
                    )

                for prod, ord_list in orders.items():
                    limit = POSITION_LIMITS.get(prod, 0)
                    pos   = state.position.get(prod, 0)
                    net_b = sum(o.quantity for o in ord_list if o.quantity > 0)
                    net_s = sum(abs(o.quantity) for o in ord_list if o.quantity < 0)
                    if net_b > limit - pos:
                        violation = f"INV_LIMIT_BUY {prod}: net_buy={net_b} avail={limit-pos}"
                        self._pipeline_violations.append(violation)
                        logger.log(ts, prod, "INV_VIOLATION", extra=violation)
                        # Auto-fix: trim buy orders
                        trimmed, remaining = [], limit - pos
                        for o in ord_list:
                            if o.quantity > 0:
                                actual = min(o.quantity, remaining)
                                if actual > 0:
                                    trimmed.append(Order(o.symbol, o.price, actual))
                                    remaining -= actual
                            else:
                                trimmed.append(o)
                        orders[prod] = trimmed
                    if net_s > limit + pos:
                        violation = f"INV_LIMIT_SELL {prod}: net_sell={net_s} avail={limit+pos}"
                        self._pipeline_violations.append(violation)
                        logger.log(ts, prod, "INV_VIOLATION", extra=violation)
                        # Auto-fix: trim sell orders (mirror of buy-side trim)
                        trimmed_s, remaining_s = [], limit + pos
                        for o in orders[prod]:
                            if o.quantity < 0:
                                actual_s = min(abs(o.quantity), remaining_s)
                                if actual_s > 0:
                                    trimmed_s.append(Order(o.symbol, o.price, -actual_s))
                                    remaining_s -= actual_s
                            else:
                                trimmed_s.append(o)
                        orders[prod] = trimmed_s
            except Exception:
                pass

            # 10. Key metrics каждые N тиков
            if self.tick % CONFIG["LOG_EVERY_N_TICKS"] == 0:
                for product in state.order_depths:
                    od_m       = state.order_depths[product]
                    pos        = state.position.get(product, 0)
                    mid_m      = self.prices.get(product, [None])[-1]
                    best_bid_m = self._best_bid(od_m)
                    best_ask_m = self._best_ask(od_m)
                    spread_m   = (best_ask_m - best_bid_m) if best_bid_m and best_ask_m else None
                    fv_m       = CONFIG.get(product, {}).get("fair_value")
                    pnl_m      = self.pnl.get(product, 0.0)
                    weight_m   = CONFIG.get(product, {}).get("strategy_weight", 1.0)
                    ema_val_m  = self.ema.get(product)
                    spec_m     = get_limit(product)
                    # extended metrics (code 1)
                    kf_x_m     = ext["kf"].get(product, {}).get("x")
                    toxic_m    = is_toxic_flow(ext, product)
                    weights_m  = get_strategy_weights(ext, product)
                    logger.log(ts, product, "METRICS",
                               extra=f"pos={pos} mid={mid_m} "
                                     f"ema={f'{ema_val_m:.2f}' if ema_val_m else 'None'} "
                                     f"kf_x={f'{kf_x_m:.2f}' if kf_x_m else 'None'} "
                                     f"spread={spread_m} fv={fv_m} pnl={pnl_m:.2f} weight={weight_m} "
                                     f"soft={spec_m.soft} hard={spec_m.hard} "
                                     f"toxic={toxic_m} mw={weights_m}")

            # Сброс adversarial счётчиков каждые 500 тиков
            if self.tick % 500 == 0:
                for p in PRODUCTS:
                    if p in state.order_depths:
                        reset_adv_counters(ext, p)

        except TickTimeout:
            logger.log(ts, "ALL", "TIMEOUT",
                       extra=f"tick={self.tick} exceeded {CONFIG['TICK_TIMEOUT_MS']}ms")
            orders = {p: [] for p in state.order_depths}

        finally:
            timeout_guard.cancel()

        # 11. Сохранить traderData — синхронизировать ext и сохранить через dump_state
        ext["pnl"]               = self.pnl
        ext["ema"]               = self.ema
        ext["calibrated_params"] = self.calibrated_params
        ext["tick"]              = self.tick
        for p, v in self.prices.items():
            ext["prices"][p] = v

        traderData = dump_state(ext)

        # conversions: >0 = импорт, <0 = экспорт (Round 3–4)
        conversions = 0

        # 12. Профилирование
        if self.profiling:
            self.profiler.disable()
            self.profiling = False
            s  = io.StringIO()
            ps = pstats.Stats(self.profiler, stream=s).sort_stats("cumulative")
            ps.print_stats(5)
            logger.log(ts, "ALL", "PROFILE",
                       extra=s.getvalue().replace("\n", " ")[:300])
            self.profiler.clear()

        logger.flush(state, orders, conversions, traderData)
        return orders, conversions, traderData

    # ─── MW-BASED STRATEGY ROUTING ────────────────────────────────────────────

    def _trade_with_strategies(self, product: str, state: TradingState,
                                ext: dict) -> List[Order]:
        """
        Multiplicative-weights based strategy routing для non-RESIN продуктов.
        Интегрирует: circuit breakers, adversarial flow detection,
        bot fingerprinting, MW weight scaling, PositionManager clamping.
        """
        ts       = state.timestamp
        od       = state.order_depths.get(product)
        if od is None:
            return []
        position = state.position.get(product, 0)
        mp       = self._mid(od)
        if mp is None:
            return []

        toxic    = is_toxic_flow(ext, product)
        bot_flag = detect_bot_pattern(ext, product)
        if toxic:
            logger.log(ts, product, "TOXIC_FLOW", extra="skipping all strategies")
            return []
        if bot_flag:
            logger.log(ts, product, "BOT_DETECTED", extra="bot pattern active")

        weights    = get_strategy_weights(ext, product)
        all_orders: List[Order] = []
        prices_buf = ext["prices"].get(product, [])
        prev_mid   = prices_buf[-2] if len(prices_buf) >= 2 else mp
        actual_delta = mp - prev_mid
        pm = PositionManager(product, state, ts)  # one instance per product per tick

        # [§31] Volatility targeting: scale order size by current vol
        current_vol = 0.0
        if len(prices_buf) >= 10:
            _rets = [prices_buf[i] / prices_buf[i-1] - 1.0
                     for i in range(-min(9, len(prices_buf)-1), 0)]
            if _rets:
                current_vol = (sum(r**2 for r in _rets) / len(_rets)) ** 0.5
        base_order_size = CONFIG.get(product, {}).get("order_size", 8)
        vol_adjusted_size = vol_targeter.vol_based_size(base_order_size, current_vol)

        # [§30] TargetPositionTracker: inventory risk = deviation from target=0
        inv_risk = target_tracker.inventory_risk(product, position)

        for sname, sfunc in STRATEGIES.items():
            if check_circuit_breaker(ext, product, sname, self.tick):
                continue
            if toxic and sname == "mm":
                continue
            w    = weights.get(sname, 1.0 / len(STRATEGIES))
            ords = sfunc(product, od, ext, position, self.tick)
            # PnL + MW update per strategy
            strat_pnl = actual_delta * position * w
            update_strategy_pnl(ext, product, sname, strat_pnl)
            loss = -strat_pnl / (abs(strat_pnl) + 1e-8)
            loss = max(-MW_LOSS_CLIP, min(MW_LOSS_CLIP, loss))  # clip before MW update
            update_mw(ext, product, sname, loss)
            # Scale by weight, clamp via PositionManager (pending-aware)
            # [§31] Apply vol-based sizing + OrderSizer.clip_order
            for o in ords:
                raw_qty = o.quantity
                # Vol-adjusted scaling
                vol_ratio = vol_adjusted_size / max(1, base_order_size)
                scaled = max(1, int(abs(raw_qty) * w * vol_ratio))
                scaled = scaled if raw_qty > 0 else -scaled
                # [§30] Clip to max_order_size per tick
                scaled = order_sizer.clip_order(
                    scaled, product, position, POSITION_LIMITS,
                    max_order_size=vol_adjusted_size)
                clamped = pm.clamp(scaled)
                if clamped != 0:
                    all_orders.append(Order(product, o.price, clamped))

        return all_orders

    # ─── КАЛИБРОВКА ───────────────────────────────────────────────────────────

    def _walk_forward_validate(self, product: str, params: dict) -> bool:
        """
        Walk-forward validation: test params on held-out recent window.
        [Algorithm 5 / capacity estimation]: before scaling up strategy,
        verify it has positive PnL on the LAST 20 ticks (not training window).
        Returns True if params pass validation.
        """
        prices = self.prices.get(product, [])
        if len(prices) < 40:
            return True  # not enough data — allow by default
        # Split: train = first 20, test = last 20
        train = prices[-40:-20]
        test  = prices[-20:]
        # Simple validation: spread param should yield positive MM PnL on test
        spread = params.get("spread", 2)
        mean_train = sum(train) / len(train)
        pnl_estimate = 0.0
        for i in range(1, len(test)):
            delta = test[i] - test[i - 1]
            # MM: buy at mean-spread, sell at mean+spread
            # If price reverts to mean within 1 tick → PnL += spread
            if abs(test[i - 1] - mean_train) > spread:
                # Out of range: MM gets filled → expect reversion
                if abs(delta) <= spread:
                    pnl_estimate += spread * 0.5  # partial credit
        return pnl_estimate >= 0  # positive expected PnL

    def _calibrate_params(self, state: TradingState, ts: int):
        try:
            from scipy.optimize import minimize_scalar
            import numpy as np
            for product in self.prices:
                prices = self.prices[product]
                n = len(prices)
                if n < 10:
                    continue
                if n < 100:
                    arr  = np.array(prices[-n:])
                    vol  = float(np.std(arr))
                    mean = float(np.mean(arr))
                else:
                    vol  = 0.0
                    mean = self.ema.get(product, prices[-1])
                def spread_cost(s, v=vol):
                    return abs(v - s) + 0.1 * s
                result         = minimize_scalar(spread_cost, bounds=(1, 10), method="bounded")
                optimal_spread = round(result.x)
                if product in CONFIG and "spread" in CONFIG[product]:
                    candidate = {"spread": optimal_spread, "vol": vol, "mean": mean}
                    # Walk-forward validation: only apply if test window is positive
                    wf_ok = self._walk_forward_validate(product, candidate)
                    if wf_ok:
                        self.calibrated_params[product] = candidate
                    logger.log(ts, product, "CALIBRATE",
                               extra=f"spread={optimal_spread} vol={vol:.2f} mean={mean:.2f} n={n} wf_ok={wf_ok}")
        except Exception as e:
            logger.log(ts, "ALL", "CALIBRATE_ERROR", extra=str(e))

    def _run_cointegration(self, ts: int):
        try:
            from statsmodels.tsa.stattools import coint
            import numpy as np
            products = [p for p in self.prices if len(self.prices[p]) >= 100]
            if len(products) < 2:
                return
            for i in range(len(products)):
                for j in range(i + 1, len(products)):
                    p1, p2 = products[i], products[j]
                    n    = min(len(self.prices[p1]), len(self.prices[p2]), 100)
                    arr1 = np.array(self.prices[p1][-n:])
                    arr2 = np.array(self.prices[p2][-n:])
                    score, pvalue, _ = coint(arr1, arr2)
                    self.coint_result[f"{p1}_{p2}"] = {
                        "score": float(score), "pvalue": float(pvalue),
                        "cointegrated": pvalue < 0.05,
                    }
                    logger.log(ts, f"{p1}_{p2}", "COINT",
                               extra=f"score={score:.2f} pvalue={pvalue:.4f} "
                                     f"cointegrated={pvalue < 0.05}")
        except Exception as e:
            logger.log(ts, "ALL", "COINT_ERROR", extra=str(e))

    # ─── ХЕЛПЕРЫ ──────────────────────────────────────────────────────────────

    def _phase(self) -> str:
        t = self.tick
        if t < CONFIG["WARMUP_TICKS"]:      return "WARMUP"
        if t >= CONFIG["CLOSE_TICK"]:        return "CLOSE"
        if t >= CONFIG["LIQUIDATION_TICK"]:  return "LIQUIDATE"
        if t >= CONFIG["PHASE_EXIT_START"]:  return "EXIT_TO_ZERO"
        if t >= CONFIG["PHASE_REDUCE_START"]: return "REDUCE"
        return "TRADING"

    def size_fraction(self) -> float:
        """Returns a position-sizing multiplier (0.0–1.0) based on current tick."""
        t = self.tick
        if t < 100:  return 0.25
        if t < 200:  return 0.5
        if t < 800:  return 1.0
        if t < 950:  return 0.5
        return 0.0

    def _mid(self, od: OrderDepth) -> Optional[float]:
        has_bids = bool(od.buy_orders)
        has_asks = bool(od.sell_orders)
        if not has_bids and not has_asks:
            return None
        if has_bids and has_asks:
            return (max(od.buy_orders) + min(od.sell_orders)) / 2.0
        if has_bids:
            return float(max(od.buy_orders))  # one-sided: use best bid
        return float(min(od.sell_orders))     # one-sided: use best ask

    def _best_bid(self, od: OrderDepth) -> Optional[int]:
        return max(od.buy_orders) if od.buy_orders else None  # O(n) vs sorted O(n log n)

    def _best_ask(self, od: OrderDepth) -> Optional[int]:
        return min(od.sell_orders) if od.sell_orders else None  # O(n) vs sorted O(n log n)

    # обратная совместимость
    def get_mid_price(self, od): return self._mid(od)
    def get_best_bid(self, od):  return self._best_bid(od)
    def get_best_ask(self, od):  return self._best_ask(od)
    def get_position(self, state, product): return state.position.get(product, 0)
    def get_round_phase(self): return self._phase()

    def clamp_order(self, product: str, quantity: int, state: TradingState) -> int:
        """Обёртка для совместимости. Не учитывает pending — использовать PositionManager напрямую."""
        return PositionManager(product, state, state.timestamp).clamp(quantity)

    def _close_position(self, product: str, state: TradingState) -> List[Order]:
        """
        Закрывает позицию линейно по расписанию.
        LIQUIDATE: пассивно (bid-1 / ask+1) — равномерно за оставшиеся тики до CLOSE_TICK
        CLOSE:     агрессивно (bid / ask)   — весь остаток сразу
        """
        od  = state.order_depths[product]
        pos = state.position.get(product, 0)
        if pos == 0:
            return []

        phase     = self._phase()
        at_market = (phase == "CLOSE")

        # линейное расписание закрытия
        if at_market:
            rate = abs(pos)
        else:
            ticks_left = max(1, CONFIG["CLOSE_TICK"] - self.tick)
            # liquidation_urgency: 1.0 at LIQUIDATION_TICK, grows to 3.0 at CLOSE_TICK
            liq_span = max(1, CONFIG["CLOSE_TICK"] - CONFIG["LIQUIDATION_TICK"])
            elapsed  = max(0, self.tick - CONFIG["LIQUIDATION_TICK"])
            liquidation_urgency = 1.0 + 2.0 * (elapsed / liq_span)
            rate = math.ceil(abs(pos) / ticks_left * liquidation_urgency)

        best_bid = self._best_bid(od)
        best_ask = self._best_ask(od)

        if pos > 0:
            if best_bid is None:
                return []
            price = best_bid if at_market else best_bid - 1
            qty   = PositionManager(product, state, state.timestamp).clamp(-rate)
        else:
            if best_ask is None:
                return []
            price = best_ask if at_market else best_ask + 1
            qty   = PositionManager(product, state, state.timestamp).clamp(rate)

        if qty == 0:
            return []

        action = ("CLOSE_SELL" if pos > 0 else "CLOSE_BUY")
        logger.log(state.timestamp, product, action,
                   price=price, qty=qty,
                   extra=f"phase={phase} rate={rate} pos={pos}")
        return [Order(product, int(price), qty)]

    # ─── СТРАТЕГИИ ────────────────────────────────────────────────────────────

    def trade_resin(self, product: str, state: TradingState,
                    ext: dict = None) -> List[Order]:
        """
        Маркет-мейкинг RAINFOREST_RESIN.
        PositionManager: soft/hard лимит, pending-aware, skew.
        FeeAwareQuoter:  spread с учётом fee, min_edge.
        Интегрировано: circuit breaker, toxic flow, bot detection, Kalman signal.
        """
        ts  = state.timestamp
        od  = state.order_depths[product]
        mid = self._mid(od)
        if mid is None:
            return []

        # Circuit breaker (code 1)
        if ext is not None and check_circuit_breaker(ext, product, "mm", self.tick):
            logger.log(ts, product, "CB_SKIP", extra="mm circuit breaker active")
            return []

        # Toxic flow (code 1)
        if ext is not None and is_toxic_flow(ext, product):
            logger.log(ts, product, "TOXIC_SKIP", extra="toxic flow, skipping mm")
            return []

        # Bot pattern detection — log only (code 1)
        if ext is not None and detect_bot_pattern(ext, product):
            logger.log(ts, product, "BOT_PATTERN", extra="bot pattern active")

        cal            = self.calibrated_params.get(product, {})
        desired_spread = cal.get("spread", CONFIG[product]["spread"])
        base_size      = CONFIG[product]["order_size"]
        fv             = CONFIG[product]["fair_value"]
        weight         = CONFIG[product]["strategy_weight"]
        skew_factor    = CONFIG[product]["skew_factor"]

        if weight == 0:
            logger.log(ts, product, "SKIP", extra="weight=0")
            return []

        # Kalman FV как дополнительный сигнал (code 1) — log only, static fv используется
        if ext is not None:
            kf_x = ext["kf"].get(product, {}).get("x")
            if kf_x is not None:
                logger.log(ts, product, "KF_SIGNAL",
                           extra=f"kf_fv={kf_x:.2f} static_fv={fv}")

        ema    = self.ema.get(product, mid)
        signal = ema - fv
        logger.log(ts, product, "SIGNAL",
                   extra=f"mid={mid} ema={ema:.2f} fv={fv} signal={signal:.2f} weight={weight}")

        pm = PositionManager(product, state, ts)
        logger.log(ts, product, "POSITION_STATE",
                   extra=f"pos={pm.position} soft=±{pm.spec.soft} hard=±{pm.spec.hard} "
                         f"avail_buy={pm.soft_available_buy} avail_sell={pm.soft_available_sell} "
                         f"headroom={pm.headroom_pct:.0%}")

        bid_size, ask_size = pm.skew_size(base_size, skew_factor)

        # TODO(Round 3+): оптимальный размер через argmax(net_expected_return)
        #
        #   ШАГ 0 — добавить в __init__:
        #     self.sentiment_history: Dict[str, List[float]] = {}
        #     # накапливать каждый тик:
        #     # val = obs.plainValueObservations.get("SENTIMENT") if obs else None
        #     # if val is not None:
        #     #     self.sentiment_history.setdefault(product, []).append(val)
        #     #     if len(self.sentiment_history[product]) > CONFIG["PRICE_HISTORY_MAX"]:
        #     #         self.sentiment_history[product] = self.sentiment_history[product][-CONFIG["PRICE_HISTORY_MAX"]:]
        #
        #   ШАГ 1 — expected_price_change:
        #     vol  = self.calibrated_params.get(product, {}).get("vol", 0)
        #     obs  = state.observations
        #     conv = obs.conversionObservations.get(product) if obs else None
        #     # вариант А: sentiment = obs.plainValueObservations.get("SENTIMENT", 0) if obs else 0
        #     # вариант Б: sentiment = (conv.sunlight - 50) / 50 if conv else 0  (MACARONS R4)
        #     sentiment = 0  # ← заменить на реальный источник
        #     expected_price_change = sentiment * vol
        #
        #   ШАГ 2+3 — argmax(net_expected_return) раздельно для buy и sell:
        #     # buy профитит от роста, sell — от падения (разный знак!)
        #     net_ret_buy  = lambda s: s *   expected_price_change  - quoter.fee_total(int(mid), s)
        #     net_ret_sell = lambda s: s * (-expected_price_change) - quoter.fee_total(int(mid), s)
        #     if pm.soft_available_buy > 0:
        #         cands    = range(1, pm.soft_available_buy + 1)
        #         opt      = max(cands, key=net_ret_buy)
        #         bid_size = opt if net_ret_buy(opt) > 0 else 0
        #     if pm.soft_available_sell > 0:
        #         cands    = range(1, pm.soft_available_sell + 1)
        #         opt      = max(cands, key=net_ret_sell)
        #         ask_size = opt if net_ret_sell(opt) > 0 else 0
        #
        #   ШАГ 4 — resize если новость слабее ожидаемой:
        #     # сохранять в _calibrate_params:
        #     #   hist = self.sentiment_history.get(product, [])
        #     #   if hist: self.calibrated_params[product]["sentiment_mean"] = float(np.mean(hist[-100:]))
        #     exp_sent = self.calibrated_params.get(product, {}).get("sentiment_mean", 0)
        #     if exp_sent != 0 and abs(sentiment) < abs(exp_sent) * 0.5:
        #         bid_size //= 2
        #         ask_size //= 2
        #         logger.log(ts, product, "RESIZE_WEAK_SIGNAL",
        #                    extra=f"sentiment={sentiment:.3f} expected={exp_sent:.3f}")

        quoter       = FeeAwareQuoter(product)
        result       = quoter.quote(fv=fv, mid=mid, desired_spread=desired_spread,
                                    bid_qty=bid_size, ask_qty=ask_size, ts=ts)
        raw_orders   = quoter.to_orders(product, result)
        final_orders = pm.clamp_orders(raw_orders)

        for order in final_orders:
            direction = "BID" if order.quantity > 0 else "ASK"
            logger.log(ts, product, f"SUBMIT_{direction}",
                       price=order.price, qty=order.quantity,
                       extra=f"net_edge_bid={result.bid_net_edge:.3f} "
                             f"net_edge_ask={result.ask_net_edge:.3f} "
                             f"spread={result.spread_used} min_spread={result.min_spread} "
                             f"fv={fv} signal={signal:.2f}")

        # Strategy PnL + MW update (code 1)
        if ext is not None and final_orders:
            prices_buf = ext["prices"].get(product, [])
            prev_mid_  = prices_buf[-2] if len(prices_buf) >= 2 else mid
            actual_d   = mid - prev_mid_
            strat_pnl  = actual_d * pm.position
            update_strategy_pnl(ext, product, "mm", strat_pnl)
            loss = -strat_pnl / (abs(strat_pnl) + 1e-8)
            update_mw(ext, product, "mm", loss)

        return final_orders

