class RoundType(Enum):
    R1_SIMPLE       = 1   # простые продукты / лотерея
    R2_BASKET       = 2   # корзины / корреляционные
    R3_OPTIONS      = 3   # опционы — критичный
    R4_INSIDER      = 4   # инсайдеры / внешние данные
    R5_NEWS         = 5   # новости / portfolio construction

class ManualScenario(Enum):
    LOTTERY         = "lottery"
    NEWS            = "news"
    NASH            = "nash"
    PORTFOLIO       = "portfolio"


