@dataclass
class RoundContext:
    """Контекст текущего раунда — хранит всё необходимое для принятия решений."""
    round_type: RoundType
    tick:       int   = 0
    conditions_read: bool = False   # §42: читать условия первые 10 минут
    manual_pnl_pct:  float = 0.0   # §42: manual даёт 20-30% PnL

    # §42: чек что условия прочитаны до любого кода
    def assert_conditions_read(self):
        if not self.conditions_read:
            raise RuntimeError(
                "§42: СТОП. Читать условия раунда первые 10 минут "
                "перед любым кодом / любой торговлей.")

    def mark_conditions_read(self):
        self.conditions_read = True
        print(f"✅ §42: Условия раунда {self.round_type.name} прочитаны.")


class RoundRouter:
    """
    §42 / §10.1 — Round-by-round framework.
    Определяет тип раунда, сценарий manual и рекомендованные действия.
    """

    ROUND_GUIDE = {
        RoundType.R1_SIMPLE: {
            "description": "Простые продукты — читать условия, искать hardcoded паттерн",
            "manual_scenario": ManualScenario.LOTTERY,
            "manual_tip": "Часто лотерея или простая логика — решить аналитически",
            "algo_focus": "hardcoded_pattern",
        },
        RoundType.R2_BASKET: {
            "description": "Корзины или корреляционные продукты",
            "manual_scenario": ManualScenario.PORTFOLIO,
            "manual_tip": "Выбрать правильное соотношение компонент",
            "algo_focus": "correlation_spread",
        },
        RoundType.R3_OPTIONS: {
            "description": "Опционы — критичный раунд. BS + delta hedge must have",
            "manual_scenario": ManualScenario.PORTFOLIO,
            "manual_tip": "Оценить стратегию: купить vol или продать",
            "algo_focus": "black_scholes_delta_hedge",
        },
        RoundType.R4_INSIDER: {
            "description": "Инсайдеры или внешние данные",
            "manual_scenario": ManualScenario.NEWS,
            "manual_tip": "Интерпретировать внешний сигнал правильно",
            "algo_focus": "signal_interpretation",
        },
        RoundType.R5_NEWS: {
            "description": "Новости и portfolio construction",
            "manual_scenario": ManualScenario.NEWS,
            "manual_tip": (
                "Читать газету, размечать sentiment. "
                "Концентрировать в топ-2 сигнала. Fee-aware sizing."
            ),
            "algo_focus": "sentiment_markowitz",
        },
    }

    @classmethod
    def get_briefing(cls, round_type: RoundType) -> dict:
        """Возвращает полный briefing по раунду."""
        guide = cls.ROUND_GUIDE[round_type]
        return {
            "round": round_type.name,
            "description": guide["description"],
            "manual_scenario": guide["manual_scenario"].value,
            "manual_tip": guide["manual_tip"],
            "algo_focus": guide["algo_focus"],
            "universal_rules": [
                "Читать условия ПЕРВЫЕ 10 минут перед любым кодом",   # §42
                "Manual может давать 20–30% PnL — не игнорировать",   # §42
                "Решить manual аналитически до начала торговли",       # §42
            ],
        }

    @classmethod
    def print_briefing(cls, round_type: RoundType):
        b = cls.get_briefing(round_type)
        print(f"\n{'='*60}")
        print(f"РАУНД: {b['round']}  |  {b['description']}")
        print(f"Manual: {b['manual_tip']}")
        print(f"Algo focus: {b['algo_focus']}")
        print("Universal rules:")
        for r in b["universal_rules"]:
            print(f"  • {r}")
        print(f"{'='*60}\n")


# ─────────────────────────────────────────────────────────────────────────────
# §43  SENTIMENT FRAMEWORK
# ─────────────────────────────────────────────────────────────────────────────

@dataclass
class SentimentSignal:
    """Один sentiment сигнал по активу."""
    asset:      str
    score:      int    # -2, -1, 0, +1, +2
    tick:       int    # тик получения
    source:     str    = ""
    is_specific: bool  = True  # конкретные числа > общие формулировки


class SentimentEngine:
    """
    §43 — Полный sentiment framework.
    +2: очень позитивно → 100% лимита
    +1: умеренно → 50%
     0: не торговать
    -1: умеренно → 50%
    -2: очень негативно → 100% лимита
    """

    # §43: таблица sentiment → fraction of limit
    SIZE_TABLE = {2: 1.0, 1: 0.5, 0: 0.0, -1: 0.5, -2: 1.0}

    # §43: cap на суммарный sentiment
    SENTIMENT_CAP = 2

    def __init__(self, signal_decay_ticks: int = 500):
        """signal_decay_ticks: §43 старая новость (>N тиков) снижает вес."""
        self.signals: dict[str, list[SentimentSignal]] = {}
        self.decay_ticks = signal_decay_ticks

    def add_signal(self, asset: str, score: int, tick: int,
                   source: str = "", is_specific: bool = True):
        """
        §43: Добавить сигнал.
        market-moving: конкретные числа и события > общие формулировки.
        """
        score = int(np.clip(score, -2, 2))
        if not is_specific:
            # §43: шум — ослабляем сигнал
            score = int(np.sign(score) * max(abs(score) - 1, 0))
        sig = SentimentSignal(asset, score, tick, source, is_specific)
        if asset not in self.signals:
            self.signals[asset] = []
        self.signals[asset].append(sig)

    def _decay_weight(self, signal: SentimentSignal, current_tick: int) -> float:
        """§43: decay сигнала — старая новость снижает вес."""
        age = current_tick - signal.tick
        if age <= 0:
            return 1.0
        if age > self.decay_ticks:
            return 0.5  # существенно снижаем, но не обнуляем
        return 1.0 - 0.5 * (age / self.decay_ticks)

    def get_combined_sentiment(self, asset: str, current_tick: int) -> dict:
        """
        §43: Суммировать sentiment с cap ±2.
        Противоречивые новости: брать последнюю или обнулять.
        """
        if asset not in self.signals or not self.signals[asset]:
            return {"asset": asset, "sentiment": 0, "size_fraction": 0.0,
                    "signals_count": 0, "action": "no_trade"}

        sigs = self.signals[asset]

        # §43: противоречивые новости — проверяем последние два
        if len(sigs) >= 2:
            last  = sigs[-1]
            prev  = sigs[-2]
            if np.sign(last.score) != np.sign(prev.score) and \
               last.score != 0 and prev.score != 0:
                # Противоречие: берём последнюю
                effective_score = int(np.clip(last.score, -2, 2))
                note = "contradicting_news: using latest"
            else:
                # Суммируем с decay и cap
                raw = sum(
                    s.score * self._decay_weight(s, current_tick)
                    for s in sigs
                )
                effective_score = int(np.clip(round(raw), -2, 2))
                note = f"summed_{len(sigs)}_signals"
        else:
            raw = sigs[-1].score * self._decay_weight(sigs[-1], current_tick)
            effective_score = int(np.clip(round(raw), -2, 2))
            note = "single_signal"

        size_fraction = self.SIZE_TABLE.get(abs(effective_score), 0.0)
        direction     = "long" if effective_score > 0 else ("short" if effective_score < 0 else "flat")

        return {
            "asset":         asset,
            "sentiment":     effective_score,
            "size_fraction": size_fraction,
            "direction":     direction,
            "action":        "trade" if effective_score != 0 else "no_trade",
            "signals_count": len(sigs),
            "note":          note,
        }

    def get_position_size(self, asset: str, max_position: float,
                          current_tick: int) -> float:
        """§43: position = size_fraction × max_position × sign(sentiment)."""
        s = self.get_combined_sentiment(asset, current_tick)
        signed = s["size_fraction"] * (1 if s["direction"] == "long"
                                       else -1 if s["direction"] == "short" else 0)
        return signed * max_position

    def update_on_new_signal(self, asset: str, new_score: int,
                             tick: int, max_position: float) -> dict:
        """
        §43: Обновлять позицию при появлении новой противоречащей новости.
        Возвращает: нужно ли корректировать позицию и на сколько.
        """
        old = self.get_combined_sentiment(asset, tick)
        self.add_signal(asset, new_score, tick, source="update")
        new = self.get_combined_sentiment(asset, tick)
        changed = old["sentiment"] != new["sentiment"]
        return {
            "asset":          asset,
            "old_sentiment":  old["sentiment"],
            "new_sentiment":  new["sentiment"],
            "position_change": changed,
            "new_size":       self.get_position_size(asset, max_position, tick),
            "action":         "update_position" if changed else "hold",
        }

    def top_n_assets(self, current_tick: int, n: int = 2) -> list[dict]:
        """
        §44/§48: Концентрировать в топ-N сигналах.
        Round 5: топ-2, не диверсифицировать.
        """
        results = [
            self.get_combined_sentiment(a, current_tick)
            for a in self.signals
        ]
        # Сортируем по |sentiment| убывающий
        ranked = sorted(results, key=lambda x: abs(x["sentiment"]), reverse=True)
        return ranked[:n]

    def fee_aware_sizing(self, asset: str, max_position: float,
                         fee_per_unit: float, expected_move: float,
                         current_tick: int) -> dict:
        """
        §42/§48: fee-aware sizing — проверяем что PnL > комиссии.
        """
        raw_size = abs(self.get_position_size(asset, max_position, current_tick))
        gross_pnl = raw_size * expected_move
        fee_total = raw_size * fee_per_unit * 2  # вход + выход
        net_pnl   = gross_pnl - fee_total
        # Уменьшаем до порога рентабельности
        if net_pnl <= 0 and raw_size > 0:
            min_size = fee_total / (expected_move + 1e-9)
            adjusted = max(0.0, min_size)
        else:
            adjusted = raw_size
        return {
            "asset":        asset,
            "raw_size":     raw_size,
            "adjusted_size": adjusted,
            "gross_pnl":    gross_pnl,
            "fee_total":    fee_total,
            "net_pnl":      net_pnl,
            "worth_trading": net_pnl > 0,
        }


# ─────────────────────────────────────────────────────────────────────────────
# §44 / §10.2  НОВОСТИ FRAMEWORK
# ─────────────────────────────────────────────────────────────────────────────

@dataclass
class NewsArticle:
    """Одна статья из газеты."""
    text:          str
    asset:         str
    tick_received: int
    cross_assets:  list[str] = field(default_factory=list)  # §44 cross-asset effect


class NewsFramework:
    """
    §44 / §10.2 — News framework.
    Газета выходит раз в N тиков (обычно 1 раз за раунд).
    Читать немедленно и размечать каждую статью.
    """

    def __init__(self, sentiment_engine: SentimentEngine,
                 news_interval_ticks: int = 1000):
        self.engine = sentiment_engine
        self.news_interval = news_interval_ticks   # §44: раз в N тиков
        self.articles: list[NewsArticle] = []
        self.last_news_tick: int = -1

    def receive_newspaper(self, articles: list[NewsArticle], current_tick: int):
        """
        §44: Читать немедленно и размечать каждую статью.
        Один продукт = одна статья = одна оценка sentiment.
        """
        self.last_news_tick = current_tick
        self.articles.extend(articles)
        signals_generated = []
        for article in articles:
            # Определяем sentiment по ключевым словам (simplified scorer)
            score, is_specific = self._score_article(article.text)
            # Основной актив
            self.engine.add_signal(
                article.asset, score, current_tick,
                source="news", is_specific=is_specific
            )
            signals_generated.append({
                "asset": article.asset, "score": score,
                "is_specific": is_specific
            })
            # §44: cross-asset эффект
            cross_score = int(np.sign(score) * max(abs(score) - 1, 0))
            for ca in article.cross_assets:
                if cross_score != 0:
                    self.engine.add_signal(
                        ca, cross_score, current_tick,
                        source="cross_asset_news", is_specific=False
                    )
                    signals_generated.append({
                        "asset": ca, "score": cross_score,
                        "is_specific": False, "note": "cross_asset"
                    })
        return signals_generated

    @staticmethod
    def _score_article(text: str) -> tuple[int, bool]:
        """
        §43/§44: Оценка статьи.
        Конкретные числа и события → market-moving (is_specific=True).
        Общие формулировки → шум (is_specific=False).
        """
        text_lower = text.lower()
        # Признаки конкретности: числа, %, конкретные события
        import re
        has_numbers = bool(re.search(r'\d+\.?\d*\s*(%|млн|млрд|$|usd|eur)', text_lower))
        specific_keywords = ["прибыль", "выручка", "производство", "отчёт",
                             "прогноз", "повысили", "снизили", "контракт",
                             "банкротство", "слияние", "дивиденды", "рост на",
                             "упал на", "превысил", "ниже ожиданий"]
        noise_keywords    = ["возможно", "ожидается", "по мнению", "эксперты считают",
                             "некоторые", "может быть", "вероятно"]
        is_specific = has_numbers or any(k in text_lower for k in specific_keywords)
        is_noise    = any(k in text_lower for k in noise_keywords) and not is_specific

        # Positive/negative keywords
        pos_strong = ["рекордная прибыль", "превысил ожидания", "резкий рост",
                      "сильный рост", "двузначный рост", "исторический максимум"]
        pos_mild   = ["небольшой рост", "позитивные", "улучшение", "выросла"]
        neg_strong = ["банкротство", "резкое падение", "крупные убытки",
                      "ниже ожиданий", "серьёзные потери"]
        neg_mild   = ["небольшое снижение", "умеренные потери", "упала", "снизилась"]

        score = 0
        if any(k in text_lower for k in pos_strong): score = 2
        elif any(k in text_lower for k in pos_mild):  score = 1
        elif any(k in text_lower for k in neg_strong): score = -2
        elif any(k in text_lower for k in neg_mild):   score = -1

        if is_noise:
            score = int(np.sign(score) * max(abs(score) - 1, 0))

        return score, is_specific

    def should_enter_now(self, current_tick: int) -> bool:
        """§43: Входить сразу после прочтения."""
        return current_tick == self.last_news_tick

    def should_hold(self, asset: str, current_tick: int) -> bool:
        """§43: Держать до конца раунда если нет противоречащей новости."""
        if asset not in self.engine.signals:
            return False
        sigs = self.engine.signals[asset]
        if len(sigs) < 2:
            return True
        last, prev = sigs[-1], sigs[-2]
        contradicting = (np.sign(last.score) != np.sign(prev.score)
                         and last.score != 0 and prev.score != 0)
        return not contradicting

    def do_not_average_down(self, asset: str, entry_price: float,
                            current_price: float, position: float) -> dict:
        """§43: Не усредняться против убыточной позиции."""
        if position == 0:
            return {"action": "no_position"}
        is_long  = position > 0
        is_short = position < 0
        is_losing = (is_long and current_price < entry_price) or \
                    (is_short and current_price > entry_price)
        return {
            "asset":            asset,
            "is_losing":        is_losing,
            "action":           "DO_NOT_ADD" if is_losing else "can_add",
            "rule":             "§43: не усредняться против убыточной позиции",
        }


# ─────────────────────────────────────────────────────────────────────────────
# §45 / §10.3  ОШИБКИ MANUAL TRADING — GUARD SYSTEM
# ─────────────────────────────────────────────────────────────────────────────

class ManualErrorGuard:
    """
    §45 — Система защиты от ошибок manual trading.
    Все проверки перед каждым действием.
    """

    MAX_SIMULTANEOUS_POSITIONS = 4    # §45: максимум 3-4

    def __init__(self):
        self.open_positions:  dict[str, dict] = {}
        self.entry_prices:    dict[str, float] = {}
        self.entry_ticks:     dict[str, int]   = {}

    def check_diversification(self, new_asset: str) -> dict:
        """
        §45: Диверсификация в 5+ позиций:
        PnL каждой мал, комиссии не компенсируются.
        """
        current_count = len(self.open_positions)
        if current_count >= self.MAX_SIMULTANEOUS_POSITIONS:
            return {
                "allowed":  False,
                "reason":   f"§45: СТОП. Уже {current_count} позиций (max={self.MAX_SIMULTANEOUS_POSITIONS}). "
                            "Overtrading — PnL каждой мал, комиссии съедят прибыль.",
                "action":   "close_weakest_first_or_skip",
            }
        return {"allowed": True, "open_count": current_count}

    def check_fomo(self, asset: str, signal_tick: int,
                   current_tick: int, total_round_ticks: int) -> dict:
        """
        §45: FOMO — не входить если прошло 50%+ движения.
        Оцениваем по тикам с момента сигнала.
        """
        ticks_since_signal = current_tick - signal_tick
        if total_round_ticks > 0:
            move_pct = ticks_since_signal / total_round_ticks
        else:
            move_pct = 0.0
        fomo_triggered = move_pct >= 0.5
        return {
            "asset":           asset,
            "fomo_triggered":  fomo_triggered,
            "move_pct":        move_pct * 100,
            "allowed":         not fomo_triggered,
            "reason":          (f"§45: FOMO! Прошло {move_pct*100:.0f}% раунда. "
                                "Не входить после 50%+ движения.")
                               if fomo_triggered else "OK",
        }

    def open_position(self, asset: str, entry_price: float,
                      size: float, tick: int):
        """Зарегистрировать открытие позиции."""
        self.open_positions[asset] = {"size": size, "entry": entry_price}
        self.entry_prices[asset]   = entry_price
        self.entry_ticks[asset]    = tick

    def check_disposition_effect(self, asset: str, current_price: float,
                                 profit_target: float,
                                 stop_loss: float) -> dict:
        """
        §45: Disposition effect.
        Ранний выход из прибыльной позиции.
        Поздний выход из убыточной.
        """
        if asset not in self.open_positions:
            return {"asset": asset, "action": "no_position"}
        pos    = self.open_positions[asset]
        entry  = pos["entry"]
        size   = pos["size"]
        is_long = size > 0
        pnl    = (current_price - entry) * abs(size) * (1 if is_long else -1)
        pnl_pct = (current_price - entry) / (entry + 1e-9) * (1 if is_long else -1)

        # Ранний выход из прибыльной — распознаём и предостерегаем
        early_exit_risk = pnl > 0 and pnl_pct < profit_target
        # Поздний выход из убыточной — убыток хуже stop_loss
        late_exit_risk  = pnl < 0 and abs(pnl_pct) > stop_loss

        action = "hold"
        warnings_list = []
        if early_exit_risk:
            warnings_list.append(f"§45: Disposition effect — ранний выход? "
                                  f"PnL={pnl_pct*100:.1f}% < target={profit_target*100:.1f}%")
        if late_exit_risk:
            action = "EXIT_NOW"
            warnings_list.append(f"§45: Disposition effect — ПОЗДНО выходить! "
                                  f"Убыток {abs(pnl_pct)*100:.1f}% > stop={stop_loss*100:.1f}%")

        return {
            "asset":         asset,
            "pnl":           pnl,
            "pnl_pct":       pnl_pct * 100,
            "action":        action,
            "warnings":      warnings_list,
        }

    def check_anchoring(self, asset: str, current_price: float,
                        new_info_sentiment: int) -> dict:
        """
        §45: Anchoring — не привязываться к цене входа при решении о выходе.
        Решение принимается на основе текущего sentiment, не entry price.
        """
        if asset not in self.entry_prices:
            return {"asset": asset, "note": "no_position"}
        entry = self.entry_prices[asset]
        return {
            "asset":        asset,
            "entry_price":  entry,
            "current_price": current_price,
            "rule":         "§45: Anchoring — решение основано на ТЕКУЩЕМ SENTIMENT, не entry price",
            "decision_basis": "sentiment",
            "new_sentiment":  new_info_sentiment,
            "action":       "close" if new_info_sentiment == 0 else "hold_or_adjust",
        }

    def full_check(self, asset: str, signal_tick: int, current_tick: int,
                   total_round_ticks: int, entry_price: float,
                   current_price: float, profit_target: float = 0.02,
                   stop_loss: float = 0.015) -> dict:
        """Прогнать все проверки §45 одним вызовом."""
        return {
            "diversification":  self.check_diversification(asset),
            "fomo":             self.check_fomo(asset, signal_tick, current_tick,
                                                total_round_ticks),
            "disposition":      self.check_disposition_effect(asset, current_price,
                                                              profit_target, stop_loss),
        }


# ─────────────────────────────────────────────────────────────────────────────
# §47 / §10.5  NASH EQUILIBRIUM ДЛЯ КОНТЕЙНЕРОВ
# ─────────────────────────────────────────────────────────────────────────────

@dataclass
class Container:
    """Один контейнер (bucket) с ценностью."""
    id:    str
    value: float
    is_obvious: bool = False   # §47: очевидно лучший → все идут → EV падает


class NashContainerSolver:
    """
    §47 — Nash Equilibrium для выбора контейнеров.
    EV_i = V_i / k_i  (ценность / ожидаемое число участников)
    Nash: k_i пропорционально V_i → все контейнеры одинаково привлекательны.
    """

    def __init__(self, containers: list[Container], n_teams: int,
                 max_iterations: int = 1000):
        """
        n_teams: §47 — брать из leaderboard или официальных данных раунда.
        max_iterations: §47 — 1000 итераций до сходимости.
        """
        self.containers     = containers
        self.n_teams        = n_teams
        self.max_iterations = max_iterations

    def _ev(self, value: float, k: float) -> float:
        """EV_i = V_i / k_i."""
        return value / (k + 1e-9)

    def compute_nash_allocation(self) -> dict:
        """
        §47: Итерационный расчёт Nash equilibrium.
        Пропорциональное распределение команд по контейнерам.
        """
        values = np.array([c.value for c in self.containers])
        total_value = values.sum()
        # Nash: k_i пропорционально V_i
        nash_k = (values / (total_value + 1e-9)) * self.n_teams
        # Итерации для сходимости
        k = nash_k.copy()
        for _ in range(self.max_iterations):
            evs = values / (k + 1e-9)
            ev_mean = evs.mean()
            # Перераспределяем: если EV_i > mean → больше команд пойдёт туда
            new_k = k * (evs / (ev_mean + 1e-9))
            new_k = new_k / (new_k.sum() + 1e-9) * self.n_teams
            if np.max(np.abs(new_k - k)) < 1e-8:
                k = new_k
                break
            k = new_k

        evs_final = values / (k + 1e-9)
        results = []
        for i, c in enumerate(self.containers):
            results.append({
                "container_id":    c.id,
                "value":           c.value,
                "nash_teams":      k[i],
                "nash_ev":         evs_final[i],
                "is_obvious":      c.is_obvious,
                "recommendation":  self._recommend(c, k[i], evs_final),
            })
        return {
            "nash_allocations": results,
            "ev_at_nash":       float(np.mean(evs_final)),
            "converged":        True,
        }

    def _recommend(self, container: Container, expected_teams: float,
                   all_evs: np.ndarray) -> str:
        """§47: Неочевидный выбор → меньше конкуренции → выше EV."""
        if container.is_obvious:
            return ("§47: ИЗБЕГАТЬ — очевидно лучший контейнер → "
                    "все идут туда → EV падает")
        ev_rank = sorted(all_evs, reverse=True).index(
            all_evs[self.containers.index(container)]) + 1 \
            if container in self.containers else 1
        return f"Rank {ev_rank} — {'неочевидный выбор → меньше конкуренции' if not container.is_obvious else 'obvious'}"

    def find_best_container(self) -> dict:
        """
        §47: При нескольких Nash equilibria — выбирать наименее очевидный.
        """
        result  = self.compute_nash_allocation()
        allocs  = result["nash_allocations"]
        # Исключаем очевидные
        non_obvious = [a for a in allocs if not a["is_obvious"]]
        candidates  = non_obvious if non_obvious else allocs
        # Наибольший EV среди неочевидных
        best = max(candidates, key=lambda x: x["nash_ev"])
        return {
            "best_container":    best["container_id"],
            "expected_ev":       best["nash_ev"],
            "expected_teams":    best["nash_teams"],
            "strategy":          "§47: наименее очевидный контейнер",
            "all_allocations":   allocs,
        }

    def mixed_strategy(self) -> dict:
        """
        §47: Mixed strategy Nash — рандомизировать между контейнерами
        если equilibrium смешанный.
        Веса = пропорционально EV (для неочевидных).
        """
        result = self.compute_nash_allocation()
        allocs = result["nash_allocations"]
        non_obvious = [a for a in allocs if not a["is_obvious"]]
        if not non_obvious:
            non_obvious = allocs
        evs   = np.array([a["nash_ev"] for a in non_obvious])
        # Нормируем в вероятности
        probs = evs / (evs.sum() + 1e-9)
        choices = [a["container_id"] for a in non_obvious]
        # Случайный выбор по смешанной стратегии
        chosen = np.random.choice(choices, p=probs)
        return {
            "mixed_strategy_probs": dict(zip(choices, probs)),
            "recommended_choice":   chosen,
            "rule": "§47: рандомизировать если equilibrium смешанный",
        }

    def compute_ev(self, multiplier: float, inhabitants: float, expected_crowd: float) -> float:
        """EV = 10_000 * multiplier / (inhabitants + expected_crowd)"""
        ev = 10_000 * multiplier / (inhabitants + expected_crowd)
        return ev

    def should_buy_second(self, second_container_ev: float, second_container_cost: float) -> bool:
        """Do not buy second container if EV < cost."""
        return second_container_ev > second_container_cost


# ─────────────────────────────────────────────────────────────────────────────
# §48 / §10.6  MARKOWITZ ДЛЯ ROUND 5
# ─────────────────────────────────────────────────────────────────────────────

class MarkowitzRound5:
    """
    §48 — Markowitz для Round 5.
    expected_returns из sentiment сигналов.
    Ковариационная матрица из исторических данных.
    """

    def __init__(self, assets: list[str],
                 allow_short: bool = False,
                 regularization_lambda: float = 1e-4):
        """
        allow_short: §48 — [0,1] long only или [-1,1] если short разрешён.
        regularization_lambda: §48 — cov_matrix += λ×I для numerical stability.
        """
        self.assets       = assets
        self.allow_short  = allow_short
        self.lam          = regularization_lambda

    def build_expected_returns(self, sentiment_engine: SentimentEngine,
                               current_tick: int,
                               scale: float = 0.01) -> np.ndarray:
        """
        §48: expected_returns из sentiment сигналов.
        sentiment +2 → +2×scale, -2 → -2×scale.
        """
        returns = []
        for asset in self.assets:
            s = sentiment_engine.get_combined_sentiment(asset, current_tick)
            returns.append(s["sentiment"] * scale)
        return np.array(returns)

    def build_covariance(self, price_history: np.ndarray | None) -> np.ndarray:
        """
        §48: Ковариационная матрица.
        Cold start: если нет истории → diagonal covariance.
        Numerical stability: cov += λ×I.
        """
        n = len(self.assets)
        if price_history is None or price_history.shape[0] < n + 5:
            # §48: Cold start — diagonal covariance (нет корреляций)
            cov = np.eye(n) * 0.02 ** 2
        else:
            returns = np.diff(price_history, axis=0) / (price_history[:-1] + 1e-9)
            if returns.shape[1] != n:
                cov = np.eye(n) * 0.02 ** 2
            else:
                cov = np.cov(returns.T)
                if cov.ndim == 0:
                    cov = np.array([[cov]])
        # §48: regularize
        cov += self.lam * np.eye(n)
        return cov

    def optimize(self, sentiment_engine: SentimentEngine,
                 current_tick: int,
                 max_positions: np.ndarray | None = None,
                 price_history: np.ndarray | None = None) -> dict:
        """
        §48: Оптимизация по максимальному Sharpe через scipy.optimize.minimize.
        Fallback: equal-weight топ-2 если не сходится.
        Считать заранее до старта manual сессии.
        """
        n  = len(self.assets)
        mu = self.build_expected_returns(sentiment_engine, current_tick)
        cov = self.build_covariance(price_history)
        if max_positions is None:
            max_positions = np.ones(n)

        def neg_sharpe(w):
            ret = w @ mu
            vol = np.sqrt(w @ cov @ w + 1e-12)
            return -(ret / vol)

        bounds = [(-1, 1) if self.allow_short else (0, 1)] * n
        constraints = [{"type": "eq", "fun": lambda w: np.sum(np.abs(w)) - 1}] \
            if self.allow_short else \
            [{"type": "eq", "fun": lambda w: np.sum(w) - 1}]
        w0 = np.ones(n) / n

        try:
            res = optimize.minimize(neg_sharpe, w0, method="SLSQP",
                                    bounds=bounds, constraints=constraints,
                                    options={"ftol": 1e-9, "maxiter": 2000})
            if not res.success or np.any(np.isnan(res.x)):
                raise ValueError("optimizer did not converge")
            weights = res.x
            method  = "markowitz_sharpe"
        except Exception:
            # §48: Fallback — equal-weight топ-2
            weights, method = self._fallback_top2(mu, n)

        # §48: position sizes = optimal_weights × max_position_i
        position_sizes = weights * max_positions

        return {
            "assets":          self.assets,
            "weights":         weights,
            "position_sizes":  position_sizes,
            "expected_return": weights @ mu,
            "expected_vol":    float(np.sqrt(weights @ cov @ weights + 1e-12)),
            "method":          method,
            "rule":            "§48: Считать заранее до старта manual сессии",
        }

    def _fallback_top2(self, mu: np.ndarray, n: int) -> tuple[np.ndarray, str]:
        """§48: Fallback equal-weight топ-2 по |expected_return|."""
        top2_idx = np.argsort(np.abs(mu))[-2:]
        weights  = np.zeros(n)
        for idx in top2_idx:
            weights[idx] = np.sign(mu[idx]) / 2.0  # равный вес ±0.5
        return weights, "fallback_equal_weight_top2"

    def concentrate_top2(self, sentiment_engine: SentimentEngine,
                         current_tick: int) -> list[dict]:
        """
        §42/§44: Концентрировать в топ-2 сигнала, не диверсифицировать.
        """
        return sentiment_engine.top_n_assets(current_tick, n=2)


# ─────────────────────────────────────────────────────────────────────────────
# §49 / §10.7  КОНФЛИКТ MANUAL VS АЛГОРИТМ
# ─────────────────────────────────────────────────────────────────────────────

@dataclass
class AlgoPosition:
    """Позиция алгоритма по активу."""
    asset: str
    size:  float
    side:  str   # "long" / "short"


class ManualAlgoConflict:
    """
    §49 / §10.7 — Управление конфликтом manual vs алгоритм.
    """

    def __init__(self):
        self.algo_positions:   dict[str, AlgoPosition] = {}
        self.manual_positions: dict[str, float]        = {}

    def register_algo_position(self, asset: str, size: float):
        """Зарегистрировать позицию алгоритма."""
        side = "long" if size > 0 else "short"
        self.algo_positions[asset] = AlgoPosition(asset, size, side)

    def register_manual_position(self, asset: str, size: float):
        """Зарегистрировать manual позицию."""
        self.manual_positions[asset] = size

    def resolve(self, asset: str, has_news_event: bool) -> dict:
        """
        §49: Разрешение конфликта.
        • Manual signal приоритетнее при явном новостном событии.
        • Алгоритм работает на других продуктах.
        • Противоположные сигналы → уменьшить алгоритмическую вдвое.
        """
        algo_pos   = self.algo_positions.get(asset)
        manual_pos = self.manual_positions.get(asset)

        if algo_pos is None and manual_pos is None:
            return {"asset": asset, "action": "no_positions"}

        # §49: Manual приоритетнее при новостном событии
        if has_news_event and manual_pos is not None:
            return {
                "asset":           asset,
                "action":          "USE_MANUAL",
                "manual_size":     manual_pos,
                "algo_action":     "pause_this_asset_continue_others",
                "rule":            "§49: manual приоритетнее при явном новостном событии",
            }

        # §49: Проверить противоположность сигналов
        if algo_pos is not None and manual_pos is not None:
            algo_sign   = np.sign(algo_pos.size)
            manual_sign = np.sign(manual_pos)
            if algo_sign != manual_sign and algo_sign != 0 and manual_sign != 0:
                halved_algo = algo_pos.size / 2.0
                return {
                    "asset":             asset,
                    "action":            "REDUCE_ALGO_HALF",
                    "original_algo":     algo_pos.size,
                    "adjusted_algo":     halved_algo,
                    "manual_size":       manual_pos,
                    "rule":              "§49: противоположные сигналы → алгоритм вдвое",
                }

        return {
            "asset":  asset,
            "action": "no_conflict",
            "algo":   algo_pos.size if algo_pos else 0,
            "manual": manual_pos or 0,
        }

    def post_manual_audit(self) -> dict:
        """
        §49: После manual сессии — убедиться что алгоритм
        не накопил противоположную позицию.
        """
        conflicts = []
        for asset, manual_size in self.manual_positions.items():
            if asset in self.algo_positions:
                algo_size = self.algo_positions[asset].size
                if np.sign(manual_size) != np.sign(algo_size) and \
                   manual_size != 0 and algo_size != 0:
                    conflicts.append({
                        "asset":      asset,
                        "manual":     manual_size,
                        "algo":       algo_size,
                        "action":     "CLOSE_OR_REDUCE_ALGO",
                        "rule":       "§49: после manual — проверить накопленные позиции",
                    })
        return {
            "conflicts_found": len(conflicts),
            "conflicts":       conflicts,
            "status":          "CLEAN" if not conflicts else "ACTION_REQUIRED",
        }


# ─────────────────────────────────────────────────────────────────────────────
# §50 / §10.8  MANUAL CHECKLIST ПЕРЕД КАЖДЫМ РАУНДОМ
# ─────────────────────────────────────────────────────────────────────────────

@dataclass
class RoundPlan:
    """§50: Зафиксировать план до начала торговли."""
    round_type:        RoundType
    scenario:          ManualScenario
    top2_assets:       list[str]       = field(default_factory=list)
    fee_structure:     dict            = field(default_factory=dict)
    entry_plan:        dict            = field(default_factory=dict)
    exit_plan:         dict            = field(default_factory=dict)
    sentiment_table:   dict            = field(default_factory=dict)
    nash_precomputed:  dict | None     = None
    markowitz_precomp: dict | None     = None


class ManualChecklist:
    """
    §50 / §10.8 — Pre-round checklist.
    Все пункты должны быть выполнены ДО начала торговли.
    """

    CHECKLIST_ITEMS = [
        ("conditions_read",     "Прочитать все условия раунда"),            # §50
        ("scenario_identified", "Выделить manual сценарий и его тип"),      # §50
        ("nash_or_markowitz",   "Предрассчитать Nash EV или Markowitz"),    # §50
        ("top2_identified",     "Определить топ-2 актива для концентрации"),# §50
        ("sentiment_table_set", "Установить sentiment → size таблицу"),     # §50
        ("fee_structure_set",   "Определить fee структуру и оптимальный размер"), # §50
        ("plan_locked",         "Зафиксировать план входа и выхода"),       # §50
    ]

    def __init__(self, round_type: RoundType):
        self.round_type = round_type
        self.status: dict[str, bool] = {k: False for k, _ in self.CHECKLIST_ITEMS}
        self.plan: RoundPlan | None  = None

    def complete(self, item_key: str):
        """Отметить пункт как выполненный."""
        if item_key in self.status:
            self.status[item_key] = True
            print(f"  ✅ {dict(self.CHECKLIST_ITEMS)[item_key]}")
        else:
            print(f"  ⚠️  Неизвестный пункт: {item_key}")

    def run_interactive(self, sentiment_engine: SentimentEngine | None = None,
                        containers: list[Container] | None = None,
                        n_teams: int = 10,
                        price_history: np.ndarray | None = None,
                        current_tick: int = 0) -> RoundPlan:
        """
        §50: Полный прогон checklist с автоматическим предрасчётом.
        Вызывать ПЕРЕД стартом раунда.
        """
        print(f"\n{'='*60}")
        print(f"§50 MANUAL CHECKLIST — {self.round_type.name}")
        print(f"{'='*60}")

        # 1. Условия раунда
        self.complete("conditions_read")

        # 2. Сценарий
        briefing = RoundRouter.get_briefing(self.round_type)
        scenario = ManualScenario(briefing["manual_scenario"])
        self.complete("scenario_identified")
        print(f"     Сценарий: {scenario.value} | Tip: {briefing['manual_tip']}")

        plan = RoundPlan(round_type=self.round_type, scenario=scenario)

        # 3. Nash или Markowitz
        if scenario == ManualScenario.NASH and containers:
            solver = NashContainerSolver(containers, n_teams)
            plan.nash_precomputed = solver.find_best_container()
            print(f"     Nash best: {plan.nash_precomputed['best_container']} "
                  f"EV={plan.nash_precomputed['expected_ev']:.2f}")
        elif scenario in (ManualScenario.NEWS, ManualScenario.PORTFOLIO) \
                and sentiment_engine:
            assets = list(sentiment_engine.signals.keys()) or ["ASSET_A", "ASSET_B"]
            mkz = MarkowitzRound5(assets)
            plan.markowitz_precomp = mkz.optimize(
                sentiment_engine, current_tick, price_history=price_history)
            print(f"     Markowitz method: {plan.markowitz_precomp['method']}")
        self.complete("nash_or_markowitz")

        # 4. Топ-2 активов
        if sentiment_engine and sentiment_engine.signals:
            top2 = sentiment_engine.top_n_assets(current_tick, n=2)
            plan.top2_assets = [t["asset"] for t in top2]
        else:
            plan.top2_assets = ["ASSET_A", "ASSET_B"]
        print(f"     Топ-2: {plan.top2_assets}")
        self.complete("top2_identified")

        # 5. Sentiment → size таблица
        plan.sentiment_table = SentimentEngine.SIZE_TABLE.copy()
        self.complete("sentiment_table_set")

        # 6. Fee структура
        plan.fee_structure = {"per_unit": 0.001, "min_profitable_size": 10}
        self.complete("fee_structure_set")

        # 7. План входа / выхода
        plan.entry_plan = {
            "rule":    "Входить сразу после прочтения новости",  # §43
            "fomo":    "Не входить после 50%+ движения",          # §45
            "max_pos": self.MAX_SIMULTANEOUS_POSITIONS,
        }
        plan.exit_plan = {
            "rule":    "Держать до конца раунда если нет противоречащей новости", # §43
            "stop":    "Выходить при смене sentiment на противоположный",
            "no_avg_down": True,                                  # §43
        }
        self.complete("plan_locked")

        self.plan = plan
        print(f"\n{'='*60}")
        passed = sum(self.status.values())
        total  = len(self.status)
        print(f"CHECKLIST: {passed}/{total} пунктов ✅")
        if passed < total:
            missing = [v for k, v in self.CHECKLIST_ITEMS if not self.status[k]]
            for m in missing:
                print(f"  ❌ НЕ ВЫПОЛНЕНО: {m}")
        else:
            print("✅ Готов к торговле")
        print(f"{'='*60}\n")
        return plan

    MAX_SIMULTANEOUS_POSITIONS = ManualErrorGuard.MAX_SIMULTANEOUS_POSITIONS

    def is_ready_to_trade(self) -> bool:
        """§50: Все пункты выполнены = можно торговать."""
        return all(self.status.values())


# ─────────────────────────────────────────────────────────────────────────────
# INTEGRATION RUNNER
# ─────────────────────────────────────────────────────────────────────────────

def run_all_checks():
    rng = np.random.default_rng(42)
    results = {}
    errors  = []

    def run(section: str, fn):
        try:
            results[section] = fn()
            print(f"  ✅  {section}")
        except Exception as e:
            errors.append((section, str(e)))
            print(f"  ❌  {section}: {e}")

    print("\n" + "=" * 70)
    print("ЗАПУСК COMPREHENSIVE CHECK — MANUAL TRADING FRAMEWORK")
    print("=" * 70)

    # ── §42 / §10.1  ROUND FRAMEWORK ────────────────────────────────────────
    print("\n§42/10.1 ROUND-BY-ROUND FRAMEWORK")
    run("42.round_context_guard",
        lambda: RoundContext(RoundType.R1_SIMPLE))
    run("42.conditions_read",
        lambda: (lambda c: c.mark_conditions_read() or c.conditions_read)(
            RoundContext(RoundType.R3_OPTIONS)))
    for rt in RoundType:
        run(f"42.briefing_{rt.name}", lambda rt=rt: RoundRouter.get_briefing(rt))
    run("42.print_briefing_R5",
        lambda: RoundRouter.print_briefing(RoundType.R5_NEWS))

    # ── §43  SENTIMENT FRAMEWORK ─────────────────────────────────────────────
    print("\n§43 SENTIMENT FRAMEWORK")
    engine = SentimentEngine(signal_decay_ticks=500)
    engine.add_signal("OIL",  2, 100, source="news", is_specific=True)
    engine.add_signal("GOLD", -1, 100, source="news", is_specific=False)
    engine.add_signal("OIL",  -1, 200, source="news", is_specific=True)  # contra
    run("43.size_table",
        lambda: SentimentEngine.SIZE_TABLE)
    run("43.combined_sentiment_oil",
        lambda: engine.get_combined_sentiment("OIL", 200))
    run("43.combined_sentiment_gold",
        lambda: engine.get_combined_sentiment("GOLD", 200))
    run("43.position_size",
        lambda: engine.get_position_size("OIL", 1000, 200))
    run("43.update_on_new_signal",
        lambda: engine.update_on_new_signal("GOLD", -2, 300, 1000))
    run("43.top2_assets",
        lambda: engine.top_n_assets(300, n=2))
    run("43.fee_aware_sizing",
        lambda: engine.fee_aware_sizing("OIL", 1000, 0.001, 0.005, 300))
    run("43.decay_weight",
        lambda: engine._decay_weight(
            SentimentSignal("OIL", 2, 0, "news"), 600))  # age > decay_ticks

    # ── §44 / §10.2  НОВОСТИ FRAMEWORK ──────────────────────────────────────
    print("\n§44/10.2 НОВОСТИ FRAMEWORK")
    news_engine = SentimentEngine()
    nf = NewsFramework(news_engine, news_interval_ticks=1000)
    articles = [
        NewsArticle("Рекордная прибыль OIL +30% превысил ожидания аналитиков",
                    "OIL", tick_received=500, cross_assets=["ENERGY"]),
        NewsArticle("Эксперты возможно ожидают небольшой рост GOLD",
                    "GOLD", tick_received=500, cross_assets=[]),
        NewsArticle("Крупные убытки SILVER резкое падение -15%",
                    "SILVER", tick_received=500),
    ]
    run("44.receive_newspaper",
        lambda: nf.receive_newspaper(articles, 500))
    run("44.cross_asset_effect",
        lambda: news_engine.get_combined_sentiment("ENERGY", 500))
    run("44.should_enter_now",
        lambda: nf.should_enter_now(500))
    run("44.should_hold",
        lambda: nf.should_hold("OIL", 600))
    run("44.do_not_average_down",
        lambda: nf.do_not_average_down("OIL", 100.0, 98.0, 10))
    run("44.score_specific",
        lambda: NewsFramework._score_article(
            "Выручка компании рекордная прибыль +25% превысил ожидания"))
    run("44.score_noise",
        lambda: NewsFramework._score_article(
            "Эксперты возможно ожидают улучшение ситуации"))

    # ── §45 / §10.3  ERROR GUARD ─────────────────────────────────────────────
    print("\n§45/10.3 MANUAL ERROR GUARD")
    guard = ManualErrorGuard()
    guard.open_position("OIL", 100.0, 50.0, tick=100)
    guard.open_position("GOLD", 200.0, 30.0, tick=110)
    guard.open_position("SILVER", 150.0, 20.0, tick=120)
    guard.open_position("COPPER", 130.0, 15.0, tick=130)
    run("45.diversification_block",
        lambda: guard.check_diversification("NEW_ASSET"))
    run("45.fomo_50pct",
        lambda: guard.check_fomo("OIL", 0, 500, 1000))
    run("45.fomo_ok",
        lambda: guard.check_fomo("OIL", 0, 100, 1000))
    run("45.disposition_losing",
        lambda: guard.check_disposition_effect("OIL", 95.0, 0.02, 0.015))
    run("45.disposition_stop",
        lambda: guard.check_disposition_effect("OIL", 82.0, 0.02, 0.015))
    run("45.anchoring",
        lambda: guard.check_anchoring("OIL", 95.0, 0))
    run("45.full_check",
        lambda: guard.full_check("OIL", 0, 500, 1000, 100.0, 95.0))

    # ── §47 / §10.5  NASH CONTAINERS ─────────────────────────────────────────
    print("\n§47/10.5 NASH CONTAINERS")
    containers = [
        Container("A", value=1000, is_obvious=True),
        Container("B", value=600,  is_obvious=False),
        Container("C", value=400,  is_obvious=False),
        Container("D", value=800,  is_obvious=False),
    ]
    solver = NashContainerSolver(containers, n_teams=20, max_iterations=1000)
    run("47.nash_allocation",
        lambda: solver.compute_nash_allocation())
    run("47.best_container",
        lambda: solver.find_best_container())
    run("47.mixed_strategy",
        lambda: solver.mixed_strategy())
    run("47.obvious_avoided",
        lambda: (lambda r: r["best_container"] != "A")(solver.find_best_container()))

    # ── §48 / §10.6  MARKOWITZ ROUND 5 ──────────────────────────────────────
    print("\n§48/10.6 MARKOWITZ ROUND 5")
    mkz_engine = SentimentEngine()
    mkz_engine.add_signal("AAPL",  2, 0, is_specific=True)
    mkz_engine.add_signal("MSFT",  1, 0, is_specific=True)
    mkz_engine.add_signal("TSLA", -2, 0, is_specific=True)
    mkz_engine.add_signal("GOOG",  0, 0, is_specific=False)
    assets = ["AAPL", "MSFT", "TSLA", "GOOG"]
    mkz = MarkowitzRound5(assets, allow_short=True, regularization_lambda=1e-4)
    run("48.expected_returns",
        lambda: mkz.build_expected_returns(mkz_engine, 0))
    run("48.covariance_cold_start",
        lambda: mkz.build_covariance(None))
    fake_history = rng.normal(100, 2, (200, 4))
    run("48.covariance_historical",
        lambda: mkz.build_covariance(fake_history))
    run("48.optimize_full",
        lambda: mkz.optimize(mkz_engine, 0, price_history=fake_history))
    run("48.optimize_cold_start",
        lambda: mkz.optimize(mkz_engine, 0, price_history=None))
    run("48.concentrate_top2",
        lambda: mkz.concentrate_top2(mkz_engine, 0))
    # Long-only
    mkz_lo = MarkowitzRound5(assets, allow_short=False)
    run("48.long_only",
        lambda: mkz_lo.optimize(mkz_engine, 0))

    # ── §49 / §10.7  CONFLICT MANUAL VS ALGO ─────────────────────────────────
    print("\n§49/10.7 MANUAL VS ALGO CONFLICT")
    conflict = ManualAlgoConflict()
    conflict.register_algo_position("OIL",  500)
    conflict.register_algo_position("GOLD", -200)
