    conflict.register_manual_position("GOLD", -150)   # совпадает
    conflict.register_manual_position("SILVER", 100)  # только manual
    run("49.news_event_priority",
        lambda: conflict.resolve("OIL", has_news_event=True))
    run("49.opposite_signals_halve",
        lambda: conflict.resolve("OIL", has_news_event=False))
    run("49.no_conflict",
        lambda: conflict.resolve("GOLD", has_news_event=False))
    run("49.post_manual_audit",
        lambda: conflict.post_manual_audit())

    # ── §50 / §10.8  PRE-ROUND CHECKLIST ────────────────────────────────────
    print("\n§50/10.8 PRE-ROUND CHECKLIST")
    # R5 News — самый сложный (Nash + sentiment + Markowitz)
    cl_engine = SentimentEngine()
    cl_engine.add_signal("OIL",    2, 0, is_specific=True)
    cl_engine.add_signal("SILVER", 1, 0, is_specific=True)
    checklist = ManualChecklist(RoundType.R5_NEWS)
    run("50.run_checklist_R5",
        lambda: checklist.run_interactive(
            sentiment_engine=cl_engine, current_tick=0))
    run("50.is_ready",
        lambda: checklist.is_ready_to_trade())
    # R1 Lottery
    cl2 = ManualChecklist(RoundType.R1_SIMPLE)
    run("50.run_checklist_R1",
        lambda: cl2.run_interactive())
    # R3 Options — с Nash контейнерами
    c3_containers = [Container("X", 500, False), Container("Y", 300, True)]
    cl3 = ManualChecklist(RoundType.R3_OPTIONS)
    run("50.run_checklist_R3",
        lambda: cl3.run_interactive(
            containers=c3_containers, n_teams=15))
    run("50.plan_has_top2",
        lambda: len(checklist.plan.top2_assets) == 2)
    run("50.plan_has_entry_exit",
        lambda: bool(checklist.plan.entry_plan and checklist.plan.exit_plan))

    # ── ФИНАЛЬНАЯ СВОДКА ────────────────────────────────────────────────────
    print("\n" + "=" * 70)
    total  = len(results) + len(errors)
    passed = len(results)
    failed = len(errors)
    print(f"ИТОГ: {passed}/{total} проверок пройдено")
    if errors:
        print(f"\n❌ ОШИБКИ ({failed}):")
        for sec, err in errors:
            print(f"   {sec}: {err}")
    else:
        print("✅ 0 пропусков, каждый пункт выполнен, ошибок нет")
    print("=" * 70)
    return results, errors


