# ==============================================================================
# SECTION 2 — STATE DATA CLASSES
# ==============================================================================

# ── LOCATION ARB [7.5] ──

@dataclass
# [7.4] отдельный inventory tracking
class LocationState:
    """[7.5] State одной локации."""
    inventory: float = 0.0           # [7.5] inventory по локации
    active_arb: bool = False          # [7.5] флаг активного арба
    arb_history: List[float] = field(default_factory=list)  # для buffer size


@dataclass
class RouteState:
    """[7.5] State одного маршрута."""
    transport_cost: float = 0.0      # [7.5] последние известные transport_cost
    tariff: float = 0.0              # [7.5] последние известные tariff
    current_profit: float = 0.0      # [7.5] текущий profit по маршруту
    active: bool = False             # [7.5] флаг активного арба


@dataclass
class LocationArbState:
    """[7.5] Полный location arb state — сериализуется в traderData."""
    locations: Dict[str, LocationState] = field(default_factory=dict)
    routes: Dict[str, RouteState] = field(default_factory=dict)    # "A→B"
    graph_recalc_counter: int = 0    # [7.5] счётчик тиков с последнего пересчёта
    cost_check_counter: int = 0

    def get_location(self, loc: str) -> LocationState:
        if loc not in self.locations:
            self.locations[loc] = LocationState()
        return self.locations[loc]

    def get_route(self, src: str, dst: str) -> RouteState:
        key = f"{src}→{dst}"
        if key not in self.routes:
            self.routes[key] = RouteState()
        return self.routes[key]


# ── STAT ARB [3.4] ──

@dataclass
class KalmanHedgeState:
    """[3.4] Kalman adaptive hedge ratio state."""
    # [3.2] state = [intercept, slope]
    x_est: List[float] = field(default_factory=lambda: [0.0, 1.0])
    P_est: List[List[float]] = field(default_factory=lambda: [[1.0, 0.0], [0.0, 1.0]])
    initialized: bool = False   # [3.2] cold start


@dataclass
class PairState:
    """[3.4] State одной пары/корзины."""
    # [3.4] Rolling spread window (последние 500 значений)
    spread_history: List[float] = field(default_factory=list)
    # [3.4] spread_mean и spread_std текущие
    spread_mean: float = 0.0
    spread_std: float = 1.0
    # Инкрементальные суммы для O(1) обновления [3.1]
    _sum: float = 0.0
    _sum_sq: float = 0.0
    _n: int = 0
    # [3.4] Текущий z-score
    z_score: float = 0.0
    # [3.4] Hedge ratios
    hedge_ratio: float = 1.0
    hedge_recalc_counter: int = 0
    # [3.4] Kalman state
    kalman: KalmanHedgeState = field(default_factory=KalmanHedgeState)
    # [3.4] Johansen eigenvectors
    johansen_eigvec: List[float] = field(default_factory=list)
    johansen_recalc_counter: int = 0
    # [3.4] Half-life
    half_life: float = 0.0
    # [3.4] Leg imbalance счётчик
    leg_imbalance_ticks: int = 0
    # [3.4] Structural break флаг
    structural_break: bool = False
    struct_break_counter: int = 0
    # Position state
    position: int = 0   # +1 long spread, -1 short spread, 0 flat
    leg1_filled: int = 0
    leg2_filled: int = 0


@dataclass
class StatArbState:
    """[3.4] Полный stat arb state."""
    pairs: Dict[str, PairState] = field(default_factory=dict)

    def get_pair(self, key: str) -> PairState:
        if key not in self.pairs:
            self.pairs[key] = PairState()
        return self.pairs[key]


# ── CROSS-PRODUCT [11.5] ──

@dataclass
class ProductCrossState:
    """[11.5] Cross-product state per product."""
    capacity_weight: float = 0.0       # [11.5] текущий capacity weight
    sharpe_estimate: float = 0.0       # [11.5] Sharpe rolling
    cross_year_corr: float = 0.0       # [11.5] rolling correlation
    cross_year_active: bool = False    # [11.5] флаг активности кросс-год сигнала
    net_exposure: float = 0.0          # [11.5] нетто-экспозиция по связке
    pnl_history: List[float] = field(default_factory=list)
    vol_history: List[float] = field(default_factory=list)


@dataclass
class CrossProductState:
    """[11.5] Полный cross-product state."""
    products: Dict[str, ProductCrossState] = field(default_factory=dict)
    capacity_recalc_counter: int = 0

    def get_product(self, name: str) -> ProductCrossState:
        if name not in self.products:
            self.products[name] = ProductCrossState()
        return self.products[name]


# ==============================================================================
# SECTION 16 — UTILITIES
# ==============================================================================

def _std(values: List[float]) -> float:
    if len(values) < 2:
        return 0.0
    mean = sum(values) / len(values)
    return math.sqrt(sum((v - mean)**2 for v in values) / len(values))

def _pearson(x: List[float], y: List[float]) -> float:
    n = min(len(x), len(y))
    if n < 2:
        return 0.0
    mx = sum(x[:n]) / n
    my = sum(y[:n]) / n
    num = sum((x[i]-mx)*(y[i]-my) for i in range(n))
    dx = math.sqrt(sum((x[i]-mx)**2 for i in range(n)))
    dy = math.sqrt(sum((y[i]-my)**2 for i in range(n)))
    if dx*dy == 0:
        return 0.0
    return num / (dx*dy)

def _ols_xy(x: List[float], y: List[float]) -> Tuple[float, float]:
    n = min(len(x), len(y))
    if n < 2:
        return 0.0, 0.0
    mx = sum(x[:n])/n; my = sum(y[:n])/n
    num = sum((x[i]-mx)*(y[i]-my) for i in range(n))
    den = sum((x[i]-mx)**2 for i in range(n))
    if den == 0:
        return 0.0, my
    slope = num/den
    return slope, my - slope*mx


