# SECTION 3 — LOCATION ARB ENGINE  [7.1–7.5]
# ==============================================================================

class LocationArbEngine:
    """
    Локационный арбитраж.                                           [7.1–7.5]
    profit = bid_A - ask_B - transport - tariff - fee_A - fee_B.   [7.1]
    Торговать если profit > min_threshold (мин 2–3 ед.).            [7.1]
    Размер = min(capacity, bid_A_vol, ask_B_vol).                   [7.1]
    Capacity constraints из документации раунда.                    [7.1]
    Если арб исчез → не доисполнять вторую ногу.                   [7.1]
    Минимальный holding period — проверять в документации.          [7.1]
    Декай стоимости при хранении — проверять в документации.       [7.1]
    """

    def compute_profit(
        self,
        bid_a: float,
        ask_b: float,
        transport: float,
        tariff: float,
        fee_a: float,
        fee_b: float,
    ) -> float:
        """[7.1] profit = bid_A - ask_B - transport_A→B - tariff - fee_A - fee_B"""
        return bid_a - ask_b - transport - tariff - fee_a - fee_b

    def compute_size(
        self,
        capacity: int,
        bid_a_volume: int,
        ask_b_volume: int,
    ) -> int:
        """[7.1] Размер = min(capacity, bid_A_volume, ask_B_volume)"""
        return min(capacity, bid_a_volume, ask_b_volume)

    def should_trade(self, profit: float, min_threshold: float = LOC_MIN_THRESHOLD) -> bool:
        """[7.1] Торговать если profit > min_threshold"""
        return profit > min_threshold

    def second_leg_valid(self, arb_still_exists: bool) -> bool:
        """[7.1] Если арб исчез → не доисполнять вторую ногу."""
        return arb_still_exists

    # [7.2] Мониторинг затрат
    # [7.2] state.observations или константы из документации
    def check_costs(
        self,
        state: LocationArbState,
        src: str,
        dst: str,
        new_transport: float,
        new_tariff: float,
        tick: int,
    ) -> bool:
        """
        [7.2] Динамика транспортных затрат и тарифов: каждые 100 тиков.
        Если изменились → пересчитать min_threshold немедленно.
        Хранить последние transport_cost и tariff в traderData.          [7.2]
        """
        state.cost_check_counter += 1
        if state.cost_check_counter < LOC_COST_CHECK_TICKS - 1:
            return False

        state.cost_check_counter = 0
        route = state.get_route(src, dst)
        changed = (
            abs(new_transport - route.transport_cost) > 1e-6 or
            abs(new_tariff - route.tariff) > 1e-6
        )
        # [7.2] Хранить последние известные значения в traderData
        route.transport_cost = new_transport
        route.tariff = new_tariff
        return changed  # → если True пересчитать min_threshold немедленно [7.2]

    def recalc_min_threshold(
        self,
        transport: float,
        tariff: float,
        fee_a: float,
        fee_b: float,
        buffer: float = 1.0,
    ) -> float:
        """[7.2] Пересчитать min_threshold немедленно при изменении затрат."""
        base_cost = transport + tariff + fee_a + fee_b
        return base_cost + buffer

    # [7.3] Граф и Беллман-Форд
    # [7.3] вершины = локации, рёбра = (profit-cost)
    def bellman_ford(
        self,
        locations: List[str],
        edges: List[Tuple[str, str, float]],  # (src, dst, weight=profit-cost)
    ) -> Tuple[Optional[List[str]], float]:
        """
        [7.3] Алгоритм Беллмана-Форда: найти цикл с положительным весом.
        [7.3] Сложность O(V×E) — проверить укладывается ли в 900ms.
        [7.3] Если networkx недоступен в IMC — реализовать вручную.
        [7.3] Если локаций мало (2–3) — Беллман-Форд избыточен.
        Возвращает (цикл, profit) или (None, 0) если нет положительного цикла.
        """
        # [7.3] Граф тривиален при 2–3 локациях — простой перебор
        if len(locations) <= 3:
            return self._brute_force_cycle(locations, edges)

        # Полный Беллман-Форд [7.3]
        n = len(locations)
        idx = {loc: i for i, loc in enumerate(locations)}
        dist = [0.0] * n
        pred = [-1] * n

        # V-1 итераций
        for _ in range(n - 1):
            for src, dst, w in edges:
                u, v = idx[src], idx[dst]
                if dist[u] + w > dist[v]:
                    dist[v] = dist[u] + w
                    pred[v] = u

        # Проверка на положительный цикл
        for src, dst, w in edges:
            u, v = idx[src], idx[dst]
            if dist[u] + w > dist[v]:
                # Положительный цикл найден — восстановить
                cycle = self._reconstruct_cycle(pred, v, idx, locations)
                profit = dist[v] + w - dist[u]
                return cycle, profit

        return None, 0.0

    def _brute_force_cycle(
        self,
        locations: List[str],
        edges: List[Tuple[str, str, float]],
    ) -> Tuple[Optional[List[str]], float]:
        """[7.3] Тривиальный поиск для 2–3 локаций."""
        edge_map: Dict[Tuple[str, str], float] = {(s, d): w for s, d, w in edges}
        best_profit = 0.0
        best_cycle = None
        for a in locations:
            for b in locations:
                if a == b:
                    continue
                w_ab = edge_map.get((a, b), -999)
                w_ba = edge_map.get((b, a), -999)
                cycle_profit = w_ab + w_ba
                if cycle_profit > best_profit:
                    best_profit = cycle_profit
                    best_cycle = [a, b, a]
        return best_cycle, best_profit

    def _reconstruct_cycle(self, pred, start, idx, locations) -> List[str]:
        n = len(locations)
        rev = {v: k for k, v in idx.items()}
        visited = set()
        node = start
        for _ in range(n):
            node = pred[node]
        cycle_start = node
        cycle = []
        while True:
            cycle.append(rev[node])
            node = pred[node]
            if node == cycle_start and cycle:
                cycle.append(rev[node])
                break
            if len(cycle) > n:
                break
        return cycle[::-1]

    def should_recalc_graph(self, state: LocationArbState) -> bool:
        """[7.3] Пересчитывать граф каждые 100 тиков."""
        state.graph_recalc_counter += 1
        if state.graph_recalc_counter > LOC_GRAPH_RECALC_TICKS:
            state.graph_recalc_counter = 0
            return True
        return False

    def close_route_if_cycle_gone(
        self,
        state: LocationArbState,
        route_key: str,
        cycle_exists: bool,
    ) -> bool:
        """[7.3] Если положительный цикл исчез → закрыть позиции."""
        route = state.routes.get(route_key)
        if route and route.active and not cycle_exists:
            route.active = False
            return True  # сигнал закрыть
        return False

    # [7.4] Inventory management
    def compute_buffer_size(self, loc_state: LocationState) -> float:
        """
        [7.4] Buffer size: мин = средний размер одной арб-сделки за последние 100 тиков.
        """
        hist = loc_state.arb_history[-LOC_BUFFER_WINDOW:]
        if not hist:
            return 1.0
        return sum(hist) / len(hist)

    # [7.4] Конвертация потребляет capacity и времени
    def update_inventory(
        self,
        state: LocationArbState,
        src: str,
        dst: str,
        size: int,
    ) -> None:
        """[7.4] Обновление inventory при конвертации."""
        src_loc = state.get_location(src)
        dst_loc = state.get_location(dst)
        # [7.4] Не опустошать локацию полностью
        src_loc.inventory -= size
        dst_loc.inventory += size
        src_loc.arb_history.append(size)
        if len(src_loc.arb_history) > LOC_BUFFER_WINDOW * 2:
            src_loc.arb_history = src_loc.arb_history[-LOC_BUFFER_WINDOW:]

    # [7.4] Восстановление inventory
    def cross_location_net_position(self, state: LocationArbState) -> float:
        """[7.4] Cross-location нетто-позиция учитывается в общем position limit."""
        return sum(ls.inventory for ls in state.locations.values())


