# SECTION 17 — STATE SERIALIZATION
# ==============================================================================

def save_arb_state(
    loc: LocationArbState,
    stat: StatArbState,
    cross: CrossProductState,
) -> str:
    def ps_dict(ps: PairState) -> dict:
        return {
            "spread_hist": ps.spread_history[-500:],
            "mean": ps.spread_mean, "std": ps.spread_std,
            "z": ps.z_score, "hr": ps.hedge_ratio,
            "kalman_x": ps.kalman.x_est, "kalman_P": ps.kalman.P_est,
            "kalman_init": ps.kalman.initialized,
            "johansen": ps.johansen_eigvec,
            "half_life": ps.half_life,
            "leg_imbal": ps.leg_imbalance_ticks,
            "struct_break": ps.structural_break,
            "pos": ps.position,
            "_sum": ps._sum, "_sum_sq": ps._sum_sq, "_n": ps._n,
        }
    payload = {
        "loc": {
            "locations": {k: {"inv": v.inventory, "active": v.active_arb}
                          for k, v in loc.locations.items()},
            "routes": {k: {"transport": v.transport_cost, "tariff": v.tariff,
                           "profit": v.current_profit, "active": v.active_arb}
                       for k, v in loc.routes.items()},
            "graph_counter": loc.graph_recalc_counter,
        },
        "stat": {k: ps_dict(v) for k, v in stat.pairs.items()},
        "cross": {
            name: {
                "cap_weight": ps.capacity_weight,
                "sharpe": ps.sharpe_estimate,
                "cy_corr": ps.cross_year_corr,
                "cy_active": ps.cross_year_active,
                "net_exp": ps.net_exposure,
            }
            for name, ps in cross.products.items()
        },
    }
    return json.dumps(payload)


def load_arb_state(data: str) -> Tuple[LocationArbState, StatArbState, CrossProductState]:
    loc   = LocationArbState()
    stat  = StatArbState()
    cross = CrossProductState()
    if not data:
        return loc, stat, cross
    try:
        p = json.loads(data)
    except Exception:
        return loc, stat, cross

    for k, d in p.get("loc", {}).get("locations", {}).items():
        ls = loc.get_location(k)
        ls.inventory = d.get("inv", 0.0); ls.active_arb = d.get("active", False)
    for k, d in p.get("loc", {}).get("routes", {}).items():
        rs = RouteState()
        rs.transport_cost = d.get("transport", 0.0); rs.tariff = d.get("tariff", 0.0)
        rs.current_profit = d.get("profit", 0.0); rs.active = d.get("active", False)
        loc.routes[k] = rs
    loc.graph_recalc_counter = p.get("loc", {}).get("graph_counter", 0)

    for k, d in p.get("stat", {}).items():
        ps = stat.get_pair(k)
        ps.spread_history = d.get("spread_hist", [])
        ps.spread_mean = d.get("mean", 0.0); ps.spread_std = d.get("std", 1.0)
        ps.z_score = d.get("z", 0.0); ps.hedge_ratio = d.get("hr", 1.0)
        ps.kalman.x_est = d.get("kalman_x", [0.0, 1.0])
        ps.kalman.P_est = d.get("kalman_P", [[1,0],[0,1]])
        ps.kalman.initialized = d.get("kalman_init", False)
        ps.johansen_eigvec = d.get("johansen", [])
        ps.half_life = d.get("half_life", 0.0)
        ps.leg_imbalance_ticks = d.get("leg_imbal", 0)
        ps.structural_break = d.get("struct_break", False)
        ps.position = d.get("pos", 0)
        ps._sum = d.get("_sum", 0.0); ps._sum_sq = d.get("_sum_sq", 0.0)
        ps._n = d.get("_n", 0)

    for name, d in p.get("cross", {}).items():
        ps = cross.get_product(name)
        ps.capacity_weight = d.get("cap_weight", 0.0)
        ps.sharpe_estimate = d.get("sharpe", 0.0)
        ps.cross_year_corr = d.get("cy_corr", 0.0)
        ps.cross_year_active = d.get("cy_active", False)
        ps.net_exposure = d.get("net_exp", 0.0)

    return loc, stat, cross


# ══════════════════════════════════════════════════════════════════════════════
# БЛОК 11.1 — ПРОДУКТЫ КОТОРЫЕ НЕЛЬЗЯ ТОРГОВАТЬ НЕЗАВИСИМО
# ══════════════════════════════════════════════════════════════════════════════


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.1  ПРОПОРЦИИ КОРЗИН
# PICNIC_BASKET1 = 6 CROISSANTS + 3 JAMS + 1 DJEMBES
# PICNIC_BASKET2 = другая пропорция — уточнять из документации раунда
# ─────────────────────────────────────────────────────────────────────────────

PB1_WEIGHTS: Dict[str, int] = {
    "CROISSANTS": 6,
    "JAMS":       3,
    "DJEMBES":    1,
}

PB2_WEIGHTS: Dict[str, int] = {
    "CROISSANTS": 4,    # P3/P4: PICNIC_BASKET2 = 4 Croissants + 2 Jams (no Djembes)
    "JAMS":       2,
}

# P2 historical data: GIFT_BASKET = 4*CHOCOLATE + 6*STRAWBERRY + 1*ROSES + 379
# Historical spread std ≈ 76
GIFT_BASKET_CONSTANT: int = 379
GIFT_BASKET_WEIGHTS: Dict[str, int] = {
    "CHOCOLATE":    4,
    "STRAWBERRIES": 6,
    "ROSES":        1,
}
GIFT_BASKET_Z_THRESHOLD: float = 2.0  # P2 2nd place: hardcoded z-score with rolling std

BASKET_WEIGHTS: Dict[str, Dict[str, int]] = {
    "PICNIC_BASKET1": PB1_WEIGHTS,
    "PICNIC_BASKET2": PB2_WEIGHTS,
    "GIFT_BASKET":    GIFT_BASKET_WEIGHTS,
}


def get_synthetic_value(
    basket: str,
    mid_prices: Dict[str, float],
) -> Optional[float]:
    """
    Считает синтетическую стоимость корзины из компонентов.
    Возвращает None если цены компонентов недоступны.
    """
    weights = BASKET_WEIGHTS.get(basket)
    if not weights:
        return None
    total = 0.0
    for product, qty in weights.items():
        price = mid_prices.get(product)
        if price is None:
            return None
        total += qty * price
    return total


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.2  ХЕДЖИРОВАНИЕ КОРЗИНЫ ЧЕРЕЗ КОМПОНЕНТЫ
# Если торгуешь корзину → хеджировать через компоненты в точной пропорции
# ─────────────────────────────────────────────────────────────────────────────

def compute_hedge_orders(
    basket: str,
    basket_qty: int,           # сколько корзин куплено/продано (+/-)
    current_positions: Dict[str, int],
    position_limits: Dict[str, int],
) -> Dict[str, int]:
    """
    Возвращает словарь {component: qty_to_trade} для хеджирования корзинной позиции.
    basket_qty > 0 → купили корзину → нужно продать компоненты
    basket_qty < 0 → продали корзину → нужно купить компоненты
    """
    weights = BASKET_WEIGHTS.get(basket, {})
    hedge_orders: Dict[str, int] = {}

    for component, weight in weights.items():
        # хедж: противоположный знак к корзине
        raw_qty = -basket_qty * weight
        current = current_positions.get(component, 0)
        limit = position_limits.get(component, 0)

        # не превышать лимит
        new_pos = current + raw_qty
        if new_pos > limit:
            raw_qty = limit - current
        elif new_pos < -limit:
            raw_qty = -limit - current

        if raw_qty != 0:
            hedge_orders[component] = raw_qty

    return hedge_orders


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.3  УЧЁТ ВОЗДЕЙСТВИЯ КОМПОНЕНТОВ НА КОРЗИНУ
# Если торгуешь компоненты → учитывать суммарное воздействие на корзину
# ─────────────────────────────────────────────────────────────────────────────

def component_basket_exposure(
    component: str,
    component_qty: int,
    basket: str,
) -> float:
    """
    Сколько "корзинных единиц" эквивалентно component_qty единиц компонента.
    Используется для расчёта суммарного exposure.
    """
    weights = BASKET_WEIGHTS.get(basket, {})
    weight = weights.get(component, 0)
    if weight == 0:
        return 0.0
    return component_qty / weight


def total_basket_exposure(
    positions: Dict[str, int],
    basket: str,
) -> float:
    """
    Суммарный exposure корзины с учётом позиций в компонентах.
    Возвращает эквивалентное кол-во корзин (может быть дробным — leg risk).
    """
    weights = BASKET_WEIGHTS.get(basket, {})
    exposures = []
    for component, weight in weights.items():
        pos = positions.get(component, 0)
        exposures.append(pos / weight if weight != 0 else 0.0)
    if not exposures:
        return 0.0
    return min(exposures, key=abs)  # консервативная оценка по binding компоненту


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.4  BINDING CONSTRAINT — ЛИМИТ КОМПОНЕНТА ОГРАНИЧИВАЕТ КОРЗИНУ
# Если лимит достигнут на одном компоненте → обрезать всю позицию корзины
# ─────────────────────────────────────────────────────────────────────────────

POSITION_LIMITS: Dict[str, int] = {
    # Round 1 (P3/P4 confirmed from backtester)
    "RAINFOREST_RESIN":              50,
    "KELP":                          50,
    "SQUID_INK":                     50,
    # Round 2
    "CROISSANTS":                    250,
    "JAMS":                          350,
    "DJEMBES":                       60,
    "PICNIC_BASKET1":                60,
    "PICNIC_BASKET2":                100,
    # Round 3 — per-strike vouchers (P3 backtester confirmed)
    "VOLCANIC_ROCK":                 400,
    "VOLCANIC_ROCK_VOUCHER_9500":    200,
    "VOLCANIC_ROCK_VOUCHER_9750":    200,
    "VOLCANIC_ROCK_VOUCHER_10000":   200,
    "VOLCANIC_ROCK_VOUCHER_10250":   200,
    "VOLCANIC_ROCK_VOUCHER_10500":   200,
    "VOLCANIC_ROCK_VOUCHER":         200,  # fallback generic
    # Round 4+ (P2 legacy)
    "COCONUT":                       300,
    "COCONUT_COUPON":                600,
    # Round 5
    "MAGNIFICENT_MACARONS":          75,
    # P4 new products
    "TOMATOES":                      50,
    "EMERALDS":                      50,
}

SOFT_LIMITS: Dict[str, int] = {
    "RAINFOREST_RESIN":      40,
    "KELP":                  30,
    "SQUID_INK":             25,
    "CROISSANTS":            175,
    "JAMS":                  245,
    "DJEMBES":               42,
    "PICNIC_BASKET1":        42,
    "PICNIC_BASKET2":        70,
    "COCONUT":               225,
    "COCONUT_COUPON":        450,
    "VOLCANIC_ROCK":         280,
    "VOLCANIC_ROCK_VOUCHER": 150,
    "MAGNIFICENT_MACARONS":  55,
}


def max_basket_size(
    basket: str,
    current_positions: Dict[str, int],
    direction: int,  # +1 buy basket, -1 sell basket
) -> int:
    """
    Максимально допустимый размер сделки по корзине с учётом лимитов компонентов.
    Binding constraint = компонент с наименьшим доступным запасом.
    """
    weights = BASKET_WEIGHTS.get(basket, {})
    if not weights:
        return 0

    max_sizes = []
    for component, weight in weights.items():
        current = current_positions.get(component, 0)
        limit = POSITION_LIMITS.get(component, 0)
        # хедж компонентов противоположен направлению корзины
        hedge_dir = -direction
        if hedge_dir > 0:
            available = limit - current
        else:
            available = limit + current
        max_basket = available // weight
        max_sizes.append(max(0, max_basket))

    # также учитываем лимит самой корзины
    basket_current = current_positions.get(basket, 0)
    basket_limit = POSITION_LIMITS.get(basket, 0)
    if direction > 0:
        basket_available = basket_limit - basket_current
    else:
        basket_available = basket_limit + basket_current
    max_sizes.append(max(0, basket_available))

    return min(max_sizes)


def is_component_limit_breached(
    basket: str,
    current_positions: Dict[str, int],
) -> Tuple[bool, Optional[str]]:
    """
    Проверяет достигнут ли лимит любого компонента корзины.
    Возвращает (breached, binding_component).
    """
    weights = BASKET_WEIGHTS.get(basket, {})
    for component in weights:
        pos = abs(current_positions.get(component, 0))
        limit = POSITION_LIMITS.get(component, 0)
        if pos >= limit:
            return True, component
    return False, None


def trim_basket_position(
    basket: str,
    current_positions: Dict[str, int],
) -> Dict[str, int]:
    """
    Обрезает всю позицию корзины и хеджирующих компонентов до нуля.
    Вызывать при breach лимита компонента.
    Возвращает ордера на закрытие.
    """
    close_orders: Dict[str, int] = {}

    # закрыть корзину
    basket_pos = current_positions.get(basket, 0)
    if basket_pos != 0:
        close_orders[basket] = -basket_pos

    # закрыть компоненты
    weights = BASKET_WEIGHTS.get(basket, {})
    for component in weights:
        comp_pos = current_positions.get(component, 0)
        if comp_pos != 0:
            close_orders[component] = -comp_pos

    return close_orders


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.5  LEG RISK — АСИНХРОННОЕ ДВИЖЕНИЕ КОРЗИНЫ И КОМПОНЕНТОВ
# ─────────────────────────────────────────────────────────────────────────────

LEG_RISK_THRESHOLD = 0.05  # 5% расхождение synthetic vs basket = опасность

def compute_leg_risk(
    basket: str,
    basket_price: float,
    mid_prices: Dict[str, float],
) -> Optional[float]:
    """
    Возвращает относительное расхождение между ценой корзины и synthetic.
    Положительное = корзина дороже synthetic (опасность для long basket).
    None если данных недостаточно.
    """
    synthetic = get_synthetic_value(basket, mid_prices)
    if synthetic is None or synthetic == 0:
        return None
    return (basket_price - synthetic) / synthetic


def is_leg_risk_exceeded(
    basket: str,
    basket_price: float,
    mid_prices: Dict[str, float],
    threshold: float = LEG_RISK_THRESHOLD,
) -> bool:
    risk = compute_leg_risk(basket, basket_price, mid_prices)
    if risk is None:
        return False
    return abs(risk) > threshold


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.6  ПРИОРИТЕТ ЗАКРЫТИЯ ПРИ EMERGENCY
# Сначала корзина, потом компоненты
# ─────────────────────────────────────────────────────────────────────────────

def emergency_close_sequence(
    basket: str,
    current_positions: Dict[str, int],
) -> List[Tuple[str, int]]:
    """
    Возвращает последовательность закрытия: [(product, qty), ...]
    Порядок: 1) корзина, 2) компоненты.
    """
    sequence: List[Tuple[str, int]] = []

    # 1. сначала корзина
    basket_pos = current_positions.get(basket, 0)
    if basket_pos != 0:
        sequence.append((basket, -basket_pos))

    # 2. потом компоненты
    weights = BASKET_WEIGHTS.get(basket, {})
    for component in weights:
        comp_pos = current_positions.get(component, 0)
        if comp_pos != 0:
            sequence.append((component, -comp_pos))

    return sequence


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.7  DELTA HEDGE — COCONUT_COUPON → COCONUT
# Delta hedge coupon через COCONUT позицию
# Нельзя торговать coupon без учёта coconut exposure
# ─────────────────────────────────────────────────────────────────────────────


DELTA_BAND       = 5      # rebalance если delta изменилась > ±5
COCONUT_K        = None   # страйк — уточнять из документации
COCONUT_T        = None   # время до экспирации — уточнять
COCONUT_IV       = None   # implied vol — калибровать на первых 500 тиках


def bs_delta(S: float, K: float, T: float, sigma: float, r: float = 0.0) -> float:
    """
    Black-Scholes delta для call опциона.
    """
    if T <= 0 or sigma <= 0:
        return 1.0 if S >= K else 0.0
    d1 = (math.log(S / K) + (r + 0.5 * sigma ** 2) * T) / (sigma * math.sqrt(T))
    return 0.5 * (1 + math.erf(d1 / math.sqrt(2)))


def bs_price(S: float, K: float, T: float, sigma: float, r: float = 0.0) -> float:
    """
    Black-Scholes цена call опциона.
    """
    if T <= 0:
        return max(0.0, S - K)
    d1 = (math.log(S / K) + (r + 0.5 * sigma ** 2) * T) / (sigma * math.sqrt(T))
    d2 = d1 - sigma * math.sqrt(T)
    nd1 = 0.5 * (1 + math.erf(d1 / math.sqrt(2)))
    nd2 = 0.5 * (1 + math.erf(d2 / math.sqrt(2)))
    return S * nd1 - K * math.exp(-r * T) * nd2


def compute_coupon_delta(
    coconut_price: float,
    K: Optional[float] = COCONUT_K,
    T: Optional[float] = COCONUT_T,
    sigma: Optional[float] = COCONUT_IV,
) -> Optional[float]:
    """
    Считает delta COCONUT_COUPON.
    Возвращает None если параметры не откалиброваны.
    """
    if K is None or T is None or sigma is None:
        return None
    return bs_delta(coconut_price, K, T, sigma)


def required_coconut_hedge(
    coupon_position: int,
    coconut_price: float,
    K: Optional[float] = COCONUT_K,
    T: Optional[float] = COCONUT_T,
    sigma: Optional[float] = COCONUT_IV,
) -> Optional[int]:
    """
    Сколько COCONUT нужно держать для delta hedge coupon позиции.
    coupon_position > 0 → long call → нужно short coconut
    Возвращает None если delta не вычислить.
    """
    delta = compute_coupon_delta(coconut_price, K, T, sigma)
    if delta is None:
        return None
    return -round(coupon_position * delta)


def coconut_hedge_order(
    coupon_position: int,
    current_coconut_position: int,
    coconut_price: float,
    last_delta: Optional[float],
    K: Optional[float] = COCONUT_K,
    T: Optional[float] = COCONUT_T,
    sigma: Optional[float] = COCONUT_IV,
    delta_band: int = DELTA_BAND,
) -> Tuple[Optional[int], Optional[float]]:
    """
    Возвращает (coconut_order, new_delta).
    coconut_order = None если rebalance не нужен.
    Rebalance только если delta изменилась > delta_band.
    """
    delta = compute_coupon_delta(coconut_price, K, T, sigma)
    if delta is None:
        return None, last_delta

    target_coconut = -round(coupon_position * delta)
    order_qty = target_coconut - current_coconut_position

    # проверяем delta band — не ребалансировать при малых изменениях
    if last_delta is not None:
        delta_change = abs(delta - last_delta) * abs(coupon_position)
        if delta_change < delta_band:
            return None, last_delta

    # проверяем лимит COCONUT
    limit = POSITION_LIMITS.get("COCONUT", 300)
    new_pos = current_coconut_position + order_qty
    if new_pos > limit:
        order_qty = limit - current_coconut_position
    elif new_pos < -limit:
        order_qty = -limit - current_coconut_position

    return (order_qty if order_qty != 0 else None), delta


def validate_coupon_trade(
    coupon_qty: int,
    coupon_position: int,
    coconut_position: int,
    coconut_price: float,
) -> bool:
    """
    Нельзя торговать coupon без учёта coconut exposure.
    Проверяет что после сделки coconut hedge останется в лимите.
    """
    new_coupon_pos = coupon_position + coupon_qty
    required = required_coconut_hedge(new_coupon_pos, coconut_price)
    if required is None:
        return False  # не можем захеджировать — не торгуем
    limit = POSITION_LIMITS.get("COCONUT", 300)
    return abs(required) <= limit


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.8  DELTA HEDGE — VOLCANIC_ROCK_VOUCHER → VOLCANIC_ROCK
# Delta hedge voucher через VOLCANIC_ROCK позицию
# Нельзя торговать voucher без учёта volcanic_rock exposure
# Суммарный net delta по ВСЕМ страйкам → хеджировать через VOLCANIC_ROCK
# ─────────────────────────────────────────────────────────────────────────────

VOUCHER_MAX_NET  = 400    # суммарный лимит по всем страйкам нетто
VOUCHER_T        = None   # время до экспирации — уточнять
VOUCHER_STRIKES  = None   # список страйков — уточнять из документации


def compute_voucher_net_delta(
    voucher_positions: Dict[str, int],   # {strike_key: position}
    volcanic_price: float,
    strikes: Dict[str, float],           # {strike_key: K}
    T: Optional[float],
    sigma_surface: Dict[str, float],     # {strike_key: implied_vol}
) -> Optional[float]:
    """
    Суммарный net delta по всем страйкам VOLCANIC_ROCK_VOUCHER.
    Возвращает None если данных недостаточно.
    """
    if T is None:
        return None
    total_delta = 0.0
    for strike_key, position in voucher_positions.items():
        K = strikes.get(strike_key)
        sigma = sigma_surface.get(strike_key)
        if K is None or sigma is None:
            return None
        delta = bs_delta(volcanic_price, K, T, sigma)
        total_delta += position * delta
    return total_delta


def volcanic_rock_hedge_order(
    voucher_positions: Dict[str, int],
    current_volcanic_position: int,
    volcanic_price: float,
    strikes: Dict[str, float],
    T: Optional[float],
    sigma_surface: Dict[str, float],
    last_net_delta: Optional[float],
    delta_band: int = DELTA_BAND,
) -> Tuple[Optional[int], Optional[float]]:
    """
    Возвращает (volcanic_rock_order, new_net_delta).
    Хеджирует суммарный net delta всех страйков через VOLCANIC_ROCK.
    """
    net_delta = compute_voucher_net_delta(
        voucher_positions, volcanic_price, strikes, T, sigma_surface
    )
    if net_delta is None:
        return None, last_net_delta

    target_volcanic = -round(net_delta)
    order_qty = target_volcanic - current_volcanic_position

    # проверяем delta band
    if last_net_delta is not None:
        delta_change = abs(net_delta - last_net_delta)
        if delta_change < delta_band:
            return None, last_net_delta

    # проверяем лимит VOLCANIC_ROCK
    limit = POSITION_LIMITS.get("VOLCANIC_ROCK", 400)
    new_pos = current_volcanic_position + order_qty
    if new_pos > limit:
        order_qty = limit - current_volcanic_position
    elif new_pos < -limit:
        order_qty = -limit - current_volcanic_position

    return (order_qty if order_qty != 0 else None), net_delta


def validate_voucher_trade(
    strike_key: str,
    voucher_qty: int,
    voucher_positions: Dict[str, int],
    current_volcanic_position: int,
    volcanic_price: float,
    strikes: Dict[str, float],
    T: Optional[float],
    sigma_surface: Dict[str, float],
) -> bool:
    """
    Нельзя торговать voucher без учёта volcanic_rock exposure.
    Проверяет что после сделки:
    1. Суммарный нетто по всем страйкам ≤ VOUCHER_MAX_NET
    2. Требуемый volcanic_rock hedge в лимите
    """
    new_positions = dict(voucher_positions)
    new_positions[strike_key] = new_positions.get(strike_key, 0) + voucher_qty

    # 1. суммарный нетто
    total_net = sum(abs(p) for p in new_positions.values())
    if total_net > VOUCHER_MAX_NET:
        return False

    # 2. volcanic_rock hedge в лимите
    net_delta = compute_voucher_net_delta(
        new_positions, volcanic_price, strikes, T, sigma_surface
    )
    if net_delta is None:
        return False
    required_hedge = abs(round(net_delta))
    limit = POSITION_LIMITS.get("VOLCANIC_ROCK", 400)
    return required_hedge <= limit


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.9  СУММАРНЫЙ НЕТТО POSITION LIMIT ПРИ ОДНОВРЕМЕННОЙ ТОРГОВЛЕ
# Считать нетто: basket + компоненты вместе
# ─────────────────────────────────────────────────────────────────────────────

def compute_net_exposure(
    basket: str,
    positions: Dict[str, int],
) -> Dict[str, float]:
    """
    Считает нетто exposure по каждому компоненту с учётом позиции в корзине.
    Позиция в корзине конвертируется в эквивалентные компоненты.
    """
    weights = BASKET_WEIGHTS.get(basket, {})
    basket_pos = positions.get(basket, 0)
    net: Dict[str, float] = {}

    for component, weight in weights.items():
        component_pos = positions.get(component, 0)
        basket_component_equiv = basket_pos * weight  # сколько компонентов эквивалентно
        net[component] = component_pos + basket_component_equiv

    return net


def check_net_limits(
    basket: str,
    positions: Dict[str, int],
) -> Dict[str, bool]:
    """
    Проверяет нетто позиции по всем компонентам.
    Возвращает {component: within_limit}.
    """
    net = compute_net_exposure(basket, positions)
    result = {}
    for component, net_pos in net.items():
        limit = POSITION_LIMITS.get(component, 0)
        result[component] = abs(net_pos) <= limit
    return result


def max_basket_net_size(
    basket: str,
    positions: Dict[str, int],
    direction: int,  # +1 buy, -1 sell
) -> int:
    """
    Максимальный размер сделки по корзине с учётом нетто лимитов.
    """
    weights = BASKET_WEIGHTS.get(basket, {})
    max_sizes = []

    for component, weight in weights.items():
        component_pos = positions.get(component, 0)
        basket_pos = positions.get(basket, 0)
        limit = POSITION_LIMITS.get(component, 0)

        # нетто exposure после сделки на 1 единицу корзины
        # покупка корзины = добавляет +weight к net component exposure
        net_current = component_pos + basket_pos * weight
        net_per_basket = direction * weight
        available = (limit - net_current) / net_per_basket if net_per_basket > 0 else \
                    (-limit - net_current) / net_per_basket if net_per_basket < 0 else float('inf')
        max_sizes.append(max(0, int(available)))

    # лимит самой корзины
    basket_pos = positions.get(basket, 0)
    basket_limit = POSITION_LIMITS.get(basket, 0)
    if direction > 0:
        max_sizes.append(max(0, basket_limit - basket_pos))
    else:
        max_sizes.append(max(0, basket_limit + basket_pos))

    return min(max_sizes) if max_sizes else 0


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.10  ГЛАВНЫЙ КОНТРОЛЛЕР СВЯЗАННЫХ ПРОДУКТОВ
# Единая точка входа для всех проверок перед отправкой ордера
# ─────────────────────────────────────────────────────────────────────────────

class LinkedProductController:
    """
    Контролирует торговлю связанными продуктами.
    Используется внутри Trader.run() перед каждым ордером.
    """

    def __init__(self):
        self.positions: Dict[str, int] = defaultdict(int)
        self.coupon_last_delta: Optional[float] = None
        self.voucher_last_net_delta: Optional[float] = None
        self.voucher_positions: Dict[str, int] = defaultdict(int)

    def update_positions(self, new_positions: Dict[str, int]):
        self.positions.update(new_positions)

    # ── BASKET ────────────────────────────────────────────────────────────────

    def can_trade_basket(self, basket: str, qty: int) -> bool:
        direction = 1 if qty > 0 else -1
        max_size = max_basket_size(basket, self.positions, direction)
        return abs(qty) <= max_size

    def get_basket_hedge(self, basket: str, basket_qty: int) -> Dict[str, int]:
        return compute_hedge_orders(basket, basket_qty, self.positions, POSITION_LIMITS)

    def check_emergency(self, basket: str) -> bool:
        breached, _ = is_component_limit_breached(basket, self.positions)
        return breached

    def emergency_close(self, basket: str) -> List[Tuple[str, int]]:
        return emergency_close_sequence(basket, self.positions)

    def get_leg_risk(self, basket: str, basket_price: float, mid_prices: Dict[str, float]) -> Optional[float]:
        return compute_leg_risk(basket, basket_price, mid_prices)

    # ── COCONUT_COUPON ────────────────────────────────────────────────────────

    def can_trade_coupon(self, qty: int, coconut_price: float) -> bool:
        return validate_coupon_trade(
            qty,
            self.positions.get("COCONUT_COUPON", 0),
            self.positions.get("COCONUT", 0),
            coconut_price,
        )

    def get_coupon_hedge(self, coconut_price: float) -> Tuple[Optional[int], Optional[float]]:
        order, new_delta = coconut_hedge_order(
            coupon_position=self.positions.get("COCONUT_COUPON", 0),
            current_coconut_position=self.positions.get("COCONUT", 0),
            coconut_price=coconut_price,
            last_delta=self.coupon_last_delta,
        )
        self.coupon_last_delta = new_delta
        return order, new_delta

    # ── VOLCANIC_ROCK_VOUCHER ─────────────────────────────────────────────────

    def can_trade_voucher(
        self,
        strike_key: str,
        qty: int,
        volcanic_price: float,
        strikes: Dict[str, float],
        T: Optional[float],
        sigma_surface: Dict[str, float],
    ) -> bool:
        return validate_voucher_trade(
            strike_key, qty,
            dict(self.voucher_positions),
            self.positions.get("VOLCANIC_ROCK", 0),
            volcanic_price, strikes, T, sigma_surface,
        )

    def get_voucher_hedge(
        self,
        volcanic_price: float,
        strikes: Dict[str, float],
        T: Optional[float],
        sigma_surface: Dict[str, float],
    ) -> Tuple[Optional[int], Optional[float]]:
        order, new_delta = volcanic_rock_hedge_order(
            voucher_positions=dict(self.voucher_positions),
            current_volcanic_position=self.positions.get("VOLCANIC_ROCK", 0),
            volcanic_price=volcanic_price,
            strikes=strikes,
            T=T,
            sigma_surface=sigma_surface,
            last_net_delta=self.voucher_last_net_delta,
        )
        self.voucher_last_net_delta = new_delta
        return order, new_delta

    # ── NET EXPOSURE ──────────────────────────────────────────────────────────

    def get_net_exposure(self, basket: str) -> Dict[str, float]:
        return compute_net_exposure(basket, self.positions)

    def check_net_limits(self, basket: str) -> Dict[str, bool]:
        return check_net_limits(basket, self.positions)

    def max_net_basket_size(self, basket: str, direction: int) -> int:
        return max_basket_net_size(basket, self.positions, direction)

    def can_trade_basket_soft(self, basket: str, qty: int) -> bool:
        direction = 1 if qty > 0 else -1
        max_size = max_basket_size_soft(basket, self.positions, direction)
        return abs(qty) <= max_size

    def can_trade_voucher_with_checks(
        self,
        strike_key: str,
        qty: int,
        volcanic_price: float,
        strikes: Dict[str, float],
        T: Optional[float],
        sigma_surface: Dict[str, float],
        market_iv: float,
        model_iv: float,
        capital: float,
        prices: Dict[str, float],
    ) -> Tuple[bool, str]:
        """
        Полная проверка перед торговлей voucher:
        1. ATM/OTM фильтр
        2. Min edge IV
        3. Vega limit
        4. Position / delta hedge
        Возвращает (allowed, reason).
        """
        if not is_voucher_tradeable(strike_key, volcanic_price, strikes):
            return False, "deep_otm"
        if not has_min_edge(market_iv, model_iv):
            return False, "insufficient_edge"
        if not check_vega_limit(
            dict(self.voucher_positions), prices, sigma_surface, capital
        ):
            return False, "vega_limit_exceeded"
        if not self.can_trade_voucher(
            strike_key, qty, volcanic_price, strikes, T, sigma_surface
        ):
            return False, "position_or_delta_limit"
        return True, "ok"


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.11  SOFT LIMIT ВЕРСИЯ max_basket_size
# ─────────────────────────────────────────────────────────────────────────────

def max_basket_size_soft(
    basket: str,
    current_positions: Dict[str, int],
    direction: int,
) -> int:
    """
    Как max_basket_size, но использует SOFT_LIMITS вместо POSITION_LIMITS.
    Используется для входа в позицию (не для аварийного закрытия).
    """
    weights = BASKET_WEIGHTS.get(basket, {})
    if not weights:
        return 0

    max_sizes = []
    for component, weight in weights.items():
        current = current_positions.get(component, 0)
        soft = SOFT_LIMITS.get(component, 0)
        hedge_dir = -direction
        if hedge_dir > 0:
            available = soft - current
        else:
            available = soft + current
        max_basket = available // weight
        max_sizes.append(max(0, max_basket))

    basket_current = current_positions.get(basket, 0)
    basket_soft = SOFT_LIMITS.get(basket, 0)
    if direction > 0:
        basket_available = basket_soft - basket_current
    else:
        basket_available = basket_soft + basket_current
    max_sizes.append(max(0, basket_available))

    return min(max_sizes)


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.12  ATM/OTM ФИЛЬТР ДЛЯ VOUCHER
# Глубокие OTM не торговать
# ─────────────────────────────────────────────────────────────────────────────

ATM_OTM_MAX_DISTANCE: Optional[float] = None  # уточнять из документации раунда
ATM_OTM_MAX_LOG_MONEYNESS: float = 0.15        # fallback: |log(S/K)| > 0.15 = глубокий OTM


def is_voucher_tradeable(
    strike_key: str,
    volcanic_price: float,
    strikes: Dict[str, float],
    max_distance: Optional[float] = ATM_OTM_MAX_DISTANCE,
    max_log_moneyness: float = ATM_OTM_MAX_LOG_MONEYNESS,
) -> bool:
    """
    Возвращает True если страйк ATM или ближайший OTM — торговать разрешено.
    Возвращает False если глубокий OTM — не торговать.
    Использует abs(log(S/K)) как меру монейнеса.
    """
    K = strikes.get(strike_key)
    if K is None or K <= 0 or volcanic_price <= 0:
        return False

    log_moneyness = abs(math.log(volcanic_price / K))

    if max_distance is not None:
        return log_moneyness <= max_distance
    return log_moneyness <= max_log_moneyness


def filter_tradeable_strikes(
    volcanic_price: float,
    strikes: Dict[str, float],
    max_distance: Optional[float] = ATM_OTM_MAX_DISTANCE,
) -> List[str]:
    """
    Возвращает список страйков разрешённых для торговли.
    """
    return [
        sk for sk in strikes
        if is_voucher_tradeable(sk, volcanic_price, strikes, max_distance)
    ]


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.13  VEGA LIMIT CHECK
# Суммарная vega ≤ 30% капитала
# ─────────────────────────────────────────────────────────────────────────────

VEGA_LIMIT_PCT: float = 0.30  # vega ≤ 30% капитала


def bs_vega(S: float, K: float, T: float, sigma: float) -> float:
    """
    Black-Scholes vega: чувствительность цены к изменению vol на 1 пункт.
    """
    if T <= 0 or sigma <= 0 or S <= 0 or K <= 0:
        return 0.0
    d1 = (math.log(S / K) + 0.5 * sigma ** 2 * T) / (sigma * math.sqrt(T))
    phi = math.exp(-0.5 * d1 ** 2) / math.sqrt(2 * math.pi)
    return S * phi * math.sqrt(T)


def compute_total_vega(
    positions: Dict[str, int],        # {strike_key: position}
    underlying_price: float,
    strikes: Dict[str, float],        # {strike_key: K}
    T: Optional[float],
    sigma_surface: Dict[str, float],  # {strike_key: implied_vol}
) -> Optional[float]:
    """
    Суммарная vega по всем опционным позициям.
    Возвращает None если данных недостаточно.
    """
    if T is None:
        return None
    total_vega = 0.0
    for strike_key, position in positions.items():
        K = strikes.get(strike_key)
        sigma = sigma_surface.get(strike_key)
        if K is None or sigma is None:
            return None
        vega = bs_vega(underlying_price, K, T, sigma)
        total_vega += abs(position) * vega
    return total_vega


def check_vega_limit(
    positions: Dict[str, int],
    prices: Dict[str, float],         # {strike_key: option_price}
    sigma_surface: Dict[str, float],
    capital: float,
    limit_pct: float = VEGA_LIMIT_PCT,
    underlying_price: Optional[float] = None,
    strikes: Optional[Dict[str, float]] = None,
    T: Optional[float] = None,
) -> bool:
    """
    Проверяет что суммарная vega ≤ limit_pct × капитал.
    """
    if capital <= 0:
        return False
    if underlying_price is None or strikes is None or T is None:
        return True  # нет данных — пропускаем проверку
    total_vega = compute_total_vega(positions, underlying_price, strikes, T, sigma_surface)
    if total_vega is None:
        return True  # нет данных — пропускаем
    return total_vega <= limit_pct * capital


# ─────────────────────────────────────────────────────────────────────────────
# 11.1.14  MIN EDGE IV CHECK
# Торговать только если |IV расхождение| > min_edge
# ─────────────────────────────────────────────────────────────────────────────

MIN_EDGE_IV: float = 2.0  # мин edge в IV пунктах (%)


def has_min_edge(
    market_iv: float,
    model_iv: float,
    min_edge: float = MIN_EDGE_IV,
) -> bool:
    """
    Торговать только если расхождение market IV vs model IV > min_edge пунктов.
    market_iv > model_iv + min_edge → продавать (IV завышена)
    market_iv < model_iv - min_edge → покупать (IV занижена)
    """
    return abs(market_iv - model_iv) > min_edge


def iv_trade_direction(
    market_iv: float,
    model_iv: float,
    min_edge: float = MIN_EDGE_IV,
) -> Optional[int]:
    """
    Возвращает направление торговли по IV арб:
    +1 → buy option (gamma scalping, IV занижена)
    -1 → sell option (theta harvesting, IV завышена)
    None → нет edge
    """
    if market_iv > model_iv + min_edge:
        return -1  # sell
    if market_iv < model_iv - min_edge:
        return +1  # buy
    return None 

