# ==============================================================================
# БЛОК: KILL SWITCH  §36
# Если PnL упал ниже threshold → остановить все ордера.
# Флаг в traderData, логирование, manual override.
# ==============================================================================

class KillSwitch:
    """
    §36 — Kill switch / аварийное закрытие позиций.
    Условие: если PnL упал ниже threshold → остановить все ордера.
    Vol-based: включать при экстремальной волатильности.
    Реализация: flag в traderData.
    Уведомление: логировать момент срабатывания.
    Manual override: возможность включить обратно вручную.
    """

    # Параметры (калибровать по раунду)
    # NOTE: self.pnl tracks cash_flow (not M2M PnL), so threshold must account
    # for unrealized positions. 500k covers typical multi-product portfolio.
    PNL_THRESHOLD       = -500000.0  # PnL ниже этого уровня → kill
    VOL_THRESHOLD       = 30.0       # σ выше этого уровня (в % от fair value) → vol kill
    DRAWDOWN_WINDOW     = 50         # тиков для drawdown расчёта
    DRAWDOWN_THRESHOLD  = -500000.0  # drawdown за окно → kill

    def __init__(self):
        self.active:        bool         = False   # текущий статус kill switch
        self.reason:        str          = ""
        self.activated_tick: int         = -1
        self.pnl_history:   list[float]  = []      # rolling window
        self._override:     bool         = False   # manual override (force off)

    # ── Обновление и проверка ──────────────────────────────────────────────────

    def update(self, tick: int, total_pnl: float,
               realized_vol: float, fair_value: float) -> bool:
        """
        Вызывать каждый тик.
        Возвращает True если kill switch активен (не торговать).
        """
        if self._override:
            self.active = False
            return False

        self.pnl_history.append(total_pnl)
        # §15.1.2 rolling cap
        if len(self.pnl_history) > self.DRAWDOWN_WINDOW * 2:
            self.pnl_history = self.pnl_history[-self.DRAWDOWN_WINDOW * 2:]

        # 1. Абсолютный PnL порог
        if total_pnl < self.PNL_THRESHOLD:
            self._activate(tick, f"PnL={total_pnl:.1f} < threshold={self.PNL_THRESHOLD}")
            return True

        # 2. Drawdown за окно
        if len(self.pnl_history) >= self.DRAWDOWN_WINDOW:
            window_start = self.pnl_history[-self.DRAWDOWN_WINDOW]
            drawdown = total_pnl - window_start
            if drawdown < self.DRAWDOWN_THRESHOLD:
                self._activate(tick, f"drawdown={drawdown:.1f} < threshold={self.DRAWDOWN_THRESHOLD}")
                return True

        # 3. Vol-based kill switch §36
        fv_safe = max(fair_value, 1.0)
        vol_pct = realized_vol / fv_safe * 100
        if vol_pct > self.VOL_THRESHOLD:
            self._activate(tick, f"vol={vol_pct:.2f}% > threshold={self.VOL_THRESHOLD}%")
            return True

        # Автоматически деактивировать если условия пропали
        if self.active:
            self.active = False
            self.reason = ""
        return False

    def _activate(self, tick: int, reason: str):
        if not self.active:
            self.active        = True
            self.reason        = reason
            self.activated_tick = tick
            # Логирование момента срабатывания
            logger.log(tick, "ALL", "KILL_SWITCH",
                       extra=f"ACTIVATED reason={reason}")

    def manual_override(self, force_off: bool = True):
        """Manual override: принудительно выключить kill switch."""
        self._override = force_off
        if force_off:
            self.active = False
            logger.log(-1, "ALL", "KILL_SWITCH", extra="MANUAL_OVERRIDE force_off=True")

    def should_trade(self) -> bool:
        return not self.active

    def to_dict(self) -> dict:
        return {"ks_active": self.active, "ks_reason": self.reason,
                "ks_tick": self.activated_tick}

    def from_dict(self, d: dict):
        self.active          = d.get("ks_active", False)
        self.reason          = d.get("ks_reason", "")
        self.activated_tick  = d.get("ks_tick", -1)


class DrawdownController:
    """[13.1] Per-instrument drawdown controller.
    Freezes individual instruments when loss exceeds per-instrument limit.
    Freezes ALL trading when daily drawdown limit is breached.

    Separate from KillSwitch — KillSwitch is global/portfolio level.
    DrawdownController is per-instrument granular control.
    """
    MAX_DAILY_LOSS_PCT: float = 0.90  # Freeze ALL if total loss > 90% of peak
    MAX_PER_INSTRUMENT_LOSS: float = 500000.0  # Freeze instrument if loss > 500k
    DRAWDOWN_WINDOW: int = 200  # ticks for rolling high-water

    def __init__(self):
        self._instrument_high_water: dict[str, float] = {}
        self._portfolio_high_water: float = 0.0
        self._frozen_instruments: set[str] = set()
        self._all_frozen: bool = False
        self._freeze_reason: dict[str, str] = {}

    def update(self, instrument_pnls: dict[str, float], total_pnl: float, tick: int):
        """Update drawdown state. Call every tick with current PnL per instrument."""
        # Update portfolio high-water
        if total_pnl > self._portfolio_high_water:
            self._portfolio_high_water = total_pnl

        # Check global drawdown
        if self._portfolio_high_water > 0:
            drawdown_pct = (self._portfolio_high_water - total_pnl) / self._portfolio_high_water
            if drawdown_pct > self.MAX_DAILY_LOSS_PCT:
                self._all_frozen = True
                self._freeze_reason["ALL"] = (
                    f"Portfolio drawdown {drawdown_pct*100:.1f}% > {self.MAX_DAILY_LOSS_PCT*100:.0f}%"
                )

        # Check per-instrument
        for instrument, pnl in instrument_pnls.items():
            if pnl > self._instrument_high_water.get(instrument, pnl):
                self._instrument_high_water[instrument] = pnl
            hw = self._instrument_high_water.get(instrument, 0.0)
            loss = hw - pnl
            if loss > self.MAX_PER_INSTRUMENT_LOSS:
                self._frozen_instruments.add(instrument)
                self._freeze_reason[instrument] = (
                    f"Loss {loss:.0f} > limit {self.MAX_PER_INSTRUMENT_LOSS}"
                )

    def can_trade(self, instrument: str) -> bool:
        """Returns True if instrument can be traded."""
        if self._all_frozen:
            return False
        return instrument not in self._frozen_instruments

    def unfreeze(self, instrument: str):
        """Manually unfreeze an instrument (after manual review)."""
        self._frozen_instruments.discard(instrument)
        self._freeze_reason.pop(instrument, None)

    def unfreeze_all(self):
        self._frozen_instruments.clear()
        self._all_frozen = False
        self._freeze_reason.clear()

    def status(self) -> dict:
        return {
            "all_frozen": self._all_frozen,
            "frozen_instruments": list(self._frozen_instruments),
            "reasons": self._freeze_reason,
            "portfolio_high_water": self._portfolio_high_water,
        }

    def to_dict(self) -> dict:
        return {
            "hw": self._instrument_high_water,
            "port_hw": self._portfolio_high_water,
            "frozen": list(self._frozen_instruments),
            "all_frozen": self._all_frozen,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "DrawdownController":
        obj = cls()
        obj._instrument_high_water = d.get("hw", {})
        obj._portfolio_high_water = d.get("port_hw", 0.0)
        obj._frozen_instruments = set(d.get("frozen", []))
        obj._all_frozen = d.get("all_frozen", False)
        return obj


class CorrelationBreakdownDetector:
    """[13.2] Detects when correlation structure breaks down.

    When correlations shift suddenly, covariance-based models (VaR, pairs arb)
    become unreliable. Detect via Frobenius norm of correlation matrix diff.

    Metric: normalized_diff = ||C_recent - C_historical||_F / ||C_historical||_F
    If normalized_diff > threshold (0.3) → correlations broke → reduce positions.
    """
    THRESHOLD: float = 0.3
    RECENT_WINDOW: int = 50
    HISTORICAL_WINDOW: int = 200

    def __init__(self, products: list[str]):
        self.products = products
        self.n = len(products)
        self._price_history: dict[str, list[float]] = {p: [] for p in products}
        self._last_breakdown_tick: int = -1
        self._breakdown_active: bool = False

    def update(self, prices: dict[str, float], tick: int) -> bool:
        """Update price history and check for correlation breakdown.
        Returns True if breakdown detected."""
        for p in self.products:
            if p in prices:
                self._price_history[p].append(prices[p])
                if len(self._price_history[p]) > self.HISTORICAL_WINDOW + 10:
                    self._price_history[p] = self._price_history[p][-(self.HISTORICAL_WINDOW + 10):]

        min_len = min(len(v) for v in self._price_history.values())
        if min_len < self.RECENT_WINDOW + 20:
            return False

        recent_corr = self._corr_matrix(self.RECENT_WINDOW)
        hist_corr = self._corr_matrix(self.HISTORICAL_WINDOW)

        diff = self._frobenius_norm_diff(recent_corr, hist_corr)
        hist_norm = self._frobenius_norm(hist_corr)
        normalized_diff = diff / (hist_norm + 1e-9)

        self._breakdown_active = normalized_diff > self.THRESHOLD
        if self._breakdown_active:
            self._last_breakdown_tick = tick
        return self._breakdown_active

    def _returns(self, prices: list[float]) -> list[float]:
        return [(prices[i] - prices[i-1]) / (prices[i-1] + 1e-9)
                for i in range(1, len(prices))]

    def _corr_matrix(self, window: int) -> list[list[float]]:
        n = self.n
        ret_series = []
        for p in self.products:
            hist = self._price_history[p][-window:]
            ret_series.append(self._returns(hist))
        min_len = min(len(r) for r in ret_series)
        if min_len < 5:
            return [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
        # Compute correlation matrix
        means = [sum(r[:min_len]) / min_len for r in ret_series]
        stds = [(sum((x - m)**2 for x in r[:min_len]) / min_len)**0.5 + 1e-9
                for r, m in zip(ret_series, means)]
        corr = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    corr[i][j] = 1.0
                else:
                    cov = sum((ret_series[i][k] - means[i]) * (ret_series[j][k] - means[j])
                              for k in range(min_len)) / min_len
                    corr[i][j] = cov / (stds[i] * stds[j])
        return corr

    def _frobenius_norm(self, matrix: list[list[float]]) -> float:
        return sum(x**2 for row in matrix for x in row)**0.5

    def _frobenius_norm_diff(self, a: list[list[float]], b: list[list[float]]) -> float:
        return sum((a[i][j] - b[i][j])**2
                   for i in range(len(a)) for j in range(len(a[0])))**0.5

    def should_reduce_positions(self) -> bool:
        return self._breakdown_active

    def action(self) -> str:
        if self._breakdown_active:
            return "REDUCE_POSITIONS: correlation structure changed, recompute covariance"
        return "NORMAL"


# ==============================================================================
# БЛОК: STOP-LOSS МЕХАНИЗМЫ  §33
# Hard stop, Time stop, Vol stop, Drawdown stop.
# ==============================================================================

class StopLossManager:
    """
    §33 — Stop-loss механизмы:
    - Hard stop по позиции: не увеличивать убыточную позицию.
    - Time stop: закрыть если удерживается >N тиков без прибыли.
    - Vol stop: закрыть если реализованная vol выросла >X%.
    - Drawdown stop: не торговать если PnL упал >Y за последние N тиков.
    """

    TIME_STOP_TICKS    = 100     # §33: закрыть если позиция >N тиков без прибыли
    VOL_STOP_MULT      = 2.0     # §33: закрыть если vol вырос в X раз от baseline
    DRAWDOWN_STOP_VAL  = -200.0  # §33: не торговать если PnL упал >Y за окно
    DRAWDOWN_STOP_WIN  = 30      # тиков для drawdown stop

    def __init__(self):
        # per-product: (entry_tick, entry_price, baseline_vol)
        self._position_entry: dict[str, tuple[int, float, float]] = {}
        self._pnl_buf: list[float] = []

    # ── Hard stop ──────────────────────────────────────────────────────────────

    def hard_stop(self, product: str, position: int,
                  unrealized_pnl: float) -> bool:
        """
        §33: Hard stop по позиции.
        Если позиция убыточна → не увеличивать.
        Возвращает True если нужно закрыть позицию немедленно.
        """
        if position == 0:
            self._position_entry.pop(product, None)
            return False
        # Убыток превышает допустимый порог
        if unrealized_pnl < self.DRAWDOWN_STOP_VAL * 0.5:
            return True
        return False

    # ── Time stop ──────────────────────────────────────────────────────────────

    def time_stop(self, product: str, position: int,
                  current_tick: int, current_pnl: float) -> bool:
        """
        §33: Time stop — закрыть позицию если удерживается >TIME_STOP_TICKS без прибыли.
        """
        if position == 0:
            self._position_entry.pop(product, None)
            return False
        if product not in self._position_entry:
            self._position_entry[product] = (current_tick, 0.0, 0.0)
            return False
        entry_tick, entry_pnl, _ = self._position_entry[product]
        held_ticks = current_tick - entry_tick
        if held_ticks > self.TIME_STOP_TICKS and current_pnl <= entry_pnl:
            logger.log(current_tick, product, "TIME_STOP",
                       extra=f"held={held_ticks} ticks pnl_delta={current_pnl - entry_pnl:.2f}")
            self._position_entry.pop(product, None)
            return True
        return False

    def record_entry(self, product: str, tick: int,
                     entry_pnl: float, baseline_vol: float):
        """Записать момент входа в позицию."""
        self._position_entry[product] = (tick, entry_pnl, baseline_vol)

    # ── Vol stop ───────────────────────────────────────────────────────────────

    def vol_stop(self, product: str, current_vol: float) -> bool:
        """
        §33: Vol stop — закрыть если реализованная vol выросла >VOL_STOP_MULT×baseline.
        """
        if product not in self._position_entry:
            return False
        _, _, baseline_vol = self._position_entry[product]
        if baseline_vol <= 0:
            return False
        if current_vol > baseline_vol * self.VOL_STOP_MULT:
            logger.log(-1, product, "VOL_STOP",
                       extra=f"current_vol={current_vol:.4f} baseline={baseline_vol:.4f}"
                             f" mult={current_vol/baseline_vol:.2f}x")
            return True
        return False

    # ── Drawdown stop ──────────────────────────────────────────────────────────

    def drawdown_stop(self, current_pnl: float) -> bool:
        """
        §33: Drawdown stop — не торговать если PnL упал >Y за последние N тиков.
        """
        self._pnl_buf.append(current_pnl)
        if len(self._pnl_buf) > self.DRAWDOWN_STOP_WIN * 2:
            self._pnl_buf = self._pnl_buf[-self.DRAWDOWN_STOP_WIN * 2:]
        if len(self._pnl_buf) < self.DRAWDOWN_STOP_WIN:
            return False
        window_start = self._pnl_buf[-self.DRAWDOWN_STOP_WIN]
        drawdown = current_pnl - window_start
        if drawdown < self.DRAWDOWN_STOP_VAL:
            logger.log(-1, "ALL", "DRAWDOWN_STOP",
                       extra=f"drawdown={drawdown:.1f} threshold={self.DRAWDOWN_STOP_VAL}")
            return True
        return False

    def should_trade(self, product: str, position: int,
                     current_tick: int, current_pnl: float,
                     current_vol: float) -> bool:
        """Единая проверка: True = торговать разрешено."""
        if self.drawdown_stop(current_pnl):
            return False
        if self.time_stop(product, position, current_tick, current_pnl):
            return False
        if self.vol_stop(product, current_vol):
            return False
        return True


# ==============================================================================
# БЛОК: VOLATILITY TARGETER  §31  + §32 (vol-based limit reduction)
# Volatility targeting: нормировать позицию по волатильности.
# Vol-based limit reduction: снижать лимиты при высокой волатильности.
# ==============================================================================

class VolatilityTargeter:
    """
    §31 — Volatility targeting: нормировать позицию по волатильности.
    target_position_size = target_vol / current_vol × base_size
    §32 — Volatility-based limit reduction:
    При vol > threshold уменьшать позиционный лимит.
    """

    BASE_VOL        = 0.01   # baseline volatility (1%)
    TARGET_VOL      = 0.005  # target daily vol fraction
    MIN_SIZE_FRAC   = 0.1    # минимум 10% от базового размера
    VOL_HIGH_MULT   = 1.5    # если vol > BASE_VOL * VOL_HIGH_MULT → снизить лимит
    LIMIT_REDUCTION = 0.5    # снизить лимит до 50% при высокой vol

    def vol_based_size(self, base_size: int, current_vol: float) -> int:
        """
        §31 Volatility targeting.
        Нормировать размер позиции по текущей волатильности.
        При высокой vol → меньший размер. При низкой → до base_size.
        """
        if current_vol <= 0:
            return base_size
        scale = self.TARGET_VOL / current_vol
        scaled = int(base_size * min(1.0, max(self.MIN_SIZE_FRAC, scale)))
        return max(1, scaled)

    def vol_based_limit(self, product: str, current_vol: float,
                        position_limits: dict) -> int:
        """
        §32 Volatility-based limit reduction.
        При экстремальной волатильности уменьшать допустимый лимит позиции.
        """
        hard_limit = position_limits.get(product, 100)
        if current_vol <= 0:
            return hard_limit
        if current_vol > self.BASE_VOL * self.VOL_HIGH_MULT:
            reduced = int(hard_limit * self.LIMIT_REDUCTION)
            return max(1, reduced)
        return hard_limit

    def target_position(self, signal_strength: float, base_size: int,
                        current_vol: float, confidence: float = 1.0) -> int:
        """
        §30/§31: Target position = signal × vol_sized × confidence.
        signal_strength: -1 (max short) to +1 (max long).
        confidence: 0..1 (уверенность сигнала).
        """
        vol_size = self.vol_based_size(base_size, current_vol)
        target = int(signal_strength * vol_size * confidence)
        return target


# ==============================================================================
# БЛОК: ORDER SIZER  §30, §31
# max_order_size per tick, Kelly, Half-Kelly, proportional sizing.
# Passive/aggressive order type distinction.
# ==============================================================================

class OrderSizer:
    """
    §30 — Max order size per tick.
    §31 — Kelly criterion, Half-Kelly, proportional sizing.
    §30 — Passive (limit) vs Aggressive (taker) order type.
    """

    MAX_ORDER_SIZE_DEFAULT = 20   # §30: default max order per tick
    KELLY_FRACTION         = 0.5  # §31: Half-Kelly по умолчанию

    # ── Passive / Aggressive order types ──────────────────────────────────────

    @staticmethod
    def passive_order(product: str, price: int, qty: int) -> "Order":
        """
        §30 Passive (limit) order — ставить в стакан, ждать исполнения.
        В Prosperity только limit orders; passive = quote inside spread.
        """
        return Order(product, price, qty)

    @staticmethod
    def aggressive_order(product: str, price: int, qty: int) -> "Order":
        """
        §30 Aggressive order — исполняться по лучшей цене контрагента.
        Taker: цена = лучший bid/ask контрагента (crossing the spread).
        """
        return Order(product, price, qty)

    # ── Max order size per tick ────────────────────────────────────────────────

    @staticmethod
    def clip_order(qty: int, product: str, position: int,
                   position_limits: dict,
                   max_order_size: int = MAX_ORDER_SIZE_DEFAULT) -> int:
        """
        §30 clip_order() — обрезать ордер до допустимого размера.
        Учитывает: max_order_size per tick + position limit.
        """
        hard_limit = position_limits.get(product, 100)
        # Не выйти за position limit
        if qty > 0:
            available = hard_limit - position
            qty = min(qty, available)
        else:
            available = hard_limit + position
            qty = max(qty, -available)
        # Не превысить max per tick
        qty = max(-max_order_size, min(max_order_size, qty))
        return qty

    # ── Kelly criterion ────────────────────────────────────────────────────────

    @staticmethod
    def kelly(p: float, b: float) -> float:
        """
        §31 Kelly criterion: f = (p×b - q) / b
        p = вероятность выигрыша, b = reward/risk ratio, q = 1 - p.
        Возвращает фракцию от капитала (0..1).
        """
        if b <= 0 or p <= 0 or p >= 1:
            return 0.0
        q = 1.0 - p
        f = (p * b - q) / b
        return max(0.0, f)

    @staticmethod
    def half_kelly(p: float, b: float) -> float:
        """
        §31 Half-Kelly: безопаснее полного Kelly при ошибке в p.
        f_half = kelly(p, b) / 2.
        """
        return OrderSizer.kelly(p, b) * 0.5

    @staticmethod
    def vol_sizing(base_size: int, current_vol: float,
                   target_vol: float = 0.005) -> int:
        """
        §31 Sizing по волатильности (volatility targeting).
        Нормировать размер позиции: размер ∝ target_vol / current_vol.
        """
        if current_vol <= 0:
            return base_size
        scale = target_vol / current_vol
        return max(1, int(base_size * min(1.0, scale)))

    @staticmethod
    def confidence_sizing(base_size: int, confidence: float) -> int:
        """
        §C — Sizing по уверенности сигнала.
        confidence: 0..1. Линейное масштабирование.
        """
        return max(1, int(base_size * max(0.0, min(1.0, confidence))))

    @staticmethod
    def proportional_sizing(signal: float, max_size: int) -> int:
        """
        §31 Proportional sizing: размер пропорционален силе сигнала.
        signal: -1..+1.
        """
        return int(signal * max_size)


# ==============================================================================
# БЛОК: TARGET POSITION TRACKER  §30, §C
# target_position vs current_position.
# Target inventory = 0 для market maker.
# Long/short exposure отдельно.
# ==============================================================================

class TargetPositionTracker:
    """
    §30/§C — Отслеживать target position и отклонение от него.
    Target inventory = 0 для market maker.
    Long / short exposure считать отдельно.
    """

    def __init__(self, target_inventory: int = 0):
        self.target_inventory: int = target_inventory   # §30: обычно 0 для MM
        self._targets: dict[str, int] = {}              # per-product target

    def set_target(self, product: str, target: int):
        """Установить target position для продукта."""
        self._targets[product] = target

    def inventory_risk(self, product: str, current_position: int) -> int:
        """
        §30 Текущее отклонение от таргета = inventory risk.
        >0 → long bias (нужно продавать), <0 → short bias (нужно покупать).
        """
        target = self._targets.get(product, self.target_inventory)
        return current_position - target

    def long_exposure(self, positions: dict[str, int]) -> int:
        """§30 Long exposure — сумма всех положительных позиций."""
        return sum(v for v in positions.values() if v > 0)

    def short_exposure(self, positions: dict[str, int]) -> int:
        """§30 Short exposure — сумма всех отрицательных позиций (абс. знач.)."""
        return sum(-v for v in positions.values() if v < 0)

    def net_exposure(self, positions: dict[str, int],
                     hedge_ratios: Optional[dict[str, float]] = None) -> float:
        """
        §32 Net exposure с учётом hedge ratios.
        hedge_ratios: {product: ratio} — напр. {COCONUT: -0.5} если 1 coupon = 0.5 coconut.
        """
        if hedge_ratios is None:
            hedge_ratios = {}
        net = 0.0
        for product, pos in positions.items():
            ratio = hedge_ratios.get(product, 1.0)
            net += pos * ratio
        return net

    def aggressively_unwind(self, product: str, position: int,
                             position_limit: int) -> bool:
        """
        §30 Aggressively unwind: True если позиция близко к лимиту.
        Порог: 80% от лимита.
        """
        return abs(position) >= position_limit * 0.80

    def should_close_new_positions(self, tick: int, total_ticks: int,
                                   last_n: int = 10) -> bool:
        """
        §C End-of-round liquidation.
        Не открывать новые позиции в последние last_n тиков раунда.
        """
        return (total_ticks - tick) <= last_n


# ==============================================================================
# БЛОК: MEAN REVERSION STRATEGY  §B
# Standalone класс для mean reversion стратегии.
# Z-score вход, EMA fair value, halflife decay.
# ==============================================================================

class MeanReversionStrategy:
    """
    §B — Mean reversion стратегия.
    Логика:
    1. Оценить fair value через EMA / Kalman.
    2. Вычислить z-score отклонения текущей цены от fair value.
    3. При |z| > entry_threshold → входить против движения.
    4. При |z| < exit_threshold → выходить.
    5. Не торговать если ADF тест не подтверждает стационарность.
    """

    ENTRY_Z      = 1.5    # z-score для входа
    EXIT_Z       = 0.3    # z-score для выхода
    LOOKBACK     = 50     # окно для std оценки
    EMA_ALPHA    = 0.05   # сглаживание EMA

    def __init__(self, product: str):
        self.product  = product
        self.ema      = 0.0
        self.prices:  list[float] = []
        self.tick     = 0
        self._ready   = False

    def update(self, mid: float) -> Optional[dict]:
        """
        Вызывать каждый тик.
        Возвращает dict с сигналом или None если не готов.
        """
        self.tick += 1
        # EMA fair value
        self.ema = self.ema * (1 - self.EMA_ALPHA) + mid * self.EMA_ALPHA if self.ema else mid
        self.prices.append(mid)
        # §15.1.2 rolling cap
        if len(self.prices) > self.LOOKBACK * 2:
            self.prices = self.prices[-self.LOOKBACK * 2:]
        if len(self.prices) < self.LOOKBACK:
            return None
        self._ready = True

        window = self.prices[-self.LOOKBACK:]
        mu  = sum(window) / len(window)
        std = (sum((x - mu) ** 2 for x in window) / len(window)) ** 0.5
        if std < 1e-9:
            return None

        zscore     = (mid - self.ema) / std
        # §B Mean reversion: сигнал против z-score
        if zscore > self.ENTRY_Z:
            signal = "SELL"   # цена выше fair value → ожидаем возврат вниз
        elif zscore < -self.ENTRY_Z:
            signal = "BUY"    # цена ниже fair value → ожидаем возврат вверх
        elif abs(zscore) < self.EXIT_Z:
            signal = "EXIT"
        else:
            signal = "HOLD"

        return {
            "product":  self.product,
            "mid":      mid,
            "ema":      self.ema,
            "zscore":   zscore,
            "signal":   signal,
            "strategy": "mean_reversion",
            "note":     "§B: mean reversion только на стационарных продуктах",
        }

    def target_position(self, zscore: float, max_size: int,
                        confidence: float = 1.0) -> int:
        """
        Target position = -sign(z) × size × confidence (proportional).
        """
        if abs(zscore) < self.EXIT_Z:
            return 0
        direction = -1 if zscore > 0 else 1
        magnitude = min(abs(zscore) / self.ENTRY_Z, 1.0)
        return int(direction * max_size * magnitude * confidence)


# ==============================================================================
# ==============================================================================
# БЛОК: QUOTE STUFFING DETECTION  §E
# Detect when a bot places/cancels orders rapidly to create latency.
# ==============================================================================

class QuoteStuffingDetector:
    """
    §E — Quote stuffing detection.
    Признаки: резкий рост числа ордеров без реальных сделок,
    ордера появляются и тут же исчезают, bid/ask прыгают без трендового движения.
    Метрика: quote_to_trade_ratio за окно.
    """

    WINDOW           = 20     # тиков для расчёта
    STUFFING_RATIO   = 3.0    # если quotes / trades > этого → quote stuffing (P2/P3 calibrated)
    MIN_QUOTES       = 10     # минимум quotes для срабатывания

    def __init__(self):
        self._quote_counts: list[int] = []  # кол-во изменений стакана за тик
        self._trade_counts: list[int] = []  # кол-во сделок за тик
        self._spread_series: list[float] = []

    def update(self, n_quote_changes: int, n_trades: int,
               spread: float) -> dict:
        """
        n_quote_changes: сколько раз обновился best bid/ask за тик.
        n_trades: сколько сделок прошло за тик.
        spread: текущий bid-ask spread.
        """
        self._quote_counts.append(n_quote_changes)
        self._trade_counts.append(n_trades)
        self._spread_series.append(spread)
        # §15.1.2 rolling cap
        if len(self._quote_counts) > self.WINDOW * 2:
            self._quote_counts = self._quote_counts[-self.WINDOW * 2:]
            self._trade_counts = self._trade_counts[-self.WINDOW * 2:]
            self._spread_series = self._spread_series[-self.WINDOW * 2:]

        win_q = self._quote_counts[-self.WINDOW:]
        win_t = self._trade_counts[-self.WINDOW:]
        total_q = sum(win_q)
        total_t = sum(win_t)

        ratio = total_q / max(total_t, 1)
        is_stuffing = (total_q >= self.MIN_QUOTES and ratio >= self.STUFFING_RATIO)

        return {
            "quote_stuffing":    is_stuffing,
            "quote_trade_ratio": ratio,
            "total_quotes":      total_q,
            "total_trades":      total_t,
            "action":            "WIDEN_SPREAD" if is_stuffing else "NORMAL",
            "note":              "§E: при stuffing — расширить спред, не ставить passive внутри",
        }


# ==============================================================================
# БЛОК: MOMENTUM IGNITION DETECTION  §E
# Detect large orders designed to move price artificially, then reverse.
# ==============================================================================

class MomentumIgnitionDetector:
    """
    §E — Momentum ignition detection.
    Признаки: резкое ценовое движение (>Z σ) при большом объёме с одной стороны,
    за которым следует быстрый разворот.
    Стратегия: не следовать за движением — это ловушка.
    """

    WINDOW        = 30      # тиков для baseline
    PRICE_Z_THRESH = 2.0    # σ для «резкого движения»
    VOL_MULT       = 2.5    # объём должен быть >VOL_MULT × baseline

    def __init__(self):
        self._prices:  list[float] = []
        self._volumes: list[float] = []
        self._ignition_tick: int   = -1

    def update(self, mid: float, volume: float, tick: int) -> dict:
        self._prices.append(mid)
        self._volumes.append(volume)
        if len(self._prices) > self.WINDOW * 2:
            self._prices  = self._prices[-self.WINDOW * 2:]
            self._volumes = self._volumes[-self.WINDOW * 2:]

        if len(self._prices) < self.WINDOW:
            return {"momentum_ignition": False, "action": "NORMAL"}

        win_p = self._prices[-self.WINDOW:]
        win_v = self._volumes[-self.WINDOW:]

        mu_p  = sum(win_p) / len(win_p)
        std_p = (sum((x - mu_p) ** 2 for x in win_p) / len(win_p)) ** 0.5 + 1e-9
        mu_v  = sum(win_v) / len(win_v)

        current_z      = abs(mid - mu_p) / std_p
        current_vol_z  = volume / max(mu_v, 1e-9)
        large_move     = current_z > self.PRICE_Z_THRESH
        large_volume   = current_vol_z > self.VOL_MULT

        # Детектируем ignition: резкое движение + высокий объём
        is_ignition = large_move and large_volume
        if is_ignition:
            self._ignition_tick = tick

        # Разворот детектируется если после ignition цена откатилась обратно к μ
        recent_reversal = (
            tick - self._ignition_tick <= 5
            and abs(mid - mu_p) / std_p < 0.5
        ) if self._ignition_tick >= 0 else False

        return {
            "momentum_ignition": is_ignition,
            "price_z":           current_z,
            "vol_z":             current_vol_z,
            "recent_reversal":   recent_reversal,
            "action":            "DO_NOT_FOLLOW" if is_ignition else "NORMAL",
            "note":              "§E: не следовать за ignition — это ловушка",
        }

    def directional_fade_signal(self, market_trades: list,
                                  threshold_ticks: int = 10,
                                  directional_threshold: float = 0.80) -> dict:
        """[11.2] Detect momentum ignition by >80% trades in one direction.
        Fade the movement (trade AGAINST it) — the igniter will reverse.

        market_trades: list of recent Trade objects
        Returns: {signal: 'FADE_BUY'/'FADE_SELL'/'NONE', confidence, n_trades}
        """
        if len(market_trades) < 5:
            return {"signal": "NONE", "confidence": 0.0}

        recent = market_trades[-threshold_ticks:]
        buy_count = sum(1 for t in recent if getattr(t, 'quantity', 0) > 0)
        total = len(recent)
        if total == 0:
            return {"signal": "NONE", "confidence": 0.0}

        buy_pct = buy_count / total
        sell_pct = 1.0 - buy_pct

        if buy_pct >= directional_threshold:
            confidence = (buy_pct - directional_threshold) / (1.0 - directional_threshold)
            return {
                "signal": "FADE_SELL",   # Too many buys → fade by selling
                "confidence": round(confidence, 3),
                "buy_pct": round(buy_pct, 3),
                "n_trades": total,
                "reasoning": f"{buy_pct*100:.0f}% buys → artificial momentum → fade sell",
            }
        elif sell_pct >= directional_threshold:
            confidence = (sell_pct - directional_threshold) / (1.0 - directional_threshold)
            return {
                "signal": "FADE_BUY",    # Too many sells → fade by buying
                "confidence": round(confidence, 3),
                "sell_pct": round(sell_pct, 3),
                "n_trades": total,
                "reasoning": f"{sell_pct*100:.0f}% sells → artificial momentum → fade buy",
            }

        return {"signal": "NONE", "confidence": 0.0, "buy_pct": round(buy_pct, 3)}


# ==============================================================================
# БЛОК: SPREAD TARGET CONFIG  §F
# Spread target normal vs wide. Quote refresh rate. Min conversion profit.
# ==============================================================================

class SpreadConfig:
    """
    §F — Параметры рынка для spread management.
    spread_target_normal: целевой спред при нормальных условиях.
    spread_target_wide:   расширенный спред при высокой vol / adverse selection.
    quote_refresh_rate:   каждые N тиков обновлять котировки.
    min_conversion_profit: мин edge для конверсионного арба.
    """

    # Per-product spread targets (normal, wide)
    SPREAD_TARGET: dict[str, tuple[int, int]] = {
        "RAINFOREST_RESIN":      (1, 3),
        "KELP":                  (3, 6),
        "SQUID_INK":             (4, 8),
        "CROISSANTS":            (1, 3),
        "JAMS":                  (1, 3),
        "DJEMBES":               (2, 5),
        "PICNIC_BASKET1":        (3, 7),
        "PICNIC_BASKET2":        (3, 7),
        "COCONUT":               (2, 5),
        "COCONUT_COUPON":        (5, 12),
        "VOLCANIC_ROCK":         (2, 6),
        "VOLCANIC_ROCK_VOUCHER": (5, 15),
        "MAGNIFICENT_MACARONS":  (3, 8),
    }

    # Quote refresh: как часто обновлять котировки (тиков)
    QUOTE_REFRESH_RATE: dict[str, int] = {
        "RAINFOREST_RESIN":      1,   # стабильный → обновлять каждый тик
        "KELP":                  1,
        "SQUID_INK":             1,
        "CROISSANTS":            1,
        "JAMS":                  1,
        "DJEMBES":               1,
        "PICNIC_BASKET1":        1,
        "PICNIC_BASKET2":        1,
        "COCONUT":               1,
        "COCONUT_COUPON":        2,
        "VOLCANIC_ROCK":         1,
        "VOLCANIC_ROCK_VOUCHER": 2,
        "MAGNIFICENT_MACARONS":  1,
    }

    # Мин profit для конверсионного арба (в тиках цены)
    MIN_CONVERSION_PROFIT: dict[str, float] = {
        "MAGNIFICENT_MACARONS":  2.0,   # покрыть transport cost + margin
        "COCONUT_COUPON":        3.0,
        "VOLCANIC_ROCK_VOUCHER": 2.0,
    }
    MIN_CONVERSION_PROFIT_DEFAULT = 1.0

    @classmethod
    def get_spread_target(cls, product: str,
                          wide: bool = False) -> int:
        """Вернуть spread target для продукта. wide=True при high vol / adverse selection."""
        normal, widen = cls.SPREAD_TARGET.get(product, (2, 5))
        return widen if wide else normal

    @classmethod
    def get_refresh_rate(cls, product: str) -> int:
        return cls.QUOTE_REFRESH_RATE.get(product, 1)

    @classmethod
    def get_min_conversion_profit(cls, product: str) -> float:
        return cls.MIN_CONVERSION_PROFIT.get(
            product, cls.MIN_CONVERSION_PROFIT_DEFAULT)


# ==============================================================================
# БЛОК: QUOTE LADDER  §F
# Слои котировок (quote ladder): несколько уровней bid/ask.
# Стакан уровни 1/2/3.
# ==============================================================================

class QuoteLadder:
    """
    §F — Quote ladder (слои котировок).
    Размещать ордера на нескольких уровнях цены вместо одного.
    Уровень 1 (tight): узкий спред, малый размер — для быстрого исполнения.
    Уровень 2 (mid):   средний спред, средний размер.
    Уровень 3 (wide):  широкий спред, большой размер — пассивный inventory.
    """

    # (spread_offset_ticks, size_fraction_of_limit)
    LADDER_LEVELS = [
        (1, 0.20),   # level 1: ±1 tick from mid, 20% of limit
        (2, 0.30),   # level 2: ±2 ticks,         30%
        (4, 0.25),   # level 3: ±4 ticks,          25%
    ]

    @classmethod
    def build_quotes(cls, product: str, mid: float,
                     position_limit: int, current_position: int,
                     inventory_skew: float = 0.0) -> list[dict]:
        """
        Построить ladder котировок.
        inventory_skew: -1..+1 (positive = long bias, надо продавать).
        Возвращает список {'side', 'price', 'qty'}.
        """
        quotes = []
        remaining_limit = position_limit - abs(current_position)
        if remaining_limit <= 0:
            return quotes

        for spread_off, size_frac in cls.LADDER_LEVELS:
            size = max(1, int(position_limit * size_frac))
            # Inventory skew: уменьшать bid qty при long position, ask qty при short
            bid_size = max(1, int(size * (1.0 - max(0.0, inventory_skew))))
            ask_size = max(1, int(size * (1.0 + min(0.0, inventory_skew))))

            bid_price = int(mid) - spread_off
            ask_price = int(mid) + spread_off

            if bid_size > 0:
                quotes.append({"side": "BUY",  "price": bid_price, "qty":  bid_size})
            if ask_size > 0:
                quotes.append({"side": "SELL", "price": ask_price, "qty": -ask_size})

        return quotes

    @classmethod
    def get_level(cls, product: str, od: object,
                  level: int = 1) -> dict:
        """
        §F Стакан уровни 1/2/3.
        Вернуть price/qty на уровне 1, 2 или 3 order book.
        od: OrderDepth.
        """
        if not od:
            return {"bid": None, "ask": None, "bid_qty": 0, "ask_qty": 0}

        sorted_bids = sorted(od.buy_orders.keys(),  reverse=True)
        sorted_asks = sorted(od.sell_orders.keys())
        idx = level - 1

        bid_price = sorted_bids[idx] if idx < len(sorted_bids) else None
        ask_price = sorted_asks[idx] if idx < len(sorted_asks) else None
        bid_qty   = od.buy_orders.get(bid_price, 0)  if bid_price is not None else 0
        ask_qty   = od.sell_orders.get(ask_price, 0) if ask_price is not None else 0

        return {
            "bid":     bid_price,
            "ask":     ask_price,
            "bid_qty": bid_qty,
            "ask_qty": ask_qty,
            "spread":  (ask_price - bid_price) if bid_price and ask_price else None,
        }


